```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct record {
    long offset;
    int key;
    int value;
} Record;

typedef struct hash_table {
    unsigned int size;
    Record** array;
} HashTable;

HashTable* create_hash_table(unsigned int size) {
    if (!(size > 0)) return NULL;

    HashTable* table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->size = size;
    table->array = calloc(size, sizeof(Record*));
    if (!table->array) {
        free(table);
        return NULL;
    }

    return table;
}

unsigned int hash_function(const unsigned int size, const Record* record) {
    return (abs((unsigned long)record->key % size));
}

Record* find_record(HashTable* table, int key) {
    Record* record = &table->array[hash_function(table->size, &table->array[0])];
    unsigned int idx = hash_function(table->size, record);

    while (idx < table->size && record->key != key) {
        if (!record->key) break; // empty slot
        record++;
        idx = (idx + 1) % table->size;
    }

    return record;
}

void insert_record(HashTable* table, const Record* new_record) {
    Record* record = find_record(table, new_record->key);

    if (record->key) { // existing key found
        free(record);
    } else { // empty slot found
        table->array[idx] = *new_record;
    }
}

void delete_record(HashTable* table, int key) {
    Record* record = find_record(table, key);

    if (record->key) { // existing key found
        memset(record, 0, sizeof(*record));
    }
}

Record get_random_record(unsigned int min_key, unsigned int max_key) {
    Record record = { .key = rand() % (max_key - min_key + 1) + min_key };
    return record;
}

void initialize_hash_table(HashTable* table, long* offsets, int* keys, unsigned int size) {
    for (unsigned int i = 0; i < size; ++i) {
        Record random_record = get_random_record(1, INT_MAX);
        random_record.offset = offsets[i];
        random_record.key = keys[i];
        insert_record(table, &random_record);
    }
}

void destroy_hash_table(HashTable* table) {
    if (!table) return;

    for (unsigned int i = 0; i < table->size; ++i) {
        Record* record = table->array[i];
        free(record);
    }

    free(table->array);
    free(table);
}
