```c
#include <arpa/inet.h>
#include <netdb.h>
#include <resolv.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>

typedef struct {
    char* fields; // dynamically allocated array of strings
    size_t len;   // length of the array
} LogEntry;

LogEntry* parse_log_line(const char* line) {
    char** fields = calloc(10, sizeof(char*)); // assume 10 fields at most
    size_t current_field = 0;
    char* token = strtok(line, " \t");

    while (token != NULL && current_field < 9) {
        fields[current_field] = token;
        ++current_field;
        token = strtok(NULL, " \t");
    }

    if (current_field < 2) { // insufficient data
        fields[current_field++] = "<Insufficient Data>";
    }

    // Allocate memory for the last two numerical fields to store their average as a string
    char* avg_field = malloc(32);
    sprintf(avg_field, "%.2f", (fields[current_field - 2] + fields[current_field - 1]) / 2.0);
    fields[current_field++] = avg_field;

    LogEntry* log_entry = malloc(sizeof(LogEntry));
    log_entry->fields = realloc(fields, (current_field + 1) * sizeof(char*));
    log_entry->len = current_field;

    return log_entry;
}

void dns_resolve(const char* hostname, void (*callback)(const char*, in_addr_t)) {
    struct hostent* he = gethostbyname(hostname);
    if (he == NULL) {
        // DNS error or unknown host
        return;
    }

    in_addr_t ip = he->h_addr3.s_addr;
    callback(hostname, ip);
}

void process_log_entry(LogEntry* entry, void (*callback)(const char*, in_addr_t)) {
    const char* hostname = entry->fields[0];
    dns_resolve(hostname, [=](const char* h, in_addr_t i) {
        printf("%s -> %s\n", h, inet_ntoa(*((struct in_addr*)&i)));
        callback(entry, i);
    });
}

int main() {
    FILE* file = fopen("log.txt", "r");
    if (file == NULL) {
        // Handle error
        return 1;
    }

    char line[4096];
    while (fgets(line, sizeof(line), file)) {
        LogEntry* entry = parse_log_line(line);
        process_log_entry(entry, [](const char* data, in_addr_t ip) {
            free(data); // deallocate log entry memory
        });
    }

    fclose(file);
    return 0;
}
```

This code demonstrates a basic DNS resolver and a log parsing mechanism. It reads a log file, processes each line by creating a LogEntry structure for the parsed fields, and performs a DNS lookup using gethostbyname(). The main function uses recursive callbacks to manage concurrent access to shared resources (the DNS resolver function). The memory allocation strategy is not optimized in this example but could be improved with techniques like using malloc/free pairs or implementing pool-based memory allocation.']

