#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <limits.h>
#include <string.h>

typedef struct {
    int *data;
    size_t capacity;
    size_t count;
} IntArray;

IntArray* create_int_array() {
    return calloc(1, sizeof(IntArray));
}

void destroy_int_array(IntArray *arr) {
    if (arr == NULL) return;
    free(arr->data);
    free(arr);
}

bool is_valid_input(int num) {
    return (num >= -1000000 && num <= 1000000);
}

void insert_sort(IntArray *arr, int value) {
    if (arr->count == arr->capacity) {
        arr->data = realloc(arr->data, sizeof(int) * (arr->capacity + 1024));
        arr->capacity += 1024;
    }

    size_t i;
    for (i = arr->count - 1; i >= 0 && arr->data[i] > value; --i) {
        arr->data[i + 1] = arr->data[i];
    }
    arr->data[i + 1] = value;
    ++arr->count;
}

void merge_sort(IntArray *arr, size_t left, size_t right) {
    if (right - left <= 15) insert_sort(arr, arr->data[left + (right - left) / 2]);
    else {
        size_t mid = left + (right - left) / 2;
        merge_sort(arr, left, mid);
        merge_sort(arr, mid, right);
        merge(arr, left, mid, right);
    }
}

void merge(IntArray *arr, size_t left, size_t mid, size_t right) {
    int *temp = malloc((right - left) * sizeof(int));
    size_t i = left, j = mid, k = 0;

    while (i < mid && j < right) {
        if (arr->data[i] <= arr->data[j]) {
            temp[k++] = arr->data[i++];
        } else {
            temp[k++] = arr->data[j++];
        }
    }

    while (i < mid) {
        temp[k++] = arr->data[i++];
    }

    while (j < right) {
        temp[k++] = arr->data[j++];
    }

    memcpy(arr->data + left, temp, (right - left) * sizeof(int));
    free(temp);
}

void read_and_process_input(IntArray *arr) {
    int num;
    while (1) {
        if (scanf("%d", &num) != 1) {
            printf("Invalid input. Expected an integer within the range -1,000,000 to 1,000,000\n");
            break;
        }
        if (!is_valid_input(num)) {
            printf("Invalid input. Expected an integer within the range -1,000,000 to 1,000,000\n");
            break;
        }
        insert_sort(arr, num);
        if (arr->count >= 1000000) {
            printf("Exceeded the maximum number of integers. Exiting gracefully.\n");
            destroy_int_array(arr);
            return;
        }
    }
}

void sort_and_find_minimum(IntArray *arr) {
    merge_sort(arr, 0, arr->count);
    printf("Smallest integer: %d\n", arr->data[0]);
    destroy_int_array(arr);
}

int main() {
    IntArray *arr = create_int_array();
    read_and_process_input(arr);
    sort_and_find_minimum(arr);
    return 0;
}
```
This solution uses an insertion sort for small sub-arrays and a merge sort algorithm for larger ones, providing a trade-off between efficiency and usability. The function dynamically allocates memory as needed, handles error conditions gracefully, and sorts the array in ascending order before finding the smallest integer.']

['```c
#include <stdio.h>
#include <stdarg.h>
#include <pthread.h>
#include <time.h>
#include <sys/mman.h>
#define BUFFER_GROWTH_FACTOR 2
#define FLUSH_INTERVAL 500000 /* in number of log entries */

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

struct LogBuffer {
    char* buffer;
    size_t capacity;
    size_t head;
    size_t tail;
    pthread_mutex_t mutex;
    LogLevel threshold;
    FILE* file;
    void(*flush)(const char*); /* callback for flushing to an external service */
};

void log_init(struct LogBuffer* buffer, size_t initial_size, LogLevel threshold, FILE* file, void(*flush_func)(const char*)) {
    buffer->buffer = mmap(NULL, initial_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    buffer->capacity = initial_size;
    buffer->head = buffer->tail = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
    buffer->threshold = threshold;
    buffer->file = file;
    buffer->flush = flush_func;
}

void log_append(struct LogBuffer* buffer, LogLevel level, const char* format, ...) {
    if (level <= buffer->threshold) {
        pthread_mutex_lock(&buffer->mutex);
        size_t free_space = buffer->capacity - ((buffer->head + 1) % buffer->capacity) + ((buffer->tail - 1) % buffer->capacity);
        va_list args;
        va_start(args, format);
        int len = vsnprintf(buffer->buffer + buffer->tail, free_space, format, args) + 1;
        if (len > free_space) {
            if ((buffer->capacity * BUFFER_GROWTH_FACTOR) < len)
                buffer->capacity *= BUFFER_GROWTH_FACTOR;
            else
                buffer->capacity += len - free_space;
            char* new_buffer = mremap(buffer->buffer, buffer->capacity, buffer->capacity * BUFFER_GROWTH_FACTOR, MREMAP_MAYMOVE);
            if (new_buffer == MAP_FAILED) {
                perror("mremap");
                exit(EXIT_FAILURE);
            }
            buffer->buffer = new_buffer;
        }
        buffer->tail += len;
        va_end(args);
        pthread_mutex_unlock(&buffer->mutex);
    }
}

void log_flush(struct LogBuffer* buffer) {
    if (buffer->file)
        fprintf(buffer->file, "%s", buffer->buffer);
    if (buffer->flush)
        buffer->flush(buffer->buffer);
    memset(buffer->buffer, 0, buffer->tail);
    buffer->tail = 0;
}

void log_conditional_flush(struct LogBuffer* buffer, clock_t interval) {
    clock_t now = clock();
    if ((now - buffer->flush_time) >= interval) {
        log_flush(buffer);
        buffer->flush_time = now;
    }
}
```

This code provides a basic implementation of the task, using `pthread_mutex_lock` and `pthread_mutex_unlock` for thread safety. The log messages are buffered and can be formatted dynamically using `vsnprintf`. The logging level is defined by an enumeration, and the function supports conditional flushing to a file or external service at specified intervals without blocking the main execution flow. Additionally, the buffer grows as needed to accommodate large log entries while minimizing memory overhead.']

