import java.io.IOException;
import java.text.MessageFormat;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import okhttp3.*;
import com.google.gson.Gson;

public class PokemonWeaknessReport {
    private static final Logger LOGGER = LoggerFactory.getLogger(PokemonWeaknessReport.class);
    private static final ExecutorService executor = Executors.newFixedThreadPool(10);
    private static final int CACHE_EXPIRATION_MINUTES = 5;
    private static final ConcurrentHashMap<String, Future<Response>> cache = new ConcurrentHashMap<>();
    private static final Gson gson = new Gson();

    public void generateReport(Pokemon pokemon, String language) {
        String pokemonId = pokemon.getId();
        String cachedResponseKey = "cache_" + pokemonId;

        // Check cache for previously fetched data
        Future<Response> cachedFuture = cache.get(cachedResponseKey);
        if (cachedFuture != null && !cachedFuture.isDone()) {
            try {
                Response response = cachedFuture.get();
                if (!response.isSuccessful()) {
                    // If the response is not successful, remove it from the cache and retry fetching data
                    cache.remove(cachedResponseKey);
                } else {
                    // Use the cached response to generate the report
                    PokemonApiData apiData = gson.fromJson(response.body().string(), PokemonApiData.class);
                    generateReportFromApiData(apiData, language);
                }
            } catch (InterruptedException | ExecutionException e) {
                LOGGER.error("Error while retrieving data from cache", e);
