class Cipher {
public:
    virtual ~Cipher() {}
    virtual void init(const map<string, string>& config) = 0;
    virtual string encrypt(const string& plaintext) const = 0;
    virtual string decrypt(const string& ciphertext) const = 0;
};

class ThreadSafeCipherManager {
private:
    map<string, unique_ptr<Cipher>> ciphers_;
    mutex mtx_;
    atomic_bool running_;
    io_service io_;
    deadline_timer timer_;
    const string configFilePath_;

public:
    ThreadSafeCipherManager(const string& configFilePath) : configFilePath_(configFilePath), running_(true), timer_(io_) {
        loadConfig();
    }

    ~ThreadSafeCipherManager() {
        stop();
    }

    void stop() {
        running_.store(false, memory_order_relaxed);
        io_.stop();
        timer_.expires_from_now(seconds(0));
        timer_.async_wait([this](const system_error&) {});
        io_.run();
    }

    unique_ptr<Cipher> getCipher(const string& algorithm) {
        lock_guard<mutex> lk(mtx_);
        return move(ciphers_[algorithm]);
    }

    void loadConfig() {
        ifstream ifs(configFilePath_);
        if (!ifs.is_open()) {
            cerr << "Error: Unable to open configuration file." << endl;
            exit(1);
        }

        pt::ptree tree;
        read_xml(ifs, tree);

        loadCiphers(tree);
    }

    void loadCiphers(const pt::ptree& tree) {
        for (auto& pair : tree.get_child("ciphers").get_children()) {
            string algorithm = pair.first.data();
            map<string, string> config;

            for (auto& value : pair.second) {
                config[value.first.data()] = value.second.data();
            }

            unique_ptr<Cipher> cipher(createCipher(algorithm, config));
            lock_guard<mutex> lk(mtx_);
            ciphers_[algorithm] = move(cipher);
        }
    }

    void onConfigUpdate() {
        stop();
        loadConfig();
        io_.run();
    }

private:
    virtual unique_ptr<Cipher> createCipher(const string& algorithm, const map<string, string>& config) = 0;
};

