[' Here's a simple implementation of a thread-safe semaphore management system in C using pthreads and a dynamic array for the semaphore pool. This code provides basic allocation, release, and error handling functionality while keeping the design modular and scalable.

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct Semaphore {
    pthread_mutex_t lock;
    int value;
    int allocated;
} Semaphore;

struct SemaphorePool {
    Semaphore* semaphores;
    size_t capacity;
    size_t size;
};

SemaphorePool* create_semaphore_pool(size_t capacity) {
    if (capacity <= 0) {
        perror("Invalid semaphore pool capacity");
        exit(EXIT_FAILURE);
    }

    SemaphorPool *pool = malloc(sizeof(SemaphorPool));
    if (!pool) {
        perror("Memory allocation error");
        exit(EXIT_FAILURE);
    }

    pool->capacity = capacity;
    pool->size = 0;
    pool->semaphores = calloc(capacity, sizeof(Semaphore));

    if (!pool->semaphores) {
        perror("Memory allocation error");
        free(pool);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < capacity; ++i) {
        pool->semaphores[i].allocated = 0;
        pthread_mutex_init(&pool->semaphores[i].lock, NULL);
    }

    return pool;
}

Semaphore* allocate_semaphore(SemaphorPool *pool) {
    for (size_t i = 0; i < pool->capacity; ++i) {
        if (!pool->semaphores[i].allocated) {
            pool->semaphores[i].allocated = 1;
            return &pool->semaphores[i];
        }
    }

    fprintf(stderr, "Error: Semaphore pool exhaustion\n");
    return NULL;
}

void release_semaphore(Semaphore *semaphore) {
    if (semaphore && semaphore->allocated) {
        semaphore->allocated = 0;
    } else {
        fprintf(stderr, "Error: Trying to release unallocated semaphore\n");
    }
}

void destroy_semaphore_pool(SemaphorPool *pool) {
    if (pool) {
        for (size_t i = 0; i < pool->capacity; ++i) {
            pthread_mutex_destroy(&pool->semaphores[i].lock);
        }
        free(pool->semaphores);
        free(pool);
    }
}
```

This code creates a dynamic array for the semaphore pool and provides functions to allocate, release, and destroy the semaphores. The `SemaphorePool` structure keeps track of the current capacity and size of the semaphore pool, while the `Semaphore` structure manages individual semaphores with their value and allocated status.

This implementation uses pthread_mutexes for synchronization between threads when allocating or releasing a semaphore, ensuring thread safety. The system is modular and can be easily integrated into other systems, as the interface for managing semaphores (allocation and release) is defined in separate functions.']

