using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

public class GameEngine
{
    private readonly IConfiguration _configuration;
    private readonly IMemoryCache _cache;
    private readonly ConcurrentDictionary<string, object> _configSources = new ConcurrentDictionary<string, object>();

    public GameEngine()
    {
        var configurationBuilder = new ConfigurationBuilder()
            .SetBasePath(Directory.GetCurrentDirectory())
            .AddXmlFile("appSettings.xml")
            .AddEnvironmentVariables();

        _configuration = configurationBuilder.Build();

        RegisterServices();
    }

    private void RegisterServices()
    {
        var services = new ServiceCollection();
        services.AddMemoryCache();
        Services.BuildServiceProvider();

        _cache = services.GetRequiredService<IMemoryCache>();
    }

    public T GetConfigValue<T>(string key)
    {
        if (_configSources.TryGetValue(key, out var source))
        {
            return (T)source;
        }

        var cached = _cache.GetOrCreate(key, entry =>
        {
            entry.AbsoluteExpiration = DateTimeOffset.MaxValue;

            var configValues = GetAllConfigValues()
                .Where(config => config.Key == key)
                .ToList();

            if (configValues.Any())
            {
                return configValues[0].Value;
            }

            throw new KeyNotFoundException($"The configuration '{key}' was not found.");
        });

        _configSources[key] = cached;
        return (T)cached;
    }

    public void UpdateConfig(Func<IConfiguration, IConfiguration> updateFunction)
    {
        var updatedConfiguration = updateFunction(_configuration);
        _cache.Clear(); // Clear cache on configuration update

        Parallel.ForEach(updatedConfiguration.AsEnumerable(), config =>
        {
            _configSources[config.Key] = config.Value;
            _cache.Set(config.Key, config.Value, new MemoryCacheEntryOptions()
                .SetSlidingExpiration(TimeSpan.FromMinutes(5)));
        });
    }

    private IEnumerable<KeyValuePair<string, string>> GetAllConfigValues()
    {
