                }
                else
                {
                    try
                    {
                        Directory.CreateDirectory(directoryPath);
                        Environment.SetEnvironmentVariable("Path", directoryPath);
                    }
                    catch (Exception ex)
                    {
                        Debug.WriteLine($"Error: Failed to create directory '{directoryName}'. Reason: {ex.Message}");
                    }
                }
            }
            else
            {
                var temporaryDirectory = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
                Directory.CreateDirectory(temporaryDirectory);
                Environment.SetEnvironmentVariable("Path", temporaryDirectory);

                try
                {
                    Directory.Move(temporaryDirectory, Path.Combine(Path.GetTempPath(), directoryName));
                }
                catch (Exception ex)
                {
                    Debug.WriteLine($"Error: Failed to move temporary directory '{temporaryDirectory}' to '{directoryName}'. Reason: {ex.Message}");
                }
            }
        }

        private static XmlElement GetFirstMatchingElement(XmlDocument document, string elementName)
        {
            var nodes = document.SelectNodes($"//{elementName}");
            if (nodes is null || nodes.Count == 0)
            {
                Debug.WriteLine($"Information: No elements matching '{elementName}' were found.");
                return null;
            }

            var firstElement = (XmlElement)nodes[0];
            if (nodes.Count > 1)
            {
