  public class ExceptionMiddleware
  {
      private readonly RequestDelegate _next;
      private readonly IMemoryCache _memoryCache;
      private readonly IDistributedCache _redisCache;

      public ExceptionMiddleware(RequestDelegate next, IMemoryCache memoryCache, IDistributedCache redisCache)
      {
          _next = next;
          _memoryCache = memoryCache;
          _redisCache = redisCache;
      }

      public async Task InvokeAsync(HttpContext context)
      {
          try
          {
              await _next(context);
          }
          catch (Exception ex)
          {
              // Log exception to memory cache and Redis cache
              _memoryCache.Set("exception", ex.Message);
              _redisCache.HashSetAsync("exceptions", context.Request.Path, ex.Message);
              throw;
          }
      }
  }
  ```

