                result.forEach((subResult) => updateField(fieldName, subResult));
            } else {
                updateField(fieldName, result);
            }
        });

        results.forEach((result, index) => {
            if (result === null || typeof result !== 'object') {
                sendMessageToParent(fieldNamesArray[index], result);
            }
        });
    });
}
```

