#include <list>
#include <stdexcept>
#include <string>
#include <algorithm>
#include <iterator>

template<typename ForwardListType>
void insertAfterFirstOccurrence(ForwardListType& list, const std::string& searchStr, const std::string& newStr) {
    auto it = list.begin();

    if (it == list.end() || *it != searchStr) {
        list.push_back(newStr);
        return;
    }

    it = std::next(list.begin(), 1);
    list.insert(it, newStr);
}
