const { Queue } = require('bull');
const axios = require('axios');
const dotenv = require('dotenv');

// Load environment variables
dotenv.config();

class DataProcessor {
  constructor(serviceConfigs) {
    this.queues = serviceConfigs.map(({ name, url }) =>
      new Queue(name, { connection: redis })
        .process((job) => {
          return axios.post(url, job.data)
            .catch((error) => {
              if (error.isAxiosError && error.config.retry <= 0) {
                console.error(`Failed to process data: ${JSON.stringify(job.data)}`, error);
              } else {
                job.reject('Retrying in a few moments');
                return job.attempts += 1, job.delay(5000).save();
              }
            })
            .then((response) => {
              console.log(`Successfully processed data: ${JSON.stringify(job.data)}`);
              return response.data;
            });
        })
        .on('failed', (job, err) => {
          if (err.isAxiosError && err.config.retry > 0) {
            console.log(`Job failed, retrying: ${job.id}`);
          } else {
            console.error(`Failed to process data: ${JSON.stringify(job.data)}`, err);
          }
        })
    );
  }

  start() {
    this.queues.forEach((queue) => queue.process(this._processOptions));
  }

  stop() {
    this.queues.forEach((queue) => queue.pause());
  }

  pause() {
    // Implement dynamic adjustment of the frequency based on current system load and resource availability
  }

  resume() {
    this.start();
  }
}

// Example usage:
