#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>
#include <pthread.h>
#include <stdlib.h>
#include <unistd.h>

typedef struct {
  char *filename;
  int counter;
} unique_filename;

void generateUniqueFilename(char *originalFileName, unique_filename *uniqueData) {
  struct stat sb;
  stat(originalFileName, &sb);
  uniqueData->counter = 0;
  char uniqueFilePath[256];
  snprintf(uniqueFilePath, sizeof(uniqueFilePath), "%s_%lu_%d", originalFileName, (long unsigned int) time(NULL), uniqueData->counter++);

  while (access(uniqueFilePath, F_OK)) {
    snprintf(uniqueFilePath, sizeof(uniqueFilePath), "%s_%lu_%d", originalFileName, (long unsigned int) time(NULL), uniqueData->counter++);
  }

  strcpy(uniqueData->filename, uniqueFilePath);
}
