['```java
import java.time.Instant;
import java.util.ConcurrentMap;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.concurrent.ConcurrentLinkedDeque;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.util.stream.Collectors;

public class TransactionSessionProcessor {
    private static final long SESSION_DURATION_THRESHOLD = TimeUnit.MINUTES.toMillis(10);
    private final ConcurrentMap<String, Session> sessions = new LinkedHashMap<>();
    private final Deque<Transaction> transactions = new ConcurrentLinkedDeque<>();
    private final AtomicLong startTime = new AtomicLong();
    private final AtomicInteger numSessions = new AtomicInteger();
    private final AtomicLong totalSessionDuration = new AtomicLong();

    public void processTransaction(String userId, Instant transactionTimestamp) {
        long currentTime = startTime.getAndUpdate(time -> time + System.nanoTime());
        transactions.add(new Transaction(userId, transactionTimestamp));
        Transaction lastTransaction = transactions.peekLast();
        if (lastTransaction != null && TimeUnit.NANOSECONDS.toMillis(currentTime - lastTransaction.getTimestamp().toEpochMilli()) <= SESSION_DURATION_THRESHOLD) {
            Session session = sessions.get(userId);
            if (session == null) {
                session = new Session(userId, currentTime);
                sessions.putIfAbsent(userId, session);
            }
            session.addTransaction(lastTransaction);
        } else {
            Session completedSession = sessions.remove(userId);
            if (completedSession != null) {
                numSessions.incrementAndGet();
                totalSessionDuration.addAndGet(System.currentTimeMillis() - completedSession.getEndTime());
            }
        }
    }

    public SessionStatistics getStatistics() {
        return new SessionStatistics(numSessions.get(), totalSessionDuration.get() / numSessions.get());
    }

    static class Transaction {
        private final String userId;
        private final Instant timestamp;

        Transaction(String userId, Instant timestamp) {
            this.userId = userId;
            this.timestamp = timestamp;
        }

        Instant getTimestamp() {
            return timestamp;
        }
    }

    static class Session {
        private final String userId;
        private final long startTime;
        private Deque<Transaction> transactions = new ConcurrentLinkedDeque<>();

        Session(String userId, long startTime) {
            this.userId = userId;
            this.startTime = startTime;
        }

        void addTransaction(Transaction transaction) {
            transactions.add(transaction);
        }

        long getEndTime() {
            return System.currentTimeMillis();
        }
    }

    static class SessionStatistics {
        private final int numberOfSessions;
        private final double averageSessionDuration;

        SessionStatistics(int numberOfSessions, double averageSessionDuration) {
            this.numberOfSessions = numberOfSessions;
            this.averageSessionDuration = averageSessionDuration;
        }

        int getNumberOfSessions() {
            return numberOfSessions;
        }

        double getAverageSessionDuration() {
            return averageSessionDuration;
        }
    }
}
```']

