@Component
public class ServiceStopper {

    private final RabbitTemplate rabbitTemplate;

    @Autowired
    public ServiceStopper(RabbitTemplate rabbitTemplate) {
        this.rabbitTemplate = rabbitTemplate;
    }

    public void sendStopMessage() {
        rabbitTemplate.convertAndSend(QUEUE_STOP, new StopMessage());
    }
}
```

6. Implement the health check and monitoring system:

```java
import org.springframework.stereotype.Component;
import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.binder.MeterBinder;
import java.time.Duration;
import java.time.Instant;

@Component
public class HealthCheck implements MeterBinder {

    private final MeterRegistry registry;
    private String status = "UP";
    private long lastUpdated = Instant.now().toEpochMilli();

    public HealthCheck(MeterRegistry registry) {
        this.registry = registry;
    }

    @Override
    public void bindTo(MeterRegistry registry, String name) {
        registry.gauge("health", this::getStatus);
        registry.histogram("health_updates").tag("service", getClass().getName()).record(Duration.ofMillis(System.currentTimeMillis() - lastUpdated));
    }

    public String getStatus() {
        final long now = Instant.now().toEpochMilli();
        if ((now - lastUpdated) >= 600000) {
            status = "UP";
            lastUpdated = now;
        }
        return status;
    }
}
```']

