const axios = require('axios');
const fs = require('fs');
const readline = require('readline');
const https = require('https');
const path = require('path');

// Load private key and certificate paths from environment variables or a configuration file.
const PRIVATE_KEY_PATH = process.env.PRIVATE_KEY_PATH || require('./config').privateKeyPath;
const CERTIFICATE_PATH = process.env.CERTIFICATE_PATH || require('./config').certificatePath;

// Function to generate a combined PEM certificate file
async function generatePEMCertificate() {
  let privateKey, certificate;

  try {
    // Read the private key file
    const privateKeyStream = fs.createReadStream(PRIVATE_KEY_PATH);
    privateKey = await new Promise((resolve) => {
      const chunks = [];
      readline.createInterface({ input: privateKeyStream }).on('line', (chunk) => chunks.push(chunk));
      privateKeyStream.on('end', () => resolve(chunks.join('\n')));
    });
  } catch (error) {
    console.error(`Error reading private key file: ${error}`);
    return;
  }

  try {
    // Read the certificate file
    const certificateStream = fs.createReadStream(CERTIFICATE_PATH);
    certificate = await new Promise((resolve) => {
      const chunks = [];
      readline.createInterface({ input: certificateStream }).on('line', (chunk) => chunks.push(chunk));
      certificateStream.on('end', () => resolve(chunks.join('\n')));
    });
  } catch (error) {
    console.error(`Error reading certificate file: ${error}`);
    return;
  }

  // Function to handle HTTP stream processing
  async function processStream(url) {
    let responseData = '';
    let response;

    try {
      response = await axios.get(url, { responseType: 'stream' });
    } catch (error) {
      if (response && response.config.url) {
        console.log(`Error fetching ${response.config.url}: ${error}`);
      } else {
        console.error('Failed to make HTTP request, ensure the URL is correct.');
      }
      return;
    }

    responseData += await new Promise((resolve) => {
      let bufferedChunk = '';
      response.data.on('data', (chunk) => {
        bufferedChunk += chunk;
        while (bufferedChunk.length > 1024) {
          const dataToEmit = bufferedChunk.slice(0, 1024);
          responseData += dataToEmit;
          bufferedChunk = bufferedChunk.slice(1024);
        }
      });
      response.data.on('end', () => resolve(responseData));
    });

    return responseData;
  }

  const certificates = ['certificate-server1.pem', 'certificate-server2.pem']; // Add more certificate URLs as needed

  let combinedCertificate = `${privateKey}\n${certificate}`;

  for (const url of certificates) {
    combinedCertificate += await processStream(url);
  }

  fs.writeFileSync('combined-certificate.pem', combinedCertificate);
}

// Call the function to generate the combined certificate file
generatePEMCertificate();
```"]

