class UserDAO {
    private $db;
    private $mfaService;
    private $logger;
    private $cache;

    public function __construct(PDO $db, MFAService $mfaService, Logger $logger, Cache $cache) {
        $this->db = $db;
        $this->mfaService = $mfaService;
        $this->logger = $logger;
        $this->cache = $cache;
    }

    public function updatePassword(int $userId, string $newPassword) {
        if (!$this->isValidPassword($newPassword)) {
            throw new Exception('Invalid password');
        }

        try {
            // Retrieve user data from cache or database if not available in cache
            $userData = $this->cache->get('user_' . $userId) ?: $this->db->query("SELECT * FROM users WHERE id = ?", [$userId])->fetch(PDO::FETCH_ASSOC);

            // Verify MFA token with external service (assuming an API response is expected)
            if (!$this->mfaService->verifyToken($userData['mfa_token'])) {
                throw new Exception('Invalid MFA token');
            }
        } catch (\Exception $e) {
            $this->logger->logError("Failed to update password for user $userId: {$e->getMessage()}");
            return false;
        }

        // Hash the new password using a secure hashing algorithm (argon2, scrypt, bcrypt...)
        $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT);

        try {
            // Update user's password in database using prepared statements and connection pooling to minimize resource usage
            $this->db->beginTransaction();
            $stmt = $this->db->prepare("UPDATE users SET password = ? WHERE id = ?");
            $stmt->execute([$hashedPassword, $userId]);
            $this->logger->logInfo("Updated password for user $userId");
            $this->db->commit();
        } catch (\Exception $e) {
            $this->logger->logError("Failed to update password for user $userId: {$e->getMessage()}");
            $this->db->rollback();
            return false;
        }

        // Store the new hashed password in cache for faster retrieval on subsequent requests
        $this->cache->set('user_' . $userId, ['id' => $userId, 'password' => $hashedPassword]);

        return true;
    }

    private function isValidPassword(string $password): bool {
        // Implement password strength validation logic here (minimum length, special characters, uppercase and lowercase letters, numbers...)
        // Return false if the password does not meet the specified requirements, otherwise return true
    }
}
