```javascript
function traverseDOMTree(node, testElement, results = []) {
    if (!node || !testElement) return results;

    let nodeType = node.nodeType;
    if (nodeType !== Node.ELEMENT_NODE && nodeType !== Node.DOCUMENT_NODE) return results;

    const matches = testElement(node.tagName, node);
    if (matches) results.push(node);

    for (let i = 0; i < node.children.length; i++) {
        results = traverseDOMTree(node.children[i], testElement, results);
    }

    return results;
}
