['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct LogEntry {
    time_t timestamp;
    char event[256];
    double* metrics;
    size_t num_metrics;
    struct LogEntry *next;
} LogEntry;

struct Cache {
    size_t capacity;
    LogEntry **entries;
    size_t head, tail;
    pthread_mutex_t lock;
};

void cache_init(struct Cache* cache, size_t capacity) {
    cache->capacity = capacity;
    cache->entries = malloc(sizeof(LogEntry*) * capacity);
    memset(cache->entries, 0, sizeof(LogEntry*) * capacity);
    cache->head = cache->tail = 0;
    pthread_mutex_init(&cache->lock, NULL);
}

void cache_push(struct Cache* cache, LogEntry* entry) {
    pthread_mutex_lock(&cache->lock);
    while (cache->head == (cache->tail + 1) % cache->capacity) {
        // cache is full, remove the oldest entry
        size_t to_remove = cache->head;
        to_remove = (to_remove + 1) % cache->capacity;
        pthread_mutex_unlock(&cache->lock);
        usleep(10000); // yield CPU to prevent busy-waiting
        pthread_mutex_lock(&cache->lock);
    }

    cache->entries[cache->tail] = entry;
    cache->tail = (cache->tail + 1) % cache->capacity;
    pthread_mutex_unlock(&cache->lock);
}

LogEntry* cache_pop(struct Cache* cache) {
    LogEntry *entry;
    pthread_mutex_lock(&cache->lock);
    if (cache->head != cache->tail) {
        entry = cache->entries[cache->head];
        cache->head = (cache->head + 1) % cache->capacity;
    } else {
        entry = NULL;
    }
    pthread_mutex_unlock(&cache->lock);
    return entry;
}

void process_log_entry(LogEntry* entry, struct Cache* cache) {
    double avg = 0.0;
    for (size_t i = 0; i < entry->num_metrics && i < 3; ++i) {
        avg += entry->metrics[i];
    }

    if (entry->num_metrics > 2) {
        avg /= 3.0;
        cache_push(cache, entry);
    }

    printf("%s %s %.2f\n", ctime(&entry->timestamp), entry->event, avg);
}

void* read_log_file(const char *filename, struct Cache* cache) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL;

    LogEntry *current_entry = NULL, *next_entry = NULL;
    char line[4096];
    size_t num_metrics = 0;

    while (fgets(line, sizeof(line), file)) {
        sscanf(line, "%*Ts %[^,],", current_entry->event, NULL);
        sscanf(line + strlen(current_entry->event), "%n", &num_metrics);

        if (!next_entry) {
            next_entry = malloc(sizeof(LogEntry));
            next_entry->timestamp = time(NULL);
            next_entry->num_metrics = num_metrics;
            next_entry->metrics = calloc(num_metrics, sizeof(double));
        }

        if (sscanf(line + strlen(current_entry->event) + 1, "%lf", &next_entry->metrics[next_entry->num_metrics - 1]) != 1) {
            free(next_entry);
            next_entry = NULL;
        }

        current_entry = next_entry;
        next_entry = NULL;
    }

    if (current_entry) process_log_entry(current_entry, cache);
    fclose(file);
    free(current_entry->metrics);
    free(current_entry);

    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s log_file\n", argv[0]);
        return 1;
    }

    const char *filename = argv[1];
    struct Cache cache;
    cache_init(&cache, 100);

    pthread_t threads[4]; // adjust thread count based on system resources and desired throughput

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        if (pthread_create(&threads[i], NULL, read_log_file, filename, &cache)) {
            fprintf(stderr, "Failed to create thread\n");
            return 1;
        }
    }

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        pthread_join(threads[i], NULL);
    }

    // cache clearing logic based on your system's memory and disk constraints

    return 0;
}
```

