[' Due to the complexity and specific requirements of the task, I'll provide you with a C++17 code structure for this multi-function task. However, please note that implementing this function requires understanding of various TIFF image parsing libraries (e.g., libtiff), MD5 hash computation using standard library functions, asynchronous network requests, and external validation service integration.

```cpp
#include <iostream>
#include <memory>
#include <string>
#include <cstdio>
#include <libtiff/tiffio.h>
#include <openssl/md5.h>
#include <boost/asio/io_service.hpp>
#include <boost/asio/connect.hpp>
#include <boost/asio/streambuf.hpp>

struct TiffInfo {
    uint16_t bitsPerSample;
    uint16_t samplePerPixel;
    uint16_t extraSamples;
    std::string md5Hash;
};

TiffInfo parseTIFF(const std::string& filePath) {
    TIFF* tif = nullptr;
    uint16_t imageSampleSize;
    uint32_t rowSize;
    tif = TIFFOpen(filePath.c_str(), "r");

    if (!tif) {
        std::cerr << "Unsupported TIFF format or file not found." << std::endl;
        return {};
    }

    imageSampleSize = TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL);
    if (imageSampleSize < 1 || imageSampleSize > 4) {
        std::cerr << "Unsupported number of samples per pixel." << std::endl;
        TIFClose(tif);
        return {};
    }

    rowSize = TIFFScanlineSize(tif);
    if (rowSize % imageSampleSize != 0) {
        std::cerr << "Invalid row size for the specified samples per pixel." << std::endl;
        TIFClose(tif);
        return {};
    }

    TIFFGetField(tif, TIFFTAG_BITSperpixel, &imageSampleSize);
    if (imageSampleSize != 1 && imageSampleSize != 2 && imageSampleSize != 4 && imageSampleSize != 8 && imageSampleSize != 16) {
        std::cerr << "Unsupported bit depth." << std::endl;
        TIFClose(tif);
        return {};
    }

    uint16_t extraSamples = TIFFGetField(tif, TIFFTAG_EXTRASAMPLES);

    unsigned char* dataBuffer = new unsigned char[rowSize];

    TIFFError error = TIFFReadScanline(tif, dataBuffer, 0);
    if (error != ERRE_OK) {
        std::cerr << "Failed to read scanline." << std::endl;
        delete[] dataBuffer;
        TIFClose(tif);
        return {};
    }

    unsigned char* md5Input = new unsigned char[TIFFGetField(tif, TIFFTAG_IMAGEWIDTH) * TIFFGetField(tif, TIFFTAG_IMAGELENGTH)];
    memcpy(md5Input, dataBuffer, rowSize);
    for (int i = 1; i < TIFFGetField(tif, TIFFTAG_IMAGECOUNT); ++i) {
        error = TIFFReadScanline(tif, dataBuffer + rowSize * i, i);
        if (error != ERRE_OK) {
            std::cerr << "Failed to read scanline." << std::endl;
            delete[] md5Input;
            delete[] dataBuffer;
            TIFClose(tif);
            return {};
        }
        memcpy(md5Input + rowSize * i, dataBuffer + rowSize * i, rowSize);
    }

    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, md5Input, TIFFGetField(tif, TIFFTAG_IMAGEWIDTH) * TIFFGetField(tif, TIFFTAG_IMAGELENGTH));
    MD5_Final(digest, &ctx);

    std::string md5Hash = b64encode(reinterpret_cast<const char*>(digest), MD5_DIGEST_LENGTH);

    delete[] md5Input;
    delete[] dataBuffer;
    TIFClose(tif);

    TiffInfo info { imageSampleSize, samplePerPixel, extraSamples, std::move(md5Hash) };
    return info;
}
```

To enhance robustness and avoid memory exhaustion with large files, you can implement the `b64encode` function using iterators and a variable-sized buffer instead of allocating a fixed-size buffer. Additionally, for external validation service integration, you'd have to define functions for creating the necessary network requests and handling responses accordingly, ensuring efficient data transfer and minimizing latency.']

