#include <pthread.h>

// Custom file type extension (Update from API or configuration)
char custom_ext[10] = ".custom";

// Maximum length of the new filename
#define MAX_LEN 255

void generate_unique_id(char* id, size_t len) {
    char chars[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    for (size_t i = 0; i < len; ++i) {
        id[i] = chars[rand() % strlen(chars)];
    }
    id[len] = '\0';
}

int is_valid_filename(const char* filename) {
    // Custom validation rules based on project requirements
    int len = strlen(filename);
    if (len > MAX_LEN || len < 3) return 0;

    const char valid_chars[] = "- _ .ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    for (size_t i = 0, j = 0; i < len; ++i) {
        if (filename[i] == '.' && (i + 1) >= len) return 0; // Disallow trailing dots
        if (strchr(valid_chars, filename[i]) == NULL) return 0;
        if (filename[i] == '.') ++j;
    }
    if (j > 1) return 0; // Disallow multiple extensions
    return 1;
}

char* generate_new_filename(const char* input_filename, const char* custom_ext) {
    size_t input_len = strlen(input_filename);
    if (!is_valid_filename(input_filename)) return NULL; // Return early on invalid filenames

    size_t new_filename_len = input_len + strlen(custom_ext) + 20; // Allocate extra space for timestamp and random ID
    if (new_filename_len > MAX_LEN) new_filename_len = MAX_LEN - input_len;

    char* new_filename = malloc(new_filename_len);
    if (!new_filename) return NULL; // Return early on failure to allocate memory

    struct tm tm;
    time_t now = time(NULL);
    localtime_r(&now, &tm);

    strftime(new_filename, new_filename_len, "%Y%m%d_%H%M%S", &tm); // Timestamp
    generate_unique_id(new_filename + strlen(new_filename), new_filename_len - strlen(new_filename) - strlen(custom_ext)); // Random ID
    strcat(new_filename, custom_ext); // Custom extension

    if (strlen(new_filename) > MAX_LEN) {
        free(new_filename);
        return NULL; // Return early on overflow
    }

    // Implement thread-safety with a recursive mutex
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, &attr);
    {
        // Critical section where the new filename is constructed and checked for uniqueness
        pthread_mutex_lock(&lock);

        while (access(new_filename, F_OK) != -1) {
            generate_unique_id(new_filename + strlen(new_filename), new_filename_len - strlen(new_filename) - strlen(custom_ext));
        }

        pthread_mutex_unlock(&lock);
    }
    pthread_mutexattr_destroy(&attr);
    pthread_mutex_destroy(&lock);

    return new_filename;
}
