static int backoff_exponential(long double *multiplier, unsigned long long delay_us, unsigned long long max_delay_us) {
    if (*multiplier >= 2.0) {
        *multiplier /= 2.0;
    } else {
        *multiplier = 1.0;
    }

    if ((*multiplier * delay_us) > max_delay_us) {
        *multiplier *= (max_delay_us / delay_us);
    }

    return (*multiplier * delay_us);
}

