    if (res != CURLE_OK) {
        fprintf(stderr, "Error setting write data: %s\n", curl_easy_strerror(res));
        return 0;
    }

    struct timeval timeout = {60, 0};
    res = curl_easy_setopt(tc->handle, CURLOPT_TIMEOUT_MS, timeout.tv_sec * 1000 + timeout.tv_usec / 1000);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error setting timeout: %s\n", curl_easy_strerror(res));
        return 0;
    }

    res = curl_easy_perform(tc->handle);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error performing request: %s\n", curl_easy_strerror(res));
        return 0;
    }

    long double backoff = 1.0;
    int attempts = 0;

    while (attempts < 5) {
        if (!tc->theme_bitmap) {
            break;
        }

        res = curl_easy_getinfo(tc->handle, CURLINFO_HTTP_CODE);
        if (res == CURLE_OK) {
