            curl_easy_getinfo(tc->handle, CURLINFO_RESPONSE_CODE, &http_code);

            if (http_code < 400) {
                break;
            }
        }

        sleep((size_t)backoff_exponential(&backoff, 1000000, 6000000));
        free(tc->theme_bitmap);
        tc->theme_bitmap = NULL;
        attempts++;
    }

    return 1;
}

