#include <sys/resource.h>

pid_t execute_command(const char *command, const char *timeout_str) {
    pid_t child_pid = fork();

    if (child_pid == -1) {
        perror("fork");
        return -1;
    }

    // Child process
    if (child_pid > 0) {
        struct rlimit rlim;
        getrlimit(RLIMIT_NOFILE, &rlim);
        setrlimit(RLIMIT_NOFILE, &rlim);

        sigset_t signal_mask;
        sigfillset(&signal_mask);

        int pipefd[2];
        pipe(pipefd);

        if (dup2(pipefd[1], STDOUT_FILENO) == -1 || dup2(pipefd[1], STDERR_FILENO) == -1) {
            perror("dup2");
            _exit(EXIT_FAILURE);
        }

        close(pipefd[1]);

        char* arg[] = {"/bin/sh", "-c", command, NULL};
        execvp("/bin/sh", arg);
        perror("execvp");
        _exit(EXIT_FAILURE);
    }

    // Parent process
    struct timespec timeout;
    clock_gettime(CLOCK_MONOTONIC, &timeout);
    timeout.tv_sec += strtol(timeout_str, NULL, 10);

    sigemptyset(&signal_mask);
    sigaddset(&signal_mask, SIGTERM);
    sigaddset(&signal_mask, SIGKILL);
    pthread_t monitor_thread;

    if (pthread_create(&monitor_thread, NULL, monitor, &child_pid) != 0) {
        perror("pthread_create");
        return -1;
    }

    // Wait for the child to complete or timeout
    struct timespec now;
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        if ((now.tv_sec > timeout.tv_sec || (now.tv_sec == timeout.tv_sec && now.tv_nsec >= timeout.tv_nsec)) || kill(child_pid, 0) == -1) {
            break;
        }
    }

    if (kill(child_pid, SIGTERM) != 0) {
        perror("SIGTERM");
        return 0;
    }

    usleep(2 * NANOSECONDS_PER_SECOND); // Delay for 2 seconds after sending SIGTERM

    if (kill(child_pid, SIGKILL) != 0) {
        perror("SIGKILL");
        return 0;
    }

    int status;
    waitpid(child_pid, &status, WNOHANG); // Check for any exit code from the child process

    if (WIFEXITED(status)) {
        return WEXITSTATUS(status) == 0 ? 1 : -1;
    } else if (WIFSIGNALED(status)) {
        return 0;
    } else {
        return -1;
    }
}

void* monitor(void *arg) {
    pid_t child_pid = *(pid_t *)arg;
    sigset_t signal_mask;
    pthread_mutex_t lock;

    // Set up signal handlers, resource management and monitoring code here...

    // Monitor the child process's status and output while it runs
    while (1) {
        // Implement logic to detect if the child process is unresponsive or consumes excessive resources here...

        // If the child process is responsive, reset the alarm for further monitoring
        alarm(30); // Reset the alarm to check the child process every 30 seconds
        pthread_mutex_lock(&lock);
        // Sleep for a short period before checking again
        usleep(50 * NANOSECONDS_PER_MILLISECOND);
        pthread_mutex_unlock(&lock);
    }

    return NULL;
}
