            LoggingUtil.LogProcessingDetails(Logger, config.Title, decryptedMessage, result);
            return 0; // Success
        }
        catch (Exception ex)
        {
            Logger.Error($"An error occurred while processing message: {ex}");
            return 4; // Callback function threw an exception
        }
    }

    private static byte[] DecryptBase64EncodedData(string base64Data, Configuration config)
    {
        try
        {
            var data = Convert.FromBase64String(base64Data);
            using (var tripleDES = TripleDESCryptoServiceProvider.Create())
            {
                tripleDES.Key = Encoding.UTF8.GetBytes(config.Password);
                tripleDES.IV = new byte[tripleDES.IV.Length]; // Use a random IV for each encryption/decryption
                var md5 = MD5.Create();
                arrayCopy(md5.ComputeHash(Encoding.UTF8.GetBytes(config.Password)), tripleDES.IV, tripleDES.IV.Length);
                using (var decryptor = new TripleDESCryptoServiceProvider() { Key = tripleDES.Key, IV = tripleDES.IV })
                {
                    return decryptor.CreateDecryptor().TransformFinalBlock(data, 0, data.Length);
                }
            }
        }
        catch (Exception ex)
        {
            Logger.Error($"An error occurred during decryption: {ex}");
            throw;
        }
    }

    private static void arrayCopy(byte[] src, byte[] dest, int length)
    {
        Buffer.BlockCopy(src, 0, dest, 0, length);
    }

    // Implement UpdateConnectionSettingsAsync method here to handle periodic updates of connection settings as needed
}
