bool parse_network_config(const char *filename) {
    Json::CharReaderBuilder builder;
    Json::CharReader *reader = builder.newCharReader();
    Json::Value root;
    std::ifstream inputFile(filename);
    if (!inputFile.is_open()) {
        std::cerr << "Failed to open configuration file: " << filename << std::endl;
        return false;
    }

    bool parsed = reader->parse(inputFile, root, false);
    delete reader;
    inputFile.close();
    if (!parsed) {
        std::cerr << "Failed to parse configuration file: " << filename << std::endl;
        return false;
    }

    if (!root["server_address"].isString() || !root["port"].isInt() ||
        !root["protocol"].isString() || !root["timeout"].isNumber()) {
        std::cerr << "Invalid configuration format" << std::endl;
        return false;
    }

    const char *protocol_str = root["protocol"].asCString();
    if (strcmp(protocol_str, "http") != 0 && strcmp(protocol_str, "https") != 0) {
        std::cerr << "Invalid protocol value: " << protocol_str << std::endl;
        return false;
    }

    int port = root["port"].asInt();
    if (port <= 0 || port > 65535) {
        std::cerr << "Invalid port value: " << port << std::endl;
        return false;
    }

    double timeout = root["timeout"].asDouble();
    if (timeout <= 0) {
        std::cerr << "Invalid timeout value: " << timeout << std::endl;
        return false;
    }

    const char *ssl_certificate_path = root["ssl_certificate_path"].isNull() ? nullptr : root["ssl_certificate_path"].asCString();
    struct stat sbuf;
    if (ssl_certificate_path && stat(ssl_certificate_path, &sbuf) != 0 || !(S_ISREG(sbuf.st_mode)) || !S_IRUSR(&sbuf.st_mode)) {
