using System;
using System.Collections.Generic;
using System.Text;
using System.Linq;
using System.Security.Cryptography;
using System.IO;
using System.Net;

public class MessageProcessor
{
    private readonly string _delimiter = "#";
    private readonly TripleDES _encryptor;

    public MessageProcessor(string key, string iv)
    {
        _encryptor = TripleDES.Create();
        _encryptor.Key = Encoding.ASCII.GetBytes(key);
        _encryptor.IV = Encoding.ASCII.GetBytes(iv);
    }

    public IDictionary<int, string> DecryptMessages(string base64EncodedString)
    {
        var messages = new Dictionary<int, string>();
        try
        {
            var bytes = Convert.FromBase64String(base64EncodedString);

            using (var memoryStream = new MemoryStream(bytes))
            using (var reader = new StreamReader(memoryStream))
            {
                string line;
                int currentId = -1;
                while ((line = reader.ReadLine()) != null)
                {
                    if (int.TryParse(line.Split(_delimiter)[0], out var id))
                    {
                        currentId = id;
                        continue;
                    }

                    if (currentId >= 0 && line.Length > 0)
                    {
                        messages[currentId] = Decrypt(line);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred while processing messages: {ex}");
        }

        return messages;
    }

    private string Decrypt(string encryptedMessage)
    {
        var decryptedBytes = _encryptor.CreateDecryptor().TransformFinalBlock(Convert.FromBase64String(encryptedMessage), 0, encryptedMessage.Length);
        return Encoding.ASCII.GetString(decryptedBytes);
    }
}
