using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace TextProcessingTool
{
    public class LineIdentifier
    {
        private readonly HashAlgorithm _hashAlgorithm;
        private readonly ILogger _logger;
        private readonly Dictionary<string, string> _cache;
        private readonly TimeSpan _cacheDuration;

        public LineIdentifier(HashAlgorithm hashAlgorithm, ILogger logger, TimeSpan cacheDuration = default)
        {
            _hashAlgorithm = hashAlgorithm;
            _logger = logger;
            _cache = new Dictionary<string, string>();
            _cacheDuration = cacheDuration;
        }

        public async Task<(string identifier, bool isCached)> ProcessLineAsync(TextReader reader)
        {
            byte[] lineBytes;
            using (var sr = new StreamReader(reader))
            {
                lineBytes = Encoding.UTF8.GetBytes(await sr.ReadToEndAsync());
            }

            var lineContent = Encoding.UTF8.GetString(lineBytes);
            string cachedIdentifier;

            if (_cache.TryGetValue(lineContent, out cachedIdentifier))
            {
                _logger.Log($"Line '{lineContent}' was found in cache.");
                return (cachedIdentifier, true);
            }

            var combinedData = Encoding.UTF8.GetBytes($"{lineContent}{DateTimeOffset.UtcNow:yyyyMMddHHmmssfff}");
            var hashedData = _hashAlgorithm.ComputeHash(combinedData);

            var identifier = BitConverter.ToString(hashedData).Replace("-", "");
            _cache[lineContent] = identifier;

            if (_cacheDuration > TimeSpan.Zero)
            {
                await Task.Delay(_cacheDuration);
                _cache.RemoveWhere(kv => kv.Key + kv.Value < DateTimeOffset.UtcNow.ToString("yyyyMMddHHmmssfff"));
            }

            _logger.Log($"Line '{lineContent}' was processed and given identifier '{identifier}'.", LogLevel.Info);
            return (identifier, false);
        }
    }

    public interface ILogger
    {
        void Log(string message, LogLevel logLevel = default);
    }

    public enum LogLevel
    {
        Debug,
        Info,
        Warning,
        Error,
        Critical
    }
}
```
