[' ```csharp
using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

public class DecryptionService : IDecryptionService
{
    private readonly IOptions<EncryptionSettings> _settings;
    private readonly ILogger<DecryptionService> _logger;

    public DecryptionService(IOptions<EncryptionSettings> settings, ILogger<DecryptionService> logger)
    {
        _settings = settings;
        _logger = logger;
    }

    public async Task<byte[]> DecryptData(byte[] ciphertext, byte[] key, byte[] iv)
    {
        if (key.Length != _settings.Value.KeyLength || iv.Length != _settings.Value.IVLength)
            throw new ArgumentException("Invalid key or IV length.");

        var encryptionAlgorithm = _settings.Value.EncryptionAlgorithm;
        var paddingScheme = _settings.Value.PaddingScheme;

        using (var aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = GetCipherMode(encryptionAlgorithm);
            aes.Padding = GetPaddingScheme(paddingScheme);

            ICryptoTransform cryptoTransform = aes.CreateDecryptor();

            var buffer = new byte[ciphertext.Length];
            int decryptedByteCount = 0;

            try
            {
                using (var ms = new MemoryStream(ciphertext))
                using (var cs = new CryptoStream(ms, cryptoTransform, CryptoStreamMode.Read))
                {
                    while (true)
                    {
                        int decryptedBytes = await cs.ReadAsync(buffer, decryptedByteCount, buffer.Length - decryptedByteCount);
                        if (decryptedBytes == 0)
                            break;

                        Array.Copy(buffer, decryptedByteCount, buffer, 0, decryptedBytes);
                        decryptedByteCount += decryptedBytes;
                    }
                }

                return RemovePadding(buffer, paddingScheme);
            }
            catch (CryptographicException ex)
            {
                _logger.LogError(ex, "Decryption error: {Message}", ex.Message);
                throw;
            }
        }
    }

    private AesAlgorithm GetCipherMode(string encryptionAlgorithm)
    {
        switch (encryptionAlgorithm.ToLower())
        {
            case "aes-cbc": return AesAlgorithm.CBC;
            default: throw new ArgumentException("Unsupported cipher mode.");
        }
    }

    private PaddingScheme GetPaddingScheme(string paddingScheme)
    {
        switch (paddingScheme.ToLower())
        {
            case "pkcs7": return PaddingScheme.PKCS7;
            case "pkcs5": return PaddingScheme.PKCS5;
            case "iso10126": return PaddingScheme.ISO10126;
            case "iso7816-4": return PaddingScheme.ISO7816_4;
            default: throw new ArgumentException("Unsupported padding scheme.");
        }
    }

    private byte[] RemovePadding(byte[] buffer, PaddingScheme paddingScheme)
    {
        var paddingLength = paddingScheme.GetPadLength(buffer);
        Array.Copy(buffer, 0, buffer, paddingLength, buffer.Length - paddingLength);
        return buffer;
    }
}

public class EncryptionSettings
{
    public int KeyLength { get; set; }
    public int IVLength { get; set; }
    public string EncryptionAlgorithm { get; set; }
    public string PaddingScheme { get; set; }
}

public enum AesAlgorithm
{
    CBC
}

public enum PaddingScheme
{
    PKCS7,
    PKCS5,
    ISO10126,
    ISO7816_4

    // Implement methods for each padding scheme to get the pad length.
}
```

