        Task {
            name: "task1".to_string(),
            condition: Box::new(|url| url.ends_with("/api/v1/some-endpoint")),
            service_url: Url::parse("http://example.com").unwrap(),
        },
        // Add more tasks as needed
    ];

    let mut runtime = Runtime::new().map_err(|e| e.into())?;
    let executor = runtime.executor();

    let arguments: Vec<String> = env::args().collect();
    if arguments.len() < 2 {
        println!("Usage: {} [task]", arguments[0]);
        return Ok(());
    }

    let task_name = &arguments[1];

    let mut logger = LOGGER.lock().unwrap();
    if let Some(ref mut log) = *logger {
        if !log.enabled(LevelFilter::Trace) {
            log.set_threshold(LevelFilter::Trace);
        }
    } else {
        let builder = EnvLoggerBuilder::new()
            .filter_level(LevelFilter::Trace)
            .format(|buf, record| {
                writeln!(
                    buf,
                    "{}[{}] {}: {}",
                    chrono::Local::now().format("[%Y-%m-%d %H:%M:%S]").to_string(),
                    record.level(),
                    record.target(),
                    record.args()
                )
                .unwrap();
            });
        *logger = Some(builder.init().map_err(|e| e.into())?);
    }

    let mut log_file = LOG_FILE.lock().unwrap();
    if !arguments[1].ends_with("log") {
        *log_file = None;
        return Ok(());
    }

    let mut file = File::create("log.txt").map_err(|e| e.into())?;
    *log_file = Some(BufWriter::new(file));

    let task = tasks
        .iter()
        .find(|t| t.name == task_name)
        .ok_or("Invalid task")??;

    executor.spawn_blocking(move || task.execute()).await?;

    Ok(())
}
```

