use std::collections::HashMap;
use std::env;
use std::fs::{self, File};
use std::io::{BufWriter, Write};
use std::path::Path;
use std::sync::Mutex;
use rayon::prelude::*;
use reqwest::Client;
use serde_json::{Map, Value};
use tempfile::Builder as TempFileBuilder;
use tokio::runtime::Runtime;
use log::error;
use chrono::Utc;

struct ConfigServiceClient {
    client: Client,
}

impl ConfigServiceClient {
    fn new() -> Self {
        ConfigServiceClient {
            client: Client::new(),
        }
    }

    async fn get_config(&self) -> Result<Value, reqwest::Error> {
        let response = self.client.get("https://example-config-service.com/config").send().await?;
        Ok(response.json().await?)
    }
}

lazy_static! {
    static ref CONFIG: Mutex<Option<Value>> = Mutex::new(None);
    static ref RUNTIME: Runtime = Runtime::new().unwrap();
}

fn create_and_update_config_dir(dir_name: &str) {
    let mut config = CONFIG.lock().unwrap();
    if let Some(ref config_data) = *config {
        let settings = config_data["directories"][dir_name].as_object().unwrap();
        let permissions = settings["permissions"].as_str().unwrap();
        create_directory_with_permissions(dir_name, permissions);
    } else {
        let client = ConfigServiceClient::new();
        RUNTIME.block_on(async move {
            if let Ok(config) = client.get_config().await {
                *CONFIG.lock().unwrap() = Some(config.clone());
                let settings = config["directories"][dir_name].as_object().unwrap();
                create_directory_with_permissions(dir_name, settings["permissions"].as_str().unwrap());
            }
        });
    }

    update_environment_variable(dir_name);
}

fn create_directory_with_permissions(dir_name: &str, permissions: &str) {
    let path = Path::new(dir_name);
    if !path.exists() {
        fs::create_dir_all(path).unwrap();
    }

    let metadata = fs::metadata(path).unwrap();
    if metadata.permissions() != Permissions::from_mode_bits_set_replace(u32::from_str_radix(permissions, 8).unwrap()) {
        let mut file = File::create(path).unwrap();
        file.set_permissions(Permissions::from_mode_bits_set_replace(u32::from_str_radix(permissions, 8).unwrap()))
            .unwrap();
    }
}

fn update_environment_variable(dir_name: &str) {
    let dir_path = TempFileBuilder::new().prefix("config_").suffix(".env").tempfile().unwrap();
    let mut file = BufWriter::new(dir_path.file());
    write!(file, "{}={}", "CONFIG_DIR", dir_name).unwrap();
    env::set_var("CONFIG_DIR", dir_name);
}

fn main() {
    create_and_update_config_dir("my_app");
}
```
