    def __init__(self):
        self._registry = {}

    def register(self, id: str, factory: Union[Type, Callable[[], Type]]):
        self._registry[id] = factory

    def get_factory(self, id: str) -> Union[Type, Callable[[], Type]]:
        return self._registry.get(id)

class DynamicJsonSchema:
    def __init__(self, data_type: type, schema: dict):
        self.data_type = data_type
        self.schema = schema

class DynamicJsonField:
    def __init__(self, name: str, data_type: type, validation_func=None):
        self.name = name
        self.data_type = data_type
        self.validation_func = validation_func

class DynamicJson:
    _id = ""
    _registry = DynamicJsonRegistry()

    @staticmethod
    def register(cls):
        DynamicJson._registry.register(cls.__name__, cls)

    def __init__(self, json_data: dict, schema: DynamicJsonSchema):
        self._fields = [DynamicJsonField(name, schema.data_type, schema.validation_func) for name, schema in schema.items()]
        self._data = {}
        for field in self._fields:
            value = json_data.get(field.name, None)
            if field.validation_func and not field.validation_func(value):
                raise ValueError("Invalid data type for field %s" % field.name)
            self._data[field.name] = value
        self._id = DynamicJson._registry.get_factory(self.__class__.__name__)()
        for field in self._fields:
            setattr(self._id, field.name, getattr(self, field.name))

    def to_json(self) -> dict:
        result = {}
        for field in self._fields:
            value = getattr(self._id, field.name)
            if isinstance(value, DynamicJson):
                result[field.name] = value.to_json()
            else:
                result[field.name] = value
        return result

