typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint32_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void validate_and_store(int arr[], size_t* size, int min, int max) {
    *size = 0;
    int num;
    while (scanf("%d", &num) == 1 && (*size < MAX_SIZE)) {
        bool duplicate = false;
        for (size_t i = 0; i < *size; ++i) {
            if (arr[i] == num) {
                duplicate = true;
                break;
            }
        }
        if (!duplicate && min <= num && num <= max) {
            arr[*size++] = num;
        }
    }
}

void find_largest(const int arr[], size_t size, uint32_t seed, NFAPI_CRC_INDICATION_PDU_T list[], size_t* list_size) {
    uint32_t largest = 0;
    for (size_t i = 0; i < size; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    *list_size = 0;
    pthread_t threads[arr_size];
    for (size_t i = 0; i < size; ++i) {
        int arg[] = {i, &seed};
        pthread_create(&threads[*list_size], NULL, create_pdu, &arg);
        (*list_size)++;
    }
    for (size_t i = 0; i < *list_size; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void* create_pdu(void* arg) {
    int index = *(int*)arg;
    uint32_t seed = *(uint32_t*)((char*)arg + sizeof(int));
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu != NULL) {
        pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu->RNTI = index;
        pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        pdu->CRCFLAG = (seed & (1 << index)) >> index;
    }
    return pdu;
}

