typedef struct {
    int id;
    int cell_id;
    int priority;
    int bandwidth;
    float power;
} UE;

struct network {
    UE* ues;
    int num_ues;
    int min_cell_id;
    int max_cell_id;
    int max_priority;
    float total_bandwidth;
    float total_power;
    bool dynamic;
    FILE* log_file;
};

void randomize(UE* ue, int min, int max) {
    ue->cell_id = rand() % (max - min + 1) + min;
    ue->priority = rand() % (max + 1);
}

void configure_ue(Network* network, UE* ue) {
    randomize(ue, network->min_cell_id, network->max_cell_id);
    ue->priority = determine_priority(ue->signal_strength);
    allocate_resources(network, ue);
}

void allocate_resources(Network* network, UE* ue) {
    // Adaptive resource allocation based on priority levels and current network load
    float total_available_bandwidth = network->total_bandwidth - ue->bandwidth;
    float available_power = network->total_power - ue->power;

    ue->bandwidth += total_available_bandwidth / network->num_ues;
    ue->power += available_power / network->num_ues;
}

int determine_priority(float signal_strength) {
    // Function to calculate priority level based on UE's signal strength
    return (int)(signal_strength * network->max_priority);
}

Network* initialize_network(int num_ues, int min_cell_id, int max_cell_id, int max_priority, float total_bandwidth, float total_power, bool dynamic, const char* log_file) {
    Network* network = malloc(sizeof(Network));
    network->ues = malloc(num_ues * sizeof(UE));
    network->num_ues = num_ues;
    network->min_cell_id = min_cell_id;
    network->max_cell_id = max_cell_id;
    network->max_priority = max_priority;
    network->total_bandwidth = total_bandwidth;
    network->total_power = total_power;
    network->dynamic = dynamic;
    network->log_file = fopen(log_file, "w");

    for (int i = 0; i < num_ues; ++i) {
        UE* ue = &network->ues[i];
        configure_ue(network, ue);
    }

    return network;
}

void log_ue_configurations(Network* network) {
    for (int i = 0; i < network->num_ues; ++i) {
        UE* ue = &network->ues[i];
        fprintf(network->log_file, "UE %d: cell_id=%d, priority=%d, bandwidth=%.2f, power=%.2f\n", i, ue->cell_id, ue->priority, ue->bandwidth, ue->power);
    }
}

void free_network(Network* network) {
    free(network->ues);
    fclose(network->log_file);
    free(network);
}
```

