use std::collections::HashMap;
use reqwest::{Client, Response, Method};
use serde_log::Logger;
use url::Url;
use thiserror::Error;

const LOG_LEVEL: &str = std::env::var("LOG_LEVEL").unwrap_or_else(|_| "info".to_string());

#[derive(Debug, Error)]
pub enum FetchResourceError {
    #[error("Invalid URL")]
    InvalidUrl,
    #[error("Network error: {0}")]
    NetworkError(String),
    #[error("Timeout error")]
    TimeoutError,
    #[error("SSL validation error: {0}")]
    SslValidationError(String),
    #[error("IO error: {0}")]
    IoError(String),
    #[error("Custom error: {0}")]
    CustomError(String),
}

pub struct Config {
    log_level: String,
    ssl_validation: bool,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            log_level: "info".to_string(),
            ssl_validation: true,
        }
    }
}

pub async fn fetch_resource(config: &Config, url: Url, method: Method, body: Option<String>) -> Result<Response, FetchResourceError> {
    let client = reqwest::Client::builder()
        .log_level(match config.log_level.as_str() {
            "debug" => LogLevelFilter::Debug,
            _ => LogLevelFilter::Info,
        })
        .build()?;

    if !config.ssl_validation {
        client = client.dangerous_configuration().http2_priority_support(false);
    }

    let mut req = match method {
        Method::GET => {
            let req = client.get(url);
            req
        }
        Method::POST => {
            let req = client.post(url);
            if let Some(ref body) = body {
                req.header("Content-Type", "application/json").body(body)
            } else {
                req
            }
        }
        _ => return Err(FetchResourceError::CustomError(format!("Unsupported method: {}", method))),
    };

    for (key, value) in config.headers().iter() {
        req = req.header(*key, *value);
    }

    let response = req.send().await?;

    if !response.status().is_success() && config.log_level == "debug" {
        serde_json::to_string(&response.json::<HashMap<String, String>>().await.unwrap()).unwrap().logs();
    }

    response
}

impl Config {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn with_log_level(mut self, log_level: &str) -> Self {
        self.log_level = log_level.to_string();
        self
    }

    pub fn with_ssl_validation(mut self, ssl_validation: bool) -> Self {
        self.ssl_validation = ssl_validation;
        self
    }

    pub fn headers(&self) -> HashMap<String, String> {
        HashMap::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_fetch_resource_get() {
        let config = Config::new();
        let url = Url::parse("https://example.com").unwrap();
        let response = fetch_resource(&config, url, Method::GET).await.unwrap();
        assert!(response.status().is_success());
    }

    #[tokio::test]
    async fn test_fetch_resource_post() {
        let config = Config::new().with_log_level("debug");
        let url = Url::parse("https://example.com").unwrap();
        let body = r#"{"key": "value"}"#;
        let response = fetch_resource(&config, url, Method::POST).await.unwrap();
        assert!(response.status().is_success());
    }

    #[tokio::test]
    async fn test_fetch_resource_invalid_url() {
        let config = Config::new();
        let url = Url::parse("http://not-a-valid-url").unwrap();
        assert!(matches!(fetch_resource(&config, url, Method::GET).await, Err(FetchResourceError::InvalidUrl)));
    }
}
```

This code defines a `Config` struct to configure the logging level and SSL validation for the requests. The `fetch_resource` function takes a config object, URL, method, and optional body for POST requests and returns a Response or an error. It also includes unit tests for testing the function under various conditions.']

