import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;

public class Utils {
    private static final long MILLISECONDS_PER_SECOND = TimeUnit.MILLISECONDS.toMillis(1);

    public static String processStringAndAnalyzeArray(String str, int[] arr) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digest = md.digest(str.getBytes());
        BigInteger bigInt = new BigInteger(1, digest);
        String hash = bigInt.toString(16);
        while (hash.length() < 32) {
            hash = "0" + hash;
        }

        Map<Integer, Integer> countMap = new HashMap<>();
        long startTime = System.nanoTime();

        for (int i = 0; i < arr.length - 1; i++) {
            int key = Arrays.binarySearch(arr, i + 1, arr.length, arr[i]);
            if (key < 0) { // disjoint pair found
                countMap.put(arr[i], (countMap.getOrDefault(arr[i], 0) + 1));
                countMap.put(arr[Math.abs(key)], (countMap.getOrDefault(arr[Math.abs(key)], 0) + 1));
            }
        }
        long timeTaken = TimeUnit.NANOSECONDS.toMillis((System.nanoTime() - startTime) / MILLISECONDS_PER_SECOND);

        int disjointPairCount = 0;
        for (Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
            if (entry.getValue() == 1) {
                disjointPairCount++;
            }
        }

        return String.format("%s %d", hash, disjointPairCount) + " (" + timeTaken + " ms)";
    }
}
