// Default styles as fallback
const defaultStyles = document.createElement('style');
defaultStyles.innerHTML = `/* Your default styles here */`;
document.head.appendChild(defaultStyles);

let cssFiles = [];

function loadCSS(href) {
  const link = document.createElement('link');
  link.rel = 'stylesheet';
  link.href = href;

  // Event listener for onError to handle loading errors and apply default styles
  link.onerror = () => {
    console.error(`Failed to load CSS: ${link.href}`);
    document.head.appendChild(defaultStyles);
  };

  // Event listener for onLoad to apply loaded styles, remove error listener, and queue next file if available
  link.onload = () => {
    document.head.removeChild(link.onerror);
    link.onload = null;
    cssFiles.splice(cssFiles.indexOf(href), 1); // Remove loaded file from the queue
    if (cssFiles.length > 0) loadCSS(cssFiles[0]); // Queue next file if available
  };

  // Prioritize loading critical styles first and defer less important styles
  if (href.match(/critical\.css$/)) link.media = 'print';

  document.head.appendChild(link);
}

// Function to update the styles based on user interactions or external API calls
function updateStyles() {
  // Perform any necessary calculations or API calls here, then update the defaultStyles.innerHTML accordingly
}

// Load initial critical and non-critical stylesheets
cssFiles = ['critical.css', 'styles.css'].concat(/* Additional CSS files */);
cssFiles.forEach(loadCSS);
