#include <iomanip>
#include <stdexcept>

namespace fs = boost::filesystem;
namespace asio = boost::asio;
namespace bt = boost::test_tools;

// Custom exception class for log file processing errors
class LogFileError : public std::runtime_error {
public:
    explicit LogFileError(const std::string& what) : std::runtime_error(what) {}
};

std::vector<std::vector<double>> processLine(const std::vector<std::string>& tokens) {
    if (tokens.size() < 4)
        throw LogFileError("Invalid log line format");

    double average;
    try {
        average = (std::stod(tokens[2]) + std::stod(tokens[3])) / 2;
    } catch (const std::invalid_argument& e) {
        throw LogFileError("Invalid numerical data");
    }

    tokens.back() = std::to_string(average);
    return tokens;
}

std::vector<std::vector<double>> processFile(const fs::path& path) {
    std::ifstream file(path, std::ios::in);
    if (!file)
        throw LogFileError("Could not open file: " + path.string());

    std::vector<std::vector<double>> data;
    boost::tokenizer<boost::char_separator<char>> tokenizer(boost::char_separator<char>(","));
    std::string line;

    while (std::getline(file, line)) {
        data.push_back({});
        auto tokens = tokenizer.tokenize(line);
        try {
            for (auto& token : tokens)
                data.back().push_back(std::stod(token));
            data.back() = processLine(data.back());
        } catch (const LogFileError& e) {
            std::cerr << "Error processing line: " << e.what() << "\n";
        }
    }

    return data;
}

void sendGETRequest(const std::string& url, const asio::yield_context& yield_context, asio::streambuf& response) {
    try {
        asio::ip::tcp::resolver resolver(asio::io_service());
        auto endpoint_iterator = resolver.resolve("", url);
        asio::ip::tcp::socket socket(asio::io_service());

        asio::connect(socket, endpoint_iterator, yield_context);
        asio::streambuf request;
        std::ostream os(&request);
        os << "GET / HTTP/1.1\r\nHost: " << url << "\r\n\r\n";
        asio::write(socket, request, yield_context);

        asio::copy(asio::buffer(response), socket, yield_context);
    } catch (const std::exception& e) {
        std::cerr << "Error sending GET request: " << e.what() << "\n";
    }
}

void checkResponse(const asio::streambuf& response) {
    auto responseStream = std::istreambuf_iterator<char>(response);
    if (responseStream.peek() != 200 || !std::getline(responseStream, std::string()))
        throw LogFileError("Invalid HTTP response");
}

void testProcessor() {
    BOOST_TEST_CASE("Test processor with valid log files") {
        // Add test cases for valid log files here
    }

    BOOST_TEST_CASE("Test processor with invalid log files") {
        // Add test cases for invalid or edge case log files here
    }
}

int main() {
    try {
        asio::io_service ioService;
        std::map<std::string, fs::path> configFiles = {{/* API URL */}, /* list of log file paths */};

        for (auto& pair : configFiles) {
            sendGETRequest(pair.first, asio::yield_context(ioService), asio::streambuf());
            checkResponse(asio::buffer_1<char>()); // Assuming predefined criteria are met

            auto data = processFile(pair.second);
            // Process the data further or save it to a database, etc.
        }

        testProcessor();
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << "\n";
        return 1;
    }

    return 0;
}
