#include <jpeglib.h>

typedef enum { MONO, LABEL1, LABEL2, LABEL3, LABEL4, LABEL8, RGB, CMYK } ColorModel;

struct TiffImageInfo {
    tdata_t *imageData;
    int bitsPerSample;
    int samplesPerPixel;
    int compressionType;
    double xResolution;
    double yResolution;
    char *colorProfile;
    ColorModel colorModel;
    int extraSamplesCount;
};

void tiffImageInfoFree(struct TiffImageInfo *info) {
    if (info->imageData) {
        free(info->imageData);
    }
    free(info->colorProfile);
    free(info);
}

struct TiffImageInfo *tiffImageInfoNew() {
    return calloc(1, sizeof(struct TiffImageInfo));
}

struct TiffImageInfo *processTiffImage(const char *filename) {
    struct TiffImageInfo *imageInfo = tiffImageInfoNew();
    if (tif_open((char *)filename, "r", &imageInfo->imageData)) {
        if (!tiffGetField(imageInfo->imageData, TIFFTAG_BITSPERSAMPLE, &imageInfo->bitsPerSample)) {
            fprintf(stderr, "Error: Missing bits per sample field in %s\n", filename);
            tiffImageInfoFree(imageInfo);
            return NULL;
        }
        if (!tiffGetField(imageInfo->imageData, TIFFTAG_SAMPLESPERPIXEL, &imageInfo->samplesPerPixel)) {
            fprintf(stderr, "Error: Missing samples per pixel field in %s\n", filename);
            tiffImageInfoFree(imageInfo);
            return NULL;
        }
        if (!tiffGetField(imageInfo->imageData, TIFFTAG_COMPRESSION, &imageInfo->compressionType)) {
            fprintf(stderr, "Error: Missing compression field in %s\n", filename);
            tiffImageInfoFree(imageInfo);
            return NULL;
        }
        if (!tiffGetField(imageInfo->imageData, TIFFTAG_XRESOLUTION, &imageInfo->xResolution)) {
            fprintf(stderr, "Error: Missing x resolution field in %s\n", filename);
            tiffImageInfoFree(imageInfo);
            return NULL;
        }
        if (!tiffGetField(imageInfo->imageData, TIFFTAG_YRESOLUTION, &imageInfo->yResolution)) {
            fprintf(stderr, "Error: Missing y resolution field in %s\n", filename);
            tiffImageInfoFree(imageInfo);
            return NULL;
        }
        if (!tiffGetField(imageInfo->imageData, TIFFTAG_COLORMAP, &imageInfo->colorModel)) {
            imageInfo->colorModel = RGB; // Default to RGB if no color map found
        }
        if (tif_get_field(imageInfo->imageData, TIFFTAG_ICC_PROFILE)) {
            const char *iccProfileData = tif_get_field_data(imageInfo->imageData, TIFFTAG_ICC_PROFILE);
            imageInfo->colorProfile = mmap(NULL, strlen(iccProfileData), PROT_READ, MAP_PRIVATE, fileno(stdin), 0);
        } else {
            fprintf(stderr, "Error: Missing or invalid ICC color profile in %s\n", filename);
            tiffImageInfoFree(imageInfo);
            return NULL;
        }

        int numExtraSamples = 0;
        for (int i = 0; i < imageInfo->samplesPerPixel; ++i) {
            if (!tiffGetField(imageInfo->imageData, TIFF_RDSampleValue(i), &numExtraSamples)) {
                fprintf(stderr, "Error: Extra samples field not found for sample %d in %s\n", i, filename);
                tiffImageInfoFree(imageInfo);
                return NULL;
            }
            if (numExtraSamples > 0) {
                ++imageInfo->extraSamplesCount;
            }
        }
    } else {
        fprintf(stderr, "Error: Unable to open file %s\n", filename);
        return NULL;
    }

    return imageInfo;
}
```
This code assumes the use of external libraries for TIFF reading (tiffio.h) and ICC color profile handling (libxml2, jpeglib). It processes each image by getting its metadata and storing it in a struct `TiffImageInfo`. The function handles common issues like missing fields or unsupported compression types gracefully, providing meaningful error messages. To minimize memory usage, the TIFF data is read with tif_open() instead of using a separate array for each image.

