void rename_file(char *current_filename, char *desired_extension, int num_digits, char *directory_path, char *log_file) {
    DIR *dir;
    struct dirent *entry;
    size_t len = strlen(directory_path);
    int base_name_len = current_filename[len-1] == '/' ? len : strlen(current_filename);

    // Create new filename
    char new_filename[base_name_len + num_digits + strlen(desired_extension) + 2];
    strncpy(new_filename, current_filename, base_name_len);
    sprintf(&new_filename[base_name_len], "%0*d.", num_digits, getpid());
    strcat(new_filename, desired_extension);

    // Validate new filename against directory structure
    dir = opendir(directory_path);
    if (!dir) {
        log4c_log_error(logger, "Error: Unable to open the specified directory %s.", directory_path);
        return;
    }

    bool conflict = false;
    while ((entry = readdir(dir))) {
        if (strcmp(new_filename, entry->d_name) == 0) {
            conflict = true;
            break;
        }
    }
    closedir(dir);

    if (conflict) {
        log4c_log_error(logger, "Warning: File %s already exists. Cannot rename file.", new_filename);
        return;
    }

    // Rename the file
    char src[base_name_len + strlen("/") + strlen(directory_path)];
    char dest[strlen(directory_path) + strlen(new_filename) + 2];
    strcpy(src, current_filename);
    strcpy(dest, directory_path);
    strcat(dest, "/");
    strcat(dest, new_filename);

    int ret = rename(src, dest);
    if (ret == -1) {
        log4c_log_error(logger, "Error: Unable to rename file from %s to %s.", src, dest);
    } else {
        log4c_log_info(logger, "Info: Successfully renamed file from %s to %s.", src, dest);
    }
}

int main() {
    // Initialize logger
    LogConfigureRetry wrapper = log4c_default_init("appender.log4c.root=CONSOLE, appender.log4c.logfile=./error.log\n");
    Logger logger = log4c_get_logger();

    // Define file properties
    char current_filename[] = "example.txt";
    char desired_extension[] = ".bak";
    int num_digits = 6;
    char directory_path[] = "./test_directory/";
    char log_file[] = "./error.log";

    // Call the rename_file function
    rename_file(current_filename, desired_extension, num_digits, directory_path, log_file);

    return 0;
}
