typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void getArray(int32_t *arr, size_t *len, int32_t MIN_VAL, int32_t MAX_VAL) {
    // Read and validate integers from standard input
    size_t current_size = 0;
    while (current_size < *len && fscanf(stdin, "%d", arr + current_size) == 1) {
        if (arr[current_size] < MIN_VAL || arr[current_size] > MAX_VAL) {
            fprintf(stderr, "Invalid integer: %" PRId32 "\n", arr[current_size]);
            exit(EXIT_FAILURE);
        }

        uint64_t hash = ((uint64_t)arr[current_size] << 32) | ((uint64_t)hash64(arr[current_size]) & 0xFFFFFFFF);
        bool duplicate = false;
        for (size_t i = 0; i < current_size && !duplicate; ++i) {
            if (hash == ((uint64_t)(arr[i] << 32) | ((uint64_t)hash64(arr[i]) & 0xFFFFFFFF))) {
                duplicate = true;
            }
        }

        if (!duplicate) {
            ++current_size;
        } else {
            fprintf(stderr, "Duplicate integer: %" PRId32 "\n", arr[current_size]);
            exit(EXIT_FAILURE);
        }
    }
}

uint64_t hash64(int64_t key) {
    // Golden Rule Hash Function
    uint64_t v;
    memcpy(&v, &key, sizeof(key));
    v = (v ^ (v >> 30)) * 0xbf58476d1ce4e5b9;
    v = (v ^ (v >> 27)) * 0x94d049bb133111eb;
    return v ^ (v >> 31);
}

void populateCRCPDU(NFAPI_CRC_INDICATION_PDU_T* pdu, size_t count, uint32_t seed, double probability) {
    time_t current_time = time(NULL);
    srand((unsigned int)current_time + (uintptr_t)seed);
    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&pdu[i].CRC_INDICATION_REL8_TAG);
        pdu[i].CRC_INDICATION_REL8_TAG = (double)rand() / RAND_MAX >= probability;
        pthread_mutex_unlock(&pdu[i].CRC_INDICATION_REL8_TAG);
    }
}

void findLargest(const int32_t* arr, size_t len) {
    if (len == 0) {
        fprintf(stderr, "Empty array\n");
        return;
    }

    int32_t largest = arr[0];
    for (size_t i = 1; i < len; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    printf("Largest integer: %" PRId32 "\n", largest);
}
