    int id = config.id;
    for (size_t i = 0; i < sizeof(interfaces) / sizeof(Node*); ++i) {
        Node *node = interfaces[i];
        while (node != NULL) {
            if (node->config.id == id && strcmp(node->config.ip, config.ip) == 0) {
                pthread_mutex_unlock(&mutex);
                return; // Duplicate entry found, exit function
            }
            node = node->next;
        }
    }

    size_t index = 0;
    for (size_t i = 0; i < sizeof(interfaces) / sizeof(Node*); ++i) {
        if (!interfaces[i]) {
            index = i;
            break;
        }
