    newNode->config = config;
    newNode->next = interfaces[index];
    interfaces[index] = newNode;

    pthread_mutex_unlock(&mutex);
}

void updateInterface(int id, InterfaceConfig newConfig) {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < sizeof(interfaces) / sizeof(Node*); ++i) {
        Node *node = interfaces[i];
        while (node != NULL) {
            if (node->config.id == id) {
                node->config = newConfig;
                break;
            }
            node = node->next;
        }
    }

    pthread_mutex_unlock(&mutex);
}

void deleteInterface(int id) {
    pthread_mutex_lock(&mutex);

    Node **prev = interfaces;
    while (*prev && !((*prev)->config.id == id)) {
        prev = &(*prev)->next;
    }

    if (!*prev) {
        pthread_mutex_unlock(&mutex);
        return; // Interface not found, exit function
    }

    Node *nodeToDelete = *prev;
    *prev = nodeToDelete->next;
    free(nodeToDelete);

    pthread_mutex_unlock(&mutex);
}
