#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct Collection {
    Record* data;
    size_t capacity;
    size_t size;
} Collection;

Collection* collection_create(size_t capacity) {
    Collection* coll = malloc(sizeof(Collection));
    if (!coll) return NULL;
    coll->capacity = capacity;
    coll->size = 0;
    coll->data = calloc(capacity, sizeof(Record));
    if (!coll->data) {
        free(coll);
        return NULL;
    }
    return coll;
}

void collection_destroy(Collection* coll) {
    if (coll && coll->data) free(coll->data);
    if (coll) free(coll);
}

Record* find_record(const Collection* coll, int key) {
    for (size_t i = 0; i < coll->size; ++i) {
        if (coll->data[i].key == key) return &coll->data[i];
    }
    return NULL;
}

void insert(Collection* coll, Record* record) {
    for (size_t i = 0; i < coll->size; ++i) {
        if (coll->data[i].key == record->key) {
            coll->data[i] = *record;
            return;
        }
    }
    if (coll->size == coll->capacity) {
        size_t new_capacity = coll->capacity * 2;
        Record* temp = realloc(coll->data, sizeof(Record) * new_capacity);
        if (!temp) return;
        coll->data = temp;
        coll->capacity = new_capacity;
    }
    coll->data[coll->size] = *record;
    ++coll->size;
}

void delete(Collection* coll, int key) {
    Record* record = find_record(coll, key);
    if (!record) return;
    memmove(&coll->data[record - coll->data], &coll->data[record + 1], (coll->size - 1 - record) * sizeof(Record));
    --coll->size;
}

