#include <openssl/aes.h>
#include <openssl/kdf.h>
#include <openssl/evp.h>
#include <openssl/err.h>
#include <string.h>
#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <sys/mman.h>
#include <pthread.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    uint8_t iv[AES_BLOCK_SIZE];
    void *mem_pool;
} aes_context;

aes_context* aes256_cbc_init(const char *password, const char *kdf, int strength, size_t iv_size, size_t key_size) {
    AES_KEY key;
    EVP_CIPHER_CTX ctx;
    EVP_KDF kdf_ctx;
    uint8_t derived_key[AES_BLOCK_SIZE + 1];
    int result;

    if(strlen(password) < 32 || strlen(kdf) > 64 || strength < 0 || iv_size < AES_BLOCK_SIZE || key_size < AES_BLOCK_SIZE) {
        ERR_clear_error();
        return NULL;
    }

    if(!EVP_get_digestbyname(kdf, NULL)) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    if((result = EVP_KDFinit(&kdf_ctx, password, strlen(password), EVP_get_digestbyname(kdf))) <= 0) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    if((result = EVP_KDF(derived_key, sizeof(derived_key), kdf, &kdf_ctx, strength ? (uint8_t *)&strength : NULL)) <= 0) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    if(!AES_set_encrypt_key((const uint8_t *)derived_key, key_size * 8, &key)) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    if(iv_size != AES_BLOCK_SIZE) {
        memset(ctx.iv, 0, sizeof(ctx.iv));
    } else {
        if(!RAND_bytes(ctx.iv, iv_size)) {
            ERR_print_errors_fp(stderr);
            return NULL;
        }
    }

    AES_cbc_encrypt_init(&ctx, &key, iv, IV_PADDING);

    aes_context *context = (aes_context *)mmap(NULL, sizeof(aes_context), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    context->ctx = &ctx;
    memcpy(context->iv, iv, iv_size);
    context->mem_pool = mmap(NULL, 128 * 1024, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    return context;
}

void aes256_cbc_free(aes_context *context) {
    munmap((void *)context->ctx, sizeof(*context->ctx));
    munmap(context->mem_pool, 128 * 1024);
}
```

