size_t allocate_records(size_t num_offsets, int min_val, int max_val, size_t *num_records) {
    size_t i, *offsets, *keys;
    record *records;
    time_t t;

    // Check for valid input
    if(num_offsets <= 0) return 0;

    // Allocate memory for offsets and keys arrays
    offsets = (size_t*) malloc(num_offsets * sizeof(size_t));
    keys = (size_t*) malloc(num_offsets * sizeof(int));

    if(!offsets || !keys) {
        free(offsets);
        free(keys);
        return 0;
    }

    // Initialize offsets and keys arrays
    for(i = 0; i < num_offsets; ++i) {
        offsets[i] = i;
        keys[i] = min_val + (rand() % (max_val - min_val + 1));
    }

    // Allocate memory for records array and initialize its elements
    records = (record*) calloc(num_offsets, sizeof(record));
    if(!records) {
        free(offsets);
        free(keys);
        return 0;
    }

    // Set pointers in records array to point to corresponding long values in offsets array
    for(i = 0; i < num_offsets; ++i)
        records[i].value = &offsets[i];

    // Save the number of allocated records and set random keys for each record
    *num_records = num_offsets;
