    int cell_id;
    int signal_strength;
    int priority;
    float bandwidth;
    float power;
} UE;

struct network {
    unsigned int num_ues;
    UE* ues;
    pthread_mutex_t mutex;
    float current_load;
    float* predicted_load;
    float* congestion_threshold;
    bool failure_occurred;
};

void init_network(struct network* network, unsigned int num_ues) {
    network->num_ues = num_ues;
    network->ues = (UE*)malloc(num_ues * sizeof(UE));
    pthread_mutex_init(&network->mutex, NULL);
    network->current_load = 0.0f;
    network->predicted_load = (float*)calloc(num_ues, sizeof(float));
    network->congestion_threshold = (float*)calloc(num_ues, sizeof(float));
    network->failure_occurred = false;
}

void configure_ue(struct network* network, UE* ue) {
