    ue->cell_id = rand() % 10 + 1;
    ue->signal_strength = rand() % 100 + 1;
    ue->priority = ue->signal_strength / 10;
    ue->bandwidth = (float)(ue->priority * network->current_load);
    ue->power = (float)(ue->priority * network->current_load);
}

void allocate_resources(struct network* network) {
    float total_bandwidth = 0.0f;
    float total_power = 0.0f;

    pthread_mutex_lock(&network->mutex);
    for (unsigned int i = 0; i < network->num_ues; ++i) {
        if (network->congestion_threshold[i] > network->predicted_load[i]) {
            network->ues[i].bandwidth += (float)(network->congestion_threshold[i] - network->predicted_load[i]);
            total_bandwidth += network->ues[i].bandwidth;
            network->ues[i].power += network->ues[i].bandwidth;
            total_power += network->ues[i].power;
        }
    }
    pthread_mutex_unlock(&network->mutex);

    if (total_bandwidth > 1.0f) {
        float scale = 1.0f / total_bandwidth;
        for (unsigned int i = 0; i < network->num_ues; ++i) {
            network->ues[i].bandwidth *= scale;
            network->ues[i].power *= scale;
        }
    }
}

