typedef struct {
    FILE *file;
    float *data;
    size_t length;
    size_t capacity;
} DataContainer;

DataContainer* read_data_from_file(const char *filename) {
    DataContainer *container = malloc(sizeof(DataContainer));
    container->file = fopen(filename, "r");
    if (!container->file) {
        free(container);
        return NULL;
    }

    container->length = 0;
    container->capacity = 16;
    container->data = malloc(container->capacity * sizeof(float));

    float num;
    size_t i = 0;
    while (fscanf(container->file, "%f", &num) == 1) {
        if (i >= container->capacity) {
            container->capacity *= 2;
            container->data = realloc(container->data, container->capacity * sizeof(float));
        }
        container->data[i++] = num;
        container->length++;
    }

    fclose(container->file);

    return container;
}

void free_data_container(DataContainer *container) {
    if (container) {
        free(container->data);
        fclose(container->file);
        free(container);
    }
}

float calculate_mean(const DataContainer *container) {
    float sum = 0.0;
    for (size_t i = 0; i < container->length; ++i) {
        sum += container->data[i];
    }
    return sum / container->length;
}

float calculate_standard_deviation(const DataContainer *container) {
    float mean = calculate_mean(container);
    float variance = 0.0;

    for (size_t i = 0; i < container->length; ++i) {
        variance += pow((container->data[i] - mean), 2);
    }

    return sqrt(variance / container->length);
}

// Integration with existing system
void process_uesim_conf_with_statistics(const char *filename) {
    DataContainer *data = read_data_from_file(filename);
    if (!data) {
        printf("Error reading file.\n");
        return;
    }

    // Process data here, integrate with the existing system as needed.

    float mean = calculate_mean(data);
    float stddev = calculate_standard_deviation(data);

    printf("Mean: %.6f\n", mean);
    printf("Standard Deviation: %.6f\n", stddev);

    free_data_container(data);
}
```

