["```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <sys/mman.h>

typedef struct record {
    int key;
    long offset __attribute__((aligned(64)));
    int value;
    pthread_mutex_t lock;
} Record;

typedef struct collection {
    Record* records;
    size_t capacity;
    size_t count;
    size_t size;
    const size_t record_size = sizeof(Record);
    const size_t alignment = alignof(Record);
} Collection;

Collection* create_collection(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    Collection *coll = malloc(sizeof(Collection));
    coll->records = calloc(initial_capacity, coll->record_size);
    if (!coll->records) {
        free(coll);
        return NULL;
    }

    coll->capacity = initial_capacity;
    coll->count = 0;
    coll->size = initial_capacity * coll->record_size;

    // Initialize mutexes for all records
    for (size_t i = 0; i < initial_capacity; ++i) {
        pthread_mutex_init(&coll->records[i].lock, NULL);
    }

    return coll;
}

void destroy_collection(Collection* coll) {
    if (!coll) return;

    free(coll->records);
    free(coll);
}

int random_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

Record* get_record(Collection* coll, int key) {
    for (size_t i = 0; i < coll->capacity; ++i) {
        if (coll->records[i].key == key) {
            pthread_mutex_lock(&coll->records[i].lock);
            return &coll->records[i];
        }
    }

    // Key not found, return NULL
    return NULL;
}

Record* add_record(Collection* coll, int key, long offset) {
    if (coll->count >= coll->capacity) {
        // Reallocate memory when capacity limit is reached
        size_t new_capacity = coll->capacity * 2;
        Record* temp = realloc(coll->records, new_capacity * coll->record_size);

        if (!temp) return NULL;

        coll->records = temp;
        coll->capacity = new_capacity;
        coll->size = new_capacity * coll->record_size;
    }

    Record* record = &coll->records[coll->count];
    record->key = key;
    record->offset = offset;
    record->value = random_in_range(0, 100);
    pthread_mutex_init(&record->lock, NULL);

    ++coll->count;

    return record;
}

void iterate_records(Collection* coll, void (*func)(Record*)) {
    for (size_t i = 0; i < coll->capacity; ++i) {
        Record* record = &coll->records[i];

        // Lock mutex to ensure thread safety during function calls
        pthread_mutex_lock(&record->lock);
        func(record);
        pthread_mutex_unlock(&record->lock);
    }
}
```

This code defines a `Record` structure for the data model and a `Collection` struct to manage dynamic collections of records. The `create_collection()` function initializes a collection with a given capacity, allocating memory in a thread-safe manner. The `destroy_collection()` function handles deallocation when the collection is no longer needed.

The `add_record()` function allows adding a new record to the collection, ensuring that the capacity limit is handled gracefully. It also initializes each record's value to a random integer within the specified range.

The `get_record()` function retrieves a record associated with a given key and locks its mutex for thread safety. If no such record exists, it returns NULL.

Finally, the `iterate_records()` function allows iterating over all records in a collection, calling a provided callback function on each record while minimizing cache misses due to concurrent access from multiple threads by locking the mutex before performing any operation on each record."]

