            outputStream = new DataOutputStream(process.getOutputStream());
            copyStream(reader, process.getInputStream(), 1024 * 8); // Copy 8KB at a time to prevent buffer overflow
            outputStream.write(structure.toByteArray());
            outputStream.flush();
            copyStream(process.getErrorStream(), System.err, 1024 * 8);
