typedef struct NICP_MSG {
    uint8_t mac[6];
    uint32_t ip;
    uint16_t port;
    pthread_mutex_t lock;
} NICP_MSG;

struct network {
    size_t capacity;
    size_t count;
    NICP_MSG* interfaces;
    pthread_mutex_t lock;
};

bool is_in_range(uint32_t ip, uint32_t net, uint32_t mask) {
    return ((ip & mask) == (net & mask));
}

struct network* init_network(uint32_t net, uint32_t mask, size_t capacity) {
    struct network* nw = malloc(sizeof(struct network));
    if (!nw) return NULL;
    nw->capacity = capacity;
    nw->count = 0;
    nw->interfaces = calloc(capacity, sizeof(NICP_MSG));
    if (!nw->interfaces) {
        free(nw);
        return NULL;
    }
    pthread_mutex_init(&nw->lock, NULL);
    return nw;
}

NICP_MSG* get_free_interface(struct network* nw) {
    for (size_t i = 0; i < nw->capacity; ++i) {
        if (!nw->interfaces[i].ip) {
            return &nw->interfaces[i];
        }
    }
    return NULL;
}

NICP_MSG* config_interface(struct network* nw, const uint8_t mac[], const uint32_t ip, const uint16_t port) {
    NICP_MSG* nicp = get_free_interface(nw);
    if (!nicp) return NULL;

    memcpy(nicp->mac, mac, sizeof(nicp->mac));
    nicp->ip = htonl(ip);
    nicp->port = htons(port);
    pthread_mutex_init(&nicp->lock, NULL);

    for (size_t i = 0; i < nw->count; ++i) {
        if (i == nicp - nw->interfaces) continue;
        if (is_in_range(nicp->ip, nw->interfaces[i].ip, inet_netmask(32)) ||
           (nicp->ip & inet_netmask(8)) == (nw->interfaces[i].ip & inet_netmask(8))) {
            pthread_mutex_lock(&nw->lock);
            free(nicp);
            nicp = NULL;
            pthread_mutex_unlock(&nw->lock);
            break;
        }
    }

    if (nicp) {
        pthread_mutex_lock(&nw->lock);
        nw->count++;
        pthread_mutex_unlock(&nw->lock);
    }

    return nicp;
}

