#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>

typedef struct {
    int* data;
    size_t capacity;
    size_t size;
} Array;

Array read_file(const char* path) {
    FILE* file = fopen(path, "r");
    if (!file) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    Array valid_numbers = {NULL, 0, 0};
    int current_number;

    while (fscanf(file, "%d", &current_number) == 1) {
        if (current_number < -1000 || current_number > 1000) continue;

        Array* numbers = realloc(valid_numbers.data, valid_numbers.size * sizeof(int));
        if (!numbers) {
            perror("Error allocating memory");
            exit(EXIT_FAILURE);
        }
        valid_numbers.data = numbers;
        valid_numbers.capacity++;
        valid_numbers.size++;
        valid_numbers.data[valid_numbers.size - 1] = current_number;
    }

    if (ferror(file)) {
        perror("Error reading file");
        exit(EXIT_FAILURE);
    }

    fclose(file);

    quicksort(&valid_numbers, 0, valid_numbers.size - 1);
    return valid_numbers;
}

void quicksort(Array* numbers, size_t left, size_t right) {
    if (left < right) {
        size_t pivotIndex = partition(numbers, left, right);
        quicksort(numbers, left, pivotIndex - 1);
        quicksort(numbers, pivotIndex + 1, right);
    }
}

size_t partition(Array* numbers, size_t left, size_t right) {
    int pivot = numbers->data[right];
    size_t i = left;

    for (size_t j = left; j < right; j++) {
        if (numbers->data[j] <= pivot) {
            swap(numbers, i, j);
            i++;
        }
    }

    swap(numbers, i, right);
    return i;
}

void swap(Array* numbers, size_t index1, size_t index2) {
    int temp = numbers->data[index1];
    numbers->data[index1] = numbers->data[index2];
    numbers->data[index2] = temp;
}

int find_min(const Array* numbers) {
    if (numbers->size == 0) return -1;
    return numbers->data[0];
}

void print_error_and_exit(const char* message) {
    printf("%s\n", message);
    exit(EXIT_FAILURE);
}

int main(int argc, const char** argv) {
    if (argc != 2) print_error_and_exit("Usage: ./program input_file");

    Array numbers = read_file(argv[1]);
    printf("Minimum number: %d\n", find_min(&numbers));

    free(numbers.data);
    return 0;
}
```

This code reads integers from a file, validates their range, sorts them in ascending order using quicksort algorithm and finds the smallest integer in the array. It handles errors during file I/O gracefully and uses streaming techniques to avoid excessive memory usage. Memory is properly managed with dynamic allocation and deallocation.']

