// Define a node structure for the linked list
struct state_node {
    int state;
    struct state_node *next;
    int ref_count; // Reference count for memory optimization
    pthread_mutex_t mutex; // Mutex for thread safety
};

// FSA structure definition (assuming it is provided by an external library)
typedef struct fsa FSA;

struct fsa_traverse_args {
    struct state_node **head;
    FSA *fsa;
    int last_state;
};

// Helper function to find next reachable state in the FSA
void find_next_state(FSA *fsa, int current_state, struct state_node **next) {
    // Implement the logic to traverse the FSA and find the next reachable state
}

// Function to build a linked list of reachable states from the last state in the FSA
struct state_node* create_linked_list(int *states, int num_states, FSA *fsa, int last_state) {
    struct state_node *head = NULL;
    struct state_node **current = &head;

    // Traverse the FSA from the last state and build a linked list of reachable states
    struct fsa_traverse_args args = {current, fsa, last_state};
    pthread_t thread;

    if (pthread_create(&thread, NULL, traverse_fsa, &args)) {
        // Handle error when creating the thread
        return NULL;
    }

    pthread_join(thread, NULL);

    // Check if there are any states in the linked list and allocate memory accordingly
    if (!*current) {
        *current = malloc(sizeof(struct state_node));
        (*current)->state = -1; // Sentinel value to indicate an empty list
        (*current)->ref_count = 1;
        pthread_mutex_init(&((*current)->mutex), NULL);
    }

    return head;
}

// Thread-safe function to traverse the FSA and find reachable states
void *traverse_fsa(void *args) {
    struct fsa_traverse_args *traverse_args = args;
    FSA *fsa = traverse_args->fsa;
    int last_state = traverse_args->last_state;
    struct state_node **head = traverse_args->head;

    pthread_mutex_lock(&(traverse_args->head->mutex));
    find_next_state(fsa, last_state, head);
    pthread_mutex_unlock(&(traverse_args->head->mutex));

    // Recursively traverse the FSA for each reachable state
    struct state_node *current = *head;
    while (current != NULL) {
        pthread_mutex_lock(&(current->mutex));
        int next_state = current->state;
        pthread_mutex_unlock(&(current->mutex));

        if (next_state == -1) break; // Sentinel value to indicate an empty list

        struct state_node *new_node = malloc(sizeof(struct state_node));
        new_node->state = next_state;
        new_node->ref_count = 1;
        new_node->next = NULL;
        pthread_mutex_init(&(new_node->mutex), NULL);

        pthread_mutex_lock(&((*head)->mutex));
        new_node->next = *head;
        *head = new_node;
        pthread_mutex_unlock(&((*head)->mutex));

        traverse_fsa(malloc(sizeof(struct fsa_traverse_args))); // Create a new traversal argument for the next state
    }

    return NULL;
}
