#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to validate a filename
int is_valid_filename(const char *filename) {
    if (!filename || strlen(filename) > 255 || !strchr(filename, '.'))
        return 0;
    size_t last_dot = strlen(filename) - 1;
    while (last_dot && filename[last_dot - 1] == '.')
        --last_dot;
    return last_dot >= 0;
}

// Function to generate a new filename
char *generate_new_filename(const char *input) {
    size_t len = strlen(input);
    const char *ext = input + len - 1; // Start from the end of the string
    while (*ext != '.') --ext;            // Find the last dot
    const char *name = input;           // Store the main filename portion
    if (ext != name)                     // Check if there's an extension
        name = input;
    else {
        name = input;
        while (*name && *name != '.') ++name;  // Move to the start of the filename
    }

    size_t digits = strlen(name) - (ext - name);
    char *new_filename = malloc(digits + 3 + strlen(name));
    if (!new_filename) return NULL;

    sprintf(new_filename, "%.*s%0*d.%c%s", (int)strlen(name), name, (int)digits, atoi(name), toupper(*ext), ext + 1);
    return new_filename;
}

// Function to process a list of filenames from an input file and write results to an output file
void process_filenames(const char *input_file, const char *output_file) {
    FILE *in = fopen(input_file, "r");
    if (!in) {
        fprintf(stderr, "Error opening input file: %s\n", input_file);
        return;
    }

    FILE *out = fopen(output_file, "w");
    if (!out) {
        fprintf(stderr, "Error opening output file: %s\n", output_file);
        fclose(in);
        return;
    }

    char line[4096];
    while (fgets(line, sizeof(line), in)) {
        char *token = strtok(line, "\r\n"); // Remove newlines from the input
        if (!token) continue;

        if (!is_valid_filename(token)) {
            fprintf(out, "Invalid filename: %s\n", token);
            continue;
        }

        char *new_name = generate_new_filename(token);
        if (!new_name) {
            fprintf(out, "Error generating new filename for %s\n", token);
            free(new_name);
            continue;
        }

        fprintf(out, "%s\n", new_name);
        free(new_name);
    }

    fclose(in);
    fclose(out);
}
