int create_session(int session_id, struct sockaddr_in addr, const struct QoS *qos) {
    Session *new_session = (Session *) malloc(sizeof(Session));
    if (!new_session) {
        return -1; // Memory allocation failure
    }

    new_session->session_id = session_id;
    new_session->addr = addr;
    new_session->qos = *qos;
    new_session->expiration_time = time(NULL) + QOS_SESSION_DURATION; // Set expiration time based on QoS settings
    new_session->thread_id = 0;
    new_session->data = NULL;
    new_session->next = session_head;
    session_head = new_session;

    pthread_mutex_lock(&sessions_mutex);
    // Start handling the session in a separate thread if not already started
    if (!new_session->thread_id) {
        pthread_create(&new_session->thread_id, NULL, handle_session, new_session);
    }
    pthread_mutex_unlock(&sessions_mutex);

    return 0; // Success
}

void delete_session(int session_id) {
    Session *current = session_head, *prev = NULL;

    while (current != NULL) {
        if (current->session_id == session_id) {
            if (prev == NULL) {
                session_head = current->next;
            } else {
                prev->next = current->next;
            }

            free(current->data);
            free(current);
            break;
        }

        prev = current;
        current = current->next;
    }
}

void *handle_session(void *arg) {
    Session *session = (Session *) arg;

    // Handle the session logic here, including data processing, QoS management, and potential integration with other systems

    pthread_mutex_lock(&sessions_mutex);
    if (time(NULL) > session->expiration_time) {
        delete_session(session->session_id);
        pthread_exit(0); // Session expired, clean up and exit the thread
    }
    pthread_mutex_unlock(&sessions_mutex);

    // Continue handling the session until it's manually deleted or the program terminates
}
