    char rand_str[16];
    sprintf(rand_str, "%08x", (unsigned int) rand());
    SHA256_CTX ctx;
    char path_hash[64];
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, params->path, strlen(params->path));
    SHA256_Update(&ctx, params->base_filename, strlen(params->base_filename));
    SHA256_Final((unsigned char*) path_hash, &ctx);

    // Construct the new filename
    size_t filename_length = strlen(timestamp_str) + strlen(rand_str) + strlen(params->extension) + 1;
    if (filename_length > 255) {
        fprintf(stderr, "New filename exceeds maximum length of 255 characters\n");
        return NULL;
    }
    char* new_filename = malloc(filename_length);
    strcpy(new_filename, timestamp_str);
    strcat(new_filename, rand_str);
    strcat(new_filename, params->extension);

    // Check for uniqueness with a retry mechanism
    int retries = 0;
    while (true) {
        pthread_mutex_lock(&lock);
        char full_path[256];
        snprintf(full_path, sizeof(full_path), "%s/%s", params->path, new_filename);
        DIR *check_dir = opendir(full_path);
        if (!check_dir) {
            closedir(check_dir);
            break;
        }
        closedir(check_dir);

        retries++;
        if (retries >= 10) {
            fprintf(stderr, "Failed to generate a unique filename after 10 attempts\n");
            free(new_filename);
            return NULL;
        }

        sleep(1); // Allow other processes to complete the check and create the file
    }

    // Log the successful filename generation (optional)
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Generated unique filename: %s\n", new_filename);
    // Insert logging code here

    return new_filename;
}
```

