typedef struct {
    unsigned long length;
    struct in_addr src_ip;
    char *payload;
} Packet;

size_t packet_count = 0;
size_t max_payload_size = 1000000; // Define maximum total payload size limit here
size_t current_payload_size = 0;
char *buffer = NULL;
Packet **packets = NULL;

void packet_free(Packet *packet) {
    free(packet->payload);
    free(packet);
}

void reallocate() {
    if (current_payload_size + max_payload_size * (packet_count+1) > 2*current_payload_size) {
        current_payload_size *= 2;
        buffer = realloc(buffer, current_payload_size);
        if (!buffer) {
            perror("realloc failed");
            exit(EXIT_FAILURE);
        }
    }
}

Packet* create_packet() {
    Packet *packet = malloc(sizeof(Packet));
    if (!packet) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    packet->length = 0;
    memcpy(&(packet->src_ip), INADDR_ANY, sizeof(struct in_addr));
    packet->payload = &buffer[current_payload_size];
    current_payload_size += max_payload_size;
    reallocate();

    return packet;
}

void add_packet(Packet *packet) {
    if (packet_count == 0) {
        packets = malloc(sizeof(Packet*));
        if (!packets) {
            perror("malloc failed");
            exit(EXIT_FAILURE);
        }
    } else {
        Packet **new_packets = realloc(packets, sizeof(Packet*) * (packet_count + 1));
        if (!new_packets) {
            perror("realloc failed");
            exit(EXIT_FAILURE);
        }
        packets = new_packets;
    }

    packets[packet_count++] = packet;
}

void process_packets() {
    for (size_t i = 0; i < packet_count; ++i) {
        // Perform packet processing logic here
        printf("Processing packet from IP: %s, length: %lu\n", inet_ntoa(packets[i]->src_ip), packets[i]->length);

        packet_free(packets[i]);
    }

    packet_count = 0;
}
