#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/types.h>
#include <dirent.h>
#include <time.h>
#include <semaphore.h>

typedef struct {
    pid_t id;
    time_t timestamp;
    enum event_type { LOG, WARNING, ERROR } type;
    char *event_data;
    int unique_id;
} log_entry;

struct directory {
    char path[256];
    sem_t lock;
    log_entry **entries;
    size_t capacity;
    size_t count;
};

void log_error(const char *message, struct directory *dir) {
    FILE *logfile = fopen("errors.log", "a");
    if (logfile) {
        fprintf(logfile, "%s: %s\n", ctime(&time(NULL)), message);
        fclose(logfile);
    }
}

void log_entry_free(log_entry *entry) {
    free(entry->event_data);
    free(entry);
}

void directory_resize(struct directory *dir, size_t new_capacity) {
    log_entry **new_entries = realloc(dir->entries, new_capacity * sizeof(log_entry*));
    if (!new_entries) {
        log_error("Memory allocation failed", dir);
        return;
    }
    dir->entries = new_entries;
    dir->capacity = new_capacity;
}

void directory_add_entry(struct directory *dir, log_entry *entry) {
    sem_wait(&dir->lock);

    if (dir->count == dir->capacity) {
        directory_resize(dir, dir->capacity * 2);
    }

    int id = entry->unique_id;
    for (size_t i = 0; i < dir->count; ++i) {
        if (dir->entries[i]->unique_id == id) {
            log_entry_free(entry);
            sem_post(&dir->lock);
            return;
        }
    }

    dir->entries[dir->count] = entry;
    ++dir->count;
    sem_post(&dir->lock);
}

log_entry *directory_get_entry(struct directory *dir, int unique_id) {
    sem_wait(&dir->lock);
    log_entry *entry = NULL;
    for (size_t i = 0; i < dir->count; ++i) {
        if (dir->entries[i]->unique_id == unique_id) {
            entry = dir->entries[i];
            break;
        }
    }
    sem_post(&dir->lock);
    return entry;
}

void directory_update_entry(struct directory *dir, log_entry *new_entry, int unique_id) {
    log_entry *old_entry = directory_get_entry(dir, unique_id);
    if (!old_entry) return;

    free(old_entry->event_data);
    old_entry->unique_id = new_entry->unique_id;
    old_entry->timestamp = new_entry->timestamp;
    old_entry->type = new_entry->type;
    old_entry->event_data = malloc(strlen(new_entry->event_data));
    strcpy(old_entry->event_data, new_entry->event_data);
}

void directory_rename_file(char *filename, int desired_ext, int digits) {
    char extension[16];
    sprintf(extension, ".%d", desired_ext);

    char *dot = strrchr(filename, '.');
    if (dot == NULL || dot - filename < digits) return;

    memmove(dot + digits + 1, dot, strlen(dot + 1));
    sprintf(dot, "%s%0*d%s", extension, digits, getpid(), extension);
}
```

This code is a starting point for the given task and provides basic functionality to manage log entries. The `log_entry` struct includes timestamps, event types, and event data, as well as a unique identifier for each entry.

The `directory` struct stores an array of pointers to `log_entry` structs, along with the directory path, a lock semaphore, capacity, and count of entries. The `directory_add_entry`, `directory_get_entry`, and `directory_update_entry` functions are provided for adding, retrieving, and updating log entries, respectively.

The `directory_resize` function manages memory allocation for the array of pointers to log entries, ensuring it scales gracefully as the number of log entries grows. The lock semaphore is used to maintain thread-safety during concurrent access to the directory.

The `log_error` and `log_entry_free` functions provide logging mechanisms for errors and memory management for log entries, respectively. The `directory_rename_file` function renames a file based on provided rules and validates against the target directory path, ensuring compliance with naming conventions.']

