int get_ext_pos(const char *filename) {
    const int len = strlen(filename);
    for (int i = len - 1; i >= 0; --i) {
        if (filename[i] == '.') return len - i;
    }
    return -1;
}

char *generate_new_name(const char *filename) {
    static int counter = 100;
    const int ext_pos = get_ext_pos(filename);
    int num_chars = ext_pos < 0 ? strlen(filename) : ext_pos + 3;
    int len = num_chars + 6; // .xxxxxx_ext
    char *new_name = malloc(len);
    ensure_len(new_name, len);

    if (ext_pos >= 0) {
        memcpy(new_name, filename, ext_pos);
    } else {
        strcpy(new_name, filename);
    }

    int num_seq = num_chars - strlen(&new_name[ext_pos + 1]);
    snprintf(&new_name[ext_pos + 1], 6, "%05d", counter++);

    return new_name;
}

int rename_file(const char *old_filename) {
    const char *ext = &old_filename[get_ext_pos(old_filename) + 1];
    char *new_filename = generate_new_name(old_filename);
    int result = rename(old_filename, new_filename);
