    if (feof(stream)) return -1; // Reached end of file
    buffer[bytes_read] = '\0';
    return bytes_read;
}

void parse_args(int argc, char **argv) {
    program_name = argv[0];
    for (int i = 1; i < argc; ++i) {
        if (!strcmp(argv[i], "-h") || !strcmp(argv[i], "--help")) {
            is_help = true;
            continue;
        }
        if (!strcmp(argv[i], "--manpage")) {
            show_manpage = true;
            continue;
        }
        if (argv[i][0] == '-' && argv[i][1] != '\0') {
            error("Invalid option: %s\n", argv[i]);
        }
        if (!output_filename) {
            output_filename = argv[i];
            redirect_output = true;
        }
    }

    if (show_manpage || !output_filename) {
        // Display manpage or usage information
        return;
    }

    if (!has_errors_log && getenv("ERRORS_LOG")) {
        has_errors_log = true;
        errors_log = fopen(getenv("ERRORS_LOG"), "w");
        if (!errors_log) {
            error("Unable to open errors log file: %s\n", getenv("ERRORS_LOG"));
        }
    }
}

void print_manpage() {
    // Print detailed usage information
}

int main(int argc, char **argv) {
    parse_args(argc, argv);

    if (is_help || show_manpage) {
        print_manpage();
        return 0;
    }

    // Open the input file with large file support under both Linux and Windows
#ifdef _WIN32
    _umask(0);
    GetTempPath(MAX_PATH, temp_path);
    strcat(temp_path, "\\tmp___error_count__");
    int tmp_file = _mknt Temp(temp_path);
    int input_fd = CreateFile(argv[output_filename], GENERIC_READ, FILE_SHARE_READ, NULL, OPEN_EXISTING, _O_LARGEFILE | FILE_FLAG_SEQUENTIAL_SCAN, NULL);
#else // Linux or macOS
    int input_fd = open(argv[output_filename], O_RDONLY | O_LARGEFILE);
#endif

    if (input_fd == -1) {
        error("Unable to open input file: %s\n", argv[output_filename]);
    }

    if (redirect_output) {
        output_file = fopen(argv[output_filename], "w");
        if (!output_file) {
            error("Unable to open output file: %s\n", argv[output_filename]);
        }
    }

    size_t line_number = 0;
    char buffer[BUFFER_SIZE];
    while (read_chunk(input_fd, buffer, BUFFER_SIZE) > 0) {
        if (strstr(buffer, "ERROR")) {
            if (has_errors_log) {
                fprintf(errors_log, "%u: %s\n", ++line_number, buffer);
            }
        }
        if (count_chars) {
            size_t chars_in_line = strlen(buffer) - count_spaces(buffer);
            printf("Line %u has %lu characters excluding spaces.\n", line_number + 1, chars_in_line);
        }

        fputs(buffer, output_file);
        line_number++;
    }

    if (errors_log) {
        fclose(errors_log);
    }
    if (!redirect_output) {
        fclose(output_file);
    }
#ifdef _WIN32
    CloseHandle(input_fd);
    _unlink(temp_path);
#else // Linux or macOS
    close(input_fd);
#endif

    return 0;
}

size_t count_spaces(const char *str) {
    size_t space_count = 0;
    for (size_t i = 0; str[i] != '\0'; ++i) {
        if (str[i] == ' ') {
            ++space_count;
        }
    }
    return space_count;
}
