#define BUFFER_SIZE 1024 * 8 // 8KB buffer size
#define FLUSH_INTERVAL 5 // seconds between automatic flushes

typedef struct {
    char* data;
    size_t length;
    pthread_mutex_t lock;
} LogBuffer;

LogBuffer* log_buffer_create() {
    LogBuffer* buffer = malloc(sizeof(LogBuffer));
    buffer->data = malloc(BUFFER_SIZE);
    buffer->length = 0;
    pthread_mutex_init(&buffer->lock, NULL);
    return buffer;
}

void log_buffer_append(LogBuffer* buffer, const char* message, size_t length) {
    pthread_mutex_lock(&buffer->lock);
    if (buffer->length + length >= BUFFER_SIZE) {
        // Buffer is full, flush before appending new data.
        log_flush(buffer);
    }
    memcpy(buffer->data + buffer->length, message, length);
    buffer->length += length;
    pthread_mutex_unlock(&buffer->lock);
}

void log_buffer_flush(LogBuffer* buffer) {
    if (buffer->length == 0) return;

    pthread_mutex_lock(&buffer->lock);
    char* data = buffer->data;
    size_t length = buffer->length;
    buffer->length = 0;
    pthread_mutex_unlock(&buffer->lock);

    FILE* file = fopen("logs.txt", "a");
    if (file != NULL) {
        fprintf(file, "%s", data);
        fclose(file);
    }

    // Handle network logging here...
}

