// External Configuration Object
struct Config {
    size_t maxMemoryUsage;
    std::chrono::milliseconds operationTimeout;
};

void insertAfterOrAppend(std::forward_list<std::string>& list, const std::string& first, const std::string& second, bool insertAfter, const Config& config) {
    auto it = list.begin();
    if (it == list.end()) return; // Empty list

    if (next(it) == list.end()) { // List contains only one element
        if (!insertAfter)
            list.push_back(second);
        return;
    }

    size_t memoryUsage = 0;
    std::chrono::steady_clock::time_point beginTime = std::chrono::steady_clock::now();

    for (; it != list.end() && *it == first; ++it) {
        if (next(it) == list.end()) { // First string is the last element in the list, append second string
            if (!insertAfter)
                list.push_back(second);
            break;
        }

        if (insertAfter) {
            auto temp = it;
            ++it;
            list.insert after_begin(temp, second);
            break;
        }

        ++memoryUsage; // Keep track of memory usage
    }

    if (it != list.end()) return; // First string not found in the list, append second string

    auto endTime = std::chrono::steady_clock::now();
    auto duration = endTime - beginTime;

    if (duration > config.operationTimeout || memoryUsage >= config.maxMemoryUsage) {
        // Handle time out or exceeded memory usage error here
    }
}
