public class SqlCommandExecutor
{
    private readonly SqlConnection _connection;

    public SqlCommandExecutor(SqlConnection connection) => _connection = connection;

    public IDataReader ExecuteParameterizedCommand<T>(string commandText, List<T> parameters)
    {
        using (var command = new SqlCommand(commandText, _connection))
        {
            command.Parameters.AddRange(parameters.Select(p => new SqlParameter(nameof(p), p)));

            try
            {
                _connection.Open();
                return command.ExecuteReader();
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error executing command: {ex.Message}");
                return null;
            }
        }
    }
}
