function countBibleBooks(text, chunkSize = 1e6) {
    let bookCounts = {};
    let currentChunk = '';
    let processedBytes = 0;

    for (let i = 0; i < text.length; i += chunkSize) {
        const chunkEnd = Math.min(i + chunkSize, text.length);
        currentChunk += text.slice(i, chunkEnd);

        if (currentChunk) {
            const matchedOldTestament = currentChunk.match(regexOldTestament);
            const matchedNewTestament = currentChunk.match(regexNewTestament);

            if (matchedOldTestament) matchedOldTestament.forEach(book => ++bookCounts[book]);
            if (matchedNewTestament) matchedNewTestament.forEach(book => ++bookCounts[book]);

            processedBytes += chunkEnd - i;

            if (processedBytes > 50 * 1e6) { // Reset and continue processing next chunk
                bookCounts = {};
                currentChunk = '';
                processedBytes = 0;
            }
        }
    }

    return bookCounts;
}

