const axios = require('axios');
const _ = require('lodash');
const minify = require('html-minifier');

async function fetchApiRules() {
  try {
    const response = await axios.get('https://api.example.com/rules');
    return response.data;
  } catch (error) {
    console.error(`Error fetching API rules: ${error}`);
    return null;
  }
}

function isValidScript(script, rules) {
  const { maxLength, keywords } = rules || {};

  if (!maxLength || !keywords.length) return true;

  if (script.code.length > maxLength) return false;

  for (const keyword of keywords) {
    if (script.code.includes(keyword)) return false;
  }

  return true;
}

function minifyHTML(html) {
  const minifier = new (minify.Minify)({
    removeComments: true,
    collapseWhitespace: true,
  });

  return minifier.minify(html).toString();
}

async function renderScriptFooter(scripts) {
  try {
    const rules = await fetchApiRules();
    const filteredScripts = _.filter(scripts, (script) => isValidScript(script, rules));

    if (!filteredScripts.length) return '';

    const htmlTemplate = `
      <footer>
        ${filteredScripts.map(({ id, code }) => `<script src="scripts/${id}.js" defer></script>`).join('')}
      </footer>
    `;

    return minifyHTML(htmlTemplate);
  } catch (error) {
    console.error(`Error rendering script footer: ${error}`);
    return '';
  }
}
```

