2. Inside the component, we use React's `useState` hook to maintain an up-to-date data object.
3. We define a `fetchAndUpdateData` function that fetches data asynchronously using `Promise.all` on the provided keys array.
4. The initial render triggers the first data fetch using the `useEffect` hook without dependencies.
5. Subsequent updates are handled by another `useEffect` hook with dependencies on `keysToUpdate` and `dataSource`. This ensures that we only re-fetch data when necessary.
6. Replace `<YourComponent />` with your existing UI element component, making sure to pass the key and value as props."]

["```javascript
const Stream = require('stream');
const { promisify } = require('util');
const fs = require('fs');
const yargs = require('yargs/yargs');
const argv = yargs
  .option('add', {
    alias: 'a',
    describe: 'Add a new data source stream',
    type: 'string',
  })
  .option('remove', {
    alias: 'r',
    describe: 'Remove an existing data source stream',
    type: 'string',
  })
  .option('pause', {
    alias: 'p',
    describe: 'Pause the current data processing',
    boolean: true,
  })
  .option('resume', {
    alias: 'u',
    describe: 'Resume data processing after pause',
    boolean: true,
  })
  .option('stop', {
    alias: 's',
    describe: 'Stop the current data processing and reset system',
    boolean: true,
  }).argv;

class DataManager {
  constructor() {
    this.streams = new Map();
    this.paused = false;
  }

  async addStream(name) {
    const reader = fs.createReadStream(`data/${name}`);
    const pipeline = promisify(require('stream').pipeline);
    const buffer = new Stream.Transform({
      transform(chunk, encoding, callback) {
        this.push(JSON.parse(chunk));
        callback();
      },
      flush(callback) {
        callback();
      }
    });

    await pipeline(reader, buffer).then((data) => {
      this.streams.set(name, data);
    });
  }

  async removeStream(name) {
    this.streams.delete(name);
  }

  async process() {
    if (this.paused) return;

    for (let [key, value] of this.streams.entries()) {
      const result = await value.getNextData();
      if (!result) break;

      console.log(`Received data from ${key}:`, result);
    }

    requestAnimationFrame(() => this.process());
  }

  async getNextData() {
    for (let [, value] of this.streams.entries()) {
      if (!value.ended) return await value.getNextData();
    }

    return null;
  }
}

const dataManager = new DataManager();

async function main() {
  if (argv.add) dataManager.addStream(argv.add);
  if (argv.remove) dataManager.removeStream(argv.remove);
  if (argv.pause) dataManager.paused = true;
  if (argv.resume) dataManager.paused = false;
  if (argv.stop) {
    dataManager.streams.clear();
    dataManager.paused = false;
  }

  dataManager.process();
}

main().catch((error) => console.error(error));
```

