class ServiceOrchestrator:
    def __init__(self, service_handlers: dict[str, ServiceResponseHandler]):
        self.service_handlers = service_handlers
        self.available_services = set(service_handlers)

    def _get_required_services(self, required_services: frozenset) -> list[str]:
        missing_services = required_services - self.available_services
        if not missing_services:
            return []
        return sorted(list(missing_services))

    def _load_and_execute_service(self, service_name: str, retry_count: int, fallback_func: Callable[[], Any]) -> Any:
        try:
            handler = self.service_handlers[service_name]
            result = handler._get()
        except KeyError:
            if not retry_count:
                raise Exception(f"Service {service_name} is unavailable.")
            return self._load_and_execute_service(service_name, retry_count - 1, fallback_func)
        return result

    def _process_request(self, request: dict, service_dependencies: frozenset[str], retry_count: int = 3, fallback_func: Callable[[], Any] = lambda: fallback_response) -> Any:
        required_services = self._get_required_services(service_dependencies)
        if required_services:
