        service_handlers = {}
        for service_name, service_data in services_config.items():
            url = service_data["url"]
            service_handlers[service_name] = ServiceResponseHandler(service_name, url)
        return service_handlers

    def run(self, request: dict) -> Any:
        service_dependencies = set(request.get("dependencies", []))
        return self._process_request(request, frozenset(service_dependencies), retry_count=3, fallback_func=lambda: fallback_response)

def main():
