from functools import lru_cache
from typing import Callable, Union

class MemoryManager:
    def __init__(self, max_memory):
        self.max_memory = max_memory
        self.current_memory = 0

    def add(self, amount: int) -> bool:
        if self.current_memory + amount > self.max_memory:
            return False
        self.current_memory += amount
        return True

class RealtimeSummaryReport:
    def __init__(self):
        self.summary = {}
        self.lock = threading.Lock()

    def update(self, data: dict) -> None:
        with self.lock:
            for key, value in data.items():
                if key not in self.summary:
                    self.summary[key] = [value]
                else:
                    self.summary[key].append(value)

def process_entry(queue: queue.Queue, report: RealtimeSummaryReport, memory_manager: MemoryManager, process_func: Callable[[Union[str, bytes]], None]) -> None:
    while True:
        try:
            entry = queue.get(block=True, timeout=1)
            if isinstance(entry, str):
                processed_entry = process_func(entry.encode())
            else:
                processed_entry = process_func(entry)

            memory_manager.add(sys.getsizeof(processed_entry))
            report.update({str(uuid.uuid4()): processed_entry})
        except queue.Empty:
            continue

def log_processor(input_queues: list[queue.Queue], output_queue: queue.Queue, memory_manager: MemoryManager, process_func: Callable[[Union[str, bytes]], None], summary_report: RealtimeSummaryReport) -> None:
    workers = []
    for queue in input_queues:
        worker = threading.Thread(target=process_entry, args=(queue, summary_report, memory_manager, process_func))
        worker.start()
        workers.append(worker)

