public class CustomRandomGenerator
{
    private double minValue;
    private double maxValue;
    private readonly Dictionary<string, object> cache = new Dictionary<string, object>();

    public CustomRandomGenerator(double minValue, double maxValue)
    {
        if (maxValue <= minValue)
            throw new ArgumentException("Max value must be greater than min value.");

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public int GetRandomInt(bool inclusive) => Mathf.RoundToInt((UnityEngine.Random.value * (maxValue - minValue)) + minValue * (inclusive ? 1 : 0));

    public float GetRandomFloat(bool inclusive) => UnityEngine.Random.Range(minValue, maxValue * (inclusive ? 1 : 0));

    public override string ToString() => $"Range: [{minValue}, {maxValue})";

    public Vector3 GetRandomVector3() => new Vector3(GetRandomFloat(true), GetRandomFloat(true), GetRandomFloat(true));

    public Matrix4x4 GetRandomMatrix(int cacheSize)
    {
        string key = $"{minValue}_{maxValue}_{cacheSize}";
        object matrix;

        if (cache.TryGetValue(key, out matrix))
            return (Matrix4x4)matrix;

        Matrix4x4 result = new Matrix4x4();
        for (int i = 0; i < 16; i++)
            result[i] = GetRandomFloat(true);

        if (cache.Count >= cacheSize)
            cache.Clear();

        cache[key] = result;
        return result;
    }

