    unsigned char output[strlen(data) + AES_BLOCK_SIZE];
    unsigned int length = sizeof(output);
    if (1 != EVP_EncryptUpdate(ctx, output, &length, data, strlen(data))) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }
    // Handle final encryption here
    if (1 != EVP_EncryptFinal_ex(ctx, output + length, &length)) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }
    free(ctx);
    printf("Encrypted data: %s\n", output);
}

void hash_data(const char* data) {
