        printf("Error: Password is empty or not provided.\n");
        return -1;
    }

    if (session->session.id <= 0 || session->session.id > INT_MAX/10) {
        printf("Error: Invalid session ID. It should be greater than zero and less than 10,000.\n");
        return -2;
    }

    if (strlen(session->session.title) >= 64) {
        printf("Error: Session title exceeds the maximum allowed length of 64 characters.\n");
        return -3;
    }

    const char *reservedKeywords[] = {"admin", "super", "root"};
    for (size_t i = 0; i < sizeof(reservedKeywords)/sizeof(char*); ++i) {
        if (strcmp(session->session.title, reservedKeywords[i]) == 0) {
            printf("Error: Reserved keyword found in session title.\n");
            return -4;
        }
    }

    if (!session->session.callback || !session->session.config || !access(session->session.config->path, R_OK)) {
        printf("Error: Invalid callback or configuration file.\n");
        return -5;
    }

    // Check for degraded network state using connection health check function
    if (isDegradedNetworkState(&session->session)) {
        printf("Error: Network is in a degraded state.\n");
        return -6;
    }

    return 0;
}
