    private readonly Dictionary<int, Func<byte[], object>> _formatConverters = new Dictionary<int, Func<byte[], object>>();

    public DataProcessor(string connectionString, IMemoryCache cache)
    {
        _connectionString = connectionString;
        _cache = cache;

        // Register format converters here. For example:
        _formatConverters[1] = ByteArrayToInt32;
        _formatConverters[2] = ByteArrayToString;

        // Initialize connection pool
        using (var connection = new SqlConnection(_connectionString))
        {
            connection.Open();
            // ... any initialization tasks you need to perform on the connection
        }
    }

    private void VerifyIntegrity(byte[] byteArray)
    {
        if (byteArray == null || byteArray.Length <= 4)
            throw new ArgumentException("Invalid byte array.");

        // Perform additional integrity checks here, such as checking for valid header or footer
    }

    private void ExecuteStoredProcedure(int formatId, object data, string procedureName)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            var sql = $"EXEC [{procedureName}] @data";
            connection.Open();
            connection.Execute(sql, new { data }, commandType: System.Data.CommandType.Text);
        }
    }

    private object ByteArrayToInt32(byte[] byteArray)
    {
        VerifyIntegrity(byteArray);
        return BitConverter.ToInt32(byteArray, 0);
    }

    private object ByteArrayToString(byte[] byteArray)
    {
        VerifyIntegrity(byteArray);
        string result = System.Text.Encoding.UTF8.GetString(byteArray);
        return result;
    }

    public void ProcessByteArray(byte[] byteArray)
    {
        VerifyIntegrity(byteArray);

        if (_cache.TryGetValue(HashCodeCombine(byteArray), out object cachedData))
        {
            ExecuteStoredProcedure((int)cachedData, byteArray, GetStoredProcedureNameByFormatId((int)cachedData));
        }
        else
        {
            using (var connection = new SqlConnection(_connectionString))
            {
                connection.Open();

                // Cache the data for future queries
                var data = _formatConverters[byteArray[0]](byteArray);
                _cache.Set(HashCodeCombine(byteArray), data, new MemoryCacheEntryOptions().AbsoluteExpirationRelativeToNow(TimeSpan.FromMinutes(5)));

                ExecuteStoredProcedure((int)data, byteArray, GetStoredProcedureNameByFormatId((int)data));
            }
        }
    }

    private int HashCodeCombine(byte[] byteArray)
    {
        unchecked // Overflow is fine, as long as we get a valid hash code
        {
            return (byteArray[0] * 397) ^ ((byteArray.Length - 1) & 65535);
        }
    }

    private string GetStoredProcedureNameByFormatId(int formatId)
