            _messageQueue.Enqueue(message);
        }

        public async Task ProcessMessagesAsync()
        {
            while (_messageQueue.Count > 0)
            {
                Base64Message currentMessage = default;

                if (_messageQueue.TryDequeue(out currentMessage))
                {
                    try
                    {
                        await DecryptMessageAsync(currentMessage);
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"Error decrypting message: {ex.Message}");
                    }
                }
            }
        }

        private async Task DecryptMessageAsync(Base64Message message)
        {
            var keyLength = await _encryptionService.GetKeyLengthAsync(message.Header.KeyId);
            var key = await _encryptionService.GetKeyAsync(message.Header.KeyId, keyLength);
            var iv = message.Header.Iv;

            using (var decoder = new Base64Decoder())
            {
                var cipherText = decoder.Decode(message.Body);
                _tripleDes.KeySize = keyLength;
                _tripleDes.IV = iv;
                _tripleDes.Key = key;

                using (var ms = new MemoryStream(cipherText))
                {
                    using (var cs = new CryptoStream(ms, _tripleDes.CreateDecryptor(), CryptoStreamMode.Read))
                    {
                        var plainText = new byte[1024];
                        int bytesRead;

                        do
                        {
                            bytesRead = cs.Read(plainText, 0, plainText.Length);
                            if (bytesRead > 0)
                            {
                                // Process the decrypted plain text as needed...
                            }
                        } while (bytesRead > 0);
                    }
                }
            }
        }

        public class Base64Message
        {
            public string Header { get; set; }
            public string Body { get; set; }
        }
    }
}
```
