                  return new Promise(resolve => setTimeout(() => resolve(), 1000)); // Retry after 1 second delay
                } else {
                  console.error(`Failed to upload ${url}: ${error.message}`);
                  return { url, status: 'failure', errorMessage: error.message };
                }
              });
          })
          .catch((error) => {
            if (++retries < MAX_RETRIES) {
              console.error(`Retrying network request for ${url} due to error: ${error.message}`);
              return new Promise(resolve => setTimeout(() => resolve(), 1000)); // Retry after 1 second delay
            } else {
              console.error(`Failed to make network request for ${url}: ${error.message}`);
              return { url, status: 'failure', errorMessage: error.message };
            }
          });
      })
      .then(results => resolve(results))
