// Validate CRC indication
bool validate_crc(const CRC_INDICATION_REL8_TAG *crc) {
    return (crc->crc_flag == 0 && crc->crc == 0);
}

// Log error message with a timestamp
void log_error(const char *message) {
    time_t current_time;
    struct tm *time_info;
    char time_str[26];

    time(&current_time);
    time_info = localtime(&current_time);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);
    printf("%s: %s\n", time_str, message);
}

// Generate random RNTI within the valid range
uint16_t generate_rnti() {
    return rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;
}

// Initialize and lock the list for concurrent access
void init_list() {
    list.size = 0;
    pthread_mutex_init(&list.mutex, NULL);
}

// Add an element to the dynamic list
int add_element(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (validate_crc(&pdu->crc_indication) && pdu->rnti >= MIN_RNTI && pdu->rnti <= MAX_RNTI) {
        // Protect the list from concurrent access
        pthread_mutex_lock(&list.mutex);

        if (list.size < MAX_LIST_SIZE) {
            list.data[list.size] = *pdu;
            list.size++;
            pthread_mutex_unlock(&list.mutex);
            return 0; // Success
        } else {
            log_error("List is full. Dropping data.");
            pthread_mutex_unlock(&list.mutex);
            return -1; // List is full
        }
    } else {
        log_error("Invalid RNTI or CRC indication.");
        return -2; // Invalid input
    }
}

