// BST Node definition
typedef struct bst_node {
    int key;
    size_t memory_usage;
    struct bst_node *left, *right;
} BST_NODE;

// Helper function to calculate the memory usage of a BST node
size_t bst_node_memory_usage(BST_NODE *node) {
    if (!node) return 0;
    return sizeof(*node) + node->memory_usage;
}

// Function to check if the memory usage of the BST exceeds the limit
bool bst_in_budget(BST_NODE *root, size_t budget) {
    if (!root) return true;
    return (bst_node_memory_usage(root) <= budget) && bst_in_budget(root->left, budget) && bst_in_budget(root->right, budget);
}

// Helper function to find the largest key in the BST
int bst_largest(BST_NODE *node) {
    if (!node) return INT_MIN;
    return (node->key > node->right ? node->key : bst_largest(node->right)) > (node->key > node->left ? node->key : bst_largest(node->left)) ? node->key : bst_largest(node->right);
}

// Helper function to insert a node into the BST and maintain memory budget
BST_NODE* bst_insert(BST_NODE *root, int key, size_t *memory_usage) {
    if (!root) {
        *memory_usage = sizeof(*root);
        return (BST_NODE*)malloc(*memory_usage + bst_node_memory_usage((BST_NODE*)*memory_usage));
    }

    BST_NODE **current = &root;
    bool balance_required = false;

    while (*current) {
        if (key < ((*current)->key))
            current = &((*current)->left);
        else
            current = &((*current)->right);

        // Keep track of memory usage and check for budget violation
        balance_required |= bst_in_budget(*current, *memory_usage);
    }

    *current = (BST_NODE*)malloc(*memory_usage + bst_node_memory_usage((*current)));
    (*current)->key = key;
    (*current)->left = nullptr;
    (*current)->right = nullptr;
    (*current)->memory_usage = *memory_usage;

    if (balance_required) rebalance(root);

    return root;
}

// Function to rebalance the BST by rotating nodes as needed
void rebalance(BST_NODE **root) {
    // Balancing logic implementation here
}

