NetworkEnvironment* init_network_environment(int num_ues, int min_cell_id, int max_cell_id, double initial_bandwidth, double initial_power) {
    NetworkEnvironment* env = malloc(sizeof(NetworkEnvironment));
    env->num_ues = num_ues;
    env->min_cell_id = min_cell_id;
    env->max_cell_id = max_cell_id;
    env->bandwidth = initial_bandwidth;
    env->power = initial_power;

