        ue->id = i + 1;
        ue->cell_id = rand() % (max_cell_id - min_cell_id + 1) + min_cell_id;
        ue->traffic_load = rand() % 100 + 1;
        ue->distance_to_bs = rand() % 1000 + 1;
        pthread_mutex_init(&ue->config_lock, NULL);
    }

    pthread_mutex_init(&env->resource_lock, NULL);
    return env;
}

UE* get_ue(NetworkEnvironment* env, int id) {
