#define MAX_SIZE 1000000 // Predefined maximum size limit

typedef struct Record {
    int value;
    char *str;
};

typedef unsigned long HashKey;

// Custom hash function for keys
HashKey hash(const char *key) {
    HashKey hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % (RAND_MAX / 0.7); // Adjust the divisor to control table size
}

// Hash table implementation using open addressing with linear probing
struct Table {
    unsigned int size;
    unsigned int count;
    struct Record **data;
};

void resize(struct Table *table) {
    if (table->count >= table->size) {
        unsigned int new_size = table->size * 2;
        struct Record **new_data = realloc(table->data, sizeof(struct Record*) * new_size);
        if (!new_data) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        table->data = new_data;
        table->size = new_size;
    }
}

int find(struct Table *table, const char *key) {
    unsigned int index = hash(key) % table->size;
    for (unsigned int i = index; ; ++i %= table->size) {
        if (!table->data[i]) {
            table->data[i] = malloc(sizeof(struct Record));
            if (!table->data[i]) {
                fprintf(stderr, "Error: Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
            break;
        }
        if (strcmp(key, table->data[i]->str) == 0)
            return i;
        resize(table);
    }
}

void insert(struct Table *table, const char *key, struct Record record) {
    unsigned int index = find(table, key);
    resize(table);
    table->data[index] = malloc(sizeof(struct Record));
    if (!table->data[index]) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    memcpy(table->data[index], &record, sizeof(struct Record));
}

void free_table(struct Table *table) {
    for (unsigned int i = 0; i < table->size; ++i) {
        if (table->data[i]) {
            free(table->data[i]);
            table->data[i] = NULL;
        }
    }
    free(table->data);
}

void initialize_hash_table(struct Table *table, unsigned int size) {
    table->size = size;
    table->count = 0;
    table->data = calloc(size, sizeof(struct Record*));
    if (!table->data) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

