    // Set the integer value of each record to a random value within a given range and allocate memory for the string in the records such that each string is a unique representation of the integer value in its record, formatted as a hexadecimal string.
    for (unsigned int i = 0; i < size && table.count < max_size; ++i) {
        struct Record record;
        record.value = rand() % 10000 + 1;
        char str[8];
        sprintf(str, "%lx", (unsigned long)record.value);
        resize(&table);
        insert(&table, str, record);
        records[i] = &table.data[find(&table, str)]->record;
    }
}
