struct Device {
    int id;
    ip::address ip, netmask, gateway;
};

class NetworkDeviceManager {
private:
    unordered_map<int, vector<Device>> devicesByTenant;
    mutex mtx;
public:
    void addDevice(int tenantId, const Device& device) {
        unique_lock<mutex> lock(mtx);
        while (devicesByTenant[tenantId].size() >= 1) { // Find an unused IP within the subnet for the given tenant.
            ip::sub_manager subNetManager(device.netmask);
            int index = -1;
            for (auto& d : devicesByTenant[tenantId]) {
                if (index == -1 && d.ip != device.ip) { // Check if the IP is not already in use and not equal to the new device's IP.
                    index = devicesByTenant[tenantId].size();
                }
                if (d.ip == device.ip) {
                    throw runtime_error("Cannot assign same IP address to two devices within the same tenant.");
                }
                subNetManager.next();
            }
            if (index != -1) { // If a free slot is found, add the new device.
                devicesByTenant[tenantId][index] = device;
                break;
            }
        }
    }

    Device getDeviceById(int tenantId, int id) {
        unique_lock<mutex> lock(mtx);
        auto it = devicesByTenant.find(tenantId);
        if (it != devicesByTenant.end()) {
            return it->second[id];
        } else {
            throw runtime_error("Tenant not found.");
