typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _NODE {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct _NODE* next;
    pthread_mutex_t lock;
} NODE;

void initNode(NODE** node) {
    *node = malloc(sizeof(NODE));
    if (!(*node)) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    (*node)->next = NULL;
    pthread_mutex_init(&((*node)->lock), NULL);
}

void freeNode(NODE** node) {
    if (*node) {
        free(*node);
        *node = NULL;
    }
}

void addNode(NODE** head, NFAPI_CRC_INDICATION_PDU_T data) {
    NODE* newNode = malloc(sizeof(NODE));
    if (!newNode) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&(newNode->lock), NULL);

    newNode->data = data;
    newNode->next = *head;
    *head = newNode;
}

void removeNode(NODE** head, uint32_t rnti) {
    if (*head == NULL) return;

    NODE* current = *head;
    NODE* previous = NULL;

    while (current != NULL && current->data.rnti == rnti) {
        previous = current;
        current = current->next;
    }

    if (previous == NULL) {
        *head = current;
    } else {
        previous->next = current;
    }
}

void clearList(NODE** head) {
    NODE* current = *head;
    NODE* nextNode;

    while (current != NULL) {
        nextNode = current->next;
        freeNode(&current);
        current = nextNode;
    }

    *head = NULL;
}

void setCRCFlag(NFAPI_CRC_INDICATION_PDU_T* pdu, bool crcFlag) {
    pdu->crcIndication.crcFlag = crcFlag;
}

// Randomly generate a CRC flag for testing purposes
void genCRCFlag(bool* crcFlag) {
    *crcFlag = rand() % 2 == 0 ? true : false;
}

// This function can be thread-safe if accessed from multiple threads simultaneously.
void processLinkedList(NODE** head, void (*processFunction)(NFAPI_CRC_INDICATION_PDU_T*)) {
    NODE* current = *head;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    while (current != NULL) {
        pthread_mutex_lock(&(current->lock));
        if (current != NULL) {
            processFunction(&(current->data));
        }
        pthread_mutex_unlock(&(current->lock));

        current = current->next;
    }
}
