#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int id;
    int cell_id;
    pthread_t thread_id;
} UE;

struct set {
    int parent;
    int rank;
};

int find(UE* ue) {
    if (ue->parent != ue - base_ues)
        ue->parent = find(base_ues + ue->parent);
    return ue->parent;
}

void merge(UE* a, UE* b) {
    int root_a = find(a);
    int root_b = find(b);
    if (root_a != root_b) {
        if (base_ues[root_a].rank < base_ues[root_b].rank) {
            base_ues[root_a].parent = root_b;
            base_ues[root_b].rank++;
        } else {
            base_ues[root_b].parent = root_a;
            base_ues[root_a].rank++;
        }
    }
}

int num_disjoint_pairs() {
    int count = 0;
    for (int i = 0; i < number_of_ues; ++i)
        if (find(&base_ues[i]) == &base_ues[i])
            ++count;
    return count;
}

long long time_taken() {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    // Your function implementation here
    clock_gettime(CLOCK_MONOTONIC, &end);
    return (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;
}

void log(UE* ue) {
    printf("UE %d assigned to cell ID %d\n", ue->id, ue->cell_id);
}

void init_network(int number_of_ues, int min_cell_id, int max_cell_id) {
    srand(time(NULL));
    base_ues = malloc(number_of_ues * sizeof(UE));
    for (int i = 0; i < number_of_ues; ++i) {
        UE* ue = &base_ues[i];
        ue->id = i + 1;
        ue->cell_id = rand() % (max_cell_id - min_cell_id + 1) + min_cell_id;
        ue->parent = i;
        base_ues[i].rank = 0;
    }

    // Implement your resource allocation logic and cell outage handling here

    for (int i = 0; i < number_of_ues; ++i) {
        UE* a = &base_ues[i];
        for (int j = i + 1; j < number_of_ues; ++j) {
            UE* b = &base_ues[j];
            if (find(a) != find(b)) {
                merge(a, b);
            }
        }
    }

    int disjoint_pairs = num_disjoint_pairs();
    log("Summary:\n");
    printf("# of Disjoint Pairs: %d\n", disjoint_pairs);
    printf("Time taken (ms): %lld\n", time_taken());
}
