void init_record_collection(int num_records, int min_int_value, int max_int_value, size_t char_status_size, void *buffer, size_t *total_allocated) {
    void **arrays = buffer; // Pointer to the pre-allocated buffer
    size_t total_required = 0; // Total required memory for all arrays and structures

    if (num_records <= 0 || char_status_size < sizeof(char)) {
        *total_allocated = 0;
        return;
    }

    // Calculate the size of each record structure and array
    size_t record_size = sizeof(struct Record);
    size_t key_array_size = num_records * sizeof(int);
    size_t offset_array_size = num_records * sizeof(long);
    size_t field_array_size = num_records * sizeof(int);
    size_t status_array_size = num_records * char_status_size;
    size_t pointer_offset_array_size = num_records * sizeof(long*);

    total_required += record_size + key_array_size + offset_array_size + field_array_size + status_array_size + pointer_offset_array_size;

    if (total_allocated && (*total_allocated) < total_required) {
        free(arrays);
        *total_allocated = 0;
        return;
    }

    // Allocate memory for each array
    arrays[0] = malloc(record_size * num_records + key_array_size + offset_array_size + field_array_size + status_array_size + pointer_offset_array_size);
    if (!arrays[0]) {
        free(arrays);
        *total_allocated = 0;
        return;
    }

    void *current_position = arrays[0] + key_array_size; // Start position after keys array

    // Initialize each record's integer field with a random value and determine the character status indicator based on specific conditions related to the integer value
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        struct Record *record = (struct Record*)current_position;
        record->key = rand() % (max_int_value - min_int_value + 1) + min_int_value;
        record->field = record->key % 5; // Example: status indicator based on the integer value
        record->status = (record->field > 2) ? 'A' : 'B';
        record->offset = i * 100 + rand() % 1000; // Example: offset calculation for each record
        record->pointer_offset = current_position + offset_array_size + field_array_size + status_array_size;

        current_position += record_size;
    }

    *total_allocated = total_required;
}
