  #include <vector>
  #include <new>

  template<typename T>
  class GrowableArray {
      std::vector<T> data;
      size_t capacity;
      void grow() {
          data.reserve(capacity * 2);
          data.resize(capacity * 2);
      }
   public:
      GrowableArray(size_t initialCapacity) : capacity(initialCapacity) {}
      T& operator[](size_t i) { return data[i]; }
      void add(const T& item) {
          if (data.size() == capacity) grow();
          data.push_back(item);
      }
  };
  ```

