  #include <unordered_map>
  #include <functional>

  template<typename Key, typename Value>
  class GrowableHashMap {
      std::unordered_map<Key, Value, std::hash<Key>, std::equal_to<Key>> data;
      size_t capacity;
      void grow() {
          data.rehash(data.capacity() * 2);
      }
   public:
      GrowableHashMap(size_t initialCapacity) : capacity(initialCapacity) {}
      Value& operator[](const Key& key) {
          return data[key];
      }
      void add(const Key& key, const Value& value) {
          if (data.load_factor() > 0.75) grow();
          data[key] = value;
      }
  };
