    char** friends;
    struct UserProfile *next;
} UserProfile;

typedef struct CacheEntry {
    UserProfile profile;
    time_t timestamp;
} CacheEntry;

typedef struct Cache {
    CacheEntry **cache;
    size_t capacity;
    size_t size;
    sem_t lock;
} Cache;

// Initialize and configure cache
Cache* init_cache(size_t capacity) {
    // Allocate memory for the cache array and initialize its elements to NULL
    Cache *cache = malloc(sizeof(Cache));
    cache->capacity = capacity;
    cache->size = 0;
    cache->lock = sem_init(Semaphore_UNBOUNDED, 1, 1);
    cache->cache = calloc(capacity, sizeof(CacheEntry*));
    return cache;
}

// Insert a user profile into the cache if it is not already present or update its timestamp
void insert_cache(Cache *cache, UserProfile profile) {
    sem_wait(&cache->lock);
    size_t index = hash(profile.username) % cache->capacity;
    // If the entry already exists, update its timestamp
    if (cache->cache[index]) {
        sem_post(&cache->lock);
        update_timestamp(&cache->cache[index]->profile);
        return;
    }
    // Otherwise insert the new profile at the given index
    cache->cache[index] = malloc(sizeof(CacheEntry));
    memcpy(&cache->cache[index]->profile, &profile, sizeof(UserProfile));
    sem_post(&cache->lock);
}

