['```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct LTE_NAS_Message {
    uint32_t message_type;
    uint64_t transaction_id;
    char* content;
    pthread_mutex_t lock;
    bool is_active;
} LTE_NAS_Message;

typedef struct Queue {
    size_t capacity;
    size_t count;
    size_t head;
    size_t tail;
    LTE_NAS_Message* data;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
} Queue;

Queue* create_queue(size_t capacity) {
    Queue* q = (Queue*)malloc(sizeof(Queue));
    q->capacity = capacity;
    q->count = 0;
    q->head = 0;
    q->tail = 0;
    q->data = (LTE_NAS_Message*)calloc(capacity, sizeof(LTE_NAS_Message));
    if (!q->data) {
        free(q);
        return NULL;
    }
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->not_empty, NULL);
    pthread_cond_init(&q->not_full, NULL);
    return q;
}

LTE_NAS_Message* queue_push(Queue* q, LTE_NAS_Message msg) {
    pthread_mutex_lock(&q->lock);
    while (q->count == q->capacity) {
        pthread_cond_wait(&q->not_full, &q->lock);
    }

    q->data[(q->head + q->count++) % q->capacity] = msg;
    msg.is_active = true;

    if (q->count == 1) {
        pthread_cond_signal(&q->not_empty);
    }
    pthread_mutex_unlock(&q->lock);
    return &q->data[(q->head + q->count - 1) % q->capacity];
}

LTE_NAS_Message* queue_pop(Queue* q, bool block) {
    pthread_mutex_lock(&q->lock);
    while (q->count == 0 || !q->data[(q->head + q->count) % q->capacity].is_active) {
        if (!block) {
            pthread_mutex_unlock(&q->lock);
            return NULL;
        }
        pthread_cond_wait(&q->not_empty, &q->lock);
    }

    LTE_NAS_Message* msg = &q->data[(q->head + q->count--) % q->capacity];
    msg->is_active = false;

    if (q->count == q->capacity - 1) {
        pthread_cond_signal(&q->not_full);
    }
    pthread_mutex_unlock(&q->lock);
    return msg;
}

void queue_cleanup(Queue* q, size_t inactivity_timeout_ms) {
    time_t now = time(NULL);
    struct timespec abs_timeout;

    pthread_mutex_lock(&q->lock);
    for (size_t i = q->head; i != q->tail; i = (i + 1) % q->capacity) {
        LTE_NAS_Message* msg = &q->data[i];
        if (!msg->is_active && now - msg->transaction_id.tv_sec < inactivity_timeout_ms / 1000.0) {
            free(msg->content);
            continue;
        }
        pthread_mutex_unlock(&q->lock);
        free(msg);
        q->count--;
        if (i == q->tail - 1) {
            q->tail = i;
        }
        pthread_mutex_lock(&q->lock);
    }
    pthread_mutex_unlock(&q->lock);
}
```

This code provides a basic implementation of a concurrent, dynamically sized array of `LTE_NAS_Message` structures. The queue is implemented using circular buffers to minimize memory usage and maximize performance. It employs `pthread_mutex_t` for synchronization between threads and `pthread_cond_t` for waiting on not-empty or not-full conditions.

The `queue_push()` function adds new messages, while the `queue_pop()` function retrieves messages by transaction ID (assuming each message has a unique transaction ID). The `queue_cleanup()` function clears the array periodically when no longer needed.']

