#include <logging_library.h> // External logging library

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failed");
        return NULL;
    }
    new_node->data = *data;
    new_node->next = NULL;
    return new_node;
}

void insert_at_head(Node** head, Node* new_node) {
    if (!*head) {
        *head = new_node;
        return;
    }
    new_node->next = *head;
    *head = new_node;
}

int is_unique(Node* node, Node** list) {
    for (Node* current = *list; current != NULL; current = current->next) {
        if (current->data.RX_UE_INFORMATION_TAG == node->data.RX_UE_INFORMATION_TAG) {
            return 0;
        }
    }
    return 1;
}

Node* create_linked_list(int n, int max_list_size) {
    if (n <= 0 || n > max_list_size) {
        log_error("Invalid list size provided");
        return NULL;
    }

    Node* head = NULL;
    Node** current = &head;
    srand(time(NULL));

    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = i;
        data.RNTI = i; // Default value when RNTI is duplicated
        data.CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) == 0 ? 1 : 0;

        Node* new_node = create_node(&data);
        if (!new_node) {
            log_error("Memory allocation failed");
            return NULL;
        }

        if (!is_unique(new_node, current)) {
            log_info("Duplicate RNTI encountered, using default value.");
            new_node->data.RNTI = new_node->data.RX_UE_INFORMATION_TAG;
        }

        insert_at_head(current, new_node);
    }

    return head;
}

// Thread-safe linked list operations using pthread_mutex_t for synchronization
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
