// Loads the file asynchronously using libcurl. Callback will be invoked when complete or on error.
void load_file(const char *path, void (*callback)(void *, const char *, int), void *userdata) {
    CURLcode res;
    CURLMcode mres;
    CURL *handle;
    curl_mime *form = NULL;

    if (!curl) {
        curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_ERRORBUFFER, "");
        }
    }

    handle = curl_easy_duphandle(curl);
    curl_easy_setopt(handle, CURLOPT_URL, path);

    form = curl_mime_init(handle);
    if (form) {
        curl_mime_addpart(form); // Add part for file uploading if required
    }

    res = curl_easy_perform(handle);
    mres = curl_multi_info_read(curl, 0);

    if (res != CURLE_OK && mres != CURLMCODE_OK) {
        // Error handling and error callback invocation here.
    } else {
        size_t len;
        char *buffer = curl_easy_getinfo(handle, CURLINFO_RECEIVED_DATA_SIZE_T, &len);
        if (len) {
            data = realloc(data, data_size + len);
            memcpy(&data[data_size], buffer, len);
            data_size += len;

            callback(userdata, data, CURLE_OK);
        } else {
            // File was empty or an error occurred during retrieval. Handle appropriately.
        }
    }
}

X509 *load_certificate_or_key(const char *path, const char *mode) {
    pthread_mutex_lock(&mutex);
    void (*callback)(void *, const char *, int) = process_data; // Assume process_data is defined elsewhere.
    load_file(path, callback, NULL);
    pthread_mutex_unlock(&mutex);

    EVP_PKEY *pkey = NULL;
    X509 *cert = NULL;

    if (data_size) {
        BIO *mem = BIO_new_mem_buf(data, data_size);
        if (strcmp(mode, "cert") == 0) {
            cert = PEM_read_bio_X509(mem, NULL, NULL, NULL);
        } else if (strcmp(mode, "key") == 0) {
            pkey = PEM_read_bio_PrivateKey(mem, NULL, NULL, NULL);
        }

        BIO_free_all(mem);
    }

    if (!cert && !pkey) {
        // Handle error for unsupported or malformed file format.
    }

    return cert ? cert : pkey;
}
