#include <libxml/parser.h>
#include <libxml/tree.h>
#include <list>
#include <memory>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

std::list<std::shared_ptr<NFAPI_CRC_INDICATION_PDU_T>> parseCrcIndications(const char *xml) {
    std::list<std::shared_ptr<NFAPI_CRC_INDICATION_PDU_T>> result;
    xmlDocPtr doc = xmlReadFile(xml, NULL, XML_PARSE_NONET);
    if (!doc || !xmlDocGetRootElement(doc)) {
        fprintf(stderr, "Invalid XML format\n");
        xmlFreeDoc(doc);
        return result;
    }

    xmlNodePtr root = xmlDocGetRootElement(doc);
    for (xmlNodePtr current = root->xmlChildrenNode; current != NULL; current = current->xmlNextNode) {
        if (xmlStrcmp(current->name, (const xmlChar *) "crcPdu") == 0) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = new NFAPI_CRC_INDICATION_PDU_T();
            if (parsePDU(current, pdu)) {
                result.push_back(std::shared_ptr<NFAPI_CRC_INDICATION_PDU_T>(pdu));
            } else {
                delete pdu;
            }
        }
    }
    xmlFreeDoc(doc);

    return result;
}

bool parsePDU(xmlNodePtr pdu, NFAPI_CRC_INDICATION_PDU_T *pduStruct) {
    if (!xmlStrcmp(pdu->properties->name, (const xmlChar *) "RxUEInformationTag")) {
        xmlNodePtr value = pdu->xmlChildrenNode;
        if (value && value->type == XML_ELEMENT_NODE && !xmlStrcmp((const xmlChar *) value->name, (const xmlChar *) "Value")) {
            const char *text = (const char *) xmlGetProp(value, (const xmlChar *) "id");
            sscanf(text, "%u", &pduStruct->RX_UE_INFORMATION_TAG);
        }
    } else if (!xmlStrcmp(pdu->properties->name, (const xmlChar *) "RNTI")) {
        xmlNodePtr value = pdu->xmlChildrenNode;
        if (value && value->type == XML_ELEMENT_NODE && !xmlStrcmp((const xmlChar *) value->name, (const xmlChar *) "Value")) {
            const char *text = (const char *) xmlGetProp(value, (const xmlChar *) "id");
            sscanf(text, "%hu", &pduStruct->RNTI);
        }
    } else if (!xmlStrcmp(pdu->properties->name, (const xmlChar *) "CrcIndicationRel8Tag")) {
        const char *text = (const char *) xmlGetProp(pdu, (const xmlChar *) "CRCFLAG");
        pduStruct->CRC_INDICATION_REL8_TAG = strcmp(text, "1") == 0;
    } else {
        fprintf(stderr, "Invalid field found in PDU: %s\n", pdu->properties->name);
        return false;
    }

    return true;
}
