void init_log(struct Log *log) {
    log->fd = open("log.txt", O_WRONLY | O_CREAT | O_TRUNC | O_APPEND, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
}

void append_log(struct Log *log, const char *message) {
    snprintf(log->buffer + log->position, sizeof(log->buffer) - log->position, "%s\n", message);
    log->position += strlen(message) + 1;
    if (log->position >= sizeof(log->buffer)) {
        ftruncate(log->fd, 0);
        log->position = 0;
    }
    write(log->fd, log->buffer, log->position);
}

void *node_alloc() {
