    if (!new_node) {
        append_log(g_log, "Error: Failed to allocate node memory\n");
        return NULL;
    }
    pthread_mutex_init(&new_node->node_lock, NULL);
    new_node->next = NULL;
    return new_node;
}

void add_to_list(Node **head, Node *new_node) {
    if (!*head) {
        *head = new_node;
    } else {
        Node *current = *head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
}

void remove_least_recently_used(Node **head, size_t limit) {
    Node *current = *head;
    Node *temp;
    for (size_t i = 0; i < limit - 1; ++i) {
        if (!current->next) return;
        current = current->next;
    }
    temp = current->next;
    while (current->next) {
        temp = current->next;
        current = temp->next;
        free(temp);
    }
    *head = current;
}

