const fs = require('fs');
const path = require('path');

function loadModule(dirPath, callback) {
    fs.readdirSync(dirPath).forEach(file => {
        file = path.join(dirPath, file);
        const stat = fs.statSync(file);
        if (stat.isDirectory()) loadModule(file, callback);
        else if (path.extname(file) === '.js') callback(file);
    });
}

module.exports = function(dirPath, callback) {
    let modules = [];
    loadModule(dirPath, (file) => {
        const data = fs.readFileSync(file, 'utf8');
        const mod = require(file);
        modules.push([file, mod]);
        if (callback) callback(modules);
    });
    return modules;
};
