mem_pool_t *mem_pool_create() {
    mem_pool_t *pool = malloc(sizeof(mem_pool_t));
    if (!pool) {
        perror("Failed to allocate memory for mem pool");
        return NULL;
    }

    pool->size = 0;
    pool->capacity = 0;
    pool->data = NULL;
    pthread_mutex_init(&pool->mutex, NULL);
#ifdef ENABLE_LOGGING
