    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T *mem_pool_alloc(mem_pool_t *pool, size_t num_elements) {
    if (!pool || !num_elements || pool->capacity <= 0) {
        perror("Invalid arguments");
        return NULL;
    }

    pthread_mutex_lock(&pool->mutex);

    if (num_elements > pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        while (new_capacity < num_elements) {
            new_capacity *= 2;
        }

        NFAPI_CRC_INDICATION_PDU_T *temp_data = realloc(pool->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_data) {
            pthread_mutex_unlock(&pool->mutex);
            perror("Failed to allocate memory for data");
            return NULL;
        }

        pool->data = temp_data;
        pool->capacity = new_capacity;
    }

    size_t *rnti_set = malloc(num_elements * sizeof(size_t));
    if (!rnti_set) {
        pthread_mutex_unlock(&pool->mutex);
        perror("Failed to allocate memory for RNTI set");
        return NULL;
    }

    memset(rnti_set, 0, num_elements * sizeof(size_t));

    NFAPI_CRC_INDICATION_PDU_T *result = pool->data;
    for (size_t i = 0; i < num_elements; ++i) {
        size_t rnti;
        do {
            rnti = rand() % MAX_ELEMENTS;
        } while (rnti_set[rnti] != 0);

        rnti_set[rnti] = 1;
        result[i].tag = rand();
        result[i].crc_indication.tag = rand();
        result[i].rnti = (RNTI)rnti;
        result[i].crcflag = rand() % 2 == 0 ? true : false;

        #ifdef ENABLE_LOGGING
            log_info(pool->log, "Allocated element %zu", i);
        #endif

        ++result;
    }

    free(rnti_set);
    pthread_mutex_unlock(&pool->mutex);

    return result - num_elements;
}

void mem_pool_free(mem_pool_t *pool, NFAPI_CRC_INDICATION_PDU_T *ptr) {
    if (!pool || !ptr || pool->capacity <= 0) {
        perror("Invalid arguments");
        return;
    }

    pthread_mutex_lock(&pool->mutex);

    for (NFAPI_CRC_INDICATION_PDU_T *p = ptr; p < pool->data + pool->size; ++p) {
        pthread_mutex_unlock(&pool->mutex);

        #ifdef ENABLE_LOGGING
            log_debug(pool->log, "Freed element %zu", (ptr - pool->data));
        #endif

        free(ptr);

        ptr = pool->data;
        pthread_mutex_lock(&pool->mutex);
    }

    pool->size -= (ptr - pool->data);

    pthread_mutex_unlock(&pool->mutex);
}
