// Custom packet structure
typedef struct {
    unsigned long length;
    struct in_addr sourceIP;
    char payload[1]; // Dynamic array, size determined at runtime
} Packet;

// Whitelist structure
typedef struct WhitelistNode {
    struct in_addr ip;
    struct WhitelistNode* next;
} WhitelistNode;

void addToWhitelist(WhitelistNode** whitelist, const struct in_addr ip) {
    WhitelistNode* newNode = malloc(sizeof(WhitelistNode));
    if (!newNode) return; // Handle memory allocation failure

    memcpy(&newNode->ip, &ip, sizeof(struct in_addr));
    newNode->next = *whitelist;
    *whitelist = newNode;
}

bool isValidIP(const struct in_addr ip) {
    WhitelistNode* current = whitelist; // Assume a global pointer to the head of the whitelist is provided
    while (current != NULL) {
        if (memcmp(&ip, &current->ip, sizeof(struct in_addr)) == 0) return true;
        current = current->next;
    }
    return false;
}

unsigned int createPackets(Packet** packets, const unsigned int maxCount, const struct in_addr* whitelistIPs, const unsigned int whitelistSize, const unsigned long payloadLimit) {
    unsigned int numValidPackets = 0;
    unsigned int numDiscarded = 0;

    *packets = malloc(maxCount * sizeof(Packet));
    if (!*packets) return 0; // Handle memory allocation failure

    srand(time(NULL)); // Seed random number generator

    for (unsigned int i = 0; i < maxCount; ++i) {
        Packet* packet = *packets + i;

        // Set packet length and source IP randomly, but within constraints
        packet->length = rand() % MAX_LENGTH + MIN_LENGTH;
        if (packet->length > payloadLimit || packet->length <= 0) continue; // Discard packets with invalid lengths

        memcpy(&(packet->sourceIP), whitelistIPs + rand() % whitelistSize, sizeof(struct in_addr));
        if (!isValidIP(packet->sourceIP)) {
            numDiscarded++;
            continue;
        }

        // Calculate payload size and allocate memory for it
        unsigned int payloadSize = packet->length - sizeof(unsigned long) - sizeof(struct in_addr);
        packet->payload = realloc(packet->payload, payloadSize);
        if (!packet->payload) {
            free(*packets); // Free the entire array if memory allocation for a single packet fails
            return numValidPackets;
        }

        // Fill random data into the payload
        for (unsigned int j = 0; j < payloadSize; ++j) {
            packet->payload[j] = rand() % 256;
        }

        numValidPackets++;
    }

    return numValidPackets - numDiscarded; // Return the number of valid packets created, accounting for discarded ones
}
