            return NULL;
        }

        xmlNode *rxInfoNode = xmlXPathSelectElement(ctx->xpathCtx, "./RX_UE_INFORMATION_TAG", crcPduNode);
        if (rxInfoNode == NULL) {
            free(crcPdu);
            continue;
