/* Process variable-length list of integers within a 2MB memory budget */
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    int rnti;
    int crc_indication_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    int key;
    struct Node *left, *right;
    size_t memory_usage;
} BSTNode;

void initializeBSTNode(BSTNode **node) {
    *node = malloc(sizeof(BSTNode));
    (*node)->key = -1;
    (*node)->left = NULL;
    (*node)->right = NULL;
    (*node)->memory_usage = 0;
}

size_t memoryUsage(const BSTNode *node) {
    if (node == NULL) return 0;
    return sizeof(*node) + memoryUsage(node->left) + memoryUsage(node->right);
}

void insertBST(BSTNode **root, int key) {
    if (*root == NULL) {
        initializeBSTNode(root);
        (*root)->key = key;
    } else {
        BSTNode *current = *root;
        bool isLeft = true;

        while (true) {
            if (key < current->key) {
                if (current->left == NULL) {
                    initializeBSTNode(&current->left);
                    current->left->memory_usage += memoryUsage(*root);
                    (*root)->memory_usage++;
                    current = current->left;
                    isLeft = true;
                } else {
                    current = current->left;
                }
            } else if (key > current->key) {
                if (current->right == NULL) {
                    initializeBSTNode(&current->right);
                    current->right->memory_usage += memoryUsage(*root);
                    (*root)->memory_usage++;
                    current = current->right;
                    isLeft = false;
                } else {
                    current = current->right;
                }
            } else {
                // Handle duplicate key if needed
                break;
            }

            if (current->memory_usage > 2000000) {
                printf("Error: Memory budget exceeded\n");
                freeMem(*root);
                *root = NULL;
                current = *root;
                break;
            }
        }

        current->key = key;
    }
}

int findLargest(const BSTNode *root) {
    if (root == NULL) return -1;
    return root->key;
}

void freeMem(BSTNode *node) {
    if (node != NULL) {
        freeMem(node->left);
        freeMem(node->right);
        free(node);
    }
}

void populateNFAPIList(NFAPI_CRC_INDICATION_PDU_T **list, size_t *size) {
    srand(time(NULL));
    *size = 100;
    *list = malloc(*size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (size_t i = 0; i < *size; ++i) {
        (*list)[i].rnti = i + 1;
        (*list)[i].crc_indication_tag = RX_UE_INFORMATION_TAG;
        (*list)[i].crcflag = rand() % 2;
    }
}

void processList(FILE *input, BSTNode **root, NFAPI_CRUC_INDICATION_PDU_T **list, size_t *listSize) {
    int key;
    size_t numKeys = 0;
    populateNFAPIList(list, listSize);

    while ((fscanf(input, "%d", &key)) == 1 && numKeys < 100 + (*listSize)) {
        insertBST(root, key);
        if (numKeys >= *listSize) {
            NFAPI_CRC_INDICATION_PDU_T *nextElem = realloc(*list, (*size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            nextElem[*size].rnti = key;
            nextElem[*size].crc_indication_tag = RX_UE_INFORMATION_TAG;
            nextElem[*size].crcflag = rand() % 2;
            (*list) = nextElem;
            *listSize += 1;
        }
        numKeys++;
    }
}
