};

struct CRC_INDICATION_REL8_TAG {
    bool crcFlag;
};

std::list<std::string> dataFeedList;
std::unordered_map<std::string, NFAPI_CRC_INDICATION_PDU_T> ueInfoCache;
std::mutex dataFeedMutex;
std::mutex pduListMutex;

void pollExternalDataFeed() {
    while (true) {
        std::unique_lock<std::mutex> lock(dataFeedMutex);
        // Simulate fetching new data from an external API
        std::this_thread::sleep_for(std::chrono::seconds(5));

        for (auto data : getDataFromAPI()) {
            lock.unlock();
            insertUEInfoIntoList(data);
            lock.lock();
        }

        lock.unlock();
    }
}

void insertUEInfoIntoList(const std::string& ueId) {
    if (ueInfoCache.find(ueId) == ueInfoCache.end()) {
        // Generate random CRC flag
        auto rng = std::random_device {};
        std::mt19937 gen(rng());
        std::uniform_int_distribution<> dis(0, 1);
        bool crcFlag = dis(gen) == 1;

        NFAPI_CRC_INDICATION_PDU_T pdu { RX_UE_INFORMATION_TAG(), stoi(ueId), CRC_INDICATION_REL8_TAG{crcFlag} };
        std::unique_lock<std::mutex> lock(pduListMutex);
        dataFeedList.push_front(ueId);
        ueInfoCache[ueId] = pdu;
        lock.unlock();
    } else {
        std::unique_lock<std::mutex> lock(pduListMutex);
        auto it = std::find(dataFeedList.begin(), dataFeedList.end(), ueId);
        if (it != dataFeedList.end()) {
            ++it;
            dataFeedList.insert(it, ueId);
            lock.unlock();
        } else {
            lock.unlock();
        }
    }
}

void populateNFAPICRCIndicationList(const std::list<std::string>& inputUEs, const std::string& firstInput, const std::string& secondInput) {
    for (const auto& ue : inputUEs) {
        insertUEInfoIntoList(ue);
    }

    insertUEInfoIntoList(firstInput);
    if (dataFeedList.contains(firstInput)) {
        dataFeedList.erase(std::find(dataFeedList.begin(), dataFeedList.end(), firstInput));
        dataFeedList.insert(std::next(dataFeedList.begin(), std::distance(dataFeedList.begin(), std::find(dataFeedList.begin(), dataFeedList.end(), firstInput))), secondInput);
    } else {
        insertUEInfoIntoList(secondInput);
    }
