#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint64_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

struct dynamic_array {
    Node **data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
};

static inline void init_dynamic_array(struct dynamic_array *arr, size_t capacity) {
    arr->capacity = capacity;
    arr->size = 0;
    arr->data = calloc(capacity, sizeof(Node*));
    if (!arr->data) exit(EXIT_FAILURE);
    pthread_mutex_init(&arr->lock, NULL);
}

static inline bool is_index_valid(const struct dynamic_array *arr, size_t index) {
    return (index >= 0 && index < arr->capacity);
}

static Node* create_node(const NFAPI_CRC_INDICATION_PDU_T data) {
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) exit(EXIT_FAILURE);
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

static inline void insert_node(struct dynamic_array *arr, size_t index, Node* node) {
    pthread_mutex_lock(&arr->lock);
    if (!is_index_valid(arr, index)) {
        pthread_mutex_unlock(&arr->lock);
        free(node);
        return;
    }

    for (size_t i = arr->size; i > index; --i)
        arr->data[i] = arr->data[i - 1];

    arr->data[index] = node;
    ++arr->size;
    pthread_mutex_unlock(&arr->lock);
}

static inline Node* find_node_by_rnti(struct dynamic_array *arr, uint64_t rnti) {
    pthread_mutex_lock(&arr->lock);
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->data[i]->data.rnti == rnti) {
            Node* found_node = arr->data[i];
            pthread_mutex_unlock(&arr->lock);
            return found_node;
        }
    }
    pthread_mutex_unlock(&arr->lock);
    return NULL;
}

static inline void remove_node(struct dynamic_array *arr, size_t index) {
    pthread_mutex_lock(&arr->lock);
    if (!is_index_valid(arr, index)) {
        pthread_mutex_unlock(&arr->lock);
        return;
    }

    for (size_t i = index + 1; i < arr->size; ++i)
        arr->data[i - 1] = arr->data[i];

    free(arr->data[index]);
    --arr->size;
    pthread_mutex_unlock(&arr->lock);
}

static inline void add_new_node(struct dynamic_array *arr, const NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (!new_node) exit(EXIT_FAILURE);

    pthread_mutex_lock(&arr->lock);
    for (size_t i = 0; i < arr->size && find_node_by_rnti(arr, data.rnti); ++i) {}

    if (arr->size == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        Node** new_data = realloc(arr->data, new_capacity * sizeof(Node*));
        if (!new_data) exit(EXIT_FAILURE);
        arr->data = new_data;
        arr->capacity = new_capacity;
    }

    insert_node(arr, arr->size, new_node);
    pthread_mutex_unlock(&arr->lock);
}
