    pthread_mutex_t mutex;
    FILE* file;
} Bundle;

Bundle* init_bundle(const char* path) {
    Bundle* bundle = malloc(sizeof(Bundle));
    if (!bundle) return NULL;

    bundle->size = 0;
    bundle->data = NULL;
    bundle->mutex = PTHREAD_MUTEX_INITIALIZER;
    bundle->file = fopen(path, "r");
    if (!bundle->file) {
        free(bundle);
        return NULL;
    }

    return bundle;
}

void populate_bundle(Bundle* bundle) {
    NFAPI_CRCI_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRCI_INDICATION_PDU_T));
    if (!pdu) return;

    fread(&pdu->tag, sizeof(RX_UE_INFORMATION_TAG), 1, bundle->file);
    fread(&pdu->rnti, sizeof(RNTI), 1, bundle->file);
    fread(&pdu->crc_indication, sizeof(CRC_INDICATION_REL8_TAG), 1, bundle->file);
    fread(&pdu->sequence_number, sizeof(uint32_t), 1, bundle->file);
    fread(&pdu->timestamp, sizeof(uint64_t), 1, bundle->file);
    pdu->crcflag = rand() % 2;

    pthread_mutex_lock(&bundle->mutex);
    if (bundle->size == 0) {
        bundle->data = pdu;
    } else {
        NFAPI_CRCI_INDICATION_PDU_T* temp = realloc(bundle->data, sizeof(NFAPI_CRCI_INDICATION_PDU_T) * (bundle->size + 1));
        if (!temp) {
            pthread_mutex_unlock(&bundle->mutex);
            return;
        }
        bundle->data = temp;
        bundle->data[bundle->size] = pdu;
    }
    bundle->size++;
    pthread_mutex_unlock(&bundle->mutex);
}

size_t get_bundle_size(const Bundle* bundle) {
    return bundle->size;
}

void free_bundle(Bundle* bundle) {
    if (!bundle) return;

    pthread_mutex_destroy(&bundle->mutex);
    fclose(bundle->file);
    free(bundle->data);
    free(bundle);
}
