namespace NFAPI {
    struct CRC_INDICATION_REL8_TAG {
        bool CRCFLAG;
    };

    struct RX_UE_INFORMATION_TAG {
        uint64_t value;
        RX_UE_INFORMATION_TAG() : value(std::hash<std::string>{}(__func__)) {}
    };

    struct RNTI {
        uint64_t value;
        RNTI() : value(std::hash<std::string>{}(__func__)) {}
    };

