        RX_UE_INFORMATION_TAG rxUEInformationTag;
        RNTI rnti;
        CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
    };

    std::forward_list<std::string>* g_dataStream;
    std::mutex g_mutex;

    void populateNFAPICRCIndicationList(const std::forward_list<std::string>& data, const std::string& firstKey, const std::string& secondKey) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 1);

        std::forward_list<NFAPI_CRC_INDICATION_PDU_T> indicationList;

        for (const auto& item : data) {
            if (*g_dataStream.get() == firstKey) {
                g_mutex.lock();
                indicationList.emplace_after(*g_dataStream, NFAPI_CRC_INDICATION_PDU_T{});
                g_mutex.unlock();
                *static_cast<NFAPI_CRC_INDICATION_PDU_T*>(indicationList.last())->rnti.value = std::hash<std::string>{}(secondKey);
                static_cast<NFAPI_CRC_INDICATION_PDU_T*>(indicationList.last())->crcIndicationRel8Tag.CRCFLAG = dis(gen);
            }

            g_mutex.lock();
            indicationList.emplace_back(NFAPI_CRC_INDICATION_PDU_T{});
            g_mutex.unlock();
        }

        if (!std::find(*g_dataStream.get(), data.end(), firstKey) && data.size()) {
            g_mutex.lock();
            indicationList.emplace_back(NFAPI_CRC_INDICATION_PDU_T{});
            *static_cast<NFAPI_CRC_INDICATION_PDU_T*>(indicationList.last())->rnti.value = std::hash<std::string>{}(secondKey);
            static_cast<NFAPI_CRC_INDICATION_PDU_T*>(indicationList.last())->crcIndicationRel8Tag.CRCFLAG = dis(gen);
            g_mutex.unlock();
        }
    }

    void performanceMonitor(int intervalSeconds) {
        using namespace std::chrono;
        using namespace boost::asio;
        steady_timer timer(steady_clock::now() + seconds(intervalSeconds));

        auto start = steady_clock::now();
        int opsPerSec = 0;
        size_t itemCount = 0;

        for (;;) {
            auto end = steady_clock::now();
            auto duration = duration_cast<microseconds>(end - start);

            if (duration > microseconds(1000000 / intervalSeconds)) {
                opsPerSec = itemCount * intervalSeconds / duration.count();
                itemCount = 0;
                start = end;
            }

            ++itemCount;

            if (timer.expires_at() <= steady_clock::now()) {
                BOOST_LOG_TRIVIAL(info) << "Ops per second: " << opsPerSec << ", Average insertion time: " << duration.count() / itemCount * 1e6 << "us, Memory usage: <calculate memory usage>";
                timer.restart();
            }
        }
    }
} // namespace NFAPI
