struct UTRANMessage {
    std::string message;
    unsigned int mme_id;
};

class MessageManager {
private:
    std::list<UTRANMessage> messages;
    std::mutex mtx;
    std::condition_variable cv;
    bool is_allocating = false;
    pthread_cond_t mem_cond; // Used for thread signaling

    static constexpr size_t THRESHOLD = 100;
    static std::atomic<size_t> num_large_msgs = { 0 };
    static std::function<void(const UTRANMessage&)> log_callback;

public:
    MessageManager() {
        pthread_condattr_t attr;
        pthread_condattr_init(&attr);
        pthread_condattr_setclock(&attr, CLOCK_MONOTONIC);
        pthread_cond_init(&mem_cond, &attr);
    }

    // Add message to the list and log it if necessary
    void add_message(const UTRANMessage& msg) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !is_allocating; });

        messages.emplace_back(msg);
        log_if_necessary(msg);

        is_allocating = false;
        lock.unlock();
        cv.notify_one();
    }

    // Allocate memory for a new message if possible, signaling other threads to wait
    void allocate_memory() {
        std::unique_lock<std::mutex> lock(mtx);
        is_allocating = true;
        cv.notify_all();
    }

    // Deallocate memory when done with messages, release the waiting thread
    void deallocate_memory() {
        std::unique_lock<std::mutex> lock(mtx);
        lock.unlock();
        cv.notify_one();
    }

    static void setLogCallback(const std::function<void(const UTRANMessage&)>& cb) {
        log_callback = cb;
    }
};
```

