            throw std::runtime_error("Out of memory");
        }
        data.emplace_back(std::make_unique<NFAPI_CRC_INDICATION_PDU_T>(item));
        rntiToIndexMap[item.rnti] = data.size() - 1;
    }

    const NFAPI_CRC_INDICATION_PDU_T* get(const RNTI& rnti) {
        auto it = rntiToIndexMap.find(rnti);
        if (it == rntiToIndexMap.end()) {
            return nullptr;
        }
        std::lock_guard<std::mutex> lock(mtx);
        return data[it->second].get();
    }

    bool removeByIndex(size_t index) {
        if (index >= data.size()) {
            return false;
        }

        auto it = rntiToIndexMap.find(data[index]->rnti);
        if (it == rntiToIndexMap.end()) {
            // Handle memory allocation failure gracefully
            if (index != data.size() - 1) {
                throw std::runtime_error("Internal data inconsistency");
            }
            data.pop_back();
            return true;
        }

        rntiToIndexMap.erase(it);
        data[index].reset();
        return true;
    }
};

