```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct ResourceBundle {
    int count;
    char **items;
} ResourceBundle;

int LoadResourceBundle(const char *path, ResourceBundle **bundle)
{
    FILE *file = fopen(path, "r");
    if (!file)
    {
        perror("Failed to open resource bundle file");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    char *buffer = malloc(fileSize + 1);
    if (!buffer)
    {
        perror("Failed to allocate memory for buffer");
        fclose(file);
        return -1;
    }

    size_t bytesRead = fread(buffer, sizeof(char), fileSize, file);
    if (bytesRead != fileSize)
    {
        perror("Failed to read resource bundle file");
        free(buffer);
        fclose(file);
        return -1;
    }

    buffer[fileSize] = '\0';
    char *token = strtok(buffer, "\n");
    int itemCount = 0;

    ResourceBundle *rb = malloc(sizeof(ResourceBundle));
    if (!rb)
    {
        perror("Failed to allocate memory for resource bundle");
        free(buffer);
        fclose(file);
        return -1;
    }

    while (token != NULL)
    {
        rb->items = realloc(rb->items, sizeof(char *) * ++itemCount);
        if (!rb->items)
        {
            perror("Failed to allocate memory for resource bundle items");
            free(buffer);
            fclose(file);
            free(rb);
            return -1;
        }

        rb->items[itemCount - 1] = strdup(token);
        if (!rb->items[itemCount - 1])
        {
            perror("Failed to allocate memory for a resource bundle item");
            free(buffer);
            fclose(file);
            for (int i = 0; i < itemCount - 1; ++i)
                free(rb->items[i]);
            free(rb->items);
            free(rb);
            return -1;
        }

        token = strtok(NULL, "\n");
    }

    fclose(file);
    rb->count = itemCount;

    *bundle = rb;
    return 0;
}
