#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>

typedef struct ConnectionConnection;
typedef struct ConnectionManager ConnectionManager;

struct Connection {
    int sockfd;
    struct sockaddr_in peer_addr;
};

struct ConnectionManager {
    size_t capacity;
    size_t size;
    struct Connection *connections;
    pthread_mutex_t lock;
};

ConnectionManager* connection_manager_new(size_t initial_capacity) {
    if (initial_capacity == 0)
        initial_capacity = 16;

    ConnectionManager *self = malloc(sizeof(ConnectionManager));
    if (!self) {
        fprintf(stderr, "Failed to allocate memory for ConnectionManager\n");
        return NULL;
    }

    self->capacity = initial_capacity;
    self->size = 0;
    self->connections = calloc(initial_capacity, sizeof(struct Connection));
    if (!self->connections) {
        free(self);
        fprintf(stderr, "Failed to allocate memory for connections\n");
        return NULL;
    }

    pthread_mutex_init(&self->lock, NULL);

    return self;
}

bool connection_manager_add(ConnectionManager *self, int sockfd, const char *ip, unsigned short port) {
    if (!self || !sockfd || !ip || !port) {
        fprintf(stderr, "Invalid input provided to ConnectionManager::add\n");
        return false;
    }

    struct addrinfo hints = {0};
    struct addrinfo *res = NULL;

    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    int err = getaddrinfo(ip, NULL, &hints, &res);
    if (err != 0 || !res) {
        fprintf(stderr, "Invalid IP address or port number provided to ConnectionManager::add\n");
        return false;
    }

    struct sockaddr_in *peer_addr = (struct sockaddr_in *) res->ai_addr;
    peer_addr->sin_port = htons(port);

    pthread_mutex_lock(&self->lock);

    if (self->size >= self->capacity) {
        size_t new_capacity = self->capacity * 2;
        self->connections = realloc(self->connections, new_capacity * sizeof(struct Connection));
        if (!self->connections) {
            fprintf(stderr, "Failed to reallocate memory for connections in ConnectionManager::add\n");
            pthread_mutex_unlock(&self->lock);
            return false;
        }
        self->capacity = new_capacity;
    }

    self->connections[self->size].sockfd = sockfd;
    memcpy(&self->connections[self->size].peer_addr, peer_addr, sizeof(struct sockaddr_in));
    self->size++;

    pthread_mutex_unlock(&self->lock);
    freeaddrinfo(res);

    return true;
}

const Connection* connection_manager_get(const ConnectionManager *self, size_t index) {
    if (!self || index >= self->size)
        return NULL;

    pthread_mutex_lock(&self->lock);

    const Connection *connection = &self->connections[index];

    pthread_mutex_unlock(&self->lock);

    return connection;
}
```

