#define MAX_LIST_SIZE 1024

typedef struct _node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct _node *next;
} node_t;

static node_t* head = NULL;
static int list_size = 0;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

int add_PDU(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (list_size + 1 > MAX_LIST_SIZE) {
        return -1; // Error: List size exceeded
    }

    node_t* new_node = malloc(sizeof(node_t));
    if (!new_node) {
        return -2; // Error: Memory allocation failure
    }

    new_node->data = *pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list_mutex);

    node_t* current = head;
    if (!current) {
        head = new_node;
        list_size++;
        log_info("Added new PDU to the list.");
    } else {
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
        list_size++;
        log_info("Added new PDU to the list.");
    }

    pthread_mutex_unlock(&list_mutex);

    return 0; // Success
}

void free_list() {
    pthread_mutex_lock(&list_mutex);

    node_t* current = head;
    node_t* temp;

    while (current) {
        temp = current;
        current = current->next;
        free(temp);
    }

    head = NULL;
    list_size = 0;
    pthread_mutex_unlock(&list_mutex);
}
