import java.sql.*;
import java.io.File;
import java.lang.reflect.Field;
import java.util.*;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;

public class QueryExecutor {
    private static final String SQL_SEPARATOR = ";";
    private static final String INDENT = "  ";

    public IDataReader executeDynamicQuery(String configPath, String queryTemplate, List<Object> parameters, Connection connection) throws Exception {
        Properties props = new Properties();
        props.load(new FileReader(configPath));

        // Load database driver and establish a connection using the provided configuration properties
        String driver = props.getProperty("driver");
        String url = props.getProperty("url");
        String username = props.getProperty("username");
        String password = props.getProperty("password");

        try (Connection dbConnection = DriverManager.getConnection(url, username, password)) {
            Statement stmt = dbConnection.createStatement();
            StringBuilder sql = new StringBuilder();
            StringBuilder paramsSql = new StringBuilder();

            // Construct SQL command using the provided template and parameters
            String[] queryParts = queryTemplate.split(SQL_SEPARATOR);
            for (String part : queryParts) {
                if (!part.isEmpty()) {
                    if (part.startsWith("{")) {
                        int index = Integer.parseInt(part.substring(1, part.indexOf('}')));
                        sql.append(parameters.get(index));
                        paramsSql.append(String.format("%s", parameters.get(index)).replaceAll("'", "\\'"));
                    } else {
                        sql.append(part);
                    }
                }
            }

            // Add parameters to the SQL command for query execution
            if (!paramsSql.toString().isEmpty()) {
                sql.append(SQL_SEPARATOR).append(paramsSql);
            }

            ResultSet resultSet = stmt.executeQuery(sql.toString());
            return new DataReader(resultSet);
        } catch (Exception e) {
            // Log the error and handle it appropriately
            throw new Exception("Error executing dynamic query", e);
        }
    }
}
```

