#define MAX_BUFFER_SIZE 1024
#define MIN_CRC_THRESHOLD 75

typedef struct {
    LTE_PHY_RX_FRAME frame;
    LTE_RXUEINFO_TAG tag;
    LTE_RNTI rnti;
    LTE_PHY_CRC_INDICATOR_TAG *crc_indicator;
    bool crcflag;
} lte_rx_frame_t;

typedef struct {
    lte_rx_frame_t buffer[MAX_BUFFER_SIZE];
    size_t head, tail;
    pthread_mutex_t mutex;
    void (*data_source)(void*, LTE_RX_QUALITY_METRIC, bool); // External data source callback
    void (*log_func)(const char*, const char*, double, int); // Logging function
} lte_rx_frames_t;

lte_rx_frames_t* init_lte_rx_frames(void (*data_source)(void*, LTE_RX_QUALITY_METRIC, bool), void (*log_func)(const char*, const char*, double, int)) {
    lte_rx_frames_t *rx_frames = mmap(NULL, sizeof(lte_rx_frames_t), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (rx_frames == MAP_FAILED) {
        perror("mmap");
        return NULL;
    }

    pthread_mutex_init(&rx_frames->mutex, NULL);
    rx_frames->head = rx_frames->tail = 0;
    rx_frames->data_source = data_source;
    rx_frames->log_func = log_func;

    return rx_frames;
}

void configure_lte_rx_frame(lte_rx_frame_t *frame, LTE_RXUEINFO_TAG tag, LTE_RNTI rnti, double quality) {
    frame->tag = tag;
    frame->rnti = rnti;
    frame->crc_indicator = malloc(sizeof(LTE_PHY_CRC_INDICATOR_TAG));
    if (!frame->crc_indicator) {
        perror("malloc");
        return;
    }

    frame->crcflag = quality >= MIN_CRC_THRESHOLD;
}

void process_lte_rx_frames(lte_rx_frames_t *rx_frames) {
    pthread_mutex_lock(&rx_frames->mutex);
    size_t count = rx_frames->head - rx_frames->tail;
    if (count == 0) {
        pthread_mutex_unlock(&rx_frames->mutex);
        return;
    }

    lte_rx_frame_t *first_frame = &rx_frames->buffer[rx_frames->head];
    size_t frames_to_process = count > MAX_BUFFER_SIZE ? MAX_BUFFER_SIZE : count;

    for (size_t i = 0; i < frames_to_process; ++i) {
        rx_frames->data_source(rx_frames, first_frame->frame.quality, first_frame->crcflag);
        if (rx_frames->log_func) {
            rx_frames->log_func("Frame Processing Time", "ms", 1000 * clock() - first_frame->frame.timestamp, first_frame->rnti);
        }

        // Buffer management logic goes here based on your chosen strategy

        ++rx_frames->tail;
    }

    pthread_mutex_unlock(&rx_frames->mutex);
}
```
