typedef struct {
    long offset;
    int key;
    double value;
} record;

typedef struct data_container {
    size_t offset_size;
    size_t offset_capacity;
    size_t key_size;
    size_t key_capacity;
    size_t record_size;
    size_t record_capacity;
    long *offsets;
    int *keys;
    record *records;
} data_container;

data_container* create_data(size_t limit, size_t record_threshold, size_t key_range, const char* allowed_values) {
    size_t offset_capacity = (limit + 7) / 8;
    size_t key_capacity = key_range;
    size_t record_capacity = offset_capacity * key_capacity;

    data_container* container = malloc(sizeof(data_container));
    if (!container) {
        perror("Failed to allocate data container");
        return NULL;
    }

    container->offset_size = sizeof(long);
    container->key_size = sizeof(int);
    container->record_size = sizeof(record);

    container->offsets = calloc(offset_capacity, container->offset_size);
    if (!container->offsets) {
        perror("Failed to allocate offset array");
        free(container);
        return NULL;
    }

    container->keys = calloc(key_capacity, container->key_size);
    if (!container->keys) {
        perror("Failed to allocate key array");
        free(container->offsets);
        free(container);
        return NULL;
    }

    container->records = malloc(record_capacity * container->record_size);
    if (!container->records) {
        perror("Failed to allocate record array");
        free(container->keys);
        free(container->offsets);
        free(container);
        return NULL;
    }

    srand(time(NULL));
    size_t used_keys = 0;

    // External data source validation and duplicate removal, implement using allowed_values and unique key checking
    // ...

    for (size_t i = 0; i < key_capacity && used_keys < key_capacity; ++i) {
        if (container->keys[i] == -1) { // Mark as used
            container->keys[i] = i;
            used_keys++;
        }
    }

    if (used_keys != key_range) {
        perror("Failed to allocate sufficient keys");
        free(container->records);
        free(container->offsets);
        free(container->keys);
        free(container);
        return NULL;
    }

    for (size_t i = 0; i < record_capacity; ++i) {
        size_t key = container->keys[i / key_capacity];
        if (key >= used_keys) { // Invalid key index, handle error gracefully
            break;
        }
        container->records[i].offset = (i + 1) * 8;
        container->records[i].key = key;
        container->records[i].value = (double)(rand() % record_threshold);
    }

    container->offset_capacity = offset_capacity;
    container->key_capacity = key_capacity;
    container->record_capacity = record_capacity;

    return container;
}
