typedef struct {
    uint32_t PDU_SESSION_ID;
    char NAS_PDU[MAX_NAS_PDU];
    char UE_IP_ADDRESS[MAX_UE_IP_ADDRESS];
} NRUE_CONTEXT_T;

#define N 1024 // Maximum list size

struct session_manager {
    NRUE_CONTEXT_T* sessions;
    int count;
    sem_t mutex;
    sem_t not_full;
    bool shutdown;
};

void session_init(struct session_manager* manager) {
    manager->sessions = calloc(N, sizeof(NRUE_CONTEXT_T));
    if (!manager->sessions) {
        fprintf(stderr, "Failed to allocate memory\n");
        return;
    }

    manager->count = 0;
    sem_init(&manager->mutex, 0, 1); // Mutex is initially locked
    sem_init(&manager->not_full, 0, N); // Semaphore starts full
    manager->shutdown = false;
}

NRUE_CONTEXT_T* session_pop(struct session_manager* manager) {
    NRUE_CONTEXT_T* session;
    sem_wait(&manager->not_full);
    sem_wait(&manager->mutex);

    if (manager->count == 0 || manager->shutdown) {
        session = NULL;
    } else {
        session = &manager->sessions[--manager->count];
    }

    sem_post(&manager->mutex);

    return session;
}

void session_push(struct session_manager* manager, NRUE_CONTEXT_T* session) {
    int i;
    sem_wait(&manager->mutex);

    if (manager->count >= N || manager->shutdown) {
        free(session);
        sem_post(&manager->mutex);
        return;
    }

    // Search for a gap in PDU_SESSION_ID sequence
    for (i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].PDU_SESSION_ID + 1 == manager->sessions[i + 1].PDU_SESSION_ID) {
            break;
        }
    }

    // Fill the gap with session if found, or insert at the end otherwise
    if (i < manager->count) {
        for (; i < manager->count; ++i) {
            manager->sessions[i] = manager->sessions[i + 1];
        }
    }

    session->PDU_SESSION_ID = manager->count;
    memcpy(manager->sessions + manager->count, session, sizeof(NRUE_CONTEXT_T));
    ++manager->count;

    sem_post(&manager->mutex);
}

void session_shutdown(struct session_manager* manager) {
    manager->shutdown = true;
    sem_post(&manager->not_full);
}
```

