void* mem_align(size_t align, size_t bytes) {
    void *mem = mmap(NULL, bytes + align - 1, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mem == MAP_FAILED)
        return NULL;
    return (char*) mem + align - 1 & ~(align - 1);
