FrameMetadata* frame_metadata_new() {
    FrameMetadata* metadata = malloc(sizeof(FrameMetadata));
    if (!metadata) return NULL;

    metadata->num_signals = 0;
    metadata->signal_qualities = NULL;
    init_signal_quality(&metadata->signal_qualities[0]);

    return metadata;
}

void frame_metadata_resize(FrameMetadata* metadata, int new_capacity) {
    if (new_capacity <= metadata->num_signals) return;

    SignalQuality* tmp = realloc(metadata->signal_qualities, new_capacity * sizeof(SignalQuality));
    if (!tmp) {
        fprintf(stderr, "Failed to resize signal quality array.\n");
        exit(1);
    }

    metadata->signal_qualities = tmp;
    for (int i = metadata->num_signals; i < new_capacity; ++i) {
        init_signal_quality(&metadata->signal_qualities[i]);
    }
}

void frame_metadata_append(FrameMetadata* metadata, const SignalQuality* sq, double transmission_power) {
    if (metadata->num_signals >= metadata->capacity) frame_metadata_resize(metadata, metadata->num_signals * 2);

    metadata->signal_qualities[metadata->num_signals] = *sq;
    metadata->transmission_power = transmission_power;
    ++metadata->num_signals;
}

void update_signal_quality(FrameMetadata* metadata, const SignalQuality* sq) {
