        init_signal_quality(sq);
        metadata->signal_qualities[0] = *sq;
        metadata->num_signals = 1;
        return;
    }

    // Update each signal quality indicator considering the new measurement and network conditions.
    // This function should take into account latency, jitter, loss, and other factors depending on your specific requirements.
}

FrameStatus frame_metadata_is_corrupted(const FrameMetadata* metadata) {
    if (metadata->num_signals == 0) return OK;

    double avg_loss = 0.0;
    for (int i = 0; i < metadata->num_signals; ++i) {
        avg_loss += metadata->signal_qualities[i].loss;
    }
    avg_loss /= metadata->num_signals;

    if (avg_loss > MAX_ALLOWED_LOSS) return CORRUPTED;

    return OK;
}

void log_corrupted_frame(const FrameMetadata* metadata, const char* location) {
