```c
#include <math.h>

float mean(const float *arr, int len) {
    float sum = 0;
    for (int i = 0; i < len; ++i)
        sum += arr[i];
    return sum / len;
}

float stdev(const float *arr, int len, float mean) {
    float sum_of_squares = 0;
    for (int i = 0; i < len; ++i)
        sum_of_squares += pow((arr[i] - mean), 2);
    return sqrt(sum_of_squares / len);
}
