    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void allocateAndPopulateUEArray(NFAPI_CRC_INDICATION_PDU_T** array, size_t* size) {
    *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*array) {
        fprintf(stderr, "Failed to allocate memory\n");
        return;
    }

    size_t used = 0;
    NFAPI_CRC_INDICATION_PDU_T* current = *array;

    // Generate and validate RNTIs within the array
    for (size_t i = 0; i < *size && used < *size; ++i) {
        uint16_t rnti = arc4random() % MAX_UE; // Replace with your preferred random number generation strategy

        bool unique = true;
        for (size_t j = used; j < used + 10; ++j) // Adjust buffer to accommodate potential delays in RNTI values
            if (current[j].RNTI == rnti) {
                unique = false;
                break;
            }

        if (unique) {
            current[used].RX_UE_INFORMATION_TAG = 0x12; // Replace with your desired initial value
            current[used].RNTI = rnti;
            current[used].CRC_INDICATION_REL8_TAG = arc4random() % 2; // Replace with your desired CRCFLAG initial value
            ++used;
        }
    }

    if (used != *size) {
        fprintf(stderr, "RNTI collision detected. Allocated %zu elements out of requested %zu.\n", used, *size);
        free(*array);
        *size = 0;
        *array = NULL;
    } else {
        *size = used;
    }
}
