void seed_random(uint32_t time_seed) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += time_seed;
    srand48(ts.tv_nsec * 1e-9 + ts.tv_sec);
}

void* allocate_memory(size_t count) {
    void *memory = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!memory) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
    return memory;
