    NFAPI_CRC_INDICATION_PDU_T* structures = data;
    for (size_t i = 0; i < count; ++i) {
        seed_random((unsigned int)time(NULL));
        structures[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG;
        structures[i].rnti = RNTI + i;
        structures[i].crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG;
