// Predefined cell ID range and resource thresholds
#define CELL_ID_MIN 0
#define CELL_ID_MAX 1000
#define BANDWIDTH_THRESHOLD 500
#define POWER_THRESHOLD 1.0

// UE structure definition
typedef struct {
    int id;
    int cell_id;
    int bandwidth;
    double power;
    pthread_mutex_t resource_lock;
} UE;

// External system interface for real-time monitoring and adaptive parameter adjustments
void updateUEParameters(UE* ue, double newBandwidth, double newPower);

// Global variables for concurrent access control
pthread_mutex_t collection_lock = PTHREAD_MUTEX_INITIALIZER;
int next_id = 1;
int available_cell_ids[CELL_ID_MAX + 1]; // +1 for reserved unused cell ID
size_t num_available_cell_ids = CELL_ID_MAX + 1;

// Function to initialize and configure UE collection based on network load metrics
void initUECollection(int maxUENumber) {
    UE* ues = mmap(NULL, maxUENumber * sizeof(UE), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);

    for (int i = 0; i < maxUENumber; ++i) {
        UE* ue = &ues[i];
        ue->id = next_id++;
        ue->cell_id = selectCellID(available_cell_ids, num_available_cell_ids);
        ue->bandwidth = rand() % (BANDWIDTH_THRESHOLD + 1) + BANDWIDTH_THRESHOLD / 2;
        ue->power = rand() % (int)(POWER_THRESHOLD * 100) / 100.0;
        pthread_mutex_init(&ue->resource_lock, NULL);
    }
}

// Function to select a dynamically available cell ID from the predefined range
int selectCellID(int* available_cell_ids, size_t num_available_cell_ids) {
    if (num_available_cell_ids <= 0) {
        fprintf(stderr, "No available cell IDs\n");
        return -1;
    }

    int index = rand() % num_available_cell_ids;
    int cell_id = available_cell_ids[index];
    for (size_t i = index + 1; i < num_available_cell_ids; ++i) {
        if (!available_cell_ids[i]) {
            cell_id = available_cell_ids[i];
            break;
        }
    }

    if (index == num_available_cell_ids - 1) { // Wrap around
        for (size_t i = 0; i < index; ++i) {
            if (!available_cell_ids[i]) {
                cell_id = available_cell_ids[i];
                break;
            }
        }
    }

    available_cell_ids[index] = 0;
    --num_available_cell_ids;
    return cell_id;
}

