#include <pthread.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T* data;
} CRCI_PDU_POOL_T;

CRCI_PDU_POOL_T* crc_pdu_pool_create(size_t capacity) {
    if (capacity == 0) return NULL;

    CRCI_PDU_POOL_T* pool = malloc(sizeof(CRCI_PDU_POOL_T));
    if (!pool) return NULL;

    pool->capacity = capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    pool->data = calloc(capacity, sizeof(NFAPI_CRCI_PDU_T));
    if (!pool->data) {
        free(pool);
        return NULL;
    }

    return pool;
}

NFAPI_CRC_INDICATION_PDU_T* crc_pdu_pool_get(CRCI_PDU_POOL_T* pool) {
    if (!pool || !pool->data) return NULL;

    pthread_mutex_lock(&pool->lock);

    if (pool->count < pool->capacity) {
        // Populate the structure with valid values
        NFAPI_CRC_INDICATION_PDU_T* pdu = &pool->data[pool->count];
        pdu->rx_ue_information_tag.value = 0xDEADBEEF;
        pdu->rnti.value = 0xCAFEBABE;
        pdu->crc_indication_rel8_tag.crcflag = (rand() % 2);

        pool->count++;
    }

    pthread_mutex_unlock(&pool->lock);

    return pool->data[pool->count - 1];
}

void crc_pdu_pool_destroy(CRCI_PDU_POOL_T* pool) {
    if (!pool || !pool->data) return;

    pthread_mutex_destroy(&pool->lock);
    free(pool->data);
    free(pool);
}
