#include <time.sh>

#define MAX_BUFFER_SIZE 65536
#define NUM_POOLS 128

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Pool {
    void* buffer;
    size_t buffer_size;
    size_t buffer_index;
    pthread_mutex_t mutex;
    bool is_empty;
} Pool;

Pool* create_pool(size_t size) {
    Pool* pool = (Pool*)malloc(sizeof(Pool));
    if (!pool) {
        log_error("Failed to allocate memory for pool");
        return NULL;
    }

    pool->buffer_size = size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pool->buffer = calloc(pool->buffer_size, 1);
    if (!pool->buffer) {
        log_error("Failed to allocate memory for pool buffer");
        free(pool);
        return NULL;
    }

    pool->buffer_index = 0;
    pool->is_empty = true;
    pthread_mutex_init(&pool->mutex, NULL);

    return pool;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_crc_indications(int entries, unsigned seed) {
    static Pool* pools[NUM_POOLS];
    int pool_index = -1;

    if (entries <= 0) {
        log_error("Invalid number of entries provided");
        return NULL;
    }

    for (int i = 0; i < NUM_POOLS; ++i) {
        Pool* pool = pools[i];
        if (!pool || pool->is_empty) {
            pool_index = i;
            break;
        }
    }

    if (pool_index == -1) {
        pool_index = rand() % NUM_POOLS;
        if (!pools[pool_index]) {
            pools[pool_index] = create_pool(MAX_BUFFER_SIZE / entries);
            if (!pools[pool_index]) {
                log_error("Failed to allocate memory for pool");
                return NULL;
            }
        }
    }

    Pool* pool = pools[pool_index];
    NFAPI_CRC_INDICATION_PDU_T* buffer = (NFAPI_CRC_INDICATION_PDU_T*)(pool->buffer + pool->buffer_index);
    pool->buffer_index += entries * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (pool->buffer_index >= pool->buffer_size) {
        pthread_mutex_lock(&pool->mutex);
        Pool* new_pool = create_pool((MAX_BUFFER_SIZE / entries) * 2);
        if (!new_pool) {
            log_error("Failed to allocate memory for new pool");
            pthread_mutex_unlock(&pool->mutex);
            return NULL;
        }

        memcpy(new_pool->buffer, pool->buffer, pool->buffer_index);
        free(pool);
        pools[pool_index] = new_pool;
        pool = new_pool;
    }

    pool->is_empty = false;
    pthread_mutex_unlock(&pool->mutex);

    srand(seed);
    for (int i = 0; i < entries; ++i) {
        buffer[i].rx_ue.tag = rand() % MAX_BUFFER_SIZE;
        buffer[i].rnti = rand() % MAX_BUFFER_SIZE;
        buffer[i].crc_ind.crcflag = (rand() % 2) == 0 ? true : false;
    }

    return buffer;
}
