// Function for adding a measurement to the list
int add_measurement(const LTE_PHY_MEASUREMENT* measurement) {
    if (measurements_count >= measurements_capacity) {
        // Resize array when it reaches capacity
        size_t new_capacity = measurements_capacity * 2;
        LTE_PHY_MEASUREMENT* new_array = realloc(measurements, new_capacity * sizeof(LTE_PHY_MEASUREMENT));
        if (!new_array) {
            return -1; // Failed to allocate memory
        }
        measurements = new_array;
        measurements_capacity = new_capacity;
    }

    pthread_mutex_lock(&measurements_lock);

    measurements[measurements_count] = *measurement;
    measurements_count++;

    pthread_mutex_unlock(&measurements_lock);

    return 0; // Successfully added measurement
}

// Function for removing a measurement from the list by index
int remove_measurement(size_t index) {
    if (index >= measurements_count || measurements_count == 0) {
        return -1; // Index out of range or empty list
    }

    pthread_mutex_lock(&measurements_lock);

    for (size_t i = index; i < measurements_count - 1; i++) {
        measurements[i] = measurements[i + 1];
    }

    measurements_count--;

    pthread_mutex_unlock(&measurements_lock);

    return 0; // Successfully removed measurement
}

// Function for updating a measurement in the list by index
int update_measurement(size_t index, const LTE_PHY_MEASUREMENT* new_measurement) {
    if (index >= measurements_count || measurements_count == 0) {
        return -1; // Index out of range or empty list
    }

    pthread_mutex_lock(&measurements_lock);

    LTE_PHY_MEASUREMENT* measurement = &measurements[index];
    *measurement = *new_measurement;

    pthread_mutex_unlock(&measurements_lock);

    return 0; // Successfully updated measurement
}
