ListNode* createNode() {
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) {
        perror("Memory allocation failure");
        return NULL;
    }
    newNode->next = NULL;
    return newNode;
}

void initData(NFAPI_CRC_INDICATION_PDU_T* data, uint16_t tag, uint16_t rnti, uint16_t crc_tag, uint16_t crcflag) {
    data->RX_UE_INFORMATION_TAG = tag;
    data->RNTI = rnti;
    data->CRC_INDICATION_REL8_TAG = crc_tag;
    data->CRCFLAG = crcflag;
}

ListNode* append(ListNode** head, NFAPI_CRC_INDICATION_PDU_T data) {
    ListNode* newNode = createNode();
    if (!newNode) return *head; // Return the existing list if memory allocation fails
    initData(&(newNode->data), data.RX_UE_INFORMATION_TAG, data.RNTI, data.CRC_INDICATION_REL8_TAG, rand() % 2);
    ListNode* current = *head;
    if (!current) {
        *head = newNode;
        return *head;
    }
    while (current->next) current = current->next;
    current->next = newNode;
    return *head;
}

ListNode* find(ListNode* head, uint16_t tag) {
    ListNode* current = head;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == tag) break;
        current = current->next;
    }
    return current;
}

void remove(ListNode** head, uint16_t tag) {
    ListNode* current = *head;
    if (!current) return; // Empty list case
    if (current->data.RX_UE_INFORMATION_TAG == tag) {
        *head = current->next;
        free(current);
        return;
    }
    ListNode* previous = current;
    current = current->next;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == tag) {
            previous->next = current->next;
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
}

void iterate(ListNode* head) {
    ListNode* current = head;
    while (current) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRC_INDICATION_REL8_TAG: %u, CRCFLAG: %u\n",
               current->data.RX_UE_INFORMATION_TAG, current->data.RNTI,
               current->data.CRC_INDICATION_REL8_TAG, current->data.CRCFLAG);
        current = current->next;
    }
}

void freeList(ListNode** head) {
    ListNode* temp;
    while (*head) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}
