#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    uint64_t UE_ID;
    enum RRC_STATE RRC_STATE;
    uint32_t NAS_MESSAGE_TAG;
    time_t last_processed_timestamp;
} NR_UE_CONTEXT_T;

typedef struct node {
    NR_UE_CONTEXT_T data;
    struct node *next;
} Node;

struct list {
    pthread_mutex_t mutex;
    int capacity, size;
    Node *head, *tail;
};

// Create a new list with given initial capacity
List* create_list(int cap) {
    List* list = (List*)malloc(sizeof(List));
    list->capacity = cap;
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Free all allocated memory in the list
void free_list(List* list) {
    Node *temp;
    while (list->head != NULL) {
        temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

// Insert an element at the tail of the list, handling collisions by logging an error message and releasing any allocated memory
void insert_tail(List* list, NR_UE_CONTEXT_T data) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        fprintf(stderr, "UE_ID collision: %llu\n", data.UE_ID);
        free_list(list);
        return;
    }

    if (!list->head) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    ++(list->size);
    pthread_mutex_unlock(&list->mutex);
}

// Periodically prune the list to maintain a manageable size, balancing the need for historical context against current operational efficiency
void prune_list(List* list) {
    double pruning_threshold = 0.75; // Adjust as needed

    pthread_mutex_lock(&list->mutex);
    if (list->size <= pruning_threshold * list->capacity) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    Node *current = list->head, *temp;
    while (current != NULL && list->size > pruning_threshold * list->capacity) {
        temp = current;
        current = current->next;
        free(temp);
        --list->size;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to manage and process a dynamic list of NR_UE_CONTEXT_T structures, handling error-free population, uniqueness validation, memory allocation, and potential delays in data availability
void process_ue_context_list(List* list) {
    pthread_mutex_lock(&list->mutex);
    Node *current = list->head;
    while (current != NULL) {
        if (current->data.UE_ID == current->next->data.UE_ID) {
            fprintf(stderr, "UE_ID collision: %llu\n", current->data.UE_ID);
            free_list(list);
            return;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}
