    uint16_t PHY_RXINFO_TAG;
    float signal_quality_metric; // Replace with the actual data type used in your system
} LTE_PHY_RXUEINFO_T;

sem_t mutex; // Mutex for synchronization
pthread_cond_t not_full; // Condition variable to wait when array is full
pthread_cond_t not_empty; // Condition variable to wait when array is empty
size_t array_size = 0; // Current size of the array
size_t capacity = 0; // Maximum capacity of the array
LTE_PHY_RXUEINFO_T *data = NULL; // Pointer to the dynamic array

void lte_phy_rxueinfo_init(size_t initial_capacity) {
    capacity = initial_capacity;
    data = malloc(capacity * sizeof(LTE_PHY_RXUEINFO_T));
    if (!data) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    sem_init(&mutex, 0, 1);
    pthread_cond_init(&not_full, PTHREAD_COND_INITIALIZER);
    pthread_cond_init(&not_empty, PTHREAD_COND_INITIALIZER);
    array_size = 0;
}

bool lte_phy_rxueinfo_push(LTE_PHY_RXUEINFO_T item) {
    bool success = false;

    sem_wait(&mutex); // Lock the mutex
    if (array_size < capacity) {
        data[array_size] = item;
        array_size++;
        success = true;
    } else {
        pthread_cond_signal(&not_full); // Wake up a waiting thread
    }
    sem_post(&mutex); // Unlock the mutex

    return success;
}

void lte_phy_rxueinfo_pop(LTE_PHY_RXUEINFO_T *item) {
    sem_wait(&mutex); // Lock the mutex

    if (array_size > 0) {
        *item = data[0];
        memmove(&data[0], &data[1], (array_size - 1) * sizeof(LTE_PHY_RXUEINFO_T));
        array_size--;
    } else {
        pthread_cond_signal(&not_empty); // Wake up a waiting thread
