class MemoryPool {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> _data;
    std::mutex _mtx;
    size_t _capacity = 0;

public:
    // Get a pointer to the next free element, initializing it with default values.
    NFAPI_CRC_INDICATION_PDU_T* acquire() {
        if (_data.empty()) {
            resize(_capacity + 1);
        }
        auto iter = _data.end();
        std::unique_lock<std::mutex> lock(_mtx);
        _data.swap(iter, _data.end()); // Swap the last allocated element to the end of the vector for efficient removal.
        _data.pop_back();
        return &*iter;
    }

    // Release a previously acquired pointer back to the pool.
    void release(NFAPI_CRC_INDICATION_PDU_T* ptr) noexcept {
        _data.push_back(*ptr);
    }

    // Resize the internal vector, possibly reallocating memory if needed.
