} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

static Node* head = NULL;
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t queue_notempty = PTHREAD_COND_INITIALIZER;
static pthread_cond_t queue_full = PTHREAD_COND_INITIALIZER;
static size_t buffer_size = 1024; // Optimize as needed

void* create_crc_indication() {
    NFAPI_CRC_INDICATION_PDU_T* data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
