    }
    data->crc_indication.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    return data;
}

void enqueue(NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list_lock);
    if (head == NULL) {
        head = malloc(sizeof(Node));
        if (!head) {
            perror("malloc failed for list header");
            free(data);
            pthread_mutex_unlock(&list_lock);
            return;
        }
        head->data = *data;
        head->next = NULL;
    } else {
        Node* current = head;
        while (current->next) {
            current = current->next;
        }
        current->next = malloc(sizeof(Node));
        if (!current->next) {
            perror("malloc failed for list node");
            free(data);
            pthread_mutex_unlock(&list_lock);
            return;
        }
        current->next->data = *data;
        current->next->next = NULL;
    }
    pthread_cond_signal(&queue_notempty);
    pthread_mutex_unlock(&list_lock);
}

void dequeue(NFAPI_CRC_INDICATION_PDU_T** data) {
    pthread_mutex_lock(&list_lock);
    if (head == NULL) {
        pthread_cond_wait(&queue_full, &list_lock);
    }
    Node* to_free = head;
    *data = &to_free->data;
    head = head->next;
    free(to_free);
    pthread_cond_signal(&queue_notempty);
    pthread_mutex_unlock(&list_lock);
}

