typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRIC_INDICATION_PDU_T *list = NULL;
static size_t capacity = 0, size = 0;

void initialize_cric_indication_list(size_t n) {
    if (list) pthread_mutex_destroy(&list_mutex);
    list = malloc(n * sizeof(NFAPI_CRIC_INDICATION_PDU_T));
    capacity = n;
    size = 0;
    pthread_mutex_init(&list_mutex, NULL);
}

void add_cric_indication(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (size >= capacity) {
        NFAPI_CRIC_INDICATION_PDU_T *tmp = realloc(list, (capacity *= 2) * sizeof(NFAPI_CRIC_INDICATION_PDU_T));
        if (!tmp) abort();
        list = tmp;
    }

    pthread_mutex_lock(&list_mutex);
    bool duplicate = false;
    for (size_t i = 0; i < size && !duplicate; ++i) {
        if (list[i].RNTI == pdu->RNTI && (i + 1 < size || list[i + 1].RNTI != pdu->RNTI))
            duplicate = true;
    }

    if (!duplicate) {
        list[size] = *pdu;
        list[size++].CRC_INDICATION_REL8_TAG |= rand() & ((1 << 15) - 1);
    }
    pthread_mutex_unlock(&list_mutex);
}

NFAPI_CRC_INDICATION_PDU_T *get_cric_indication(uint16_t rnti, size_t *index) {
    size_t i;
    pthread_mutex_lock(&list_mutex);
    for (i = 0; i < size && list[i].RNTI != rnti; ++i) {}
    if (i < size) {
        if (index) *index = i;
        pthread_mutex_unlock(&list_mutex);
        return &list[i];
    }
    pthread_mutex_unlock(&list_mutex);
    return NULL;
}
