```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Linq.Expressions;
using System.Reflection;
using Microsoft.EntityFrameworkCore;

public class QueryManager<T> where T : class
{
    private readonly DbContext _context;

    public QueryManager(DbContext context)
    {
        _context = context;
    }

    public async Task<List<T>> ExecuteQueryAsync(string operation, Expression<Func<T, bool>> filter, object configurationObject, params object[] parameters)
    {
        var commandType = (operation switch
        {
            "insert" => System.Data.EntityState.Added,
            "update" => System.Data.EntityState.Modified,
            "delete" => System.Data.EntityState.Deleted,
            _ => throw new ArgumentException("Invalid operation")
        });

        var queryable = _context.Set<T>().AsQueryable();

        var dynamicProperties = configurationObject.GetType()
            .GetProperties(BindingFlags.Public | BindingFlags.Instance)
            .Select(p => new { Name = p.Name, Value = parameters.FirstOrDefault(o => p.Name == o.ToString()) });

        foreach (var property in dynamicProperties)
        {
            var propInfo = typeof(T).GetProperty(property.Name);
            if (propInfo != null)
            {
                Expression<Func<T, bool>> predicate = t => propInfo.GetValue(t) == property.Value;
                queryable = queryable.Where(predicate);
            }
        }

        List<T> resultList;

        switch (operation)
        {
            case "insert":
                var newEntity = Activator.CreateInstance(typeof(T));
                foreach (var property in dynamicProperties)
                {
                    var propInfo = typeof(T).GetProperty(property.Name);
                    if (propInfo != null)
                        propInfo.SetValue(newEntity, property.Value);
                }
                _context.ChangeTracker.TrackEntry(_context.Add(newEntity)).State = commandType;
                resultList = await _context.SaveChangesAsync() > 0 ? new List<T> { newEntity as T } : null;
                break;
            case "update":
                var updateQuery = queryable.Where(filter).AsEnumerable();
                foreach (var entity in updateQuery)
                {
                    foreach (var property in dynamicProperties)
                    {
                        var propInfo = typeof(T).GetProperty(property.Name);
                        if (propInfo != null)
                            propInfo.SetValue(entity, property.Value);
                    }
                }
                _context.ChangeTracker.TrackEntries().ToList()
                    .Where(e => e.Entity is T && commandType == e.State).AsParallel().ForAll(e => e.AcceptAllChanges());
                resultList = await _context.SaveChangesAsync() > 0 ? updateQuery.ToList() : null;
                break;
            case "delete":
                resultList = queryable.Where(filter).ToList();
                _context.RemoveRange(resultList);
                resultList = await _context.SaveChangesAsync() > 0 ? new List<T>() : null;
                break;
        }

        return resultList ?? throw new Exception("Failed to execute query");
    }
}
```

