static sem_t mem_sem, log_sem;
static void* shared_memory = NULL; // Replace with your shared memory management function

NFAPI_CRC_INDICATION_PDU_T* init_list(size_t capacity) {
    if (!shared_memory) {
        shared_memory = mmap(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
        if (shared_memory == MAP_FAILED) {
            log_error("Failed to allocate shared memory");
            return NULL;
        }
    }

    sem_init(&mem_sem, 0, capacity);
    sem_init(&log_sem, 0, 1);

    NFAPI_CRC_INDICATION_PDU_T* list = shared_memory;
    for (size_t i = 0; i < capacity; ++i) {
        list[i].RX_UE_INFORMATION_TAG = generate_random_tag(); // Replace with your tag generation function
        list[i].RNTI = validate_rnti(list[i].RX_UE_INFORMATION_TAG); // Replace with your RNTI validation function
        list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    return list;
}

NFAPI_CRC_INDICATION_PDU_T* get_next_pdu(void) {
    sem_wait(&mem_sem);

    pthread_mutex_lock(&list_mutex);
    NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;
    if (!pthread_mutex_trylock( &list_mutex)) {
        // If lock was not acquired due to contention, release the semaphore and try again
        pthread_mutex_unlock(&list_mutex);
        sem_post(&mem_sem);
        return NULL;
    }

    size_t index = 0;
    for (index = 0; index < capacity; ++index) {
        if (!list[index].CRC_INDICATION_REL8_TAG.CRCFLAG) {
            list[index].CRC_INDICATION_REL8_TAG.CRCFLAG = 1;
            pdu = &list[index];
            break;
        }
    }

    if (index == capacity) {
        log_warning("All PDUs are in use, consider resetting the list");
    }

    pthread_mutex_unlock(&list_mutex);
    sem_post(&mem_sem);
    return pdu;
}

void reset_list(void) {
    // Replace with your shared memory reset function
    memset(shared_memory, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);

    sem_wait(&mem_sem);

    pthread_mutex_lock(&list_mutex);
    for (size_t i = 0; i < capacity; ++i) {
        list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = 0;
    }
    pthread_mutex_unlock(&list_mutex);
    sem_post(&mem_sem);
}
