        var localFiles = Directory.GetFiles("Configs", "*.xml");
        var remoteUrls = new List<Uri> { /* Add network stream URLs here */ };

        await Task.WhenAll(localFiles.Select(LoadConfiguration)
                          .Concat(remoteUrls.Select(async url => await DownloadAndLoadConfiguration(url)))
                          .ToArray());
    }

    private Configuration LoadConfiguration(string filePath)
    {
        try
        {
            var xmlDoc = new XmlDocument();
            xmlDoc.Load(filePath);

            return ParseConfiguration(xmlDoc.DocumentElement);
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error loading configuration from '{filePath}': {ex.Message}");
            return new Configuration(); // Return an empty configuration in case of error
        }
    }

    private async Task<Configuration> DownloadAndLoadConfiguration(Uri uri)
    {
        try
        {
            using (var webClient = new WebClient())
            {
                var xmlData = await webClient.DownloadStringTaskAsync(uri);
                return ParseConfiguration(XmlDocument.LoadXml(xmlData));
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error loading configuration from '{uri}': {ex.Message}");
            return new Configuration(); // Return an empty configuration in case of error
        }
    }

    private Configuration ParseConfiguration(XmlElement rootElement)
    {
        var configuration = new Configuration();

        foreach (XmlElement element in rootElement.ChildNodes)
        {
            switch (element.Name)
            {
                case "tiles":
                    // Handle parsing of tiles here
                    break;
                case "world":
                    if (!int.TryParse(element.GetAttribute("width"), out int width) || !int.TryParse(element.GetAttribute("height"), out int height))
                    {
                        Console.Error.WriteLine($"Invalid world dimensions in configuration.");
                        continue;
                    }

                    configuration.World = new World(Math.Max(10, Math.Min(1000, width)), Math.Max(10, Math.Min(1000, height)));
                    break;
                case "camera":
                    if (!double.TryParse(element.GetAttribute("speed"), out double speed))
                    {
                        configuration.CameraSpeed = 5.0; // Default to 5 units per frame
                    }
                    else
                    {
                        configuration.CameraSpeed = Math.Max(0, speed);
                    }
                    break;
            }
        }

        lock (_lockObject)
        {
            _configurations[rootElement.Name] = configuration;
        }

        return configuration;
    }
}

public class Configuration
{
    public World World { get; set; }
    public double CameraSpeed { get; set; }
    // Add properties for other game components here
}

public class World
{
    public int Width { get; }
    public int Height { get; }
    // Add methods and properties for managing world here
}
