function manageUserAccount($request) {
    // Define constants for persistent storage and logging
    define('DB_CONNECTION', 'YourDatabaseConnection');
    define('LOG_FILE', 'path/to/your/logfile.log');

    $id = isset($request['id']) ? (int)$request['id'] : null;
    $name = $request['name'];
    $email = $request['email'];
    $password = password_hash($request['password'], PASSWORD_DEFAULT); // Ensure password is hashed securely
    $subAction = $request['sub_action'];

    // Validate input data and ensure integrity
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        logError('Invalid email provided: ' . $email);
        return false;
    }
    if (empty($name) || empty($password)) {
        logError('Missing required input data');
        return false;
    }

    // Load database connection and start a transaction to handle concurrent updates efficiently
    try {
        $db = new PDO(DB_CONNECTION);
        $db->beginTransaction();

        // Check if the user with provided email already exists in the database
        $stmt = $db->prepare("SELECT id FROM users WHERE email = ? LIMIT 1");
        $stmt->execute([$email]);
        $existingUser = $stmt->fetch(PDO::FETCH_COLUMN);

        // Handle user account creation or update based on the provided 'id'
        if ($id) {
            if (!$existingUser) {
                logError('User with provided email does not exist');
                return false;
            }

            // Update the user account
            $stmt = $db->prepare("UPDATE users SET name = ?, password = ? WHERE id = ?");
            if ($subAction === 'delete') {
                // If 'delete' was specified, mark the user as deleted instead of physically removing it for easier recovery
                $stmt = $db->prepare("UPDATE users SET is_deleted = 1 WHERE id = ?");
            }
        } else {
            // Create a new user account
            $stmt = $db->prepare("INSERT INTO users (name, email, password) VALUES (?, ?, ?)");
        }

        if ($stmt->execute([$name, $password, $id ?? null])) {
            if ($subAction === 'delete') {
                // If 'delete' was specified, mark the user as deleted instead of physically removing it for easier recovery
                $db->exec("UPDATE users SET is_deleted = 1 WHERE id = ?", [$id]);
            } else {
                logSuccess('User account created/updated successfully');
            }

            // Integrate with external data sources for real-time UE configuration updates (Not shown here due to scope)

            // Commit the transaction and release resources
            $db->commit();
        } else {
            logError('Failed to create/update user account');
            // Rollback the transaction in case of errors
            $db->rollBack();
            return false;
        }
    } catch (PDOException $e) {
        // Log and handle any database-related exceptions gracefully
        logError('Database error: ' . $e->getMessage());
        return false;
    }

    function logSuccess($message) {
        file_put_contents(LOG_FILE, date('Y-m-d H:i:s') . " [SUCCESS] " . $message . "\n", FILE_APPEND);
    }

    function logError($message) {
        file_put_contents(LOG_FILE, date('Y-m-d H:i:s') . " [ERROR] " . $message . "\n", FILE_APPEND);
    }
}
