NFAPI_CRC_INDICATION_PDU_T *initializeArray() {
    if (!arr) {
        arr = mmap(NULL, ARRAY_INITIAL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    }

    if (used == arrSize) {
        size_t newSize = arrSize * GROWTH_FACTOR;
        NFAPI_CRC_INDICATION_PDU_T *newArr = mmap(NULL, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        memcpy(newArr, arr, arrSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
