    uint16_t rnti = 0; // Initialize with a random value or a sentinel value for uniqueness check

    while (true) {
        validateRNTI(rnti); // Validate RNTI here

        for (size_t i = 0; i < used; ++i) {
            if (arr[i].RNTI == rnti) {
                rnti++;
                break;
            }
        }

        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rnti++;
        pdu->CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % 2);

        break;
    }

    pthread_mutex_unlock(&mutex);
    return pdu;
}
