#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct _PDCP_PDU {
    uint32_t sn; // Sequence Number
    uint8_t *data; // PDCP PDU data
    size_t len; // Length of PDCP PDU data
} PDCP_PDU;

typedef struct _MAC_PDU {
    PDCP_PDU pdcp_pdu;
    struct _MAC_PDU *next;
} MAC_PDU;

#define W 10 // Sliding window size

MAC_PDU* init_mac_pdu_queue() {
    MAC_PDU* head = NULL;
    MAC_PDU* tail = NULL;
    return (MAC_PDU*)malloc(W * sizeof(MAC_PDU));
}

void enqueue_mac_pdu(MAC_PDU** queue, PDCP_PDU pdcp_pdu) {
    if (*queue == NULL) {
        *queue = init_mac_pdu_queue();
        (*queue)->pdcp_pdu = pdcp_pdu;
        (*queue)->next = NULL;
        tail = *queue;
    } else {
        MAC_PDU* current = *queue;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = (MAC_PDU*)malloc(sizeof(MAC_PDU));
        current = current->next;
        current->pdcp_pdu = pdcp_pdu;
        current->next = NULL;
        tail = current;
    }
}

PDCP_PDU dequeue_mac_pdu(MAC_PDU** queue) {
    if (*queue == NULL) return (PDCP_PDU){0};
    MAC_PDU* current = *queue;
    PDCP_PDU ret = current->pdcp_pdu;
    *queue = (*queue)->next;
    free(current);
    return ret;
}
```

