#include <time.h>
#include <pthread.h>

typedef struct LTE_Uplink_Signal_Scope {
    int frequency_offset;
    time_t timestamp;
    int signal_strength;
} LTE_Uplink_Signal_Scope_T;

struct dynamic_array {
    LTE_Uplink_Signal_Scope_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    void (*logger)(const char*, const char* format, ...);
};

struct dynamic_array* create_dynamic_array() {
    struct dynamic_array* array = malloc(sizeof(struct dynamic_array));
    if (!array) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }

    array->data = NULL;
    array->capacity = 0;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void free_dynamic_array(struct dynamic_array* array) {
    if (array->data) {
        free(array->data);
        array->data = NULL;
    }

    pthread_mutex_destroy(&array->mutex);
    free(array);
}

void log_event(struct dynamic_array* array, const char* message, ...) {
    if (array->logger) {
        va_list args;
        va_start(args, message);
        array->logger(__FUNCTION__, message, args);
        va_end(args);
    }
}

void set_log_function(struct dynamic_array* array, void (*logger)(const char*, const char* format, ...)) {
    array->logger = logger;
}

int add_scope(struct dynamic_array* array, LTE_Uplink_Signal_Scope_T scope) {
    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        if (array->capacity == 0) array->capacity = 10;
        else array->capacity *= 2;

        LTE_Uplink_Signal_Scope_T* new_data = realloc(array->data, sizeof(LTE_Uplink_Signal_Scope_T) * array->capacity);
        if (!new_data) {
            pthread_mutex_unlock(&array->mutex);
            fprintf(stderr, "Error: Out of memory\n");
            return -1;
        }

        array->data = new_data;
    }

    array->size++;
    array->data[array->size-1] = scope;

    pthread_mutex_unlock(&array->mutex);

    log_event(array, "Added signal scope: frequency_offset=%d, timestamp=%ld, signal_strength=%d", scope.frequency_offset, (long)scope.timestamp, scope.signal_strength);

    return 0;
}

void clean_obsolete_scopes(struct dynamic_array* array) {
    time_t current_time = time(NULL);
    size_t i;

    pthread_mutex_lock(&array->mutex);

    for (i = 0; i < array->size; i++) {
        if ((current_time - array->data[i].timestamp) > TIME_DIFFERENCE || array->data[i].signal_strength < SIGNAL_STRENGTH_THRESHOLD) {
            memmove(&array->data[i], &array->data[i+1], (array->size - i - 1) * sizeof(LTE_Uplink_Signal_Scope_T));
            array->size--;
        }
    }

    pthread_mutex_unlock(&array->mutex);
}

void calculate_average_signal_strength(struct dynamic_array* array, double *avg) {
    double sum = 0.0;
    size_t i;

    pthread_mutex_lock(&array->mutex);

    for (i = 0; i < array->size; i++) {
        sum += array->data[i].signal_strength;
    }

    *avg = sum / array->size;

    pthread_mutex_unlock(&array->mutex);
}

void bulk_insert(struct dynamic_array* array, LTE_Uplink_Signal_Scope_T* scopes, size_t count) {
    if (count + array->size > array->capacity) {
        array->capacity += (count + array->size - array->capacity);
    }

    pthread_mutex_lock(&array->mutex);

    memcpy(&array->data[array->size], scopes, count * sizeof(LTE_Uplink_Signal_Scope_T));
    array->size += count;

    pthread_mutex_unlock(&array->mutex);
}
