typedef struct _MEMORY_POOL {
    void *memory_block;
    size_t capacity;
    size_t current_allocation;
    struct _MEMORY_POOL *next;
} MEMORY_POOL_T;

void* memory_pool_malloc(size_t size) {
    MEMORY_POOL_T *current = NULL, *new_block = NULL;
    if (!memory_pool_head) {
        new_block = malloc(sizeof(MEMORY_POOL_T) + size);
        new_block->capacity = size;
        new_block->current_allocation = 0;
        new_block->next = NULL;
        memory_pool_head = new_block;
    } else {
        current = memory_pool_head;
        while (current->next && current->next->capacity < size) {
            current = current->next;
        }

        if (!current->next) { // If no suitable block is found, allocate a new one.
            new_block = malloc(sizeof(MEMORY_POOL_T) + size);
            new_block->capacity = size;
            new_block->current_allocation = 0;
            new_block->next = current->next;
            current->next = new_block;
        } else { // If a suitable block is found, use it.
            new_block = current->next;
            current->next = new_block->next;
            new_block->current_allocation = 0;
        }
    }

    return (char*)new_block + sizeof(MEMORY_POOL_T);
}

void memory_pool_free(void *ptr) {
    void *memory_block = ptr - sizeof(MEMORY_POOL_T);
    MEMORY_POOL_T *current = memory_pool_head, *prev;

    if (!memory_pool_head) return; // Nothing to free.

    for (; current; current = current->next) {
        if (current == memory_block / sizeof(MEMORY_POOL_T)) {
            prev->current_allocation += current->capacity - current->current_allocation;
            if (!current->next) memory_pool_head = prev;
            else prev->next = current->next;
            free(current);
            break;
        }
        prev = current;
    }
}

