typedef struct {
    long offset;
    int key;
    double value;
} record;

typedef struct {
    record* ue_records;
    size_t ue_count;
    size_t offsets_size;
    size_t keys_size;
    pthread_mutex_t mutex;
} data_container;

data_container* initialize_ue(const size_t initial_key_count, const size_t max_keys, const size_t max_offset, double min_value, double max_value, double sum_threshold, const size_t external_data_size) {
    data_container* dc = malloc(sizeof(data_container));
    if (!dc) return NULL;
    pthread_mutex_init(&dc->mutex, NULL);

    // Validate initial keys and allocate memory for offsets and keys arrays
    size_t *key_array = malloc(initial_key_count * sizeof(size_t));
    if (!key_array) {
        free(dc);
        return NULL;
    }
    size_t *offset_array = calloc(max_keys, sizeof(long));
    if (!offset_array) {
        free(key_array);
        free(dc);
        return NULL;
    }

    // Filter initial keys and assign unique cell IDs within the given range
    size_t key_count = 0;
    for (size_t i = 0; i < initial_key_count; ++i) {
        size_t key = key_array[i];
        if (key >= max_keys || find(offset_array, max_keys, key) != -1) continue;
        offset_array[key] = align_up(key, 8);
        key_count++;
    }

    // Allocate memory for the UE records array
    record* ue_records = malloc(key_count * sizeof(record));
    if (!ue_records) {
        free(offset_array);
        free(key_array);
        free(dc);
        return NULL;
    }

    // Initialize UE records and validate against external data source
    size_t remaining_keys = key_count;
    for (size_t i = 0; i < initial_key_count && remaining_keys > 0; ++i) {
        size_t key = key_array[i];
        if (remaining_keys <= external_data_size && (external_data_size == 0 || find(key_array, initial_key_count, key) != i)) continue;

        ue_records[key_count - remaining_keys].offset = offset_array[key];
        ue_records[key_count - remaining_keys].key = key;
        ue_records[key_count - remaining_keys].value = min_value + (max_value - min_value) * rand() / RAND_MAX;

        if (sum_threshold > 0.0 && ue_records[key_count - remaining_keys].value + sum_of_values(ue_records, key_count - remaining_keys, sum_threshold) > sum_threshold) {
            // Adjust individual values or truncate records as necessary to meet the constraint
            double adjustment = (sum_threshold - ue_records[key_count - remaining_keys].value - sum_of_values(ue_records, key_count - remaining_keys - 1, sum_threshold)) / (remaining_keys - 1);
            for (size_t j = key_count - remaining_keys; j < key_count; ++j) {
                ue_records[j].value -= adjustment;
                if (ue_records[j].value <= min_value || ue_records[j].value >= max_value) {
                    free(ue_records);
                    free(offset_array);
                    free(key_array);
                    free(dc);
                    return NULL;
                }
            }
        }

        remaining_keys--;
    }

    dc->ue_records = ue_records;
    dc->ue_count = key_count;
    dc->offsets_size = max_keys;
    dc->keys_size = initial_key_count;

    return dc;
}

bool find(const size_t* array, const size_t size, const size_t value) {
    for (size_t i = 0; i < size; ++i) {
        if (array[i] == value) return true;
    }
    return false;
}

double sum_of_values(const record* ue_records, const size_t count, const double sum_threshold) {
    double sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += ue_records[i].value;
        if (sum > sum_threshold) return sum - ue_records[i].value;
    }
    return sum;
}

long align_up(const size_t value, const long alignment) {
    return (value + alignment - 1) & ~(alignment - 1);
}
