    // Initialize keys with unique values from 0 to num_records - 1
    for (size_t i = 0; i < num_records; ++i) {
        keys[i] = i;
    }

    // Allocate memory for records array
    records = malloc(num_records * sizeof(record_t));
    if (!records) {
