        exit(EXIT_FAILURE);
    }

    // Populate records with appropriate offsets based on keys
    for (size_t i = 0; i < num_records; ++i) {
        size_t j = keys[i];
        while (offsets[j] != NULL) {
            if (j + 1 >= max_records || !is_sorted(offsets, j)) {
                fprintf(stderr, "Error: Failed to find suitable offset for key %d\n", keys[i]);
                exit(EXIT_FAILURE);
            }
            --j;
        }
        records[i].key = keys[i];
        records[i].offset = offsets[j];
        offsets[j] = &records[i];
    }
}

// Helper function to check if the offset array is sorted in ascending order.
bool is_sorted(const offset_t* offsets, size_t start) {
    for (size_t i = start; i + 1 < sizeof(offsets)/sizeof(*offsets); ++i) {
        if (*(offsets + i) > *(offsets + (i + 1))) return false;
    }
    return true;
}
