#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum { FILE, DIRECTORY } NodeType;
typedef struct Node *NodePtr;
struct Node {
    char name[256];
    NodeType type;
    NodePtr parent;
    size_t childCount;
    pthread_mutex_t mutex;
    NodePtr children[256];
};

void initNode(NodePtr node, const char* name, NodeType type) {
    memset(node, 0, sizeof(*node));
    strncpy(node->name, name, sizeof(node->name) - 1);
    node->type = type;
}

NodePtr createChild(NodePtr parent, const char* name, NodeType type) {
    pthread_mutex_lock(&parent->mutex);
    for (size_t i = 0; i < parent->childCount; ++i) {
        if (!strcmp(parent->children[i]->name, name)) {
            pthread_mutex_unlock(&parent->mutex);
            return NULL;
        }
    }

    NodePtr newNode = malloc(sizeof(*newNode));
    initNode(newNode, name, type);
    newNode->parent = parent;
    parent->children[parent->childCount] = newNode;
    ++parent->childCount;

    pthread_mutex_unlock(&parent->mutex);
    return newNode;
}

void traverseAndPrint(NodePtr node, int depth) {
    for (size_t i = 0; i < node->childCount; ++i) {
        NodePtr child = node->children[i];
        printf("%*s-%s: %s\n", depth * 2, "", child->name, (child->type == FILE ? "file" : "directory"));

        if (child->type == DIRECTORY)
            traverseAndPrint(child, depth + 1);
    }
}

void deleteNode(NodePtr node) {
    pthread_mutex_lock(&node->mutex);
    for (size_t i = 0; i < node->childCount; ++i) {
        NodePtr child = node->children[i];
        if (child)
            deleteNode(child);
    }

    free(node);
    pthread_mutex_unlock(&node->mutex);
}
