#define MAX_MEMORY_SIZE 1000000
#define RNTI_THRESHOLD 65535

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    unsigned char crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

void log_error(const char *message);

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Thread safety lock
static unsigned int rnti_counter = 0;
static uint32_t seed = time(NULL); // Randomness seed for CRCFLAG generation

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate(int num_users, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    if (num_users > MAX_MEMORY_SIZE / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        log_error("Error: Allocation limit exceeded.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *data = malloc(num_users * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        log_error("Error: Failed to allocate memory.");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    int total_rnti = 0;
    for (int i = 0; i < num_users && rnti_counter < RNTI_THRESHOLD; ++i) {
        data[i].tag = generate_tag();
        data[i].rnti = rnti_counter++;
        data[i].crc_indication.length = sizeof(data[i].crc_indication);
        data[i].crc_indication.tag = generate_crc_indication_tag();
        data[i].crcflag = rand_r(&seed) % 2;
        total_rnti += data[i].rnti;
    }
    pthread_mutex_unlock(&mutex);

    if (total_rnti > RNTI_THRESHOLD) {
        log_error("Error: RNTI sum exceeded the threshold.");
        free(data);
        return NULL;
    }

    for (int i = 0; i < num_users && callback; ++i)
        callback(&data[i]);

    return data;
}

void log_error(const char *message) {
    if (logging_enabled())
        log_to_file("Error:", message);
}
```

