#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdbool.h>
#include <inttypes.h>
#include <pthread.h>

// Audio file structure for storing information about the audio file
typedef struct {
    uint32_t channels;
    uint32_t sample_rate;
    uint32_t bit_depth;
    uint64_t duration; // total duration in samples
} AudioFileInfo;

// Function for initializing the AudioFileInfo structure with default values
void initAudioFileInfo(AudioFileInfo* info) {
    memset(info, 0, sizeof(AudioFileInfo));
    info->sample_rate = 44100; // default sample rate
}

// Function for parsing the RIFF/WAVE header of an audio file and populating the AudioFileInfo structure
bool parseWaveHeader(const char* filename, AudioFileInfo* info) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) return false;

    char chunk_id[5];
    fread(chunk_id, sizeof(char), 4, fp);
    if (strncmp(chunk_id, "RIFF", 4)) {
        fclose(fp);
        return false;
    }

    uint32_t file_size;
    fread(&file_size, sizeof(uint32_t), 1, fp);

    char format_chunk_id[8];
    fseek(fp, -8, SEEK_CUR); // go back to the format chunk ID position
    fread(format_chunk_id, sizeof(char), 4, fp);
    if (strncmp(format_chunk_id, "fmt ", 4)) {
        fclose(fp);
        return false;
    }

    // Read the rest of the format chunk data
    uint32_t format_size, format_type, num_channels, sample_rate, byte_rate, block_align, bit_depth;
    fread(&format_size, sizeof(uint32_t), 1, fp);
    fread(&format_type, sizeof(uint32_t), 1, fp);
    fread(&num_channels, sizeof(uint32_t), 1, fp);
    fread(&sample_rate, sizeof(uint32_t), 1, fp);
    fread(&byte_rate, sizeof(uint32_t), 1, fp);
    fread(&block_align, sizeof(uint16_t), 1, fp);
    fread(&bit_depth, sizeof(uint16_t), 1, fp);

    info->channels = num_channels;
    info->sample_rate = sample_rate;
    info->bit_depth = bit_depth;

    // Calculate the duration in samples
    info->duration = file_size / (info->channels * info->bit_depth / 8);

    fclose(fp);
    return true;
}

// Function for processing an audio file and extracting detailed information about its channels, sample rate, bit depth, duration and handling errors.
AudioFileInfo processAudioFile(const char* filename) {
    AudioFileInfo info;
    initAudioFileInfo(&info);

    if (!parseWaveHeader(filename, &info)) {
        fprintf(stderr, "Error parsing audio file: %s\n", filename);
        return info;
    }

    // Additional error handling and metadata extraction can be added here.

    info.duration /= info.sample_rate; // Convert from samples to seconds
    return info;
}
```

