```c
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    int UserID;
    double Latitude;
    double Longitude;
} LocationUpdateRequest;

void calculateDistance(double lat1, double lon1, double lat2, double lon2, double *distance) {
    const double R = 6371e3; // Earth radius in meters

    double dLat = (lat2 - lat1) * M_PI / 180.0;
    double dLon = (lon2 - lon1) * M_PI / 180.0;

    double a = sin(dLat/2) * sin(dLat/2) + cos((lat1)*M_PI/180.0) * cos((lat2)*M_PI/180.0) * sin(dLon/2) * sin(dLon/2);
    double c = 2 * atan2(sqrt(a), sqrt(1-a));
    *distance = R * c;
}

void processUserLocationData(LocationUpdateRequest* requests, int count, double referenceLatitude, double referenceLongitude) {
    LocationUpdateRequest *temp = malloc(count * sizeof(LocationUpdateRequest));
    int successCount = 0, failedCount = 0;

    for (int i = 0; i < count; ++i) {
        calculateDistance(requests[i].Latitude, requests[i].Longitude, referenceLatitude, referenceLongitude, &temp[i].distance);
        if (isnan(temp[i].distance))
            failedCount++;
        else
            temp[successCount++] = requests[i];
    }

    free(requests);
    if (failedCount > 0) {
        processUserLocationData(temp, successCount, referenceLatitude, referenceLongitude); // Recurse on the remaining successful requests
        return;
    }

    for (int i = 0; i < successCount; ++i) {
        printf("UserID: %d, Distance from Reference Point: %.6f km\n", temp[i].UserID, temp[i].distance / 1000);
    }
}
```

