public class GeolocationProcessor
{
    private double _latitude, _longitude;
    public double Latitude { get => _latitude; set => _latitude = Math.Round((double)Math.PI * value / 180, 6); }
    public double Longitude { get => _longitude; set => _longitude = Math.Round((double)Math.PI * value / 180, 6); }

    private static readonly double RADIUS_OF_EARTH_KM = 6371e3; // Earth radius in meters

    public double DistanceTo(GeolocationProcessor other, bool miles) {
        double dLat = (other.Latitude - this.Latitude);
        double dLon = (other.Longitude - this.Longitude);

        double a = Math.Sin(dLat / 2) * Math.Sin(dLat / 2) + Math.Cos(this.Latitude) * Math.Cos(other.Latitude) * Math.Sin(dLon / 2) * Math.Sin(dLon / 2);
        double c = 2 * Math.Atan2(Math.Sqrt(a), Math.Sqrt(1 - a));
        double distance = RADIUS_OF_EARTH_KM * c;

        return miles ? distance / 1093.58 : distance;
    }

    public override string ToString() {
        return $"{this.DistanceTo(new GeolocationProcessor(), false).ToString("F6")} km";
    }
}
