typedef struct radio_param {
    int id;
    int frequency;
    size_t band_classes_len;
    int* band_classes;
    pthread_mutex_t mutex;
} radio_param;

radio_param* dynamic_list_init() {
    return calloc(1, sizeof(radio_param));
}

void dynamic_list_destroy(radio_param* list) {
    if (list) {
        free(list->band_classes);
        free(list);
    }
}

size_t radio_param_size() {
    return sizeof(int) * 3 + sizeof(pthread_mutex_t);
}

void* dynamic_list_realloc(void** ptr, size_t current_len, size_t new_len) {
    void* result = realloc(*ptr, (new_len * radio_param_size()));
    if (!result) return NULL;

    // shift memory blocks to minimize fragmentation
    memmove((char*)result + (current_len * radio_param_size()), (char*)*ptr + (current_len * radio_param_size()), ((new_len - current_len) * radio_param_size()));

    return result;
}

radio_param* dynamic_list_push(radio_param** list, int id, int frequency, size_t band_classes_len, ...) {
    if (!list || !band_classes_len) return NULL;

    va_list ap;
    va_start(ap, band_classes_len);
    int* band_classes = (int*)dynamic_list_realloc(&(*list)->band_classes, (*list)->band_classes_len, band_classes_len + 1);
    if (!band_classes) return NULL;

    for (size_t i = 0; i < band_classes_len; ++i) {
        band_classes[i] = va_arg(ap, int);
    }
    band_classes[band_classes_len] = va_arg(ap, int);
    (*list)->band_classes_len = band_classes_len + 1;

    // initialize mutex if not yet initialized
    if (!(*list)->mutex) {
        pthread_mutex_init(&(*list)->mutex, NULL);
    }

    return *list;
}

void dynamic_list_delete(radio_param** list, int id) {
    if (!list || !*list) return;

    for (size_t i = 0; i < RADIO_PARAM_COUNT(*list); ++i) {
        if ((*list + i)->id == id) {
            // merge remaining elements to minimize memory fragmentation
            size_t j = i + 1;
            while (j < RADIO_PARAM_COUNT(*list)) {
                memcpy((*list + j), (*list + j + 1), radio_param_size());
                j++;
            }

            // shrink the list
            *list = dynamic_list_realloc(list, RADIO_PARAM_COUNT(*list) - 1, RADIO_PARAM_COUNT(*list));
        }
    }
}

size_t RADIO_PARAM_COUNT(const radio_param* list) {
    size_t count = 0;
    for (const radio_param* param = list; param && param->id != -1; ++count, ++param);
    return count;
}
