    return ctx;
}

void derive_session_keys(const char* api_key, unsigned char *output, size_t output_len) {
    // Derive session keys using Argon2 key derivation function (KDF)
    argon2_context context;
    argon2_ctx_init(&context, ARGON2_ID_GENERIC, ARGON2_VERIFY, 0, NULL);
    argon2_ctx_set_lane_size(ARGON2_LANE_SIZE_16);
    argon2_ctx_set_t_cost(8);
    argon2_ctx_set_p_count(4);
    argon2_ctx_set_m_len(32);

    const size_t key_size = 32;
    unsigned char hashed[key_size];

    // Derive the keys using Argon2
    argon2_ctx_derive(&context, api_key, strlen(api_key), hashed, key_size);

    memcpy(output, hashed, output_len);
}
