Record* create_record_array(int n, int min, int max) {
    if (n <= 0 || max < min)
        return NULL;

    Record *records = malloc(n * sizeof(Record));
    if (!records)
        return NULL;

    srand(time(NULL));

    for (int i = 0; i < n; ++i) {
        records[i].id = 'A' + i;
        records[i].value = rand() % ((max - min) + 1) + min;
    }

    return records;
}

bool sort_records(Record *records, int n) {
    if (!records || n <= 1)
        return true;

    qsort(records, n, sizeof(Record), compare);

    return !err;
}

int compare(const void *a, const void *b) {
    Record *recA = (Record *)a;
    Record *recB = (Record *)b;

    if (recA->value < recB->value)
        return -1;
    else if (recA->value > recB->value)
        return 1;
    else
        return 0;
}

void print_records(const Record *records, int n) {
    for (int i = 0; i < n; ++i) {
        printf("(%c, %d)\n", records[i].id, records[i].value);
    }
}

