static Node *head = NULL;
static Node **current_tail = &head;
static size_t list_size = 0;
static size_t qlen = 0;
pthread_mutex_t qmutex;
pthread_cond_t notempty_cond, full_cond;

void add_node(const NFAPI_CRC_INDICATION_PDU_T *data) {
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) return;
    new_node->data = *data;
    pthread_mutex_init(&new_node->mutex, NULL);
    new_node->next = NULL;
    new_node->access_time = time(NULL);

    pthread_mutex_lock(&qmutex);
    if (list_size < MAX_LIST_SIZE) {
        *current_tail = new_node;
        current_tail = &new_node->next;
        list_size++;
        pthread_cond_signal(&notempty_cond);
    } else {
        // Compact the list by removing least recently used nodes
        Node *node, *temp;
        time_t current = time(NULL);
        for (node = head; node != NULL; node = temp) {
            temp = node->next;
            if (current - node->access_time > 60) { // adjust time interval as needed
                pthread_mutex_lock(&node->mutex);
                *current_tail = temp;
                current_tail = &node->next;
                list_size--;
                free(node);
                pthread_mutex_unlock(&node->mutex);
            }
        }

        if (list_size < MAX_LIST_SIZE) {
            *current_tail = new_node;
            current_tail = &new_node->next;
            list_size++;
        } else {
            free(new_node);
        }
    }
    pthread_mutex_unlock(&qmutex);
}

