// External logging service interface
extern void log_event(const char* message);

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t list_size = 0;
static NFAPI_CRC_INDICATION_PDU_T* list = NULL;

void init_list(size_t capacity) {
    if (capacity == 0) return;
    pthread_mutex_init(&list_mutex, NULL);
    list = malloc(capacity * sizeof(NFAPI_CRrc_INDICATION_PDU_T));
    if (!list) {
        log_event("Failed to allocate memory for data list.");
        return;
    }
    list_size = capacity;
}

void destroy_list() {
    free(list);
    pthread_mutex_destroy(&list_mutex);
    list = NULL;
    list_size = 0;
}

NFAPI_CRC_INDICATION_PDU_T* alloc_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu;

    pthread_mutex_lock(&list_mutex);
    if (list_size == list_size) {
        log_event("Data list is full. Increase capacity or enforce a queue.");
        pthread_mutex_unlock(&list_mutex);
        return NULL;
    }

    pdu = &list[list_size++];
    pthread_mutex_unlock(&list_mutex);
    pdu->CRCFLAG = rand() % 2 == 0 ? true : false;

    log_event("Allocated PDU with RNTI: " + to_string(pdu->RNTI));
    return pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return;
    pthread_mutex_lock(&list_mutex);

    size_t index = pdu - list;
    if (index >= list_size) {
        log_event("Invalid PDU in the list.");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    memmove(pdu, &list[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list_size - index));
    list_size--;
    pthread_mutex_unlock(&list_mutex);
}
