typedef struct _bucket {
    struct _bucket *next;
    NFAPI_CRC_INDICATION_PDU_T data;
} bucket_t;

typedef struct _hashmap {
    size_t size;
    bucket_t **buckets;
    pthread_mutex_t mutex;
} hashmap_t;

static inline uint32_t hash(uint32_t key) {
    return key % HASHMAP_SIZE;
}

hashmap_t *new_hashmap(size_t size) {
    hashmap_t *h = malloc(sizeof(hashmap_t));
    h->size = size;
    h->buckets = calloc(size, sizeof(bucket_t*));
    pthread_mutex_init(&h->mutex, NULL);
    return h;
}

void delete_hashmap(hashmap_t *h) {
    for (size_t i = 0; i < h->size; ++i) {
        bucket_t *current = h->buckets[i];
        while (current != NULL) {
            bucket_t *next = current->next;
            free(current);
            current = next;
        }
    }
    free(h->buckets);
    free(h);
}

bucket_t* create_data(uint32_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T data;
    data.rnti = rnti;
    data.crc_indication.crcflag = rand() % 2;
    return malloc(sizeof(bucket_t));
}

void put(hashmap_t *h, uint32_t rnti, NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&h->mutex);
    bucket_t *new_bucket = create_data(rnti);
    size_t index = hash(rnti);
    new_bucket->next = h->buckets[index];
    h->buckets[index] = new_bucket;
    pthread_mutex_unlock(&h->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get(hashmap_t *h, uint32_t rnti) {
    pthread_mutex_lock(&h->mutex);
    size_t index = hash(rnti);
    bucket_t *current = h->buckets[index];
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T *result = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(result, &current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&h->mutex);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&h->mutex);
    return NULL;
}

size_t count(hashmap_t *h) {
    size_t total = 0;
    pthread_mutex_lock(&h->mutex);
    for (size_t i = 0; i < h->size; ++i) {
        bucket_t *current = h->buckets[i];
        while (current != NULL) {
            total++;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&h->mutex);
    return total;
}

void clear(hashmap_t *h) {
    pthread_mutex_lock(&h->mutex);
    for (size_t i = 0; i < h->size; ++i) {
        bucket_t *current = h->buckets[i];
        while (current != NULL) {
            bucket_t *next = current->next;
            free(current);
            current = next;
        }
    }
    pthread_mutex_unlock(&h->mutex);
}
