        free(new_node);
        log4cxx::LoggerPtr logger = log4cxx::Logger::getRootLogger();
        logger->error("Duplicate RNTI encountered");
        return *head;
    }

    while (current->next) {
        current = current->next;
    }
    current->next = new_node;
    return *head;
}

