const bandwidthLimit = 1000000; // Define your bandwidth limit here (in bytes)
let totalBytesSent = 0;

class ApiManager {
  constructor(apiFunction, selector) {
    this.apiFunction = apiFunction;
    this.selector = selector;
  }

  async fetchMetadata(element) {
    if (!element || !this.apiFunction) return null;

    // Check if element is already fetched to avoid redundant requests
    const cachedResult = this._cachedResults.get(element);
    if (cachedResult) return cachedResult;

    let metadata;
    try {
      metadata = await this.apiFunction(element);
      totalBytesSent += Buffer.byteLength(JSON.stringify(metadata), 'utf8');

      // If the bandwidth limit is reached, pause the requests and log a warning
      if (totalBytesSent >= bandwidthLimit) {
        console.warn(`Bandwidth limit of ${bandwidthLimit} bytes exceeded.`);
        return null;
      }
    } catch (error) {
      console.error(`Error fetching metadata for element: ${error}`);
      return null;
    }

    this._cachedResults.set(element, metadata); // Cache the result for future references
    return metadata;
  }

  // Add more APIs by creating instances of the ApiManager class and pushing them to the managers array
  static addApi(apiFunction, selector) {
    const manager = new ApiManager(apiFunction, selector);
    this.managers.push(manager);
  }
}

// Initialize an empty Map for caching API responses
ApiManager._cachedResults = new Map();
ApiManager.managers = []; // Array to store the created instances of ApiManager class

// Custom DOM traversal function using depth-first search with memoization
function traverseDOM(root, callback, context) {
  const visitedNodes = new Set();
  const queue = [[root]];

  while (queue.length > 0) {
    const currentNode = queue.shift()[0];

    // Skip if the node has been visited or if it doesn't match the provided selector
    if (visitedNodes.has(currentNode) || !callback(currentNode, context)) continue;

    visitedNodes.add(currentNode);

    // Traverse children using depth-first search and memoization
    Array.from(currentNode.children).reverse().forEach((child) => queue.push([child]));

    // Fetch metadata for the current node if an ApiManager is provided in the context
    if (context && context instanceof ApiManager) {
      context.fetchMetadata(currentNode);
    }
  }
}

// Example usage: Traverse the DOM tree and fetch metadata using two different APIs
const api1 = async (element) => ({ key1: 'value1' });
const api2 = async (element) => ({ key2: 'value2' });

ApiManager.addApi(api1, (node) => node.tagName === 'DIV');
ApiManager.addApi(api2, (node) => node.className === 'my-class');

traverseDOM(document.body, (node) => node.id === 'root', new ApiManager(api1, api2));
```

