#include <time.h>

typedef struct {
    PHY_FRAME_HEADER header;
    RX_QAM_INFO qam;
    RX_SRS_INFO srs;
} LTE_PHY_RX_FRAME_T;

static const int MAX_MEMORY_KB = 1024;
static const int FRAME_INCREMENT = 10;
static pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;
static LTE_PHY_RX_FRAME_T *frames = NULL;
static size_t frame_count = 0;
static int lcg_seed = 123456789;
static int lcg_increment = 16807;
static int lcg_modulo = 2147483647;

int create_frame(void) {
    if (frame_count >= MAX_MEMORY_KB * 1024) {
        return -1; // Error: Memory limit exceeded
    }

    LTE_PHY_RX_FRAME_T *new_frame = realloc(frames, sizeof(LTE_PHY_RX_FRAME_T) * (frame_count + FRAME_INCREMENT));
    if (!new_frame) {
        return -2; // Error: Memory allocation failed
    }

    frames = new_frame;

    pthread_mutex_lock(&memory_mutex);
    int frame_seq_num = lcg((long unsigned int *)&lcg_seed);
    while (find_duplicate_seq_num(frame_seq_num)) {
        lcg_seed = ((lcg_seed * lcg_increment) % lcg_modulo);
        frame_seq_num = lcg((long unsigned int *)&lcg_seed);
    }

    LTE_PHY_RX_FRAME_T *frame = frames + frame_count;
    frame->header.FRAME_SEQ_NUM = frame_seq_num;
    // Initialize PHY_FRAME_HEADER, RX_QAM_INFO, and RX_SRS_INFO here
    ++frame_count;
    pthread_mutex_unlock(&memory_mutex);

    return 0; // Success
}

int find_duplicate_seq_num(int frame_seq_num) {
    for (size_t i = 0; i < frame_count; ++i) {
        if (frames[i].header.FRAME_SEQ_NUM == frame_seq_num) {
            return 1; // Duplicate found
        }
    }

    return 0; // No duplicates found
}

// LCG function implementation
long unsigned int lcg(long unsigned int *seed) {
    *seed = (*seed * lcg_increment) % lcg_modulo;
    return *seed;
}
