static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRADC_INDICATION_PDU_T* list = NULL;
static size_t list_size = 0;
static size_t max_list_size = 0;

void resize_list(size_t new_size) {
    if (new_size <= max_list_size) return;

    NFAPI_CRADC_INDICATION_PDU_T* new_list = realloc(list, new_size * sizeof(NFAPI_CRADC_INDICATION_PDU_T));
    if (!new_list) {
        log_error("Failed to allocate memory for list expansion.");
        return;
    }

    list = new_list;
    max_list_size = new_size;
}

void push_to_list(const NFAPI_CRADC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list_mutex);
    if (list_size >= max_list_size) resize_list(max_list_size * 2);

    list[list_size] = *data;
    list_size++;
    pthread_mutex_unlock(&list_mutex);
}

void pop_from_list(size_t index, NFAPI_CRADC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list_mutex);
    if (index >= list_size) {
        log_error("Index out of range.");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    *data = list[index];
    memmove(list + index, list + index + 1, (list_size - index - 1) * sizeof(NFAPI_CRADC_INDICATION_PDU_T));
    list_size--;
    pthread_mutex_unlock(&list_mutex);
}

void clear_list() {
    pthread_mutex_lock(&list_mutex);
    free(list);
    list = NULL;
    list_size = 0;
    max_list_size = 0;
    pthread_mutex_unlock(&list_mutex);
}
