// Function to create and populate list of structures, with optional logging
NFAPI_CRC_INDICATION_PDU* createList(size_t numElements, bool enableLogging) {
    if (numElements == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU *list = malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!list) {
        if (enableLogging) printf("Error: Memory allocation failed\n");
        return NULL;
    }

    uint16_t RTNIs[numElements]; // Store unique RNTIs to ensure no duplicates
    bool *crcFlagInRange = calloc(numElements, sizeof(bool));

    // Populate list with valid structures
    size_t index = 0;
    for (size_t i = 0; i < numElements; ++i) {
        if (index >= numElements) break; // Handle potential delays or failures in data sources gracefully

        // Ensure RNTI is unique and CRCFLAG is within valid range
        while (RTNIs[index] == list[i].RNTI || !crcFlagInRange[index]) {
            if (!crcFlagInRange[index]) index++;
            list[index].RX_UE_INFORMATION_TAG = i;
            list[index].RNTI = index + 1; // Ensure RNTIs are incremented starting from 1
            list[index].CRC_INDICATION_REL8_TAG[0] = (rand() % 256);
            list[index].CRC_INDICATION_REL8_TAG[1] = (rand() % 256);
            list[index].CRC_INDICATION_REL8_TAG[2] = (rand() % 256);
            list[index].CRC_INDICATION_REL8_TAG[3] = (rand() % 256);

