                    crcFlagInRange[index] = true;
            }

            index++;
        }

        if (enableLogging && i < numElements - 1) printf("Created structure %zu of %zu\n", i + 1, numElements);
    }

    free(crcFlagInRange); // Deallocate memory to prevent leaks
    return list;
}
