        InterfaceConfig* currentInterface = &interfaces[index];
        currentInterface->name = interface.get<std::string>("name");
        currentInterface->ipAddress = interface.get<std::string>("ip_address");
        currentInterface->subnetMask = interface.get<std::string>("subnet_mask");
        currentInterface->gateway = interface.get<std::string>("gateway", ""); // gateway is optional

        if (currentInterface->name.empty() || currentInterface->ipAddress.empty()) {
            throw std::runtime_error("Empty interface name or IP address found in the configuration");
        }

        index++;
