struct pool {
    size_t capacity;
    size_t count;
    Record *records;
    pthread_mutex_t lock;
    void *shared_checksum;
};

Record *record_alloc(size_t len) {
    Record *rec = mmap(NULL, sizeof(Record) + len, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (rec == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    rec->data = (char*) ((long)rec + sizeof(Record));
    return rec;
}

void record_free(Record *rec) {
    munmap(rec, sizeof(Record) + rec->data_len);
}

void pool_init(struct pool *pool, size_t capacity) {
    pool->capacity = capacity;
    pool->count = 0;
    pool->records = calloc(capacity, sizeof(Record));
    if (!pool->records) {
        perror("calloc");
        exit(EXIT_FAILURE);
    }
    pool->shared_checksum = NULL;
    pthread_mutex_init(&pool->lock, NULL);
}

void pool_destroy(struct pool *pool) {
    for (size_t i = 0; i < pool->capacity; ++i) {
        record_free(pool->records + i);
    }
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
}

Record *pool_get(struct pool *pool, int key) {
    for (size_t i = 0; i < pool->capacity; ++i) {
        if (!pool->records[i].status && pool->records[i].key == key) {
            pool->records[i].status = true;
            return pool->records + i;
        }
    }
    return NULL;
}

Record *pool_create(struct pool *pool, int key, const char *data) {
    Record *rec = record_alloc(strlen(data) + 1);
    rec->key = key;
    rec->status = false;
    rec->data_len = strlen(data) + 1;
    strcpy(rec->data, data);

    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->capacity; ++i) {
        if (!pool->records[i].status && pool->records[i].key == key) {
            pool->records[i] = *rec;
            record_free(rec);
            pthread_mutex_unlock(&pool->lock);
            return pool->records + i;
        }
    }
    if (pool->count < pool->capacity) {
        pool->records[pool->count++] = *rec;
        pthread_mutex_unlock(&pool->lock);
    } else {
        // Handle overflow situation, for example by growing the array.
    }
    return rec;
}

void pool_update(struct pool *pool, int key, const char *data) {
    Record *rec = pool_get(pool, key);
    if (rec) {
        free(rec->data);
        rec->data = NULL;
        rec->data_len = strlen(data) + 1;
        rec->data = strdup(data);
    }
}

char *pool_get_data(struct pool *pool, int key) {
    Record *rec = pool_get(pool, key);
    if (rec) return rec->data;
    else return NULL;
}
