// Function to asynchronously read a file from the specified directory and return its contents as a string
void* read_file(const char* path) {
    FILE* fp = fopen(path, "r");
    if (!fp) return NULL;

    // Determine the file size
    fseek(fp, 0, SEEK_END);
    long filesize = ftell(fp);
    rewind(fp);

    // Allocate memory for the file contents and read the file into it
    char* file_contents = (char*) mmap(NULL, filesize + 1, PROT_READ, MAP_PRIVATE, fileno(fp), 0);
    if (!file_contents) {
        fclose(fp);
        return NULL;
    }

    size_t read = fread(file_contents, sizeof(char), filesize, fp);
    if (read != filesize) {
        munmap(file_contents, filesize + 1);
        fclose(fp);
        return NULL;
    }

    file_contents[filesize] = '\0';
    fclose(fp);

    // Return the file contents without leaking memory
    return file_contents;
}

// Function to dynamically allocate and initialize arrays, ensuring memory usage does not exceed a threshold
void init_arrays(size_t* thresh, size_t* keys, int* values, long* offsets, char** lines) {
    size_t total_allocated = 0;

    // Allocate memory for arrays and initialize them with default values
    *keys = malloc(*thresh * sizeof(int));
    *values = calloc(*thresh, sizeof(int));
    *offsets = malloc(*thresh * sizeof(long));
    *lines = NULL;

    total_allocated += (*keys + *values + *offsets) * sizeof(void*);

    // Allocate memory for line array and read files asynchronously into it using a thread pool
    pthread_t threads[*thresh];
    for (size_t i = 0; i < *thresh; ++i) {
        char* path = /* provide path to the file here */;
        char* line = read_file(path);
        if (!line) continue; // Skip in case of error

        total_allocated += strlen(line) + 1; // Calculate memory usage for this line
        *lines = realloc(*lines, (total_allocated - (*keys + *values + *offsets) * sizeof(void*)) * sizeof(char));
        strcpy(*lines + total_allocated - strlen(line) - 1, line); // Append the read line to the lines array
        free(line); // Free the memory for the read line since it's no longer needed
    }
}

// Main function to demonstrate the usage of the functions above
