unsigned long calculate_checksum(const void* data, size_t length) {
    const unsigned char *ptr = (const unsigned char*)data;
    unsigned long sum = 0;
    for (size_t i = 0; i < length; ++i) {
        sum += ptr[i];
    }
    return sum;
}

Record* init_record(unsigned int min, unsigned int max, size_t buffer_len) {
    Record *record = (Record*)malloc(sizeof(Record));
    if (!record) {
        perror("malloc failed");
        return NULL;
    }
    record->value = rand() % (max - min + 1) + min;
    size_t buffer_size = rand() % buffer_len + 1;
    record->buffer = malloc(buffer_size);
    if (!record->buffer) {
        perror("malloc failed");
        free(record);
        return NULL;
    }
    for (size_t i = 0; i < buffer_size; ++i) {
        record->buffer[i] = rand() % 256;
    }
    record->buffer[buffer_size] = '\0';
    unsigned long checksum = calculate_checksum(record, sizeof(*record));
    // Handle edge case: if the checksum is zero, regenerate the buffer and recalculate the checksum.
    if (checksum == 0) {
        free(record->buffer);
        return init_record(min, max, buffer_len);
    }
    record->buffer[buffer_size] = checksum & 0xFF;
    return record;
}

