    for (size_t i = 0; i < count; ++i) {
        records[i] = init_record(min, max, buffer_len);
        if (!records[i]) {
            destroy_records(records, i);
            perror("init_record failed");
            return 1;
        }
    }
    print_largest(records, count);
    destroy_records(records, count);
    free(records);
    return 0;
}
