#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct element {
    double d;
    int i;
    bool b;
};

void init_arrays(size_t* num_doubles, size_t* num_chars, size_t* num_structs, pthread_mutex_t* seed_mutex) {
    double* d_array = NULL;
    char* c_array = NULL;
    struct element** s_array = NULL;
    pthread_t threads[num_structs];

    if (!(d_array = (double*)malloc(*num_doubles * sizeof(double)))) {
        fprintf(stderr, "Failed to allocate memory for double array.\n");
        exit(EXIT_FAILURE);
    }

    if (!(c_array = (char*)malloc(*num_chars * sizeof(char)))) {
        fprintf(stderr, "Failed to allocate memory for char array.\n");
        free(d_array);
        exit(EXIT_FAILURE);
    }

    if (!(s_array = (struct element**)malloc(*num_structs * sizeof(struct element*)))) {
        fprintf(stderr, "Failed to allocate memory for struct array.\n");
        free(d_array);
        free(c_array);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(seed_mutex);
    unsigned long long seed = time(NULL);
    pthread_mutex_unlock(seed_mutex);

    for (size_t i = 0; i < *num_structs; ++i) {
        struct element* curr_elem = malloc(sizeof(struct element));
        if (!curr_elem) {
            fprintf(stderr, "Failed to allocate memory for struct element.\n");
            free(d_array);
            free(c_array);
            free(s_array);
            exit(EXIT_FAILURE);
        }

        curr_elem->d = 0.0;
        curr_elem->i = (int)(*num_structs * seed++ % (*num_doubles));
        curr_elem->b = rand() % 2;

        s_array[i] = curr_elem;
    }

    // Concurrently fetch initial seed values for random number generation.
    for (size_t i = 0; i < num_structs; ++i) {
        int rc = pthread_create(&threads[i], NULL, fetch_seed, &seed);
        if (rc) {
            fprintf(stderr, "Failed to create thread: %d\n", rc);
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all threads to finish before proceeding.
    for (size_t i = 0; i < num_structs; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Populate the double and char arrays with initial data.
    for (size_t i = 0; i < *num_doubles; ++i) {
        d_array[i] = (double)(*num_doubles * seed++ % INT_MAX);
    }

    for (size_t i = 0; i < *num_chars; ++i) {
        c_array[i] = (char)(*num_chars * seed++ % 256);
    }

    // Free all allocated memory.
    for (size_t i = 0; i < *num_structs; ++i) {
        free(s_array[i]);
    }
    free(s_array);
    free(c_array);
    free(d_array);
}

void* fetch_seed(void* arg) {
    unsigned long long* seed = (unsigned long long*)arg;
    pthread_mutex_lock(seed_mutex);
    *seed += time(NULL);
    pthread_mutex_unlock(seed_mutex);
    return NULL;
}
```

This code defines a function `init_arrays` that takes as input the number of doubles, chars, and structs to allocate. It also accepts a mutex pointer for synchronizing access to the seed value used in random number generation. The function dynamically allocates memory for each array and initializes the struct elements with a random integer field that ensures no duplicates occur across all structs. It uses threads to fetch initial seed values concurrently, ensuring thread safety and minimizing contention when multiple instances of the function are executed concurrently. The function frees all allocated memory at the end of its execution to prevent memory leaks.']

