void generateNfadbConnection(size_t N, const char* proxyServer, const char* user, const char* pass, SQLDataReader** result) {
    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (size_t i = 0; i < N; ++i) {
        pduList[i].rX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG_create(i);
        pduList[i].RNTI = RNTI_create();
        pduList[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    uint8_t* serializedData = serializeNFAPI_CRC_INDICATION_PDU(pduList, N);

    WSADATA wsaData;
    WSAStartup(MAKEWORD(2, 2), &wsaData);

    SOCKET sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);

    struct sockaddr_in serverAddr;
    memset(&serverAddr, 0, sizeof(struct sockaddr_in));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(8080); // Change this to the correct port for your server
    inet_pton(AF_INET, proxyServer, &serverAddr.sin_addr);

    connect(sock, (struct sockaddr*)&serverAddr, sizeof(serverAddr));

    char auth[256];
    sprintf(auth, "Basic %s:", base64encode((const unsigned char*)user, strlen(user) + 1 + strlen(pass) + 1, (const unsigned char*)pass, strlen(pass)));

    send(sock, auth, strlen(auth), 0);

    size_t totalBytesSent = 0;
    const size_t maxRetries = 3;
    for (size_t retry = 0; retry < maxRetries || totalBytesSent != N * sizeof(NFAPI_CRC_INDICATION_PDU_T); ++retry) {
        if (send(sock, serializedData, N * sizeof(NFAPI_CRC_INDICATION_PDU_T), 0) == -1 && errno != EAGAIN) {
            if (retry < maxRetries) {
                continue;
            } else {
                printf("Failed to send data after %d retries, logging a warning.\n", retry + 1);
                break;
            }
        }
        totalBytesSent += N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    DataTableReader* tableResult = NULL;
    for (size_t i = 0; i < maxRetries || !tableResult; ++i) {
        if (!i) {
            recv(sock, &tableResult, sizeof(DataTableReader*), 0);
        } else {
            break;
        }
        Sleep(1000); // Wait for 1 second before retrying
    }

    *result = tableResult;

    closesocket(sock);
    WSACleanup();
}
