void insert(NFAPI_CRC_INDICATION_PDU_T data) {
    if (list_size >= MAX_LIST_SIZE) return;
    pthread_mutex_lock(&list_lock);
    list[list_size] = data;
    list_size++;
    pthread_mutex_unlock(&list_lock);
}

NFAPI_CRC_INDICATION_PDU_T* get() {
    if (list_size == 0) return NULL;
    NFAPI_CRC_INDICATION_PDU_T *data = NULL;
    pthread_mutex_lock(&list_lock);
    data = list[0];
    for(int i = 1; i < list_size; i++) {
        list[i - 1] = list[i];
    }
    list_size--;
    list[list_size] = {}; // Initialize the last element to ensure proper alignment when deleted
    pthread_mutex_unlock(&list_lock);
    return data;
}

void garbage_collection() {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&list_lock);
    for(int i = 0; i < list_size; i++) {
        if (current_time - list[i].timestamp > GARBAGE_COLLECTION_INTERVAL) { // Adjust the interval according to your needs
            list[i] = list[list_size-1];
            list_size--;
        }
    }
    pthread_mutex_unlock(&list_lock);
}

