    NFAPI_CRC_INDICATION_PDU_T **pdus = malloc(numPdus * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for (size_t i = 0; i < numPdus; ++i) {
        pdus[i] = createPDU();
    }

    unsigned char *buffer = malloc(bufferSizeLimit);

    for (size_t i = 0; i < numPdus; ++i) {
        serializePDU(pdus[i], buffer, bufferSizeLimit);
    }

    int retryCount = 0;
    sqlite3_open(":memory:", &dbConnection); // Replace with appropriate database file path if needed

    while (retryCount < 3) {
        int transmissionResult = sendDataToServer(buffer, numPdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (transmissionResult == 0) {
            DataTableReader* result = retrieveQueryResult();
            free(pdus);
            free(buffer);
            return result ? result->getRows() : NULL;
        } else {
            log(Warning, "Failed to send data to server. Retrying...");
            retryCount++;
        }
    }

    sqlite3_close(dbConnection);
    free(pdus);
    free(buffer);
    return NULL;
}
