```cpp
#include <iostream>
#include <vector>
#include <map>
#include <unordered_map>
#include <chrono>
#include <thread>
#include <mutex>
#include <filesystem>
#include <nlohmann/json.hpp>
#include <boost/filesystem.hpp>

using json = nlohmann::json;
using namespace std::chrono_literals;
using namespace boost::filesystem;
using clock = std::chrono::high_resolution_clock;
using time_point = clock::time_point;

struct SessionLog {
    int userID;
    time_point startTime;
    duration<double> duration;
    path location;
};

std::mutex mtx;
unordered_map<int, SessionLog> sessions;

void processSession(const vector<SessionLog>& logs, int userId) {
    time_point current = clock::now();
    auto it = std::find_if(logs.begin(), logs.end(),
        [userId](const SessionLog& log) { return log.userID == userId; });

    duration<double> totalDuration(0);
    if (it != logs.end()) {
        it->startTime = current;
        sessions[userId].duration += it->duration + (current - it->startTime);
    }
    else {
        sessions[userId] = SessionLog{userId, current, duration<double>(0), path()};
    }
}

void processUserSessionData(const vector<SessionLog>& logs) {
    for (auto& log : logs) {
        unique_lock<mutex> lock(mtx);
        lock.unlock_shared(); // unlock to allow concurrent reads
        processSession(logs, log.userID);
        lock.lock();
    }
}

void generateSummaryReport() {
    json result;
    for (const auto& session : sessions) {
        auto durationSec = std::chrono::duration_cast<seconds>(session.second.duration).count();
        result[std::to_string(session.first)] = {{"totalActiveSessionTime", durationSec}, {"averageSessionDuration", (double)durationSec / session.second.duration.count()}};
    }

    ofstream outputFile("summary_report.json");
    outputFile << result.dump();
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        cerr << "Usage: " << argv[0] << " <input-file>" << endl;
        return 1;
    }

    path inputFile = argv[1];
    vector<SessionLog> logs;

    try {
        ifstream input(inputFile);
        if (!input) {
            cerr << "Error: Could not open the input file." << endl;
            return 2;
        }

        SessionLog log;
        while (input >> log.userID >> log.startTime >> log.duration >> log.location) {
            logs.push_back(log);
            log = {}; // reset log for next iteration
        }
    } catch (exception const& e) {
        cerr << "Error reading input file: " << e.what() << endl;
        return 3;
    }

    threadPool pool(4); // adjust number of threads as needed
    for (size_t i = 0; i < logs.size(); i += logs.size() / 4) {
        pool.enqueue([logs, this]() { processUserSessionData(vector<SessionLog>(logs.begin() + i, logs.end())); });
    }
    pool.wait_for_all();

    generateSummaryReport();
    return 0;
}
```

