#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_RECORDS 10000
#define MAX_STRING_LENGTH 256

typedef struct {
    long* offset;
    int key;
    char string[MAX_STRING_LENGTH];
} record;

size_t create_records(int num_offsets, int min_val, int max_val) {
    size_t total = 0;

    // Allocate offsets array
    long* offsets = malloc(num_offsets > MAX_RECORDS ? MAX_RECORDS : num_offsets) * sizeof(long);
    if (!offsets) {
        perror("Error allocating offsets memory");
        return 0;
    }

    // Allocate keys array
    int* keys = malloc(num_offsets * sizeof(int));
    if (!keys) {
        perror("Error allocating keys memory");
        free(offsets);
        return 0;
    }

    // Initialize offsets and keys arrays
    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = -1;
        keys[i] = min_val + (rand() % (max_val - min_val + 1));
    }

    // Allocate record array
    record* records = malloc(num_offsets * sizeof(record));
    if (!records) {
        perror("Error allocating records memory");
        free(offsets);
        free(keys);
        return 0;
    }

    // Initialize record pointers and fill the strings with random characters
    for (size_t i = 0; i < num_offsets; ++i) {
        records[i].offset = offsets + i;
        total += sizeof(record);
    }

    srand((unsigned int)time(NULL));
    char set[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (size_t i = 0; i < num_offsets * MAX_RECORDS; ++i) {
        records[i / num_offsets].string[i % num_offsets] = set[rand() % strlen(set)];
    }

    return total;
}
