```c
#include "libnfapi_crc_list.h"
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

static void nfapi_crc_list_resize(NFAPI_CRC_LIST* list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* tmp = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!tmp) return;

    list->data = tmp;
    list->capacity = new_capacity;
}

void nfapi_crc_list_init(NFAPI_CRC_LIST* list, size_t initial_capacity) {
    list->mutex = PTHREAD_MUTEX_INITIALIZER;
    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) return;

    list->capacity = initial_capacity;
    list->length = 0;
    nfapi_crc_list_resize(list, list->capacity);
}

void nfapi_crc_list_push(NFAPI_CRC_LIST* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);

    if (list->length >= list->capacity) nfapi_crc_list_resize(list, list->capacity * 2);

    memcpy(&list->data[list->length], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->length++;

    pthread_mutex_unlock(&list->mutex);
}

void nfapi_crc_list_free(NFAPI_CRC_LIST* list) {
    free(list->data);
}

void nfapi_crc_list_garbage_collect(NFAPI_CRC_LIST* list, time_t current_time) {
    pthread_mutex_lock(&list->mutex);

    size_t i = 0;
    for (; i < list->length; i++) {
        if (current_time - list->data[i].timestamp > MAX_TIMESTAMP_AGE) {
            memmove(&(list->data[i]), &(list->data[i + 1]), (list->length - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->length--;
        } else break;
    }

    pthread_mutex_unlock(&list->mutex);
}
