from dateutil.tz import tzutc
import ctypes
import ctypes.util

class NFAPI_CRC_INDICATION_PDU_T(ctypes.Structure):
    _fields_ = [
        ('tag', ctypes.c_uint64),
        ('rnti', ctypes.c_uint64),
        ('crc_indication', ctypes.c_uint32)
    ]

class CRCList(object):
    def __init__(self, library_path: str, capacity=1024):
        self._lib = ctypes.cdll.LoadLibrary(library_path)
        self._list = ctypes.POINTER(NFAPI_CRC_INDICATION_PDU_T)()
        self._capacity = capacity
        self._lib.nfapi_crc_list_init.restype = None
        self._lib.nfapi_crc_list_init.argtypes = [self._list, c_size_t(self._capacity)]

    def push(self, tag: int, rnti: int, crc_indication: int):
        pdu = self._lib.new(NFAPI_CRC_INDICATION_PDU_T)
        pdu.tag = ctypes.c_uint64(tag)
        pdu.rnti = ctypes.c_uint64(rnti)
        pdu.crc_indication = ctypes.c_uint32(crc_indication)

        self._lib.nfapi_crc_list_push.argtypes = [self._list, ctypes.POINTER(NFAPI_CRC_INDICATION_PDU_T)]
        self._lib.nfapi_crc_list_push(self._list)

    def garbage_collect(self):
        self._lib.nfapi_crc_list_garbage_collect.argtypes = [self._list, ctypes.c_double]
        current_time = time.time() + tzutc().utcoffset()
        self._lib.nfapi_crc_list_garbage_collect(self._list, current_time)

    def free(self):
        self._lib.nfapi_crc_list_free.argtypes = [self._list]
        self._lib.nfapi_crc_list_free(self._list)
