RecordPool* create_record_pool(size_t initial_capacity) {
    RecordPool *pool = malloc(sizeof(RecordPool));
    pool->records = calloc(initial_capacity, sizeof(Record));
    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_rwlock_init(&pool->lock, NULL);
    return pool;
}

Record* find_record(RecordPool *pool, int key) {
    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->records[i].key == key) {
            return &pool->records[i];
        }
    }
    return NULL;
}

Record* allocate_record(RecordPool *pool) {
    if (pool->count >= pool->capacity) {
        // Increase capacity as needed
    }
    Record *record = &pool->records[pool->count++];
    record->key = -1; // Indicate uninitialized state
    return record;
}

void initialize_record(Record *record, int key, const char *data) {
    record->key = key;
    record->status = true;
    size_t data_len = strlen(data) + 1;
    record->data = malloc(data_len);
    memcpy(record->data, data, data_len);
    record->checksum = crc32(0L, ZLIB_CRC32_TABLE, record->data, data_len);
}

bool update_record(Record *record, const char *data) {
    if (record->key == -1) return false; // Uninitialized state

    size_t data_len = strlen(data) + 1;
    record->data = realloc(record->data, data_len);
    memcpy(record->data, data, data_len);
    record->checksum = crc32(0L, ZLIB_CRC32_TABLE, record->data, data_len);
    return true;
}

const char* get_data(Record *record) {
    if (record->key == -1) return NULL; // Uninitialized state
    return record->data;
}

void destroy_record_pool(RecordPool *pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->records[i].data);
    }
    free(pool->records);
    free(pool);
}
