#include <iostream>
#include <vector>
#include <pthread.h>
#include <boost/random.hpp>
#include <boost/interprocess/sparse_array.hpp>
#include <boost/log/trivial.hpp>
#include <boost/timer/timer.hpp>

const int MAX_UE = 1024; // Max number of UE instances
typedef boost::interprocess::sparse_array<int, std::string> UERNTIArray;

struct NFAPI_CRCI_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG = 0xABCD;
    uint16_t RNTI;
    bool CRCFLAG;
};

class UEMemoryManager {
private:
    std::vector<NFAPI_CRCI_PDU_T> uePDUs;
    UERNTIArray rntiMap;
    const int capacity = 16; // Initial capacity for the array
    pthread_mutex_t mutex;
public:
    UEMemoryManager() : uePDUs(capacity), mutex(PTHREAD_MUTEX_INITIALIZER) {}

    void allocateUE(int count) {
        boost::timer::auto_cpu_timer t;
        pthread_mutex_lock(&mutex);
        if (uePDUs.size() < count) {
            uePDUs.resize(count, { .RNTI = -1 }); // Initialize with -1 as a placeholder for non-assigned RNTIs
            int newCapacity = std::min((int)(capacity * 2), MAX_UE);
            uePDUs.reserve(newCapacity);
            capacity = newCapacity;
        }
        pthread_mutex_unlock(&mutex);

        for (int i = uePDUs.size() - count; i < uePDUs.size(); ++i) {
            int rnti = -1;
            while ((rnti = getUnassignedRNTI(rnti)) != -1) {
                if (i == rntiMap[rnti]) { // RNTI is already assigned to this UE instance, skip it
                    continue;
                }
                uePDUs[i].RNTI = rnti;
                rntiMap[rnti] = i;
                uePDUs[i].CRCFLAG = boost::random::random<bool>();
            }
        }
    }

    int getUnassignedRNTI(int rnti) const {
        for (auto it = rntiMap.begin(); it != rntiMap.end(); ++it) {
            if (it->second == -1 || it->first == rnti) continue;
            if (it->first == uePDUs[it->second].RNTI) return -1; // RNTI is already assigned to this UE instance, skip it
        }
        return rntiMap.insert("new_rnti", -1).first->first;
    }

    void logResourceUsage() const {
        double memoryUsage = uePDUs.size() * sizeof(NFAPI_CRCI_PDU_T);
        BOOST_LOG_TRIVIAL(info) << "Memory usage: " << memoryUsage << " bytes";
    }
};
```

