#include <semaphore.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct dynamic_array {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    sem_t semaphore;
};

void init_dynamic_array(struct dynamic_array* array, size_t initial_capacity) {
    array->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }

    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&(array->mutex), NULL);
    sem_init(&(array->semaphore), 0, array->capacity);
}

void destroy_dynamic_array(struct dynamic_array* array) {
    free(array->data);
    pthread_mutex_destroy(&(array->mutex));
    sem_destroy(&(array->semaphore));
}

bool is_full(const struct dynamic_array* array) {
    return array->count == array->capacity;
}

bool insert(struct dynamic_array* array, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (is_full(array)) {
        // Handle capacity overflow here
        return false;
    }

    pthread_mutex_lock(&(array->mutex));

    array->data[array->count] = *pdu;
    array->count++;

    pthread_mutex_unlock(&(array->mutex));

    sem_post(&(array->semaphore)); // Release the semaphore for another thread to access the array

    return true;
}

void* delete(struct dynamic_array* array, size_t index) {
    pthread_mutex_lock(&(array->mutex));

    if (index >= array->count || index < 0) {
        // Handle out-of-bounds error here
        NFAPI_CRC_INDICATION_PDU_T empty;
        pthread_mutex_unlock(&(array->mutex));
        return &empty;
    }

    void* deleted_pdu = &(array->data[index]);

    memmove(&(array->data[index]), &(array->data[index + 1]), (array->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->count--;

    pthread_mutex_unlock(&(array->mutex));

    sem_post(&(array->semaphore)); // Release the semaphore for another thread to access the array

    return deleted_pdu;
}
```

