typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t crc;
    uint16_t length;
    unsigned char data[1]; // Variable-length array
} NFAPI_CRC_INDICATION_PDU_T;

// Synchronization object for thread safety
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Hash table structure (separate chaining)
typedef struct HashElement {
    NFAPI_CRC_INDICATION_PDU_T element;
    struct HashElement *next;
} HashElement;

HashElement* hash_table[HASH_TABLE_SIZE]; // Initialize to NULL

// Function to calculate CRC using an external library
extern void calculate_crc(unsigned char*, uint32_t*);

bool is_valid_tag(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    return strcmp(pdu->data, CRC_INDICATION_TAG) == 0;
}

void insert_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    uint32_t hash = hash_function(pdu);
    pthread_mutex_lock(&list_mutex);

    HashElement** current = &hash_table[hash];
    HashElement *new_element = malloc(sizeof(HashElement));

    if (!new_element) {
        fprintf(stderr, "Out of memory while allocating element\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    new_element->element = *pdu;
    new_element->next = NULL;

    // Iterate through the chain until the end or a valid tag is found
    while (*current && !is_valid_tag(&((*current)->element)))
        current = &(*current)->next;

    if (!*current) { // If we reached the end of the chain and there was no valid tag, insert the new element at the end
        *current = new_element;
    } else { // Otherwise, discard the invalid PDUs
        free(new_element);
    }

    pthread_mutex_unlock(&list_mutex);
}

NFAPI_CRC_INDICATION_PDU_T* find_pdu(const uint32_t crc) {
    uint32_t hash = hash_function((uint8_t*)&crc + sizeof(crc));
    pthread_mutex_lock(&list_mutex);

    HashElement* current = hash_table[hash];
    while (current != NULL) {
        if (current->element.crc == crc) {
            NFAPI_CRC_INDICATION_PDU_T *result = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(result, &current->element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&list_mutex);
            return result;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);
    return NULL;
}

uint32_t hash_function(const void* key) {
    uint32_t hash = 5381;
    const unsigned char* data = (const unsigned char*)key;
    int c;

    while ((c = *data++))
        hash = ((hash << 5) + hash) + c; // Hash function borrowed from https://en.wikipedia.org/wiki/Hash_function#Simple_functions

    return hash % HASH_TABLE_SIZE;
}
