['```cpp
#include <atomic>
#include <memory>
#include <vector>
#include <mutex>

template<typename T>
class Octree {
public:
    struct Node {
        std::array<Octree*, 8> children;
        std::unique_ptr<T[]> data;
        bool isLeaf = false;
        std::atomic_int usageCount{1};

        ~Node() {
            if (--usageCount == 0) {
                for (auto& child : children) {
                    if (child) {
                        delete child;
                    }
                }
                delete[] data.get();
                delete this;
            }
        }
    };

    Octree(size_t featureSize, size_t maxLeafNodes, std::function<void*(size_t)> memoryManager) :
        root_(nullptr), maxLeafNodes_(maxLeafNodes), memoryManager_(memoryManager) {
        auto blockSize = static_cast<size_t>(std::pow(2.0, std::ceil(std::log2(maxLeafNodes_ + 1))));
        blockMemory_ = memoryManager_(blockSize);
    }

    void* allocateData(size_t capacity) {
        if (!dataBuffer_) {
            dataBuffer_ = memoryManager_(capacity);
        }
        if (dataBufferEnd_ - dataBuffer_ >= capacity) {
            return dataBuffer_;
        }
        auto newBuffer = memoryManager_(capacity);
        std::copy(dataBuffer_, dataBufferEnd_, reinterpret_cast<char*>(newBuffer));
        dataBuffer_ = newBuffer;
        dataBufferEnd_ += capacity;
        return dataBuffer_;
    }

    OctreeNode* createNode() {
        if (freeNodes_.empty()) {
            auto nodeBlock = memoryManager_(sizeof(OctreeNode) * 8);
            for (size_t i = 0; i < 8; ++i) {
                new (nodeBlock + i * sizeof(OctreeNode)) OctreeNode();
                freeNodes_.push_back(nodeBlock + i * sizeof(OctreeNode));
            }
        }
        auto node = freeNodes_.back();
        freeNodes_.pop_back();
        return reinterpret_cast<OctreeNode*>(node);
    }

    void destroy() {
        if (root_) {
            delete root_;
            root_ = nullptr;
        }
        if (!freeNodes_.empty()) {
            freeNodes_.clear();
            memoryManager_(freeNodes_.size() * sizeof(OctreeNode));
        }
        if (dataBuffer_) {
            memoryManager_(dataBuffer_);
            dataBuffer_ = nullptr;
            dataBufferEnd_ = 0;
        }
    }

    void insert(const std::vector<float>& coords, T value) {
        std::unique_lock<std::mutex> lock(mutex_);
        auto node = root_;
        for (size_t i = 0; i < 3; ++i) {
            int bit = static_cast<int>(coords[i] / (featureSize / 2.0));
            if (!node->children[bit]) {
                node->children[bit] = createNode();
            }
            node = node->children[bit];
        }
        if (node->isLeaf) {
            // Handle leaf full condition
        }
        node->data.reset(new T[capacity_]);
        std::copy(std::begin(node->data), std::end(node->data), std::begin(node->data) + capacity_);
        std::fill(std::end(node->data), std::end(node->data) + node->data.size(), value);
    }

    T query(const std::vector<float>& coords) const {
        std::unique_lock<std::mutex> lock(mutex_);
        auto node = root_;
        for (size_t i = 0; i < 3; ++i) {
            int bit = static_cast<int>(coords[i] / (featureSize / 2.0));
            if (!node->children[bit]) {
                return T(); // Handle prefix leaf condition
            }
            node = node->children[bit];
        }
        return node->data ? node->data->at(static_cast<size_t>(coords[2] / (featureSize / 8.0))) : T();
    }

private:
    OctreeNode* root_;
    size_t maxLeafNodes_;
    std::function<void*(size_t)> memoryManager_;
    void* dataBuffer_;
    char* dataBufferEnd_;
    std::vector<OctreeNode*> freeNodes_;
    mutable std::mutex mutex_;
    size_t capacity_{featureSize / 8.0}; // Adjust this value based on desired data density
};
```
