void populateNFAPICRCIndicationList(std::list<std::string>& list, const std::string& searchKey, const std::string& newElement) {
    auto it = std::find(list.begin(), list.end(), searchKey);
    if (it != list.end()) {
        list.insert(++it, newElement);
    } else {
        list.push_back(newElement);
    }

    // Populate and initialize the NFAPI_CRC_INDICATION_PDU_T structures for each element in the list
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;
    data.reserve(list.size());
    std::mt19937 gen(std::random_device{}());
    std::generate_n(std::back_inserter(data), list.size(), [&]() { return (NFAPI_CRC_INDICATION_PDU_T){searchKey, static_cast<unsigned int>(list.size()), {true}}; });
    for (auto& element : data) {
        list.emplace(it, element);
