typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
};

static const uint32_t MIN_RNTI = 0x0001;
static const uint32_t MAX_RNTI = 0x7FFFFF;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static struct node *list_head = NULL;
static size_t list_size = 0;

void initialize_list(const uint32_t* rntis, const size_t num_rntis, const uint16_t* crc_indications) {
    pthread_mutex_lock(&list_mutex);

    for (size_t i = 0; i < num_rntis; ++i) {
        if (!is_valid_rnti(rntis[i])) {
            fprintf(stderr, "Invalid RNTI: 0x%" PRIx32 "\n", rntis[i]);
            pthread_mutex_unlock(&list_mutex);
            return;
        }
    }

    struct node *current = list_head;
    struct node *new_node;

    while (current != NULL && list_size < num_rntis) {
        free(current);
        current = NULL;
        list_size -= 1;

        new_node = malloc(sizeof(struct node));
        if (!new_node) {
            fprintf(stderr, "Out of memory\n");
            pthread_mutex_unlock(&list_mutex);
            return;
        }

        // Initialize the new node with valid data
        new_node->data.RX_UE_INFORMATION_TAG = 0;
        new_node->data.RNTI = rntis[list_size];
        new_node->data.CRC_INDICATION_REL8_TAG = crc_indications[list_size];
        new_node->next = list_head;
        list_head = new_node;
        list_size += 1;
    }

    if (current != NULL) {
        // Handle the case where there are leftover nodes from a previous allocation
        while (current != NULL) {
            struct node *temp = current;
            current = current->next;
            free(temp);
        }
    }

    pthread_mutex_unlock(&list_mutex);
}

bool is_valid_rnti(const uint32_t rnti) {
    return rnti >= MIN_RNTI && rnti <= MAX_RNTI;
}

