#include <pthread.h>
#include <stdbool.h>
#include <semaphore.h>
#include <sys/mman.h>
#include <time.h>

typedef struct record {
    int value;
} Record;

typedef struct memory_block {
    size_t size;
    Record* data;
    struct memory_block* next;
} MemoryBlock;

MemoryBlock* head = NULL;
MemoryBlock* tail = NULL;
sem_t sem_memory;

void log_memory(const char* action, MemoryBlock* block) {
    // Implement logging for memory allocation and deallocation events
}

Record* allocate_record() {
    sem_wait(&sem_memory);

    MemoryBlock* current = head;
    if (current == NULL) {
        current = (MemoryBlock*)mmap(NULL, sizeof(MemoryBlock), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        current->size = 1;
        current->data = calloc(current->size, sizeof(Record));
        current->next = NULL;
        head = current;
    } else {
        while (current->next != NULL && current->next->size >= current->size) {
            current = current->next;
        }

        if (current->size < current->next->size) {
            MemoryBlock* new_block = (MemoryBlock*)mmap(NULL, sizeof(MemoryBlock), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
            new_block->size = current->next->size - current->size;
            new_block->data = (Record*)((char*)current->next->data + current->size * sizeof(Record));
            new_block->next = current->next;
            current->next = new_block;
        }
    }

    log_memory("allocate", current);
    return current->data;
}

void deallocate_record(Record* record) {
    MemoryBlock* block = (MemoryBlock*)((char*)record - offsetof(MemoryBlock, data));

    if (block->size == 1) {
        log_memory("deallocate", block);
        free(block->data);
        munmap((void*)block, sizeof(MemoryBlock));
        if (head == block) {
            head = block->next;
        } else {
            MemoryBlock* current = head;
            while (current->next != block) {
                current = current->next;
            }
            current->next = block->next;
        }
    }
}

void initialize_records(Record* records, size_t num_records, int min_value, int max_value) {
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = min_value + i;
        while (i > 0 && records[i].value == records[i - 1].value) {
            records[i].value++;
            i--;
        }
    }
}

// Thread-safe initialization function for the record array
