    size_t num_records = *(size_t*)args;
    int min_value = *(int*)(args + sizeof(size_t));
    int max_value = *(int*)(args + (2 * sizeof(size_t)));

    Record* records = allocate_record();
    initialize_records(records, num_records, min_value, max_value);

    pthread_exit(records);
}
