// SensorData struct to store timestamp, device ID, and scaled sensor value
struct SensorData {
    long long timestamp;
    int device_id;
    double scaled_value = 0.0;
};

// Function to read and process a dynamically sized list of floating-point numbers
void processSensorData(int M) {
    std::vector<SensorData> data(M); // Dynamic array for efficient memory management
    double smallestPositiveNumber = std::numeric_limits<double>::max();
    double currentValue;
    long long timestamp, device_id;

    while (std::cin >> timestamp >> device_id >> currentValue) {
        if (currentValue > 0.0 && currentValue < smallestPositiveNumber) {
            smallestPositiveNumber = currentValue;
        }

        // Find the first empty element in the dynamic array
        auto it = std::find_if(data.cbegin(), data.cend(), [](const SensorData& s) { return !s.scaled_value; });

        if (it != data.cend()) {
            *it = { timestamp, device_id, currentValue / smallestPositiveNumber };
        }
    }
}

int main() {
    int M;
    std::cin >> M; // Read the configurable dataset size from command-line argument

