[' Here is a simple implementation of a thread-safe resource manager in C using pthreads and a circular buffer for statistics and dynamic expansion. This example manages integer resources with a configurable max size and logs resource utilization patterns.

```c
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Circular buffer structure for statistics
typedef struct {
    size_t capacity;
    size_t read;
    size_t write;
    void *data[1];
} RingBuffer;

// Resource manager structure
typedef struct {
    pthread_mutex_t lock; // Mutex for thread-safety
    RingBuffer stats;     // Circular buffer for statistics
    int max_size;          // Maximum size of the pool
    bool log_enabled;      // Enable/disable logging
    char *log_file;        // Log file path
} ResourceManager;

// Initialize ring buffer
void rb_init(RingBuffer *rb, size_t capacity) {
    rb->capacity = capacity;
    rb->read = 0;
    rb->write = 0;

    void *data[1] = malloc(rb->capacity * sizeof(void *));
    memset(data, 0, rb->capacity * sizeof(void *));
    rb->data[0] = data;
}

// Ring buffer write function (thread-safe)
void rb_write(RingBuffer *rb, void *data) {
    pthread_mutex_lock(&rb->lock);

    // Overflow handling
    if ((rb->write + 1) >= rb->capacity)
        rb->write = 0;

    // Write data to the buffer and update write index
    ((void **)(rb->data))[rb->write] = data;
    ++(rb->write);

    pthread_mutex_unlock(&rb->lock);
}

// Ring buffer read function (thread-safe)
void *rb_read(RingBuffer *rb) {
    void *data;

    pthread_mutex_lock(&rb->lock);

    // Underflow handling
    if (rb->read == rb->write)
        data = NULL;
    else {
        data = ((void **)(rb->data))[rb->read];
        ++(rb->read);

        // Overflow handling
        if ((rb->read + 1) >= rb->capacity)
            rb->read = 0;
    }

    pthread_mutex_unlock(&rb->lock);

    return data;
}

// Resource manager initialize function
void rm_init(ResourceManager *rm, int max_size, bool log_enabled, const char *log_file) {
    memset(rm, 0, sizeof(ResourceManager));
    pthread_mutex_init(&rm->lock, NULL);

    rb_init(&rm->stats, 128); // Circular buffer for statistics (capacity is configurable)
    rm->max_size = max_size;
    rm->log_enabled = log_enabled;
    if (log_file != NULL && log_enabled) {
        rm->log_file = strdup(log_file);
        freopen(rm->log_file, "a", stderr);
    }
}

// Resource allocation function
void *rm_alloc(ResourceManager *rm) {
    while (true) {
        void *resource;

        // Lock mutex and check if resources are available
        pthread_mutex_lock(&rm->lock);
        if (rm->stats.write != rm->stats.read && rm->max_size > rm->stats.data[0]) {
            resource = rm->stats.data[rm->stats.write];
            --rm->stats.write;
            pthread_mutex_unlock(&rm->lock);
            break;
        } else if (rm->max_size <= 0) { // Max size is reached, no more allocations allowed
            pthread_mutex_unlock(&rm->lock);
            return NULL;
        } else {
            pthread_mutex_unlock(&rm->lock);
            usleep(1000); // Sleep for a short time to avoid spinlock contention
        }
    }

    if (rm->log_enabled)
        fprintf(stderr, "Resource allocated\n");

    return resource;
}

// Resource deallocation function
void rm_free(ResourceManager *rm, void *resource) {
    pthread_mutex_lock(&rm->lock);

    if (rm->max_size > 0 && resource != NULL) {
        // Enforce maximum size and add the resource to the circular buffer for statistics
        if ((++(rm->stats.write) % rm->stats.capacity) == 0)
            rb_write(&rm->stats, malloc(sizeof(void)));

        ((void **)(rm->stats.data))[rm->stats.write - 1] = resource;
    }

    pthread_mutex_unlock(&rm->lock);

    if (rm->log_enabled)
        fprintf(stderr, "Resource deallocated\n");
}
```

Configure the maximum size and logging settings by calling `rm_init()` with appropriate arguments. To use the resource manager for managing resources of a specific type, you should modify the `void *` data types to match your requirements. For example, if you want to manage integers, replace all `void *` with `int`. Also, ensure that any other functions that operate on these resources are properly updated.

This resource manager is designed to handle concurrent access efficiently using a mutex lock and a circular buffer for statistics. However, it does not enforce the resource reallocation policy as it is left up to your specific application requirements. To control the number of active allocations, you could implement an eviction strategy that frees resources when the maximum number of active allocations is exceeded.']

