    if (!*data) return MEMORY_ALLOCATION_FAILURE;

    // Ensure the allocated memory is large enough to hold n elements or resize as needed
    int current_length = 1;
    while (current_length < n) {
        *data = realloc(*data, (current_length + MAX_ARRAY_RESIZE) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!*data) return MEMORY_ALLOCATION_FAILURE;
    }
    *length = n;

    // Initialize array with valid elements using custom random number generator
