        (*data)[i].tag.sequence_number = i;
        (*data)[i].rnti = generate_random(seed + i);
        (*data)[i].crc_indication.crcflag = ((*data)[i].rnti & CRCI_MASK);
    }

    return SUCCESS;
}

uint32_t generate_random(uint32_t seed) {
    srand(seed);
    return rand();
}

error_code toggle_crcflag(NFAPI_CRC_INDICATION_PDU_T *element) {
