#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <arpa/inet.h>
#include "logger.h" // Provided logger interface

typedef struct NetworkHeader {
    uint32_t packet_id;
    in_port_t source_port;
    struct in_addr source_ip;
    in_port_t destination_port;
    struct in_addr destination_ip;
    uint16_t protocol_type;
    uint16_t packet_length;
    // Payload data and metadata fields
} NetworkHeader;

typedef struct HeaderList {
    NetworkHeader **headers;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HeaderList;

// Initialize header list with given capacity
HeaderList* init_header_list(size_t capacity) {
    HeaderList *list = malloc(sizeof(HeaderList));
    if (!list) {
        log_error("Failed to allocate memory for header list.");
        return NULL;
    }

    list->headers = calloc(capacity, sizeof(NetworkHeader*));
    if (!list->headers) {
        free(list);
        log_error("Failed to allocate memory for header array.");
        return NULL;
    }

    list->capacity = capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Create a new network header and add it to the header list
NetworkHeader* create_header(const struct in_addr src_ip, const in_port_t src_port, const struct in_addr dest_ip, const in_port_t dest_port, const uint16_t protocol, const uint16_t len) {
    NetworkHeader *header = malloc(sizeof(NetworkHeader));
    if (!header) {
        log_error("Failed to allocate memory for network header.");
        return NULL;
    }

    memset(header, 0, sizeof(NetworkHeader));

    header->packet_id = (uint32_t)time(NULL);
    header->source_ip = src_ip;
    header->source_port = src_port;
    header->destination_ip = dest_ip;
    header->destination_port = dest_port;
    header->protocol_type = protocol;
    header->packet_length = len;

    return header;
}

// Add a new header to the header list, returning 1 on success and 0 on failure
int add_header(HeaderList *list, NetworkHeader *header) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        log_warning("Reached maximum header capacity.");
        pthread_mutex_unlock(&list->lock);
        free(header);
        return 0;
    }

    list->headers[list->size] = header;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    log_info("Added network header to the list.");
    return 1;
}

// Iterate over the headers in the header list
void iterate_headers(const HeaderList *list, void (*callback)(NetworkHeader*)) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        callback(list->headers[i]);
    }

    pthread_mutex_unlock(&list->lock);
}

// Cleanup the header list and its contents on destruction
void destroy_header_list(HeaderList *list) {
    pthread_mutex_destroy(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        free(list->headers[i]);
    }

    free(list->headers);
    free(list);
}
```

This code provides a basic implementation of a header list data structure, following the given constraints. The `init_header_list`, `create_header`, and `add_header` functions initialize and manage the list, while `iterate_headers` allows iterating over its contents using a callback function. The `destroy_header_list` function cleans up the list on destruction.

You can provide your own logger implementation in the "logger.h" file to log errors, warnings, and informational messages as needed. This example does not include any interaction with external data sources or performance optimizations, so you may need to further adapt it based on your specific requirements and constraints.']

