    int reusable_rntis_count;
} thread_safe_list;

thread_safe_list* create_tsl(int initial_pool_size) {
    thread_safe_list *tsl = malloc(sizeof(thread_safe_list));
    pthread_mutex_init(&(tsl->mutex), NULL);
    tsl->rnti_pool_size = initial_pool_size;
    tsl->current_rnti = 0;
    tsl->rnti_pool_exhausted = false;
    tsl->head = malloc(initial_pool_size * sizeof(NFAPI_CRC_INDICATION_PDU*));
    for (int i = 0; i < initial_pool_size; ++i) {
        tsl->head[i] = NULL;
    }
    tsl->reusable_rntis = NULL;
    tsl->reusable_rntis_count = 0;
    return tsl;
}

void destroy_tsl(thread_safe_list *tsl) {
    pthread_mutex_destroy(&(tsl->mutex));
    free(tsl->head);
    free(tsl);
}

int get_next_rnti(thread_safe_list *tsl) {
    if (tsl->reusable_rntis != NULL) {
        int rnti = tsl->reusable_rntis->rnti;
        NFAPI_CRC_INDICATION_PDU *tmp = tsl->reusable_rntis;
        tsl->reusable_rntis = tmp->next;
        ++tsl->reusable_rntis_count;
        return rnti;
    }
    if (tsl->current_rnti < tsl->rnti_pool_size) {
        return tsl->current_rnti++;
    } else {
        // handle exhaustion here
        return -1;
    }
}

void push(thread_safe_list *tsl, NFAPI_CRC_INDICATION_PDU *node) {
    pthread_mutex_lock(&(tsl->mutex));
    int rnti = get_next_rnti(tsl);
    if (rnti == -1) {
        // handle exhaustion here
        pthread_mutex_unlock(&(tsl->mutex));
        return;
    }
    node->rnti = rnti;
    node->next = tsl->head[rnti % tsl->rnti_pool_size];
    tsl->head[rnti % tsl->rnti_pool_size] = node;
    pthread_mutex_unlock(&(tsl->mutex));
}

NFAPI_CRC_INDICATION_PDU* pop(thread_safe_list *tsl, int rnti) {
    pthread_mutex_lock(&(tsl->mutex));
    NFAPI_CRC_INDICATION_PDU *node = tsl->head[rnti % tsl->rnti_pool_size];
    if (node != NULL) {
        tsl->head[rnti % tsl->rnti_pool_size] = node->next;
        NFAPI_CRC_INDICATION_PDU *tmp = node;
        tmp->next = tsl->reusable_rntis;
        tsl->reusable_rntis = tmp;
        --tsl->reusable_rntis_count;
    }
    pthread_mutex_unlock(&(tsl->mutex));
    return node;
}
```

This code provides a basic implementation of a thread-safe linked list using a dynamic `RNTI` pool. The function `create_tsl()` initializes the data structures and mutex for synchronization, while `destroy_tsl()` cleans up resources when done.

The `push()` function adds an element to the list, and `pop()` removes it. Both functions use a mutex for thread safety. The `get_next_rnti()` function manages the `RNTI` pool, returning a new `RNTI` when possible or indicating exhaustion of the pool.

