unsigned int hashFunction(unsigned int key) {
    unsigned long hash = 5381;
    int c;

    while ((c = (unsigned char)key)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
        key = (key >> 8);
    }

    return hash % INT_MAX;
}

void ensureCapacity() {
    int capacity = 10000;
    int newCapacity = capacity * 2;
    Node** current = &head;
    Node* next = NULL;

    while (capacity <= (*current)->next ? (*current)->next : (*current)) {
        next = (Node*)malloc(sizeof(Node));
        if (!next) handleError("Out of memory");
        next->data = (NFAPI_CRC_INDICATION_PDU_T){};
        next->next = NULL;
        if ((*current)->next) {
            (*current)->next = next;
            current = &(*current)->next;
        } else {
            (*current) = next;
        }
        capacity = newCapacity;
    }
}

bool isUniqueRNTI(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Node* current = head;
    unsigned int hashKey = hashFunction(pdu->rnti);

    while (current) {
        if (current->data.rnti == pdu->rnti && current != head) {
            return false;
        }
        if (hashKey == current->hashKey) {
            current = current->next;
        } else {
            current = head;
            current = current->next;
        }
    }

    return true;
}

void addPDU(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!isUniqueRNTI(pdu)) {
        log("Duplicate RNTI detected.");
        return;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) handleError("Out of memory");
    newNode->data = *pdu;
    newNode->next = NULL;

    ensureCapacity();

    unsigned int hashKey = hashFunction(pdu->rnti);
    Node* current = head;

    while (current) {
        if (hashKey == current->hashKey) {
            newNode->next = current->next;
            current->next = newNode;
            break;
        }
        current = current->next;
    }

    if (!current) {
        log("Adding to the end of the list.");
        (*(head == NULL ? &head : &((*head)->next))) = newNode;
    }
}

