void read_file(FILE **file, char *filename) {
    if (*file = fopen(filename, "r")) {
        fseek(*file, 0, SEEK_END);
        long file_size = ftell(*file);
        rewind(*file);
        char *buffer = malloc(file_size + 1);
        if (fread(buffer, 1, file_size, *file)) {
            buffer[file_size] = '\0';
            fclose(*file);
            *file = fmemopen(buffer, file_size, "r");
        } else {
            free(buffer);
            *file = NULL;
        }
    }
}

void* create_structure(void *threadarg) {
    struct thread_data *data = threadarg;
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu) {
        pthread_mutex_lock(&pdu->crci.crcflag_mutex);
        pdu->crci.crcflag = data->index % 2;
        pthread_mutex_unlock(&pdu->crci.crcflag_mutex);
        read_file(&(pdu->crci.data), "crc_indication.log");
    }
    free(data);
    return pdu;
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list() {
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(NUM_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    struct thread_data *datas = malloc(NUM_STRUCTURES * sizeof(struct thread_data));
    if (list && datas) {
        pthread_t threads[NUM_STRUCTURES];
        for (int i = 0; i < NUM_STRUCTURES; ++i) {
            struct thread_data *data = &datas[i];
            data->index = i;
            data->file = NULL;
            pthread_create(&threads[i], NULL, create_structure, data);
        }
        for (int i = 0; i < NUM_STRUCTURES; ++i) {
            pthread_join(threads[i], (void**)&list[i]);
        }
        free(datas);
    }
    return list;
}
