} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
} dynamic_list_t;

static inline void crc_indication_rel8_tag_init(CRC_INDICATION_REL8_TAG *tag) {
    tag->crcflag = rand() % 2;
}

static dynamic_list_t* create_dynamic_list(size_t initial_capacity, size_t *out_allocated_memory) {
    dynamic_list_t *list = malloc(sizeof(dynamic_list_t));
    if (!list) return NULL;

    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->length = 0;
    list->mutex = PTHREAD_MUTEX_INITIALIZER;

    *out_allocated_memory = sizeof(dynamic_list_t) + initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    return list;
}

static void dynamic_list_add(dynamic_list_t *list, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);

    if (list->length == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        dynamic_list_t *temp_list = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_list) {
            pthread_mutex_unlock(&list->mutex);
            return;
        }

        list->data = temp_list;
        list->capacity = new_capacity;
    }

    list->data[list->length] = *pdu;
    crc_indication_rel8_tag_init(&list->data[list->length].crc_indication_rel8_tag);
    list->length++;

    pthread_mutex_unlock(&list->mutex);
}

static void dynamic_list_remove(dynamic_list_t *list, size_t index) {
    pthread_mutex_lock(&list->mutex);

    if (index >= list->length) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    memmove(list->data + index, list->data + index + 1, (list->length - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->length--;

    pthread_mutex_unlock(&list->mutex);
}

static void dynamic_list_destroy(dynamic_list_t **list_ptr) {
    if (!list_ptr || !*list_ptr) return;

    free((*list_ptr)->data);
    free(*list_ptr);
    *list_ptr = NULL;
}

