```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    int value;
    struct Record *next;
} Record;

struct GAL {
    Record **array;
    size_t size, cap;
    pthread_spinlock_t lock;
};

void init_gal(GAL* gal, size_t initial_cap) {
    gal->array = malloc(initial_cap * sizeof(Record*));
    gal->size = 0;
    gal->cap = initial_cap;
    gal->lock = PTHREAD_SPINLOCK_INITIALIZER;
}

void resize_gal(GAL* gal) {
    if (gal->cap == 0)
        gal->cap = 8;
    gal->array = realloc(gal->array, (gal->cap * 2) * sizeof(Record*));
    gal->cap *= 2;
}

size_t find_gap(const GAL* gal, size_t idx) {
    for (size_t i = idx + 1; i < gal->size; ++i)
        if (!gal->array[i])
            return i - 1;
    return gal->size - 1;
}

void insert_record(GAL* gal, size_t idx, int value) {
    pthread_spin_lock(&gal->lock);
    Record *new_rec = malloc(sizeof(Record));
    new_rec->value = value;
    new_rec->next = gal->array[idx];
    if (find_gap(gal, idx) != -1) {
        gal->array[find_gap(gal, idx)] = new_rec;
    } else {
        resize_gal(gal);
        for (size_t i = gal->size - 1; i > idx; --i)
            gal->array[i] = gal->array[i - 1];
        gal->array[idx] = new_rec;
    }
    ++gal->size;
    pthread_spin_unlock(&gal->lock);
}

Record* get_record(const GAL* gal, size_t idx) {
    Record *rec = NULL;
    pthread_spin_lock(&gal->lock);
    rec = gal->array[idx];
    if (!rec) {
        size_t gap = find_gap(gal, idx);
        if (gap != -1) {
            rec = malloc(sizeof(Record));
            rec->value = gal->array[(gap + 1) % gal->size]->value + 1;
            rec->next = gal->array[idx];
            gal->array[gap] = rec;
        } else {
            resize_gal(gal);
            for (size_t i = gal->size - 1; i > idx; --i)
                gal->array[i + 1] = gal->array[i];
            Record *last = &gal->array[idx];
            rec = malloc(sizeof(Record));
            rec->value = last->next ? last->next->value + 1 : 0;
            rec->next = last->next;
            last->next = rec;
            ++gal->size;
        }
    }
    pthread_spin_unlock(&gal->lock);
    return rec;
}

void iterate_reverse(const GAL* gal, void (*fn)(Record*)) {
    for (size_t i = gal->size - 1; i != 0; ) {
        --i;
        Record *rec = get_record(gal, i);
        if (rec) fn(rec);
    }
}
```

