        return NULL;
    }

    return list;
}

void genCRCI(NFAPI_CRCI_T* list, size_t count) {
    uint32_t seed = 0;
    uint32_t bitmask = 1 << 15; // define your own bitmask

    for (size_t i = 0; i < count; ++i) {
