using System.Text.RegularExpressions;

namespace DynamicQuery
{
    public class QueryRunner
    {
        private readonly string _connectionString;

        public QueryRunner(string connectionString)
        {
            _connectionString = connectionString;
        }

        public IDataReader ExecuteQuery(string sqlTemplate, IDictionary<string, object> parameters)
        {
            if (string.IsNullOrEmpty(sqlTemplate))
                throw new ArgumentException("SQL template cannot be null or empty.");

            var dbConnection = CreateDbConnection();

            try
            {
                var commandBuilder = new SqlCommandBuilder(_dbCommand);
                BuildCommand(sqlTemplate, parameters, _dbCommand);

                dbConnection.Open();
                using (var dbCommand = _dbCommand.Clone() as DbCommand)
                {
                    dbCommand.Connection = dbConnection;
                    return commandBuilder.DataAdapter.Fill(dbCommand.ExecuteReader());
                }
            }
            catch (Exception ex)
            {
                LogError(ex);
                throw;
            }
        }

        private DbCommand _dbCommand = new SqlCommand();

        private void BuildCommand(string sqlTemplate, IDictionary<string, object> parameters, SqlCommand command)
        {
            if (sqlTemplate.Contains("{"))
                sqlTemplate = Regex.Replace(sqlTemplate, @"\{(?<name>\w+)\}", BuildParameter);

            command.CommandText = sqlTemplate;

            foreach (var parameter in parameters)
            {
                var dbType = GetDbType(parameter.Value);
                var parameterObject = new SqlParameter
                {
                    ParameterName = parameter.Key,
                    Value = parameter.Value,
                    DbType = dbType,
                    SourceColumnNullMappingBehavior = System.Data.MappingType.Ignore,
                    SourceVersionInfo = DataRowVersion.Current
                };
                command.Parameters.Add(parameterObject);
            }
        }

        private string BuildParameter(Match match) => $"@{match.Groups["name"].Value}";

        private DbConnection CreateDbConnection()
        {
            var connection = new SqlConnection(_connectionString);
            connection.Open();
            return connection;
        }

        private void LogError(Exception ex)
        {
            // Implement logging mechanism of choice, e.g., Serilog, Console.WriteLine or custom log service.
            Console.WriteLine($"Error: {ex.Message}");
        }

        private DbType GetDbType(object value)
        {
            if (value is string strValue)
                return DbType.AnsiString;

            if (value is int intValue || value is long longValue || value is float floatValue || value is double doubleValue)
                return DbType.Int32; // Default to int32 as it covers the majority of numeric data types.

            // Handle other data types based on specific requirements or performance considerations.
        }
    }
}
