['Here is a C implementation of a hash table with linear probing for the given task. The code uses an array to store records and another array for key indices. The maximum size is defined as `MAX_SIZE`. To minimize cache thrashing, we use power of 2 for both arrays' sizes.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    long offset;
    int key;
    int value;
} Record;

const int MAX_SIZE = 1 << 16; // Set maximum size to 65536

int* keys;
Record** records;

void hash(int key) {
    return hash % MAX_SIZE;
}

int find_index(int key) {
    int idx = keys[key];
    if (idx == -1) return -1; // Key not found
    return idx;
}

void set_key_index(int key, int index) {
    keys[key] = index;
}

Record* get_record(int key) {
    int index = find_index(key);
    if (index == -1) return NULL; // Key not found
    return records[index];
}

void put_record(Record record) {
    int key = record.key;
    Record* existing = get_record(key);

    if (existing != NULL) {
        int probe = 1;
        int index = find_index(key);
        while (existing != NULL && index == find_index(key)) {
            index = (hash(key + probe++) % MAX_SIZE);
            existing = get_record(key);
        }
    }

    int index = find_index(key);
    if (index != -1) records[index] = &record;
    else {
        if (records == NULL || records_size >= MAX_SIZE) {
            // Truncate the excess records and log an error message
            printf("Truncating records due to exceeding maximum size.\n");
            truncate();
        }
        index = find_index(key);
        if (index != -1) {
            printf("Duplicate key encountered during insertion. Key: %d\n", key);
        }
        records_size++;
        set_key_index(key, index);
        records[index] = &record;
    }
}

void del_record(int key) {
    int index = find_index(key);
    if (index == -1) return; // Key not found

    Record* record = records[index];
    records[index] = records[records_size - 1];
    records_size--;
    keys[record->key] = -1;
}

void batch_insert(Record* records, int size) {
    for (int i = 0; i < size; ++i) {
        put_record(records[i]);
    }
}

void batch_delete(int* keys, int size) {
    for (int i = 0; i < size; ++i) {
        del_record(keys[i]);
    }
}

// Persistent storage integration (to be implemented)
void save() {}
void load() {}

// Truncate the excess records and free memory
void truncate() {
    int deleted_count = 0;
    for (int i = records_size - 1; i >= 0; --i) {
        if (records[i] != NULL) {
            free(records[i]);
            ++deleted_count;
        }
    }
    records_size -= deleted_count;
}

// Allocate memory for records and keys arrays when the hash table is created
void init() {
    records = (Record**)calloc(MAX_SIZE, sizeof(Record*));
    keys = (int*)calloc(MAX_SIZE, sizeof(int));
    memset(keys, -1, MAX_SIZE * sizeof(int));
    records_size = 0;
}

// Free all allocated resources when the hash table is destroyed
void destroy() {
    truncate();
    free(records);
    free(keys);
}
```

To use this code, you should call `init()` before using the hash table and `destroy()` after. The `save()` and `load()` functions are placeholders for integrating with persistent storage.']

