struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
};

class ConcurrentDynamicList {
private:
    std::deque<NFAPI_CRC_INDICATION_PDU_T> data_;
    std::mutex mtx_;
    boost::asio::thread_pool thread_pool_;

public:
    ConcurrentDynamicList(size_t numThreads) : thread_pool_(numThreads) {}

    void enqueue(NFAPI_CRC_INDICATION_PDU_T data) {
        boost::asio::post(thread_pool_, [this, data]() {
            std::unique_lock<std::mutex> lock(mtx_);
            data_.push_back(data);
        });
    }

    // Other operations: dequeue, size, clear, etc. Implement these using the same pattern as enqueue.
};

void log_error(const boost::property_tree::ptree& log) {
