```rust
use reqwest::Client;
use serde_json::{Map, Value}; // Adjust depending on data format requirements
use std::env;
use std::error::Error;
use url::Url;

pub fn http_client(disable_certificate_validation: bool) -> Result<reqwest::blocking::RequestBuilder, Box<dyn Error>> {
    let client = Client::new();
    if disable_certificate_validation {
        client.builder()
            .dangerously_disable_ssl_validations()
    } else {
        client.clone()
    }
}

pub fn make_request(url: &str, method: &str, headers: Map<String, Value>, body: Option<Value>) -> Result<reqwest::Response, Box<dyn Error>> {
    let mut request = http_client(false)?.get(Url::parse(url).unwrap())?;
    request.method(method);
    for (key, value) in headers {
        request = request.header(key, value);
    }
    if let Some(body) = body {
        request = request.body(body);
    }
    request.send()
}
