typedef struct linked_list {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct linked_list *next;
} linked_list_t;

linked_list_t* create_list() {
    linked_list_t *head = malloc(sizeof(linked_list_t));
    if (!head) return NULL;

    head->data.RX_UE_INFORMATION_TAG = 0;
    head->next = NULL;

    return head;
