void add_pdu_to_list(linked_list_t **head, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!is_valid_tag(pdu->RX_UE_INFORMATION_TAG)) return;

    linked_list_t *new_node = malloc(sizeof(linked_list_t));
    if (!new_node) return;

    new_node->data = *pdu;
    new_node->next = NULL;

    if (!*head || (*head)->data.RX_UE_INFORMATION_TAG < new_node->data.RX_UE_INFORMATION_TAG) {
        new_node->next = *head;
        *head = new_node;
    } else {
        linked_list_t *current = *head;
        while (current && current->next && current->next->data.RX_UE_INFORMATION_TAG < new_node->data.RX_UE_INFORMATION_TAG) {
            current = current->next;
