        if (!current || current->next == NULL) {
            current->next = new_node;
        } else {
            new_node->next = current->next;
            current->next = new_node;
        }
    }
}

void resize_list(linked_list_t **head, size_t new_capacity) {
    if (new_capacity <= *head->data.RX_UE_INFORMATION_TAG) return;

    linked_list_t *new_head = malloc(sizeof(linked_list_t) * new_capacity);
    if (!new_head) return;

    size_t index = 1;
    linked_list_t *current = *head;
    while (current) {
        current->data.RX_UE_INFORMATION_TAG = index++;
        add_pdu_to_list(&new_head, &current->data);
        current = current->next;
