void serialize_list(const linked_list_t *head, uint8_t *buffer) {
    size_t position = 0;
    while (head) {
        memcpy(buffer + position, &head->data.RX_UE_INFORMATION_TAG, sizeof(uint32_t));
        position += sizeof(uint32_t);
        memcpy(buffer + position, &head->data.RNTI, sizeof(uint16_t));
        position += sizeof(uint16_t);
        memcpy(buffer + position, &head->data.CRC_INDICATION, sizeof(CRC_INDICATION_REL8_TAG));
        position += sizeof(CRC_INDICATION_REL8_TAG);

        head = head->next;
    }
}

linked_list_t* deserialize_list(const uint8_t *buffer, size_t buffer_size) {
    if (buffer_size < SERIALIZED_DATA_SIZE) return NULL;

    linked_list_t *head = create_list();
    linked_list_t *current = head;

    size_t position = 0;
    while (position + SERIALIZED_DATA_SIZE <= buffer_size) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) break;

        memcpy(&pdu->RX_UE_INFORMATION_TAG, buffer + position, sizeof(uint32_t));
        position += sizeof(uint32_t);
        memcpy(&pdu->RNTI, buffer + position, sizeof(uint16_t));
        position += sizeof(uint16_t);
        memcpy(&pdu->CRC_INDICATION, buffer + position, sizeof(CRC_INDICATION_REL8_TAG));
        position += sizeof(CRC_INDICATION_REL8_TAG);

        add_pdu_to_list(&current, pdu);
