class DynamicRandomGenerator {
public:
    DynamicRandomGenerator(double minValue, double maxValue) : minValue_(minValue), maxValue_(maxValue) {
        if (maxValue <= minValue) {
            throw std::invalid_argument("Max value must be greater than min value.");
        }
    }

    int getRandomInt(bool inclusive = true) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (cache_.empty()) {
            generateAndCache();
        }
        int result;
        if (inclusive) {
            result = static_cast<int>(utilitarian_generator_(minValue_, maxValue_) * (1.0 / (maxValue_ - minValue_)) * std::numeric_limits<uint32_t>::max());
        } else {
            result = static_cast<int>((utilitarian_generator_((minValue_ + maxValue_) / 2.0, (maxValue_ - minValue_) / 2.0) * (1.0 / ((maxValue_ - minValue_) / 2.0)) * std::numeric_limits<uint32_t>::max() + (maxValue_ + minValue_) / 2);
        }
        return result;
    }

    double getRandomFloat(bool inclusive = true) {
        return static_cast<double>(getRandomInt(inclusive)) * ((maxValue_ - minValue_) / std::numeric_limits<uint32_t>::max()) + minValue_;
    }

    void logErrorAndUsage(const std::string& message) {
        if (!logFile_.is_open()) {
            logFile_.open("logs.txt", std::ios::app);
        }
        logFile_ << "[" << std::this_thread::get_id() << "] " << message << "\n";
    }

    void populateNFAPICrcIndicationPduList(std::vector<NFAPI_CRC_INDICATION_PDU_T>& list, size_t count) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (count > 1024) {
            throw std::invalid_argument("The requested list size exceeds the maximum allowed.");
        }
        for (size_t i = 0; i < count; ++i) {
            list.push_back({ rand(), rand(), static_cast<int>(utilitarian_generator_(0, 1)) });
        }
    }

private:
    std::random_device rd_;
    std::mt19937 utilitarian_generator_{rd_};
    double minValue_, maxValue_;
    mutable std::mutex mutex_;
    std::unordered_map<uint64_t, int> cache_; // Key: random number (hash of value), Value: index in the sequence.
    std::deque<int> numberSequence_; // Stores the sequence of numbers generated.
    std::ofstream logFile_;

    void generateAndCache() {
        for (auto i = 0; i < std::numeric_limits<uint64_t>::max(); ++i) {
            int number = getRandomInt(false);
            cache_[i] = numberSequence_.push_back(number) - 1; // Get the index of the pushed element, which is one more than the element's position in the deque.
        }
    }
};
