```cpp
#include <iostream>
#include <memory>
#include <unordered_map>
#include <mutex>
#include <thread>
#include <vector>
#include <future>
#include <functional>
#include <stdexcept>
#include <atomic>
#include <condition_variable>
#include <boost/asio/io_service.hpp>

class MemoryPool {
public:
    virtual std::unique_ptr<Record> allocate() = 0;
};

class Record {
public:
    explicit Record(int key, long offset) : m_key(key), m_offset(offset) {}

    int getKey() const { return m_key; }
    long getOffset() const { return m_offset; }

private:
    int m_key;
    long m_offset;
};

class ValidationService {
public:
    virtual bool validate(int key, long offset) = 0;
};

class Database {
private:
    std::unordered_map<int, std::unique_ptr<Record>> m_records;
    std::shared_ptr<MemoryPool> m_memoryPool;
    std::shared_ptr<ValidationService> m_validationService;
    std::mutex m_mutex;

public:
    Database(std::shared_ptr<MemoryPool> memoryPool, std::shared_ptr<ValidationService> validationService)
        : m_memoryPool(std::move(memoryPool))
        , m_validationService(std::move(validationService)) {}

    void addRecord(int key, long offset) {
        // Create the record
        auto record = m_memoryPool->allocate();
        record->getKey() = key;
        record->setOffset(offset);

        // Validate and store if valid
        if (m_validationService->validate(key, offset)) {
            std::unique_lock<std::mutex> lock(m_mutex);
            m_records[key] = std::move(record);
        }
    }
};

class ThreadSafeDatabase : public Database {
private:
    std::condition_variable m_condVar;
    std::atomic_int m_numThreads;
    boost::asio::io_service m_ioService;

public:
    ThreadSafeDatabase(std::shared_ptr<MemoryPool> memoryPool, std::shared_ptr<ValidationService> validationService)
        : Database(std::move(memoryPool), std::move(validationService)), m_numThreads(0) {}

    void addRecord(int key, long offset) {
        // Add record to the non-threadsafe database
        Database::addRecord(key, offset);

        // Notify all threads that a new slot is available
        {
            std::unique_lock<std::mutex> lock(m_mutex);
            m_condVar.notify_all();
        }
    }

    void startThreads() {
        m_numThreads = static_cast<int>(std::thread::hardware_concurrency());

        std::vector<std::future<void>> futures;
        for (int i = 0; i < m_numThreads; ++i) {
            auto self = shared_from_this();
            futures.emplace_back(self->m_ioService.post(
                std::bind(&ThreadSafeDatabase::processNewRecord, self.get(), std::placeholders::_1, std::placeholders::_2)));
        }

        m_ioService.run();
    }

private:
    void processNewRecord(int key, long offset) {
        while (true) {
            std::unique_lock<std::mutex> lock(m_mutex);
            m_condVar.wait(lock, [this] { return m_records.size() < m_records.max_load_factor(); });

            if (!m_records.empty()) {
                auto it = m_records.begin();
                lock.unlock();

                // Process the record here
                std::unique_lock<std::mutex> logLock(it->second->getLogMutex());
                it->second->logOperation();

                lock.lock();
                m_records.erase(it);
                lock.unlock();
            } else {
                break;
            }
        }
    }
};
```

This outline creates a `ThreadSafeDatabase` that can handle millions of records concurrently while ensuring data integrity and scalability. It interfaces with an external `ValidationService` for key and offset validation, logs record operations, and employs a memory pool to allocate resources efficiently. The system utilizes a condition variable to signal new slots when the database is full, allowing multiple threads to add records concurrently without causing data corruption.']

