    void append(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::scoped_lock lock(mtx);
        if (list.size() >= maxSize) {
            list.pop_back();
        }
        auto it = std::find_if(list.begin(), list.end(), [&pdu](const std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>& p) { return *p->get()->RNTI == pdu.rnti; });
        if (it != list.end()) {
            it = list.erase(it);
            ++it = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>(pdu);
        } else {
            list.insert(it, std::move(std::make_unique<NFAPI_CRC_INDICATION_PDU_T>(pdu)));
        }
        std::sort(list.begin(), list.end(), comparator);
    }

    void replace(const std::vector<NFAPI_CRC_INDICATION_PDU_T>& newList) {
        std::scoped_lock lock(mtx);
