    sem_wait(&list->mutex);
    uint32_t index = cell_id % list->capacity;
    for (DL_FRAME_INFO_T** ptr = &list->table[index]; *ptr != NULL; ptr = &((*ptr)->next)) {
        if ((*ptr)->cell_id == cell_id) {
            sem_post(&list->mutex);
            return; // Duplicate CELL_ID detected, skip adding the frame info.
        }
    }

    DL_FRAME_INFO_T* new_entry = malloc(sizeof(DL_FRAME_INFO_T));
    if (!new_entry) {
        perror("Out of memory");
        sem_post(&list->mutex);
        return; // Handle out-of-memory error gracefully.
    }

    pthread_mutex_init(&new_entry->lock, NULL);
    new_entry->info = *info;
    new_entry->cell_id = cell_id;
    new_entry->sync_flag = sync_flag;
    new_entry->next = list->table[index];
    list->table[index] = new_entry;
    sem_post(&list->mutex);
#elif defined(USE_BALANCED_TREE)
    BTNode* node = malloc(sizeof(BTNode));
    if (!node) {
        perror("Out of memory");
        return; // Handle out-of-memory error gracefully.
    }

    pthread_mutex_init(&node->data.lock, NULL);
    node->data.info = *info;
    node->data.cell_id = cell_id;
    node->data.sync_flag = sync_flag;
    balanced_tree_insert(list->tree, &node->node, compare_cell_ids);
#endif
}

