typedef struct RX_BUFFER_T {
    void* buffer;
    size_t buffer_size;
} RX_BUFFER_T;

typedef struct RX_FRAME_INFO {
    RX_BUFFER_T* rx_buffers; // Array of pointers to RX_BUFFER_T structures
    size_t num_rx_buffers;   // Number of RX_BUFFER_T structures in the array
} RX_FRAME_INFO;

RX_FRAME_INFO* allocate_frame_info(size_t frames) {
    if (frames > 128) {
        fprintf(stderr, "Error: Cannot allocate more than 128 frames.\n");
        return NULL;
    }

    RX_FRAME_INFO* frame_infos = malloc(sizeof(RX_FRAME_INFO) * frames);

    if (!frame_infos) {
        fprintf(stderr, "Error: Out of memory.\n");
        return NULL;
    }

    for (size_t i = 0; i < frames; ++i) {
        size_t buffers_count = 16; // Initial number of RX_BUFFER_T structures per frame
        RX_BUFFER_T** rx_buffers = malloc(sizeof(RX_BUFFER_T*) * buffers_count);

        if (!rx_buffers) {
            fprintf(stderr, "Error: Out of memory.\n");
            free(frame_infos);
            return NULL;
        }

        frame_infos[i].num_rx_buffers = 0;
        for (size_t j = 0; j < buffers_count; ++j) {
            RX_BUFFER_T* rx_buffer = calloc(1, sizeof(RX_BUFFER_T));

            if (!rx_buffer) {
                fprintf(stderr, "Error: Out of memory.\n");
                free(frame_infos);
                free(rx_buffers);
                return NULL;
            }

            rx_buffer->buffer = malloc(16 * sizeof(char)); // Initial buffer size of 16 bytes
            if (!rx_buffer->buffer) {
                fprintf(stderr, "Error: Out of memory.\n");
                free(rx_buffer);
                free(frame_infos);
                free(rx_buffers);
                return NULL;
            }

            rx_buffer->buffer_size = 16;
            rx_buffers[frame_infos[i].num_rx_buffers++] = rx_buffer;
        }

        frame_infos[i].rx_buffers = rx_buffers;
    }

    return frame_infos;
}
