void deallocate(NFAPI_CRC_INDICATION_PDU_T* ptr, size_t size) {
    pthread_mutex_lock(&pool_mutex);
    if (ptr && total_allocated > allocated_count) {
        void* temp = pool + allocated_count;
        memcpy(temp, ptr, size);
        allocated_count++;
    }
    pthread_mutex_unlock(&pool_mutex);
