#include <ctime>
#include <iostream>
#include <exception>

struct LTE_PHY_RX_FRAME {
    unsigned int FRAME_NUMBER;
    std::clock_t RX_TIMESTAMP;
    int RX_POWER_LEVEL;
    short RF_CHANNEL;
};

class DynamicLTERxFrameBuffer {
public:
    explicit DynamicLTERxFrameBuffer(size_t initialSize) : buffer_(initialSize), currentIndex_(0) {}

    void resize(size_t newSize) {
        if (newSize <= currentIndex_)
            throw std::invalid_argument("New size cannot be smaller than the current index");

        auto tempBuffer = std::vector<LTE_PHY_RX_FRAME>(newSize);
        std::copy_if(std::begin(buffer_), std::min(std::end(buffer_), std::end(tempBuffer)), std::begin(tempBuffer),
                     [](const LTE_PHY_RX_FRAME& frame) { return currentIndex_ >= frame.FRAME_NUMBER; });
        buffer_.swap(tempBuffer);
        currentIndex_ = newSize;
    }

    void logMemoryOperation(const std::string& operation) const {
        using namespace std;
        time_t now = time(0);
        tm* ltm = localtime(&now);
        cout << asctime(ltm) << "[" << operation << "]" << endl;
    }

    LTE_PHY_RX_FRAME& operator[](unsigned int index) {
        if (index >= currentIndex_)
            resize(index + 1);
        return buffer_[index];
    }

private:
    std::vector<LTE_PHY_RX_FRAME> buffer_;
    unsigned int currentIndex_;
};
```

