struct data_point {
    float value;
    char identifier;
    point point;
};

// Thread-safe memory pool for data points and events
static pthread_mutex_t mem_pool_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t num_free_data_points = 0, num_free_events = 0;
static struct data_point* free_data_points = NULL;
static event* free_events = NULL;

void* allocate_data_point() {
    pthread_mutex_lock(&mem_pool_mutex);

    if (num_free_data_points > 0) {
        void* data_point = free_data_points++;
        num_free_data_points--;
        pthread_mutex_unlock(&mem_pool_mutex);
        return data_point;
    }

    void* data_point = malloc(sizeof(struct data_point));
    if (!data_point) {
        pthread_mutex_unlock(&mem_pool_mutex);
        return NULL;
    }

    num_free_data_points++;
    free_data_points = (struct data_point*)realloc(free_data_points, num_free_data_points * sizeof(struct data_point));
    pthread_mutex_unlock(&mem_pool_mutex);

    return data_point;
}

void* allocate_event() {
    pthread_mutex_lock(&mem_pool_mutex);

    if (num_free_events > 0) {
        void* event = free_events++;
        num_free_events--;
        pthread_mutex_unlock(&mem_pool_mutex);
        return event;
    }

    void* event = malloc(sizeof(event));
    if (!event) {
        pthread_mutex_unlock(&mem_pool_mutex);
        return NULL;
    }

    num_free_events++;
    free_events = (event*)realloc(free_events, num_free_events * sizeof(event));
    pthread_mutex_unlock(&mem_pool_mutex);

    return event;
}

// Function to process incoming data streams concurrently
void process_data_stream(void* arg) {
    // Initialize variables for processing a single data point
    struct data_point* current_data_point = allocate_data_point();
    if (!current_data_point) return;

    float value, *ptr = (float*)current_data_point;
    char identifier, *char_ptr = (char*)((long long)ptr + 4);
    point* point_ptr = (point*)((long long)char_ptr + 1);

    // Read the incoming data and initialize the current_data_point structure
    value = read_float_value();
    identifier = read_identifier();
    point_ptr->x = read_double();
    point_ptr->y = read_double();

    // Allocate an event and initialize its timestamp and status message
    event* current_event = allocate_event();
    if (!current_event) {
        free(current_data_point);
        return;
    }

    current_event->timestamp = get_current_time();
    read_status_message(current_event->status, sizeof(current_event->status));

    // Process the data point and event as needed for your specific application
    process_data(current_data_point, current_event);

    // Log memory allocation and deallocation events for performance analysis
    log_memory_event("Allocated", "DataPoint", current_data_point);
    log_memory_event("Allocated", "Event", current_event);
}
