#include <ctype.h>

typedef struct {
    char id[16];
    char ip[INET_ADDRSTRLEN];
    char subnet_mask[INET_ADDRSTRLEN];
    char gateway[INET_ADDRSTRLEN];
} NetworkInterface;

struct network_data {
    NetworkInterface* interfaces;
    size_t capacity;
    size_t size;
};

NetworkData network_init() {
    return (NetworkData){.interfaces = NULL, .capacity = 0, .size = 0};
}

void network_free(NetworkData* data) {
    free(data->interfaces);
    data->capacity = 0;
    data->size = 0;
}

int network_add(NetworkData* data, const NetworkInterface* interface) {
    if (data->capacity == data->size) {
        size_t new_capacity = data->capacity * 2 + 1;
        NetworkInterface* new_interfaces = realloc(data->interfaces, sizeof(NetworkInterface) * new_capacity);
        if (!new_interfaces) return -1;
        data->interfaces = new_interfaces;
        data->capacity = new_capacity;
    }
    memcpy(&data->interfaces[data->size], interface, sizeof(NetworkInterface));
    data->size++;
    return 0;
}

int network_has_duplicate(const NetworkData* data, const NetworkInterface* interface) {
    for (size_t i = 0; i < data->size; ++i) {
        if (!strcmp(data->interfaces[i].id, interface->id)) return 1;
    }
    return 0;
}
