#include <stdio.h>
#include <string.h>
#include <libtiff/tiffiop.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <openssl/md5.h>

typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
    int extra_samples;
} TiffInfo;

TiffInfo tiff_parse(const char* filename) {
    TIFF *tif;
    if (tifdopen(filename, "r", &tif) != 0) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        exit(1);
    }

    // Read image structure information
    int bit_depth;
    if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bit_depth) != 1) {
        fprintf(stderr, "Error reading bits per sample\n");
        exit(1);
    }
    uint16_t photometric;
    if (TIFFGetField(tif, TIFFTAG_PHOTOMETRIC, &photometric) != 1) {
        fprintf(stderr, "Error reading photometric\n");
        exit(1);
    }
    uint32_t samples_per_pixel;
    if (TIFFGetFieldDefaulted(tif, TIFFTAG_SAMPLESPERPIXEL, &samples_per_pixel) != 1) {
        fprintf(stderr, "Error reading samples per pixel\n");
        exit(1);
    }
    uint32_t extra_samples;
    if (TIFFGetFieldDefaulted(tif, TIFFTAG_EXTRASAMPLES, &extra_samples) != 1) {
        fprintf(stderr, "Error reading extra samples\n");
        exit(1);
    }

    // Compute MD5 hash for provided string input
    char input[1024];
    snprintf(input, sizeof(input), "%s", "your_string_here");
    unsigned char digest[MD_DIGEST_LENGTH];
    MD5((unsigned char*)input, strlen(input), digest);

    TiffInfo info = {
        .bits_per_sample = bit_depth,
        .samples_per_pixel = samples_per_pixel,
        .extra_samples = extra_samples
    };

    tifclose(tif);
    return info;
}
