    while (true) {
        NFAPI_CRC_INDICATION_PDU_T* new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_element) break;

        sem_wait(&rnti_mutex);
        while (array_capacity >= array_capacity && array) {
            sem_post(&rnti_mutex);
            sleep(1);
        }

        uint32_t rnti = 0;
        do {
            rnti = rand();
        } while (check_rnti(&rnti));

        new_element->rxi.tag = RX_UE_INFORMATION_TAG_VALID;
        new_element->rnti = rnti;
        new_element->crcind.tag = CRC_INDICATION_REL8_TAG_VALID;
        generate_crcflag(&new_element->crcind.crcFlag);

        if (!array) {
            array = new_element;
            array_capacity = 1;
        } else if (array_capacity < array_capacity * 2) {
            NFAPI_CRC_INDICATION_PDU_T* old_array = array;
            array = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (array_capacity * 2));
            if (!array) {
                free(old_array);
                free(new_element);
                break;
            }
            array_capacity *= 2;
            memcpy(array + old_array_capacity, old_array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * old_array_capacity);
            free(old_array);
        } else {
            void* temp = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (array_capacity + 1));
            if (!temp) break;
            array = temp;
            array[array_capacity++] = new_element;
        }
        sem_post(&rnti_mutex);
    }
    return NULL;
}

void cleanup() {
    if (array) {
        free(array);
        array = NULL;
        array_capacity = 0;
    }
