struct DataManager {
    size_t capacity;
    size_t size;
    NFAPICRC *array;
    char logfile[256];
};

void create_NFAPICRC(DataManager *manager) {
    manager->array = malloc(sizeof(NFAPICRC) * manager->capacity);
    for (size_t i = 0; i < manager->capacity; ++i) {
        new (&manager->array[i]) NFAPICRC();
        pthread_mutex_init(&manager->array[i].lock, NULL);
    }
}

NFAPICRC* find_NFAPICRC(DataManager *manager, uint64_t RX_UE) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].RX_UE == RX_UE)
            return &manager->array[i];
    }
    return NULL;
}

void add_NFAPICRC(DataManager *manager, NFAPICRC nfapicrc) {
    pthread_mutex_lock(&manager->array[manager->size].lock);
    manager->array[manager->size] = nfapicrc;
    manager->size++;
    pthread_mutex_unlock(&manager->array[manager->size - 1].lock);
}

void update_NFAPICRC(DataManager *manager, uint64_t RX_UE, NFAPICRC nfapicrc) {
    NFAPICRC* found = find_NFAPICRC(manager, RX_UE);
    if (found) {
        pthread_mutex_lock(&found->lock);
        *found = nfapicrc;
        pthread_mutex_unlock(&found->lock);
    }
}

