    ue_contexts = realloc(ue_contexts, sizeof(ue_context_t) * (num_ue_contexts + 1));
    if (!ue_contexts) {
        syslog(LOG_ERR, "Failed to allocate memory for UE context");
        pthread_mutex_unlock(&ue_contexts_lock);
        sem_post(&ue_contexts_semaphore);
        return;
    }

    ue_contexts[num_ue_contexts] = *context;
    ++num_ue_contexts;

    pthread_mutex_unlock(&ue_contexts_lock);
    sem_post(&ue_contexts_semaphore);

    log_ue_context(&ue_contexts[num_ue_contexts - 1]);
}

void remove_ue_context(int ue_id) {
    pthread_mutex_lock(&ue_contexts_lock);

    sem_wait(&ue_contexts_semaphore);

    int i;
    for (i = 0; i < num_ue_contexts; ++i) {
        if (ue_contexts[i].ue_id == ue_id) {
            break;
        }
    }

    if (i == num_ue_contexts) {
        syslog(LOG_ERR, "UE not found: %d", ue_id);
        pthread_mutex_unlock(&ue_contexts_lock);
        sem_post(&ue_contexts_semaphore);
        return;
    }

    memmove(&ue_contexts[i], &ue_contexts[i + 1], sizeof(ue_context_t) * (num_ue_contexts - i - 1));
    --num_ue_contexts;

    pthread_mutex_unlock(&ue_contexts_lock);
    sem_post(&ue_contexts_semaphore);

    log_ue_context(&ue_contexts[i]);
}

void update_ue_context(int ue_id, const ue_context_t* context) {
    pthread_mutex_lock(&ue_contexts_lock);

    sem_wait(&ue_contexts_semaphore);

    int i;
    for (i = 0; i < num_ue_contexts; ++i) {
        if (ue_contexts[i].ue_id == ue_id) {
            break;
        }
    }

    if (i == num_ue_contexts) {
        syslog(LOG_ERR, "UE not found: %d", ue_id);
        pthread_mutex_unlock(&ue_contexts_lock);
        sem_post(&ue_contexts_semaphore);
        return;
    }

    ue_contexts[i] = *context;
    log_ue_context(&ue_contexts[i]);

    pthread_mutex_unlock(&ue_contexts_lock);
    sem_post(&ue_contexts_semaphore);
}

int main() {
    // Initialize memory management system
    init_memory_management();

    // Initialize mutex and semaphore for thread safety
    pthread_mutex_init(&ue_contexts_lock, NULL);
    sem_init(&ue_contexts_semaphore, 0, 1);

    // Add UE contexts
    ue_context_t context1 = { .ue_id = 1, .servicing_pci = 307, .num_bwp = 2, .bwps = malloc(sizeof(struct bwp_config) * context1.num_bwp) };
    ue_context_t context2 = { .ue_id = 2, .servicing_pci = 308, .num_bwp = 3, .bwps = malloc(sizeof(struct bwp_config) * context2.num_bwp) };
    add_ue_context(&context1);
    add_ue_context(&context2);

    // Update a UE context
    ue_context_t updated_context1 = { .ue_id = 1, .servicing_pci = 309, .num_bwp = 5, .bwps = malloc(sizeof(struct bwp_config) * updated_context1.num_bwp) };
    update_ue_context(1, &updated_context1);

    // Remove a UE context
    remove_ue_context(2);

    // Clean up memory and log before exiting
    clean_up_memory();

    return 0;
}
