    while ((entry = readdir(dir)) != NULL) {
        char input_path[1024], output_path[1024];
        snprintf(input_path, sizeof(input_path), "%s/%s", input_dir, entry->d_name);
        snprintf(output_path, sizeof(output_path), "%s/%s.pdf", output_dir, entry->d_name);

        if (strcmp(entry->d_name + strlen(entry->d_name) - 4, ".png") == 0 ||
            strcmp(entry->d_name + strlen(entry->d_name) - 3, ".gif") == 0 ||
            strcmp(entry->d_name + strlen(entry->d_name) - 3, ".jpg") == 0 ||
            strcmp(entry->d_name + strlen(entry->d_name) - 3, ".jpeg") == 0) {
