            strcpy(task->path, input_path);
            strcpy(task->output_path, output_path);
            task->status = 0;

            pthread_mutex_lock(&queue_mutex);
            if (queue_length < MAX_CONCURRENT_PROCESSES || queue[queue_length - 1]->status != 0) {
                queue[queue_length++] = task;
                pthread_cond_signal(&queue_not_empty);
            } else {
                free(task);
            }
            pthread_mutex_unlock(&queue_mutex);
        }
    }

    closedir(dir);

    if (queue_length > 0) {
        Task *tasks[MAX_CONCURRENT_PROCESSES];
        int num_threads = (queue_length < MAX_CONCURRENT_PROCESSES) ? queue_length : MAX_CONCURRENT_PROCESSES;
        pthread_t threads[num_threads];

        for (size_t i = 0; i < num_threads; ++i) {
            if (queue_length > 0 && queue[0]->status == 0) {
                tasks[i] = queue[0];
                pthread_mutex_lock(&queue_mutex);
                queue[0] = queue + queue_length--;
                pthread_mutex_unlock(&queue_mutex);
            } else {
                tasks[i] = NULL;
            }
        }

        for (size_t i = 0; i < num_threads; ++i) {
            if (tasks[i]) {
                pthread_create(&threads[i], NULL, conversion_thread, tasks[i]);
            }
        }

        for (size_t i = 0; i < num_threads; ++i) {
            pthread_join(threads[i], NULL);
        }

        for (size_t i = 0; i < queue_length; ++i) {
            if (queue[i]->status == -1) {
                num_failed_conversions++;
            }
        }
    }

    return num_failed_conversions;
}
