#include <jpeglib.h>
#include <poppler-qt5/qpdf.h>
#include <log_system.h> // Your custom logging system

struct convert_data {
    char *input_file;
    char *output_file;
    int quality;
};

int jpeg_to_pdf(const char *input_file, const char *output_file, int quality) {
    struct convert_data data = {strdup(input_file), strdup(output_file), quality};

    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    pthread_t thread_id;

    // Initialize mutex and condition variable
    pthread_mutex_init(&lock, NULL);
    pthread_cond_init(&cond_var, NULL);

    // Create conversion task and enqueue it if the maximum concurrent tasks limit is not reached
    int enqueue(struct convert_data *data) {
        // Check if we can add a new task without exceeding the limit
        pthread_mutex_lock(&lock);
        if (pthread_attr_getmaxthreads() > pthread_attr_getcurbstacksize()) {
            int tasks_count = pthread_attr_getmaxthreads() - pthread_attr_getcurbstacksize();
            if (tasks_count > 0)
                --tasks_count;

            // Enqueue the task if there is room and unlock the mutex
            if (--tasks_count >= 0) {
                data->thread_id = 0;
                memcpy(pthread_attr_getattr(&data->thread_id), pthread_attr_getdefaultattr(), sizeof(pthread_t));
                pthread_create(&data->thread_id, NULL, convert_function, (void *) data);
            }

            // Update the maximum tasks limit if necessary
            if (tasks_count < 0) {
                pthread_attr_setmaxthreads(std::abs(tasks_count));
            }
        }
        pthread_mutex_unlock(&lock);

        return data->thread_id != 0;
    }

    // Convert JPEG to PDF in a separate thread and handle potential failures
    void *convert_function(void *data) {
        struct convert_data *d = (struct convert_data *) data;
        qpdf_document *pdf_doc = NULL;
        jpeg_decompress_struct cinfo;
        jpeg_error_exit_mgr jerr;
        FILE *input_file = fopen(d->input_file, "rb");
        JSAMPARRAY buffer;
        int row_stride;

        // Initialize JPEG library error handler
        jpeg_stdio_init(&cinfo, input_file);
        cinfo.err = jpeg_stderr_return_void;
        jpeg_create_error_handler(&jerr);
        jpeg_set_error_handler(&cinfo, &jerr);

        // Perform JPEG to PDF conversion
        try {
            pdf_doc = qpdf_new();
            qpdf_open(pdf_doc);
            int success = qpdf_start_pages(pdf_doc, 1);
            if (success) {
                buffer = NULL;
                row_stride = 0;
                success = jpeg_read_header(&cinfo, TRUE);
                if (success) {
                    success = jpeg_start_decompress(&cinfo);
                    if (success) {
                        while (jpeg_read_scanlines(&cinfo, buffer, 1) == 1) {
                            int ret = qpdf_add_image(pdf_doc, buffer[0], cinfo.output_width, cinfo.output_height, d->quality);
                            if (!ret) break;
                        }
                    }

                    jpeg_finish_decompress(&cinfo);
                    jpeg_finish_encoding(&cinfo);
                }
            }

            qpdf_end_pages(pdf_doc);
            FILE *output_file = fopen(d->output_file, "wb");
            success = qpdf_write_syntax(pdf_doc, output_file);
            qpdf_free(pdf_doc);
            if (success) {
                // Log conversion success and cleanup resources
                log_conversion_success(d->input_file, d->output_file);
                fclose(input_file);
                fclose(output_file);
                free(d->input_file);
                free(d->output_file);
                pthread_exit(0);
            }
        } catch (...) {
            // Log conversion failure and cleanup resources
            log_conversion_failure(d->input_file, d->output_file);
            fclose(input_file);
            if (pdf_doc) qpdf_free(pdf_doc);
            free(d->input_file);
            free(d->output_file);
        }

        // Return an error code if the conversion failed
        return 3;
    }

    // Enqueue and run the task if not already queued
    int result = enqueue(&data) ? jpeg_to_pdf(input_file, output_file, quality) : 0;

    pthread_mutex_destroy(&lock);
    pthread_cond_destroy(&cond_var);
    return result;
}
