typedef struct {
    MAC_RLC_AM_PDU_T mac_rlc;
    size_t num_macsdu;
    MACSDU* macsdu;
} LTE_PDCP_PDU_T;

typedef struct {
    size_t capacity;
    size_t size;
    LTE_PDCP_PDU_T* data;
} PDCP_PDU_ARRAY;

void pdcp_pdu_array_init(PDCP_PDU_ARRAY* arr, size_t initial_size) {
    arr->capacity = initial_size;
    arr->size = 0;
    arr->data = malloc(initial_size * sizeof(LTE_PDCP_PDU_T));
}

void pdcp_pdu_array_deinit(PDCP_PDU_ARRAY* arr) {
    free(arr->data);
    arr->capacity = 0;
    arr->size = 0;
}

static void log_performance_metric(const char* metric, size_t value) {
    // Implement your logging mechanism here.
    printf("%s: %zu\n", metric, value);
}

void pdcp_pdu_array_push(PDCP_PDU_ARRAY* arr, const MAC_RLC_AM_PDU_T* mac_rlc, size_t num_macsdu, const MACSDU* const* macsdu) {
    if (arr->size == arr->capacity) {
        // Double the capacity when it's full.
        arr->capacity *= 2;
        LTE_PDCP_PDU_T* new_data = realloc(arr->data, arr->capacity * sizeof(LTE_PDCP_PDU_T));
        if (!new_data) {
            // Handle memory allocation failure.
            return;
        }
        arr->data = new_data;
    }

    LTE_PDCP_PDU_T* current = &arr->data[arr->size];
    current->mac_rlc = *mac_rlc;
    current->num_macsdu = num_macsdu;
    current->macsdu = malloc(num_macsdu * sizeof(MACSDU));
    if (!current->macsdu) {
        // Handle memory allocation failure.
        return;
    }
    memcpy(current->macsdu, macsdu, num_macsdu * sizeof(MACSDU));

    arr->size++;
    log_performance_metric("Active PDCP PDUs", arr->size);
}
