typedef struct {
    int ueId;
    RANNodeConfig ran_node_config;
    List* pdusession_configs; // PDUSESSION_CONFIG
} UESessionConfig;

typedef struct {
    int qosClassIdentifier;
    int ambR;
} PDUSessionConfig;

List* create_list() {
    List* list = malloc(sizeof(List));
    if (!list) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    list->tail = NULL;
    return list;
}

UESessionConfig* initializeUESessionsWithMutex() {
    pthread_mutex_t mutex;
    if (pthread_mutex_init(&mutex, NULL)) {
        perror("pthread_mutex_init");
        exit(EXIT_FAILURE);
    }

    int num_uesessions = 100; // Adjust as needed
    UESessionConfig* uesessions = malloc(num_uesessions * sizeof(UESessionConfig));
    if (!uesessions) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_uesessions; ++i) {
        UESessionConfig* uesession = &uesessions[i];
        uesession->ueId = i + 1;
        // Initialize RANNodeConfig here...

        uesession->pdusession_configs = create_list();
        for (int j = 0; j < rand() % 10 + 5; ++j) { // Adjust number of PDUs per session as needed
            PDUSessionConfig* pdu = malloc(sizeof(PDUSessionConfig));
            if (!pdu) {
                perror("malloc");
                exit(EXIT_FAILURE);
            }
            pdu->qosClassIdentifier = rand() % 6 + 1; // Adjust QoS class identifier range as needed
            pdu->ambR = (rand() % 256) + 32; // Adjust AMBR value range as needed

            pthread_mutex_lock(&mutex);
            list_append(uesession->pdusession_configs, pdu);
            pthread_mutex_unlock(&mutex);
        }
    }

    void cleanup() {
        for (int i = 0; i < num_uesessions; ++i) {
            UESessionConfig* uesession = &uesessions[i];
            List* list = uesession->pdusession_configs;

            PDUSessionConfig* current = list->head;
            while (current != NULL) {
                PDUSessionConfig* temp = current;
                current = current->next;
                free(temp);
            }
            free(list);
        }
        free(uesessions);
        pthread_mutex_destroy(&mutex);
    }

    atexit(cleanup); // Ensure cleanup is called when the program terminates

    return uesessions;
}
