std::list<NFAPI_CRC_INDICATION_PDU_T> populateNFAPICRCIndicationList(const std::list<std::string>& inputList, const std::string& searchStr, const std::string& insertStr) {
    std::list<NFAPI_CRC_INDICATION_PDU_T> nfapiList;
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 65535); // RX_UE_INFORMATION_TAG range (16 bits)
    std::uniform_int_distribution<> rntiDis(1, 65535); // RNTI range (16 bits)

    // Populate nfapiList with unique NFAPI_CRC_INDICATION_PDU_T structures
    std::for_each(std::ostream_iterator<NFAPI_CRC_INDICATION_PDU_T>(nfapiList, '\n'), [&](auto&) { nfapiList.emplace_back(); }, std::move(inputList).cbegin(), inputList.cend());

    // Set CRCFLAG for each CRC_INDICATION_REL8_TAG randomly
    std::for_each(nfapiList.begin(), nfapiList.end(), [&](auto& pdu) { pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = dis(gen); });

    // Create a mutex for thread safety
    std::mutex mtx;

    // Find the position where insertStr should be inserted
    auto it = std::find(inputList.cbegin(), inputList.cend(), searchStr);

    // Insert the new element at the found position or at the end of the list
    nfapiList.insert(it, NFAPI_CRC_INDICATION_PDU_T{});
    (*(nfapiList.rbegin())).RX_UE_INFORMATION_TAG = dis(gen);
    (*(nfapiList.rbegin())).RNTI = rntiDis(gen);
    (*(nfapiList.rbegin())).CRC_INDICATION_REL8_TAG.CRCFLAG = dis(gen);

    // Handle concurrent updates from multiple threads without data corruption
    std::unique_lock<std::mutex> lock(mtx);
    std::thread t1([&]() { populateNFAPICRCIndicationList(nfapiList, "searchStr2", "insertStr2"); }); // Replace "searchStr2" and "insertStr2" with appropriate values
    t1.join();

    return nfapiList;
}
