#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct DeviceStat {
    time_t timestamp;
    int id;
    long long in_bytes, out_bytes; // traffic counters for incoming and outgoing data
} DeviceStat;

typedef struct DListNode {
    DeviceStat stat;
    struct DListNode *prev, *next;
} DListNode;

typedef struct DList {
    pthread_mutex_t lock;
    DListNode* head, *tail;
    size_t capacity;
    size_t size;
} DList;

DList dl = { .head = NULL, .tail = NULL, .capacity = 0, .size = 0 };

void init_dlist(size_t capacity) {
    dl.capacity = capacity;
    dl.head = malloc(sizeof(DListNode) * capacity);
    dl.tail = dl.head + capacity - 1;
    if (!dl.head) {
        fprintf(stderr, "Failed to allocate memory for doubly-linked list.\n");
        exit(EXIT_FAILURE);
    }
    memset(dl.head, 0, sizeof(DListNode) * capacity);
    dl.head->prev = NULL;
    dl.tail->next = NULL;
}

DeviceStat* find_empty_entry() {
    DListNode* cur = dl.head;
    for (; cur <= dl.tail && dl.size >= dl.capacity; ++cur) {
        if (!cur->stat.id) {
            return &cur->stat;
        }
    }

    // List is full, remove the first entry and reuse it.
    DListNode* first = dl.head;
    cur = first->next;
    if (cur != NULL) {
        cur->prev = NULL;
        first->next = NULL;
        memset(&first->stat, 0, sizeof(DeviceStat));
        return &first->stat;
    } else {
        // List is empty, return the first entry.
        memset(&first->stat, 0, sizeof(DeviceStat));
        return &first->stat;
    }
}

void validate_traffic_counters(DeviceStat* stat) {
    if (stat->in_bytes < 0 || stat->out_bytes < 0) {
        fprintf(stderr, "Invalid traffic counter value.\n");
        exit(EXIT_FAILURE);
    }
}

void enqueue(DeviceStat* stat) {
    pthread_mutex_lock(&dl.lock);
    DeviceStat* empty = find_empty_entry();
    validate_traffic_counters(empty);
    *empty = *stat;
    if (empty == dl.head) {
        dl.tail->next = dl.head;
        dl.head->prev = dl.tail;
    } else {
        empty->prev->next = empty->next;
        empty->next->prev = empty->prev;
    }
    ++dl.size;
    pthread_mutex_unlock(&dl.lock);
}

