constexpr size_t MAX_ELEMENTS = 10'000;
constexpr size_t MEMORY_LIMIT = 100'000'000; // Adjust as needed for your memory limits

size_t allocateMemory(std::vector<long>& offsets, std::vector<int>& keys, std::vector<Record>& records) {
    size_t allocatedOffsetCount = 0;

    offsets.resize(MAX_ELEMENTS);
    keys.resize(MAX_ELEMENTS);
    records.resize(MAX_ELEMENTS);

    long maxOffset = 0;
    std::mt19937 gen(time(nullptr));
    std::uniform_int_distribution<> distrib(0, MAX_ELEMENTS - 1);

    for (auto& record : records) {
        auto index = distrib(gen);
        if (index >= allocatedOffsetCount && index < MAX_ELEMENTS) {
            record.offset_ptr = &offsets[allocatedOffsetCount++];
            record.value = index;
            maxOffset = std::max(maxOffset, *record.offset_ptr);
            keys[index] = index;
        } else {
            // Handle memory reallocation when initial allocations are insufficient
            std::cout << "Memory reallocation required." << std::endl;
            offsets.resize(2 * MAX_ELEMENTS);
            keys.resize(2 * MAX_ELEMENTS);
            records.resize(2 * MAX_ELEMENTS);

            allocatedOffsetCount = 0;
            maxOffset = 0;
        }
    }

    // Check memory usage and handle if needed
    if (maxOffset >= MEMORY_LIMIT) {
        std::cout << "Memory limit exceeded." << std::endl;
        // Free memory and throw an exception or return an error code
    }

    return allocatedOffsetCount;
}
