void initialize_ue_array(int num_ue) {
    if (num_ue > MAX_UE || num_ue <= 0) {
        fprintf(stderr, "Invalid number of UE instances\n");
        return;
    }

    pthread_mutex_lock(&mutex);

    if (current_ue_count != 0 && ue_data) {
        free(ue_data);
    }

    current_ue_count = num_ue;
    ue_data = malloc(num_ue * sizeof(NFAPI_CRUC_INDICATION_PDU_T));

    if (!ue_data) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);
        return;
