        uint32_t rnti = i;
        while (true) {
            ue_data[i].rnti = rnti;
            if (i == rnti) {
                rnti++;
                continue;
            }
            bool unique = true;
            for (int j = 0; j < i; ++j) {
                if (ue_data[j].rnti == rnti) {
                    unique = false;
                    break;
