    LogEntry *head, *tail;
    unsigned int capacity;
};

void log_append(struct LogBuffer *buffer, size_t allocation_size, unsigned int reallocations) {
    LogEntry *entry = malloc(sizeof(LogEntry));
    if (!entry) {
        perror("Out of memory");
        return;
    }

    entry->allocation_size = allocation_size;
    entry->reallocations = reallocations;
    entry->next = NULL;
    entry->timestamp = time(NULL);

    if (!buffer->head) {
        buffer->head = entry;
        buffer->tail = entry;
    } else {
        buffer->tail->next = entry;
        buffer->tail = entry;
    }

    if (buffer->capacity <= buffer->head && buffer->head != buffer->tail) {
        LogEntry *old_head = buffer->head;
        buffer->head = old_head->next;
        free(old_head);
    }
}

void* allocate_crc_indications(size_t max_allocation_kb, size_t num_elements, size_t min_element_kb, NFAPI_CRC_INDICATION_PDU_T** pudu, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*, void*)) {
    struct LogBuffer log_buffer = { NULL, NULL, 100 };
    size_t allocation_size = 0;
    unsigned int reallocations = 0;
    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;

    if (!pudu || !callback) {
        fprintf(stderr, "Invalid callback or NULL pointer\n");
        return NULL;
    }

    srand((unsigned int)time(NULL));

    while (allocation_size < num_elements * min_element_kb && allocation_size + max_allocation_kb <= max_allocation_kb) {
        size_t chunk_size = min_element_kb;
        if ((num_elements - allocation_size) * min_element_kb >= max_allocation_kb) {
            chunk_size = (max_allocation_kb - allocation_size) / (num_elements - allocation_size);
        }

        pdus = realloc(pdus, allocation_size + chunk_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdus) {
            perror("Out of memory");
            goto cleanup;
        }

        allocation_size += chunk_size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        reallocations++;
    }

    if (allocation_size < num_elements * min_element_kb) {
        fprintf(stderr, "Failed to allocate sufficient memory\n");
        goto cleanup;
    }

    log_append(&log_buffer, allocation_size, reallocations);

    for (size_t i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = pdus + i;

        pdu->tag = i % 256;
        pdu->RNTI = i + 1; // RNTI should be greater than 0
        if (pdu->RNTI > 65535) {
            fprintf(stderr, "Invalid RNTI value: %u\n", pdu->RNTI);
            goto cleanup;
        }
        pdu->crc_indication_tag = rand() & ((1 << 8) - 1);
        pdu->CRCFLAG = rand() % 2;
    }

    *pudu = pdus;

cleanup:
    if (pdus) free(pdus);
    if (reallocations > 0) log_append(&log_buffer, allocation_size, reallocations);
    return callback(*pudu, NULL);
}
