typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

struct Cache {
    Node** table;
    int capacity;
    int size;
    pthread_mutex_t mutex;
};

void cache_init(struct Cache* cache, int capacity) {
    cache->table = (Node**)calloc(capacity, sizeof(Node*));
    cache->capacity = capacity;
    cache->size = 0;
    pthread_mutex_init(&cache->mutex, NULL);
}

void cache_insert(struct Cache* cache, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&cache->mutex);

    int index = hashFunction(data.rnti) % cache->capacity;
    Node** list_ref = &cache->table[index];
    Node* current = *list_ref;

    if (!current) {
        *list_ref = malloc(sizeof(Node));
        (*list_ref)->data = data;
        (*list_ref)->next = NULL;
        cache->size++;
    } else {
        while (current != NULL && current->data.rnti != data.rnti) {
            current = current->next;
        }

        if (!current) {
            Node* new_node = malloc(sizeof(Node));
            new_node->data = data;
            new_node->next = *list_ref;
            *list_ref = new_node;
            cache->size++;
        }
    }

    pthread_mutex_unlock(&cache->mutex);
}

void* find_data(const void* key, const void* data, size_t nmemb, size_t size, int (*compar)(const void*, const void*)) {
    Node** list_ref = (Node**)key;
    Node* current = *list_ref;

    while (current != NULL) {
        if (!compar(&current->data, data))
            return current;
        current = current->next;
    }

    return NULL;
}

int compareRNTIs(const void* a, const void* b) {
    return ((RF_RNTI_T*)a)->rnti - ((RF_RNTI_T*)b)->rnti;
}

NFAPI_CRC_INDICATION_PDU_T* cache_lookup(struct Cache* cache, RF_RNTI_T rnti) {
    pthread_mutex_lock(&cache->mutex);

    int index = hashFunction(rnti) % cache->capacity;
    Node** list_ref = &cache->table[index];
    Node* current = *list_ref;

    while (current != NULL && current->data.rnti != rnti) {
        current = current->next;
    }

    pthread_mutex_unlock(&cache->mutex);
    return current ? &current->data : NULL;
}

void cache_destroy(struct Cache* cache) {
    pthread_mutex_destroy(&cache->mutex);

    for (int i = 0; i < cache->capacity; ++i) {
        Node* node = cache->table[i];
        while (node != NULL) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(cache->table);
}

int hashFunction(RF_RNTI_T rnti) {
    uint32_t hash = 5381;
    int c;

    while ((c = *(unsigned char*)&rnti)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
        rnti++;
    }

    return hash % cache->capacity;
}

void manageCRCIndications(struct Cache* cache, int maxRNTI) {
    NFAPI_CRC_INDICATION_PDU_T indication;
    // Handle incoming CRC indications...

    RF_RNTI_T rnti = indication.tag.rnti;

    if (cache_lookup(cache, rnti)) {
        // Duplicate entry, ignore it...
    } else {
        indication.crc_tag.crcflag = rand() % 2;
        cache_insert(cache, indication);
    }
}
```

