    ue->transmission_bandwidth = rand() % MAX_BANDWIDTH + MIN_BANDWIDTH;
    ue->qos = rand() % MAX_QOS + MIN_QOS;
    ue->operational_limit = (double)ue->power_level / 100.0 * MAX_OPERATIONAL_LIMIT;
    ue->is_active = true;
    pthread_mutex_init(&ue->mutex, NULL);
}

void configure_ue(UserEquipment* ue, int power_level, int bandwidth, int qos) {
    if (power_level > MAX_POWER_LEVEL || power_level < MIN_POWER_LEVEL ||
        bandwidth > MAX_BANDWIDTH || bandwidth < MIN_BANDWIDTH ||
        qos > MAX_QOS || qos < MIN_QOS) {
        printf("Error: Invalid configuration parameters.\n");
        return;
    }

    ue->power_level = power_level;
    ue->transmission_bandwidth = bandwidth;
    ue->qos = qos;
}

void log_ue_config(UserEquipment* ue) {
    pthread_mutex_lock(&log_mutex);
    printf("UE #%d: Cell ID %d, Power Level %d, Bandwidth %d, QoS %d\n",
           ue->id, ue->cell_id, ue->power_level, ue->transmission_bandwidth, ue->qos);
    pthread_mutex_unlock(&log_mutex);
}

void configure_network(int max_ue_count) {
    ue_array = (UserEquipment*)malloc(max_ue_count * sizeof(UserEquipment));

    for (int i = 0; i < max_ue_count; ++i) {
        init_ue(&ue_array[i], i);
    }

    // Implement dynamic reconfiguration if needed
    if (dynamic_reconfiguration) {
        pthread_t thread_id;
        int reconfig_interval = MAX_RECONFIG_INTERVAL;

        while (1) {
            sleep(reconfig_interval);

            for (int i = 0; i < max_ue_count; ++i) {
                pthread_mutex_lock(&ue_array[i].mutex);
                configure_ue(&ue_array[i], rand() % MAX_POWER_LEVEL + MIN_POWER_LEVEL,
                             rand() % MAX_BANDWIDTH + MIN_BANDWIDTH,
                             rand() % MAX_QOS + MIN_QOS);
                pthread_mutex_unlock(&ue_array[i].mutex);
            }
        }
    }
}

// Thread-safe UE configuration function for handling multiple concurrent requests
void safe_configure_ue(int index, int power_level, int bandwidth, int qos) {
    pthread_mutex_lock(&ue_array[index].mutex);
    configure_ue(&ue_array[index], power_level, bandwidth, qos);
    log_ue_config(&ue_array[index]);
    pthread_mutex_unlock(&ue_array[index].mutex);
}
