#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
    enum urgency {LOW, MEDIUM, HIGH} urgency;
    pthread_mutex_t lock;
} Node;

struct queue {
    Node** queues;
    unsigned int capacity;
};

Node* new_node(NFAPI_CRC_INDICATION_PDU_T data, enum urgency urgency) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    node->urgency = urgency;
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

void enqueue(struct queue* q, Node* n) {
    unsigned int index = (n->urgency * q->capacity / 3) % q->capacity;
    if (!q->queues[index]) q->queues[index] = n;
    else {
        Node* current = q->queues[index];
        while (current->next) current = current->next;
        current->next = n;
    }
}

Node* dequeue(struct queue* q, unsigned int index) {
    if (!q->queues[index]) return NULL;
    Node* temp = q->queues[index];
    q->queues[index] = temp->next;
    return temp;
}

void process_queue(struct queue* q) {
    for (int i = 0; i < q->capacity; ++i) {
        while (Node* n = dequeue(q, i)) {
            pthread_mutex_lock(&n->lock);
            // Process data and set CRCFLAG here
            pthread_mutex_unlock(&n->lock);
            free(n);
        }
    }
}

struct queue* create_queue(unsigned int capacity) {
    struct queue* q = (struct queue*)malloc(sizeof(struct queue));
    if (!q) return NULL;
    q->capacity = capacity;
    q->queues = (Node**)calloc(q->capacity, sizeof(Node*));
    if (!q->queues) {
        free(q);
        return NULL;
    }
    return q;
}

void destroy_queue(struct queue* q) {
    for (int i = 0; i < q->capacity; ++i) {
        while (Node* n = dequeue(q, i)) free(n);
    }
    free(q->queues);
    free(q);
}
