#include <pthread.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CacheNode {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    struct CacheNode *next;
    pthread_mutex_t lock;
} CacheNode;

static CacheNode *cache_head = NULL;
static size_t cache_capacity = 0;

void* randomize_crc(void *data) {
    ((NFAPI_CRC_INDICATION_PDU_T *) data)->crc_indication.crcflag = rand() % 256;
    return data;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(void) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;
    pthread_mutex_lock(&pdu->crc_indication.crcflag_lock);
    randomize_crc(pdu);
    pthread_mutex_unlock(&pdu->crc_indication.crcflag_lock);
    return pdu;
}

void destroy_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!pdu) return;
    free(pdu);
}

CacheNode* allocate_cache(size_t size) {
    if (size > cache_capacity) {
        CacheNode *new_head = (CacheNode *) malloc(sizeof(CacheNode));
        if (!new_head) return NULL;
        new_head->data = (NFAPI_CRC_INDICATION_PDU_T *) calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_head->data) {
            free(new_head);
            return NULL;
        }
        new_head->size = size;
        new_head->next = cache_head;
        new_head->lock = PTHREAD_MUTEX_INITIALIZER;
        cache_head = new_head;
        cache_capacity = size;
    }
    CacheNode *current = cache_head;
    while (current && current->size < size) {
        current = current->next;
    }
    if (!current) return NULL;
    void *data = current->data + (current->size - 1);
    if (current->size <= 1) {
        cache_head = current->next;
        free(current);
        current = cache_head;
    } else {
        current->size--;
    }
    return (CacheNode *) data;
}

void deallocate_cache(void *data) {
    if (!data) return;
    CacheNode *current = cache_head;
    CacheNode *prev = NULL;
    while (current) {
        if (current->data == data) {
            if (prev) prev->next = current->next;
            else cache_head = current->next;
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

NFAPI_CRC_INDICATION_PDU_T* get_cached_pdu(size_t index) {
    CacheNode *current = cache_head;
    while (current) {
        if (index < current->size) {
            pthread_mutex_lock(&current->lock);
            NFAPI_CRC_INDICATION_PDU_T *pdu = &current->data[index];
            pthread_mutex_unlock(&current->lock);
            return pdu;
        }
        index -= current->size;
        current = current->next;
    }
    return create_pdu();
}
