const { execSync, cpuUsage } = require('child_process');
const axios = require('axios');
const moment = require('moment');
const os = require('os');

// Configurable settings
const MAX_EXEC_TIME = 5000; // Maximum execution time in milliseconds (default: 5000ms or 5 seconds)
const CPU_THRESHOLD = 0.9; // CPU usage threshold at which to terminate commands (default: 90%)
const ENV_VAR_API = 'https://your-env-variables-api.com'; // Replace with your environment variables API endpoint

async function executeCommands(commands) {
  let totalExecTime = 0;
  let cpuUsageSum = cpuUsage().system;
  let commandIndex = 0;

  try {
    const envVariables = await fetchEnvVariables();

    commands.forEach(async (command) => {
      if (cpuUsageSum >= CPU_THRESHOLD * os.cpus()[0].times.total_raw / 1000) {
        console.log(`Command ${commandIndex + 1} terminated due to high CPU usage: ${cpuUsageSum} > ${CPU_THRESHOLD}`);
        return;
      }

      const startTime = moment();
      execSync(command, { env: Object.fromEntries(Object.entries(envVariables).concat([['MAX_EXEC_TIME', MAX_EXEC_TIME]])})), { timeout: MAX_EXEC_TIME });
      totalExecTime += moment().diff(startTime);
      console.log(`Command ${commandIndex + 1} executed in ${moment.duration(moment().diff(startTime)).asMilliseconds()}ms`);

      commandIndex++;
      if (commandIndex < commands.length) {
        await delay(1000); // Add a short delay between command executions to prevent overwhelming the system
      }
    });
  } catch (error) {
    console.error(`Error executing commands: ${error}`);
  }

  function fetchEnvVariables() {
    return axios.get(ENV_VAR_API).then((response) => response.data);
  }

  function delay(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
