typedef struct {
    RX_RLC_AM_PDU rlc_am;
    RX_RLC_PDU rlc;
    PDCP_RX_PDU pdcp;
    unsigned int rnti;
} MAC_RX_FRAME_T;

typedef struct {
    sem_t lock;
    MAC_RX_FRAME_T* frames;
    size_t capacity;
    size_t count;
    bool (*frame_validator)(MAC_RX_FRAME_T*);
    void (*lcid_mapper)(unsigned int rnti, unsigned int lcid);
} MAC_BUFFER_T;

void *mac_buffer_init(size_t capacity, bool (*frame_validator)(MAC_RX_FRAME_T*), void (*lcid_mapper)(unsigned int rnti, unsigned int lcid)) {
    MAC_BUFFER_T* buffer = malloc(sizeof(MAC_BUFFER_T));
    if (!buffer) return NULL;
    sem_init(&buffer->lock, 0, 1);
    buffer->frames = malloc(capacity * sizeof(MAC_RX_FRAME_T));
    if (!buffer->frames) {
        free(buffer);
        return NULL;
    }
    buffer->capacity = capacity;
    buffer->count = 0;
    buffer->frame_validator = frame_validator;
    buffer->lcid_mapper = lcid_mapper;
    return buffer;
}

void mac_buffer_push(MAC_BUFFER_T* buffer, MAC_RX_FRAME_T frame) {
    if (!buffer || !frame_validator(buffer, &frame)) return;
    sem_wait(&buffer->lock);
    if (buffer->count >= buffer->capacity && frame.rnti < buffer->frames[0].rnti) { // Eviction of older frames with lower RNTI values
        MAC_RX_FRAME_T* first = &buffer->frames[0];
        MAC_RX_FRAME_T* last = &buffer->frames[buffer->capacity - 1];
        for (MAC_RX_FRAME_T* current = last; current != first; ) {
            MAC_RX_FRAME_T temp = *current;
            current = current - 1;
            *current = temp;
            buffer->count--;
        }
    }
    if (buffer->count < buffer->capacity) {
        memcpy(&buffer->frames[buffer->count], &frame, sizeof(MAC_RX_FRAME_T));
        buffer->count++;
    }
    sem_post(&buffer->lock);
}

void* lcid_handler(void* arg) {
    MAC_BUFFER_T* buffer = arg;
    while (true) {
        sem_wait(&buffer->lock);
        if (!buffer || !buffer->count) {
            sem_post(&buffer->lock);
            break;
        }
        for (size_t i = 0; i < buffer->count; ++i) {
            MAC_RX_FRAME_T frame = buffer->frames[i];
            if (frame.rnti >= 0 && frame.rnti < UINT16_MAX && buffer->lcid_mapper(frame.rnti, frame.lcid)) {
                // Process frame and deliver to corresponding logical channel
            }
        }
        sem_post(&buffer->lock);
    }
    return NULL;
}

void mac_buffer_free(MAC_BUFFER_T* buffer) {
    if (buffer) {
        free(buffer->frames);
        free(buffer);
    }
}
