```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&mutex);
    if (head == NULL || head->data.rnti != new_node->data.rnti) {
        new_node->next = head;
        head = new_node;
    }
    pthread_mutex_unlock(&mutex);
}

void remove_duplicates() {
    Node *current = head, *temp;
    while (current && current->next) {
        if (current->data.rnti == current->next->data.rnti) {
            temp = current->next;
            current->next = current->next->next;
            free(temp);
        } else {
            current = current->next;
        }
    }
}

size_t get_unique_count() {
    size_t count = 0;
    Node *current = head;
    while (current) {
        if (!count++ || current->data.rnti != current->next->data.rnti) continue;
        current = current->next;
    }
    return count;
}

size_t pending_indications() {
    size_t count = 0;
    Node *current = head;
    while (current) {
        if (!current->data.crcflag) count++;
        current = current->next;
    }
    return count;
}
