#include <stdio.h>
#include <stdlib.h>
#include <math.h>

double *input_array, mean, stddev;
size_t array_size = 0;

void read_numbers() {
    double num;
    for (size_t i = 0; i < array_size; ++i) {
        scanf("%lf", &num);
        input_array[i] = num;
    }
}

void calculate_stats() {
    double sum = 0, msum = 0, variance = 0;
    for (size_t i = 0; i < array_size; ++i) {
        sum += input_array[i];
        msum += input_array[i] * input_array[i];
    }

    mean = sum / array_size;
    variance = (msum / array_size) - mean * mean;
    stddev = sqrt(variance);
}

void print_stats() {
    printf("Mean: %.4f\n", mean);
    printf("Standard Deviation: %.4f\n", stddev);
}
```

