class NFAPI_CRC_INDICATION_PDU_T {
public:
    int RX_UE_INFORMATION_TAG;
    bool CRCFLAG;

    NFAPI_CRC_INDICATION_PDU_T(int tag, bool crc) : RX_UE_INFORMATION_TAG(tag), CRCFLAG(crc) {}
};

class CRCList {
public:
    explicit CRCList(size_t maxSize);
    ~CRCList();
    void addElement(const NFAPI_CRC_INDICATION_PDU_T& pdu);
    const std::list<NFAPI_CRC_INDICATION_PDU_T>& getList() const;
    static double getCRCProbability() { return crcProbability_; }
    static void setCRCProbability(double prob) { crcProbability_ = prob; }

private:
    std::list<NFAPI_CRC_INDICATION_PDU_T> data_;
    std::set<int> tags_;
    std::mutex mtx_;
    static std::atomic<double> crcProbability_;
};

std::atomic<double> CRCList::crcProbability_ = 0.5;

CRCList::CRCList(size_t maxSize) {
    if (maxSize <= 0) throw std::invalid_argument("Max size must be greater than zero.");
    data_.reserve(maxSize);
}

CRCList::~CRCList() {}

void CRCList::addElement(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
    std::unique_lock<std::mutex> lock(mtx_);
    if (data_.size() >= data_.capacity()) {
        throw std::runtime_error("List is full.");
    }

    int tag = pdu.RX_UE_INFORMATION_TAG;
    if (tags_.find(tag) != tags_.end()) {
        throw std::invalid_argument("Duplicate RX_UE_INFORMATION_TAG value found.");
    }
    tags_.insert(pdu.RX_UE_INFORMATION_TAG);
    data_.emplace_back(pdu);

    auto now = std::chrono::system_clock::now();
    std::time_t time = std::chrono::system_clock::to_time_t(now);
    std::cout << "Added element with tag: " << pdu.RX_UE_INFORMATION_TAG << ", timestamp: " << std::ctime(&time);

    // Set CRCFLAG to a random value based on the configured probability
    if (static_cast<unsigned>(std::rand()) / RAND_MAX < crcProbability_) {
        data_.back().CRCFLAG = true;
    } else {
        data_.back().CRCFLAG = false;
    }
}

const std::list<NFAPI_CRC_INDICATION_PDU_T>& CRCList::getList() const {
    return data_;
}
