    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_node(struct list* list, Node* node) {
    pthread_mutex_lock(&list->mutex);

    node->next = list->head;
    list->head = node;
    list->count++;
    update_checksum(list, node->data.crc_indication);

    pthread_mutex_unlock(&list->mutex);
}

Node* find_node_by_rnti(struct list* list, uint32_t rnti) {
    Node *current = list->head;
    while (current != NULL) {
        if (current->data.rnti == rnti)
            break;
        current = current->next;
    }
    return current;
}

void update_node(struct list* list, uint32_t rnti, NFAPI_CRC_INDICATION_PDU_T new_data) {
    Node *target_node = find_node_by_rnti(list, rnti);
    if (!target_node) {
        fprintf(stderr, "Node not found\n");
        return;
    }

    pthread_mutex_lock(&list->mutex);

    target_node->data = new_data;
    update_checksum(list, new_data.crc_indication);

    pthread_mutex_unlock(&list->mutex);
}

void delete_node_by_rnti(struct list* list, uint32_t rnti) {
    Node *current = list->head;
    Node *prev = NULL;

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            list->count--;
            update_checksum(list, -current->data.crc_indication);
            break;
        }
        prev = current;
        current = current->next;
    }
}

void update_checksum(struct list* list, CRC_INDICATION_REL8_TAG tag) {
    list->checksum += tag.crc16;
}
