            *pCount = 0;
            return -1;
        }

        entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        entry->RNTI = RNTI;
        entry->CRCFLAG = CRCFLAG;

        // Reallocate existing data, add new entry, and free old memory (for potential performance improvement)
        size_t currentCount = *pCount;
        NFAPI_CRC_INDICATION_PDU_T **currentData = ppData;
        if (currentCount == 0) {
            *ppData = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!*ppData) {
                free(entry);
                free_json_object(root);
                *pCount = 0;
                return -1;
            }
            currentData = ppData;
        } else {
            // Reallocate data with one more element
            NFAPI_CRC_INDICATION_PDU_T *temp = realloc(*ppData, (currentCount + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!temp) {
                free(entry);
                free_json_object(root);
                *pCount = currentCount;
                return -1;
            }
            *ppData = temp;
            currentData = *ppData;
        }

        currentData[currentCount] = entry;
        (*pCount)++;
    }

    free_json_object(root);
    *pCount = json_object_get_array_length(root);
    return 0;
