```rust
extern crate log;
extern crate rayon;
use tempfile::NamedTempFile;
use std::env;
use std::fs::{self, remove_dir_all};
use std::path::Path;
use std::sync::{Mutex, RwLock};
use parking_lot::RwLock as ParallelRwLock;
use rayon::prelude::*;

mod logger {
    use log::{debug, error, info};

    pub fn init() {
        // Configure your logging here (e.g., println!(), built-in backends like stderr or files)
    }
}

struct TempDirManager {
    active_dirs: RwLock<Vec<Path>>,
    max_active_dirs: Option<usize>,
}

impl TempDirManager {
    pub fn new() -> Self {
        TempDirManager {
            active_dirs: RwLock::new(vec![]),
            max_active_dirs: Some(100), // Default limit of 100 active directories
        }
    }

    pub fn set_max_active_dirs(num: usize) {
        TempDirManager {
            active_dirs: RwLock::new(vec![]),
            max_active_dirs: Some(num),
        }
    }

    pub async fn create(&self, prefix: &str) -> Path {
        let mut active_dirs = self.active_dirs.write().await;
        let mut path: Path;
        let mut i = 0;
        loop {
            let temp_file = NamedTempFile::new(prefix).unwrap();
            path = temp_file.path().to_owned();
            if !active_dirs.contains(&path) && !self.max_active_dirs.as_ref().map_or(true, |max| active_dirs.len() < max) {
                break;
            }
            fs::remove_dir_all(path).unwrap();
            i += 1;
        }
        self.log_event(&format!("Created: {}", path.display()));
        path
    }

    pub async fn list(&self) {
        let active_dirs = self.active_dirs.read().await;
        for dir in &active_dirs {
            self.log_event(&format!("Active: {}", dir.display()));
        }
    }

    pub async fn cleanup(&self) {
        let mut active_dirs = self.active_dirs.write().await;
        drop(active_dirs); // Release the lock to allow other tasks to add directories if needed

        let mut dirs_to_remove = vec![];

        // Parallel cleanup using Rayon
        active_dirs.par_iter_mut().for_each(|dir| {
            dir.retain(|path| {
                if fs::read_link(path).is_err() { // Check if the directory exists
                    dirs_to_remove.push(*dir);
                    false
                } else {
                    true
                }
            });
        });

        for dir in &dirs_to_remove {
            self.log_event(&format!("Removed: {}", dir.display()));
            fs::remove_dir_all(dir).unwrap();
        }
    }

    fn log_event(&self, msg: &str) {
        // Implement logging here (e.g., use your configured logger)
        println!("{}", msg);
    }
}

fn main() {
    TempDirManager::new().create("temp_dir").into_stdstream().unwrap();
}
