#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int value; // random number within a specified range
    unsigned char tag[3]; // RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG
    unsigned short CRCFLAG;
} record;

typedef struct node {
    record data;
    struct node* next;
} node;

struct queue {
    int max_queue_size;
    int current_size;
    node** queue;
    pthread_mutex_t mutex;
};

void generate_random(record *r) {
    r->key = rand() % 100000; // Adjust the range as needed
    for (int i = 0; i < 3; ++i) {
        r->tag[i] = (unsigned char)(rand() % 256);
    }
    r->CRCFLAG = rand() % 2;
}

void generate_unique_RNTI(record *r, int *unique_RTNIs, int size) {
    while (true) {
        generate_random(r);
        if (!find_in_array(r->tag[1], unique_RTNIs, size)) {
            break;
        }
    }
}

int find_in_array(int key, int* arr, int size) {
    for (int i = 0; i < size; ++i) {
        if (arr[i] == key) {
            return 1;
        }
    }
    return 0;
}

node** create_queue(int max_size) {
    node** queue = malloc(sizeof(node*) * max_size);
    for (int i = 0; i < max_size; ++i) {
        queue[i] = NULL;
    }
    return queue;
}

struct queue* create_queue_object(int max_queue_size) {
    struct queue* q = malloc(sizeof(struct queue));
    q->max_queue_size = max_queue_size;
    q->current_size = 0;
    q->queue = create_queue(max_queue_size);
    pthread_mutex_init(&q->mutex, NULL);
    return q;
}

void enqueue(struct queue* q, record data) {
    int index = q->current_size % q->max_queue_size;
    node* new_node = malloc(sizeof(node));
    new_node->data = data;
    new_node->next = q->queue[index];
    q->queue[index] = new_node;
    ++q->current_size;
}

record dequeue(struct queue* q) {
    int index = q->current_size - 1;
    if (q->current_size == 0) {
        return (record){0};
    }
    node** tail = &q->queue[index];
    record data = (*tail)->data;
    *tail = (*tail)->next;
    free((*tail));
    --q->current_size;
    return data;
}

void process_queue(struct queue* q) {
    pthread_mutex_lock(&q->mutex);
    while (true) {
        record data = dequeue(q);
        if (!data.key) break; // Reached the end of the queue
        process_record(data);
    }
    pthread_mutex_unlock(&q->mutex);
}

void init_and_manage_records(struct queue* q, int max_RTNIs, int max_queue_size) {
    record *unique_RTNIs = malloc(max_RTNIs * sizeof(record)); // Adjust the size as needed
    int unique_RTNI_count = 0;

    while (true) {
        record new_record;
        generate_unique_RNTI(&new_record, &unique_RTNIs[unique_RTNI_count], unique_RTNI_count);
        enqueue(q, new_record);
        ++unique_RTNI_count;
        if (unique_RTNI_count == max_RTNIs) break; // Reached the maximum number of unique RTNIs
    }

    int iteration = 0;
    while (true) {
        process_queue(q);
        record new_record;
        generate_random(&new_record);
        enqueue(q, new_record);
        ++iteration;
        if (iteration % 10000 == 0) { // Adjust the frequency as needed
            process_queue(q);
        }
    }
}
