#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>
#include "NFAPI_Message.h"

typedef struct NFAPIListNode {
    NFAPI_MESSAGE_T* message;
    struct NFAPIListNode* next;
    pthread_mutex_t mutex;
} NFAPIListNode;

NFAPIListNode* create_node(NFAPI_MESSAGE_T* message) {
    NFAPIListNode* node = (NFAPIListNode*) malloc(sizeof(NFAPIListNode));
    node->message = message;
    node->next = NULL;
    pthread_mutex_init(&node->mutex, NULL);
    return node;
}

void free_node(NFAPIListNode* node) {
    if (node != NULL) {
        free(node);
        pthread_mutex_destroy(&node->mutex);
    }
}

NFAPIList* create_list() {
    NFAPIList* list = (NFAPIList*) malloc(sizeof(NFAPIList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->list_mutex, NULL);
    return list;
}

void free_list(NFAPIList* list) {
    NFAPIListNode *node, *temp;
    pthread_mutex_lock(&list->list_mutex);
    node = list->head;
    while (node != NULL) {
        temp = node;
        node = node->next;
        free_node(temp);
    }
    pthread_mutex_unlock(&list->list_mutex);
}

void insert_at_head(NFAPIList* list, NFAPI_MESSAGE_T* message) {
    NFAPIListNode *new_node = create_node(message);
    pthread_mutex_lock(&list->list_mutex);
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        new_node->next = list->head;
        list->head = new_node;
    }
    pthread_mutex_unlock(&list->list_mutex);
}

void remove(NFAPIList* list, NFAPI_MESSAGE_T* message) {
    NFAPIListNode *current = list->head;
    NFAPIListNode *previous = NULL;

    pthread_mutex_lock(&list->list_mutex);
    while (current != NULL && current->message != message) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        // Message not found, do nothing
    } else if (previous == NULL) {
        list->head = current->next;
        if (list->head == NULL) list->tail = NULL;
    } else {
        previous->next = current->next;
        if (current == list->tail) list->tail = previous;
    }

    pthread_mutex_unlock(&list->list_mutex);
}

NFAPI_MESSAGE_T* retrieve(NFAPIList* list, size_t index) {
    NFAPIListNode *current = list->head;
    size_t i = 0;

    pthread_mutex_lock(&list->list_mutex);
    while (current != NULL && i < index) {
        current = current->next;
        i++;
    }

    if (current == NULL) return NULL; // Index out of range

    pthread_mutex_lock(&current->mutex);
    NFAPI_MESSAGE_T* message = current->message;
    pthread_mutex_unlock(&current->mutex);

    pthread_mutex_unlock(&list->list_mutex);
    return message;
}
```
