typedef union {
    uint8_t bytes[NFAPI_MESSAGE_SIZE];
    struct {
        uint32_t preamble;
        uint16_t subframe;
        uint16_t control_info_tag;
        bool srs_flag;
        uint8_t srs_index;
        // Error correction field (if present)
    } message;
    uint32_t crc;
} NFAPI_MESSAGE_T;

typedef struct {
    int id;
    int cell_id;
    NFAPI_MESSAGE_T *message;
} UE;

struct set {
    int count;
    int *parent;
    int *rank;
};

UE **ue_list;
NFAPI_MESSAGE_T *messages;
size_t message_capacity = 0;
struct set *sets;
size_t set_capacity = 0;

void init_set(struct set *s, size_t n) {
    s->count = n;
    s->parent = malloc(n * sizeof(int));
    s->rank = calloc(n, sizeof(int));
    for (size_t i = 0; i < n; ++i) {
        s->parent[i] = i;
        s->rank[i] = 0;
    }
}

int find_set(struct set *s, int x) {
    if (x != s->parent[x])
        s->parent[x] = find_set(s, s->parent[x]);
    return s->parent[x];
}

void union_sets(struct set *s, int x, int y) {
    int root_x = find_set(s, x);
    int root_y = find_set(s, y);
    if (root_x == root_y) return;

    if (s->rank[root_x] < s->rank[root_y]) {
        s->parent[root_x] = root_y;
        s->rank[root_y] += s->rank[root_x];
    } else {
        s->parent[root_y] = root_x;
        s->rank[root_x] += s->rank[root_y];
    }
}

void check_pairs(UE **ues, size_t n) {
    init_set(sets + sets_capacity++, n);
    for (size_t i = 0; i < n; ++i) {
        int root = find_set(sets + i, ues[i]->cell_id);
        ues[i]->message->crc = calculate_crc(ues[i]->message);
        if (ues[i]->message->crc == 0) continue; // No error
        union_sets(sets + root, i, n + i); // Mark as disjoint pair
    }
}

bool are_disjoint(UE **ues, size_t n) {
    init_set(sets, n);
    for (size_t i = 0; i < n; ++i) {
        int root = find_set(sets, ues[i]->cell_id);
        if (ues[i]->message->crc == 0) continue; // No error
        union_sets(sets, root, i); // Mark as disjoint pair
    }
    return sets->count > 1;
}

size_t allocate_message() {
    void *ptr = malloc(NFAPI_MESSAGE_SIZE);
    if (!ptr) return 0;
    messages = realloc(messages, message_capacity + 1);
    if (!messages) {
        free(ptr);
        return 0;
    }
    memset(ptr, 0, NFAPI_MESSAGE_SIZE);
    return message_capacity++;
}

UE *create_ue(int id, int cell_id) {
    UE *ue = malloc(sizeof(UE));
    if (!ue) return NULL;
    ue->id = id;
    ue->cell_id = cell_id;
    ue->message = calloc(1, NFAPI_MESSAGE_SIZE);
    if (!ue->message) {
        free(ue);
        return NULL;
    }
    return ue;
}

void configure_network(UE **ues, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        if (!ues[i]) continue; // Skip null UE pointers
        ues[i]->id = i + 1;
        ues[i]->cell_id = rand() % MAX_CELL_ID + MIN_CELL_ID;
        allocate_message();
    }
}

void log_ue(UE *ue) {
    printf("UE #%d: Cell ID %d, Message CRC %u\n", ue->id, ue->cell_id, ue->message->crc);
}

void summary_report() {
    printf("Number of disjoint pairs: %zu\n", sets->count - 1);
}

