struct Attack {
    std::string type;
    bool cooldown;
    int powerLevel;
    std::string name;
};

std::deque<Attack> attacks;
constexpr auto COOLDOWN_INTERVAL = 9s; // in seconds
std::chrono::steady_clock::time_point lastAttackTime = std::chrono::steady_clock::now();

size_t selectAndExecuteAttack() {
    if (attacks.empty()) return -1;

    auto now = std::chrono::steady_clock::now();
    auto timeElapsed = now - lastAttackTime;

    if (timeElapsed < COOLDOWN_INTERVAL) return -1; // cooldown not yet over

    size_t index = 0;
    for (auto it = attacks.begin(); it != attacks.end(); ++it) {
        if (!it->cooldown) {
            it->cooldown = true;
            lastAttackTime = now;
            std::cout << "Executed attack: " << it->name << ", power level: " << it->powerLevel << '\n';
            return index;
        }
        ++index;
    }

    // Trim the deque if resources are low and there are attacks on cooldown.
    auto trimIndex = index + 1;
    for (size_t i = 0; i < attacks.size() - trimIndex; ++i) {
        if (!attacks[i].cooldown && attacks[i].powerLevel > attacks.back().powerLevel) {
            attacks.pop_back();
        } else {
            break;
        }
    }

    return -1; // no available attack or error occurred during trimming
}
