    }

    if (!current) { // Entry not found
        sem_post(&array->list_mutex);
        return;
    }

    if (previous == NULL) { // First node to be removed
        array->head = current->next;
    } else {
        previous->next = current->next;
    }

    if (!current->next) { // Last node to be removed
        array->tail = previous;
    }

    free(current);
    array->size--;
    sem_post(&array->list_mutex);
}

Node* findEntry(DynamicArray* array, RNTI rnti) {
    Node* current = array->head;

    sem_wait(&array->list_mutex);

    while (current != NULL && current->rnti != rnti) {
        current = current->next;
    }

    Node* result = current;
    sem_post(&array->list_mutex);

    return result;
}

// Implement batch operations, statistics collection, thread-safety, and logging mechanisms as per your specific requirements.
