#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct Record {
    int key;
    long offset;
    size_t size;
    struct Record *next;
    pthread_mutex_t lock;
} Record;

Record* create_record(int key, long offset) {
    Record *new_record = (Record*) malloc(sizeof(Record));
    new_record->key = key;
    new_record->offset = offset;
    new_record->size = sizeof(Record);
    new_record->next = NULL;
    pthread_mutex_init(&new_record->lock, NULL);
    return new_record;
}

void append_to_list(Record **head_ptr, Record *new_record) {
    Record *current = *head_ptr;
    if (current == NULL) {
        *head_ptr = new_record;
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_record;
    }
}

bool find_consecutive(Record **records, int key) {
    Record *current = *records;
    if (current == NULL) return false;
    while (current != NULL) {
        if (current->key == key && current->next != NULL && current->next->key == key + 1) {
            return true;
        }
        current = current->next;
    }
    return false;
}

Record* create_system(int memory_budget, size_t record_size) {
    Record *head = NULL;
    int max_keys = (memory_budget / record_size) - 1; // allow for last record with some unused space
    for (int i = 0; i <= max_keys; ++i) {
        if (!find_consecutive(&head, i)) {
            Record *new_record = create_record(i, (long) ((i + 1) * record_size));
            append_to_list(&head, new_record);
        } else {
            --max_keys;
        }
    }
    return head;
}

void cleanup(Record **head_ptr) {
    Record *current = *head_ptr;
    Record *temp;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
    *head_ptr = NULL;
}

void print_records(Record *head) {
    Record *current = head;
    printf("System of records:\n");
    while (current != NULL) {
        printf("Key: %d, Offset: %ld\n", current->key, current->offset);
        current = current->next;
    }
}

void* update_record(void *arg) {
    Record **records = arg;
    int index = rand() % RAND_MAX / 10;
    Record *target = NULL;
    pthread_mutex_t lock;

    for (Record *current = *records; current != NULL; current = current->next) {
        if (current->key == index) {
            target = current;
            break;
        }
    }

    if (target != NULL) {
        pthread_mutex_lock(&(target->lock));
        target->offset += rand() % 10000;
        pthread_mutex_unlock(&(target->lock));
    }
}

int main() {
    const int memory_budget = 2048; // in bytes
    const size_t record_size = sizeof(Record);
    Record *system = create_system(memory_budget, record_size);
    pthread_t threads[5];

    for (int i = 0; i < 5; ++i) {
        pthread_create(&threads[i], NULL, &update_record, &system);
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    print_records(system);
    cleanup(&system);

    return 0;
}
```

This code creates a dynamic system of records where each record contains an integer key and corresponding long offset value. The function `create_system()` initializes the system within a specified memory budget, ensuring efficient use of resources by accounting for the variability in record sizes due to different key lengths and offset ranges.

The implementation uses thread safety by locking individual records when updating their offsets using pthread mutexes. The code handles potential discrepancies in data synchronization between different components of the system, as multiple threads can update the records concurrently.

To prevent memory leaks, there is a cleanup function that deallocates all allocated memory upon request. The implementation is scalable to accommodate future increases in the number of records by considering trade-offs between memory efficiency and ease of maintenance.']

