#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>
#include <semaphore.h>
#include <sys/mman.h>

#define MAX_UE_COUNT 10000 // Maximum number of UEs in the pool
#define LOG_INTERVAL 1000   // Logging interval for resource utilization

typedef struct {
    pthread_mutex_t lock;  // Mutex for thread safety
    sem_t sem_alloc, sem_free; // Semaphores for resource allocation and deallocation
    unsigned int* ue_ids;     // Array to store UE identifiers
    unsigned int* cell_ids;   // Array to store cell IDs
    unsigned int total_allocations; // Total allocations since initialization
    unsigned int active_allocations; // Number of currently allocated resources
} resource_manager_t;

resource_manager_t* initializeUECollection(void) {
    resource_manager_t* manager = mmap(NULL, sizeof(resource_manager_t), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    pthread_mutex_init(&manager->lock, NULL);
    sem_init(&manager->sem_alloc, 0, MAX_UE_COUNT); // Initialize semaphore with maximum count
    sem_init(&manager->sem_free, 0, 0);             // Initialize semaphore with zero count

    manager->ue_ids = calloc(MAX_UE_COUNT, sizeof(unsigned int));
    manager->cell_ids = calloc(MAX_UE_COUNT, sizeof(unsigned int));
    manager->total_allocations = 0;
    manager->active_allocations = 0;

    return manager;
}

void allocateResource(resource_manager_t* manager) {
    sem_wait(&manager->sem_alloc); // Wait for resource availability

    pthread_mutex_lock(&manager->lock);
    unsigned int next_id = manager->active_allocations++;
    manager->ue_ids[next_id] = next_id;
    manager->cell_ids[next_id] = rand() % 100 + 1; // Generate a cell ID within the specified range (1-100)
    pthread_mutex_unlock(&manager->lock);

    sem_post(&manager->sem_free); // Signal resource availability for deallocation
}

void releaseResource(resource_manager_t* manager, unsigned int id) {
    pthread_mutex_lock(&manager->lock);

    if (manager->ue_ids[id] == id && manager->active_allocations > 0) {
        manager->ue_ids[id] = 0;
        manager->cell_ids[id] = 0;
        manager->active_allocations--;
    }

    pthread_mutex_unlock(&manager->lock);
    sem_post(&manager->sem_alloc); // Signal resource availability for allocation
}

void logUEResourceUsage(resource_manager_t* manager) {
    static unsigned int last_log = 0;
    if (time(NULL) - last_log >= LOG_INTERVAL) {
        printf("Active allocations: %u\n", manager->active_allocations);
        printf("Total allocations: %u\n", manager->total_allocations);
        last_log = time(NULL);
    }
}
```

