typedef struct Message {
    time_t timestamp;
    unsigned long id;
    size_t payload_len;
    char payload[1]; // Variable-length array
} Message;

typedef struct DynArray {
    Message** data;
    size_t capacity;
    size_t size;
    size_t max_messages;
    time_t threshold;
    pthread_mutex_t mutex;
} DynArray;

DynArray* create_dyn_array(size_t max_messages, time_t threshold) {
    DynArray* dyn_array = (DynArray*)malloc(sizeof(DynArray));
    dyn_array->capacity = 16;
    dyn_array->max_messages = max_messages;
    dyn_array->threshold = threshold;
    dyn_array->size = 0;
    dyn_array->data = (Message**)calloc(dyn_array->capacity, sizeof(Message*));
    pthread_mutex_init(&dyn_array->mutex, NULL);
    return dyn_array;
}

void resize_dyn_array(DynArray* dyn_array) {
    dyn_array->capacity *= 2;
    Message** new_data = (Message**)realloc(dyn_array->data, dyn_array->capacity * sizeof(Message*));
    if (!new_data) {
        fprintf(stderr, "Failed to reallocate memory\n");
        return;
    }
    dyn_array->data = new_data;
}

void push_message(DynArray* dyn_array, const Message* message) {
    pthread_mutex_lock(&dyn_array->mutex);
    if (dyn_array->size == dyn_array->capacity) {
        resize_dyn_array(dyn_array);
    }
    dyn_array->data[dyn_array->size] = malloc(sizeof(Message) + message->payload_len);
    memcpy(dyn_array->data[dyn_array->size], message, sizeof(Message));
    dyn_array->size++;
    pthread_mutex_unlock(&dyn_array->mutex);
}

bool remove_message_by_id(DynArray* dyn_array, unsigned long id) {
    pthread_mutex_lock(&dyn_array->mutex);
    for (size_t i = 0; i < dyn_array->size; ++i) {
        if (dyn_array->data[i]->id == id) {
            for (size_t j = i + 1; j < dyn_array->size; ++j) {
                dyn_array->data[j - 1] = dyn_array->data[j];
            }
            free(dyn_array->data[--dyn_array->size]);
            pthread_mutex_unlock(&dyn_array->mutex);
            return true;
        }
    }
    pthread_mutex_unlock(&dyn_array->mutex);
    return false;
}

void iterate_messages(DynArray* dyn_array, void (*func)(const Message*)) {
    pthread_mutex_lock(&dyn_array->mutex);
    for (size_t i = dyn_array->size - 1; i != UINT_MAX; --i) {
        if (i < dyn_array->size) {
            func(dyn_array->data[i]);
        } else {
            break;
        }
    }
    pthread_mutex_unlock(&dyn_array->mutex);
}

void clean_expired_messages(DynArray* dyn_array, time_t current_time) {
    pthread_mutex_lock(&dyn_array->mutex);
    for (size_t i = 0; i < dyn_array->size; ++i) {
        if (difftime(current_time, dyn_array->data[i]->timestamp) > dyn_array->threshold) {
            free(dyn_array->data[i]);
            for (size_t j = i + 1; j < dyn_array->size; ++j) {
                dyn_array->data[j - 1] = dyn_array->data[j];
            }
            dyn_array->size--;
        }
    }
    pthread_mutex_unlock(&dyn_array->mutex);
}
