static void* load_json_config(const char *url) {
    CURL *curl;
    CURLcode res;
    struct json_config *config;
    size_t length = 0;
    char *response;

    curl_global_init(CURL_GLOBAL_DEFAULT);

    curl = curl_easy_init();
    if (!curl) {
        perror("curl_easy_init");
        return NULL;
    }

    res = curl_easy_setopt(curl, CURLOPT_URL, url);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to set URL: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return NULL;
    }

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to fetch JSON configuration: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return NULL;
    }

    res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to get response code: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return NULL;
    }

    res = curl_easy_getinfo(curl, CURLINFO_SIZE_RECEIVED, &length);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to get response size: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return NULL;
    }

    response = malloc(length + 1);
    if (!response) {
        perror("malloc");
        curl_easy_cleanup(curl);
        return NULL;
    }

    res = curl_easy_read(curl, response, length);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to read JSON configuration: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        free(response);
        return NULL;
    }

    response[length] = '\0';
    config = malloc(sizeof(*config));
    if (!config) {
        perror("malloc");
        free(response);
        curl_easy_cleanup(curl);
        return NULL;
    }

    config->root = json_loads(response, 0, NULL);
    if (!config->root) {
        fprintf(stderr, "Failed to parse JSON configuration.\n");
        free(response);
        curl_easy_cleanup(curl);
        free(config);
        return NULL;
    }

    config->num_elements = json_array_size(config->root);

    curl_easy_cleanup(curl);
    free(response);
    return config;
}

static void validate_json_config(struct json_config *config) {
    size_t i;
    json_t *element, *tag, *rnti, *crc_indication;

    for (i = 0; i < config->num_elements; ++i) {
        element = json_array_get(config->root, i);

        tag = json_object_get(element, "RX_UE_INFORMATION_TAG");
        if (!tag || !json_is_valid(tag, JSON_OBJECT)) {
            fprintf(stderr, "Invalid RX_UE_INFORMATION_TAG structure.\n");
            return;
        }

        rnti = json_object_get(element, "RNTI");
        if (!rnti || !json_is_integer(rnti)) {
            fprintf(stderr, "Invalid RNTI structure.\n");
            return;
        }

        crc_indication = json_object_get(element, "CRC_INDICATION_REL8_TAG");
        if (!crc_indication || !json_is_boolean(crc_indication)) {
            fprintf(stderr, "Invalid CRC_INDICATION_REL8_TAG structure.\n");
            return;
        }
    }
}

static void init_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t num_elements) {
    *list = malloc(num_elements * sizeof((*list)[0]));
    if (!(*list)) {
        perror("malloc");
        return;
    }

    memset(*list, 0, num_elements * sizeof((*list)[0]));
}

static void populate_list(NFAPI_CRC_INDICATION_PDU_T *list, size_t num_elements, struct json_config *config) {
    size_t i;

    for (i = 0; i < num_elements; ++i) {
        list[i].tag.ue_id = json_integer_value(json_object_get(json_array_get(config->root, i), "UE_ID"));
        list[i].tag.lte_information_transfer_identity = json_boolean_value(json_object_get(json_array_get(config->root, i), "LTE_INFORMATION_TRANSFER_IDENTITY"));
        list[i].rnti = json_integer_value(json_object_get(json_array_get(config->root, i), "RNTI"));
        list[i].crc_indication.CRCFLAG = rand() % 2;
    }
}

pthread_mutex_t mutex;

void manage_list(size_t num_elements) {
    NFAPI_CRC_INDICATION_PDU_T *list;
    struct json_config *config;
    int retries = MAX_RETRIES;
    long sleep_time = BASE_SLEEP_TIME;

    pthread_mutex_init(&mutex, NULL);

    while (retries > 0) {
        config = load_json_config("http://remote-server.com/config.json");
        if (config) {
            validate_json_config(config);
            break;
        }
        --retries;
        usleep(sleep_time);
        sleep_time += sleep_time * 2;
    }

    if (!config) {
        fprintf(stderr, "Failed to load JSON configuration after %d retries.\n", MAX_RETRIES);
        return;
    }

    init_list(&list, config->num_elements);
    populate_list(list, config->num_elements, config);

    pthread_mutex_lock(&mutex);
    // Implement access and modification of list with synchronization mechanisms here.
    pthread_mutex_unlock(&mutex);
}
