void initializeAndManageTaskQueue(const std::vector<std::string>& categories, const std::string& categoryName, const std::string& task) {
    // Check for an existing category and insert if not present.
    auto it = std::find(categories.begin(), categories.end(), categoryName);
    if (it == categories.end()) {
        categories.push_back(categoryName);
    }

    // Insert the task into the appropriate category, ensuring thread safety with a mutex.
    std::lock_guard<std::mutex> lock(queue_mutex);
    Task_PDU newTask{};
