    newTask.priority_level = 0; // Adjust according to priority requirements.
    newTask.task_identifier = task;
    newTask.execution_time = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();
