struct list_data {
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T* data;
    pthread_mutex_t mutex;
};

void list_init(struct list_data** list, size_t capacity) {
    *list = malloc(sizeof(struct list_data));
    if (*list == NULL) {
        fprintf(stderr, "Failed to allocate memory for list\n");
        return;
    }

    (*list)->capacity = capacity > 10000 ? 10000 : capacity;
    (*list)->size = 0;
    (*list)->data = calloc((*list)->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if ((*list)->data == NULL) {
        fprintf(stderr, "Failed to allocate memory for list data\n");
        free(*list);
        *list = NULL;
        return;
    }

    (*list)->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void push(struct list_data* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].rnti == pdu->rnti) {
            fprintf(stderr, "Duplicate RNTI found: %d\n", pdu->rnti);
            pthread_mutex_unlock(&list->mutex);
            return;
        }
    }

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2 > 10000 ? 10000 : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* temp_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (temp_data == NULL) {
            fprintf(stderr, "Failed to reallocate memory for list data\n");
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->capacity = new_capacity;
        list->data = temp_data;
    }

    list->data[list->size] = *pdu;
    ++(list->size);

    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* pop(struct list_data* list) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == 0) {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* result = &list->data[0];
    memmove(list->data, list->data + 1, (list->size - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    --list->size;

    pthread_mutex_unlock(&list->mutex);
    return result;
}
