#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <tcmalloc/tcmalloc.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} node_t;

typedef struct {
    node_t **head;
    unsigned int size;
    unsigned int capacity;
    pthread_mutex_t mutex;
} concurrent_queue_t;

void init_concurrent_queue(concurrent_queue_t *q, unsigned int capacity) {
    q->size = 0;
    q->capacity = capacity;
    q->head = malloc(sizeof(node_t*) * capacity);
    memset(q->head, 0, sizeof(node_t*) * capacity);
    pthread_mutex_init(&q->mutex, NULL);
}

void push(concurrent_queue_t *q, NFAPI_CRC_INDICATION_PDU_T data) {
    node_t *new_node = malloc(sizeof(node_t));
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&q->mutex);
    unsigned int index = q->size % q->capacity;
    if (!q->head[index]) {
        q->head[index] = new_node;
    } else {
        node_t *current = q->head[index];
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
    q->size++;
    pthread_mutex_unlock(&q->mutex);
}

NFAPI_CRC_INDICATION_PDU_T pop(concurrent_queue_t *q) {
    pthread_mutex_lock(&q->mutex);
    node_t *result = NULL;
    if (q->size > 0) {
        unsigned int index = q->size - 1 % q->capacity;
        result = q->head[index];
        q->head[index] = q->head[index]->next;
