    for (size_t i = indexof(context, dynamic_array, array_size); i < array_size - 1; ++i) {
        dynamic_array[i] = dynamic_array[i + 1];
    }
    --array_size;

    pthread_mutex_unlock(&context_mutex);
    delete_context(context);
}
