typedef struct list_head {
    pthread_mutex_t mutex;
    LTE_PHY_RX_BUFFER_T* head;
    size_t size;
} list_head_t;

void validate_metrics(LTE_PHY_RX_BUFFER_T* buf) {
    if (buf->signal_strength < -50 || buf->signal_quality < 10) {
        free(buf);
    }
}

void add_to_list(list_head_t* list, LTE_PHY_RX_BUFFER_T* buf) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == 0 || buf->UE_INDEX < list->head->UE_INDEX) {
        buf->next = list->head;
        list->head = buf;
    } else {
        LTE_PHY_RX_BUFFER_T* current = list->head;
        while (current->next && current->next->UE_INDEX < buf->UE_INDEX) {
            current = current->next;
        }
        buf->next = current->next;
        current->next = buf;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

void init_list(list_head_t* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}
