#include <mutex>
#include <chrono>
#include <functional>

template<typename T>
class Record {
public:
    explicit Record(T value) : value_(value) {}
    T getValue() const { return value_; }

private:
    T value_;
};

void manageMemory(std::forward_list<std::string>& data, const std::string& key, int range, int offsetSize, int keySize, int recordSize) {
    std::mutex mtx;

    auto longArr = std::make_unique<long[]>(offsetSize);
    auto keyArr = std::make_unique<int[]>(keySize);
    auto recArr = std::make_unique<Record<int>[]>(recordSize);

    std::default_random_engine generator;
    std::uniform_int_distribution<int> distribution(0, range);

    // Populate record array with random values.
    for (auto& r : recArr)
        r = Record<int>(distribution(generator));

    auto it = data.begin();
    std::size_t index = 0;
    {
        std::unique_lock<std::mutex> lock(mtx);
        while (it != data.end()) {
            if (*it == key) {
                longArr[index] = it - data.begin();
                keyArr[index] = index;
                recArr[index].getValue() = *it++;
                it = std::next(it);
                ++index;
            }
            if (it == std::next(it)) {
                break;
            }
            it = data.insert(it, key);
        }
    }

    // Insert remaining data after the last occurrence of 'key'.
    {
        std::unique_lock<std::mutex> lock(mtx);
        while (it != data.end()) {
            if (*it == key) {
                ++it;
            }
            it = data.insert(it, key);
        }
    }

    // Set offset, key, and record pointers in the newly created elements.
    {
        std::unique_lock<std::mutex> lock(mtx);
        for (auto newIt = it; newIt != data.end(); ++newIt) {
            if (index < keySize) {
                longArr[index] = newIt - data.begin();
                keyArr[index++] = index;
                recArr[index - 1].getValue() = *newIt++;
            }
        }
    }
}
