#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>

typedef struct LTE_PHY_RX_FRAME {
    RX_FRAME_HEADER header;
    PHY_PARAMS params;
    FRAME_BUFFER buffer;
    bool FRAME_VALID_FLAG;
} LTE_PHY_RX_FRAME;

typedef struct LTE_RX_QUEUE {
    LTE_PHY_RX_FRAME* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
} LTE_RX_QUEUE;

void lte_rx_queue_init(LTE_RX_QUEUE* queue, size_t capacity) {
    queue->data = malloc(capacity * sizeof(LTE_PHY_RX_FRAME));
    if (!queue->data) {
        perror("Failed to allocate memory for LTE RX queue");
        return;
    }

    queue->capacity = capacity;
    queue->count = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
}

void lte_rx_queue_deinit(LTE_RX_QUEUE* queue) {
    free(queue->data);
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->not_empty);
}

bool lte_rx_queue_push(LTE_RX_QUEUE* queue, LTE_PHY_RX_FRAME frame) {
    pthread_mutex_lock(&queue->lock);

    // Check if the queue is full and cannot accept new data.
    if (queue->count == queue->capacity) {
        pthread_mutex_unlock(&queue->lock);
        return false;
    }

    // Copy the frame into the queue and set its FRAME_VALID_FLAG randomly.
    queue->data[queue->count++] = frame;

    // Notify any waiting threads that there is new data in the queue.
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);

    return true;
}

LTE_PHY_RX_FRAME lte_rx_queue_pop(LTE_RX_QUEUE* queue) {
    LTE_PHY_RX_FRAME frame;
    pthread_mutex_lock(&queue->lock);

    // Check if the queue is empty and cannot provide data.
    if (queue->count == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }

    frame = queue->data[--queue->count];
    memset(queue->data + queue->count, 0, sizeof(LTE_PHY_RX_FRAME));

    pthread_mutex_unlock(&queue->lock);

    return frame;
}
