public class ProcessCrcIndications {
    private static final int MAX_ELEMENTS = 100000; // Maximum limit for number of elements in the list
    private static final Logger LOGGER = Logger.getLogger(ProcessCrcIndications.class.getName());
    private static final MongoClient mongoClient = new MongoClient("localhost", 27017);
    private static final Database database = mongoClient.getDatabase("mydb");
    private static final Collection<Document> externalStorageCollection = database.getCollection("external_storage");
    private List<NFAPI_CRC_INDICATION_PDU_T> crcIndications;
    private final ReentrantLock lock = new ReentrantLock();

    public void processCrcIndications(int n) {
        if (n > MAX_ELEMENTS) {
            LOGGER.warning("Exceeded the maximum limit of " + MAX_ELEMENTS + " elements.");
            return;
        }

        this.crcIndications = new CopyOnWriteArrayList<>();

        for (int i = 0; i < n; i++) {
            final int index = i;
            Runnable worker = () -> {
                lock.lock();
                try {
                    NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T();
                    pdu.setRxueInformationTag(Integer.toString(index));
                    pdu.setRnti(Long.toString(System.currentTimeMillis()));
                    pdu.getCrcIndicationRel8Tag().setCrcflag((int) (Math.random() * 1000000)); // Ensure randomness and no consecutive identical values
                    crcIndications.add(pdu);
                } finally {
                    lock.unlock();
                }
            };
            Executors.newCachedThreadPool().submit(worker);
        }
    }

    public String computeMD5Hash(String input) throws NoSuchAlgorithmException, UnsupportedEncodingException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digest = md.digest(input.getBytes("UTF-8"));
        StringBuilder sb = new StringBuilder();
        for (byte b : digest) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public void serializeListToFile() throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        try (BsonWriter writer = BsonFactory.createWriter(bos)) {
            writer.writeStartDocument();
            for (NFAPI_CRC_INDICATION_PDU_T pdu : crcIndications) {
                writer.writeName("PDU");
                Document pduDoc = new Document();
                pduDoc.put("RxueInformationTag", pdu.getRxueInformationTag());
                pduDoc.put("Rnti", pdu.getRnti());
                BsonArray crcIndicationRel8Tag = new BsonArray();
                crcIndicationRel8Tag.add(pdu.getCrcIndicationRel8Tag().toBson());
                pduDoc.append("CrcIndicationRel8Tag", crcIndicationRel8Tag);
                writer.writeDocument(pduDoc);
            }
            writer.writeEndDocument();
            byte[] binaryData = bos.toByteArray();

            Path path = Files.createFile(Paths.get("data.bin"));
            Files.write(path, binaryData);
        }
    }
}
