void create_and_populate_pdus(NFAPI_RRC_PDU_T **rrc_pdu_array, size_t *rrc_pdu_count) {
    for (size_t i = 0; i < *rrc_pdu_count; ++i) {
        rrc_pdu_array[i] = init_rrc_pdu(RRC_MESSAGE_TYPE, i % MAX_UE_ID, i % MAX_TRX_ID);
    }
