void process_pdus(NFAPI_RRC_PDU_T **rrc_pdu_array, size_t rrc_pdu_count) {
    sem_t rate_limiter;
    sem_init(&rate_limiter, 0, RATE_LIMIT);

    pthread_t threads[NUM_THREADS];
    for (size_t i = 0; i < NUM_THREADS; ++i) {
        int err = pthread_create(&threads[i], NULL, process_pdu_thread, rrc_pdu_array + (i * (rrc_pdu_count / NUM_THREADS)), (void*)(rrc_pdu_count / NUM_THREADS));
        if (err != 0) {
            fprintf(stderr, "Can't create thread :[%s]", strerror(-err));
            return;
        }
    }

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void* process_pdu_thread(void *arg, void *data) {
    size_t slice_size = *(size_t*)data;
    NFAPI_RRC_PDU_T **rrc_pdu_array = (NFAPI_RRC_PDU_T**)arg;
    qsort(rrc_pdu_array, slice_size, sizeof(NFAPI_RRC_PDU_T*), compare_ue_id);

