    for (size_t i = 0; i < slice_size; ++i) {
        sem_wait(&rate_limiter);
        // Process the PDU here, including logging and telemetry
    }

    return NULL;
}

int compare_ue_id(const void *a, const void *b) {
    return ((NFAPI_RRC_PDU_T *)a)->ue_id - ((NFAPI_RRC_PDU_T *)b)->ue_id;
}
