struct nic_stat {
    uint64_t id; // Network interface identifier
    time_t timestamp; // Timestamp of the measurement
    uint64_t in_packets; // Incoming packet counter
    uint64_t out_packets; // Outgoing packet counter
    uint64_t in_bytes; // Incoming bytes counter
    uint64_t out_bytes; // Outgoing bytes counter;
    pthread_mutex_t lock; // Mutex for thread-safe access
};

typedef struct nic_stat nic_stat_t;

// Thread-safe initialization of nic_stat_t structure with unique identifier
void init_nic_stat(nic_stat_t* stat, uint64_t id) {
    stat->id = id;
    stat->timestamp = time(NULL);
    stat->in_packets = 0;
    stat->out_packets = 0;
    stat->in_bytes = 0;
    stat->out_bytes = 0;
    pthread_mutex_init(&stat->lock, NULL);
}

// Function to populate the array with nic_stat_t structures based on available network interfaces.
void populate_nic_array(nic_stat_t** nic_arr, size_t* nic_count) {
    struct ifaddrs *ifap, *ifa;
    getifaddrs(&ifap);
    size_t i = 0;

    for (ifa = ifap; ifa != NULL; ifa = ifa->ifa_next) {
        // Skip loopback and virtual interfaces
        if (ifa->ifa_name == NULL || ifa->ifa_addr == NULL)
            continue;

        nic_stat_t* nic_stat = malloc(sizeof(nic_stat_t));
        init_nic_stat(nic_stat, ifa->ifa_index);
        nic_arr[i++] = nic_stat;
    }
    freeifaddrs(ifap);
    *nic_count = i;
}

// Logging function to record statistics for long-term analysis.
