#include <json-c/json.h> // External library for parsing JSON (assuming it adheres to performance and reliability standards)

#define BUFFER_SIZE 1024
#define CHUNK_SIZE 32 * 1024

typedef struct Bundle {
    size_t count;
    json_object **items;
} Bundle;

int load_resource_bundle(const char *path, Bundle **bundle) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("fopen");
        return 1; // Error: File access error
    }

    size_t num_items = 0;
    Bundle *bundle_ptr = calloc(1, sizeof(Bundle));
    if (!bundle_ptr) {
        perror("calloc");
        fclose(file);
        return 2; // Error: Memory allocation failure
    }

    char buffer[BUFFER_SIZE];
    ssize_t bytes_read = 0;
    json_object *obj = NULL;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    while ((bytes_read = getc(file)) != EOF) {
        if (feof(file)) break; // End of file reached

        buffer[bytes_read] = '\0';
        if (!strchr("\n", buffer[0])) continue; // Skip non-newline characters

        obj = json_tokener_parse(buffer);
        if (IS_ERR(obj)) {
            json_object_put(obj);
            perror("json_tokener_parse");
            fclose(file);
            free(bundle_ptr);
            return 3; // Error: JSON parsing error
        }

        pthread_mutex_lock(&mutex);
        size_t new_size = ++num_items > bundle_ptr->count ? num_items * 2 : bundle_ptr->count * 2;
        bundle_ptr->items = realloc(bundle_ptr->items, sizeof(json_object *) * new_size);
        if (!bundle_ptr->items) {
            perror("realloc");
            json_object_put(obj);
            pthread_mutex_unlock(&mutex);
            fclose(file);
            free(bundle_ptr);
            return 2; // Error: Memory allocation failure
        }
        bundle_ptr->items[num_items - 1] = obj;
        pthread_mutex_unlock(&mutex);
    }

    if (ferror(file)) {
        perror("getc");
        fclose(file);
        free(bundle_ptr);
        return 1; // Error: File read error
    }
    fclose(file);

    bundle_ptr->count = num_items;
    *bundle = bundle_ptr;
    return 0; // Success
}
