typedef struct {
    time_t timestamp;
    double temperature;
    int station_id;
    int timezone_offset;
} Reading;

struct Storage {
    Reading* data;
    size_t capacity;
    size_t count;
};

void init_storage(StructStorage *storage, size_t initial_capacity) {
    storage->data = malloc(initial_capacity * sizeof(Reading));
    storage->capacity = initial_capacity;
    storage->count = 0;
}

bool validate_reading(const Reading* reading) {
    return reading->temperature >= -273.15 && reading->temperature <= 1000.0;
}

void process_data(StructStorage *storage, const char* data, int station_id, int timezone_offset) {
    Reading* current = &storage->data[storage->count];

    // Parse the input format
    sscanf(data, "%ld %lf %d %d", &current->timestamp, &current->temperature, &current->station_id, &current->timezone_offset);

    if (sscanf(data, 4) != 4) {
        // Handle malformed input or unexpected data format
        current->temperature = NAN;
        return;
    }

    // Adjust timestamp for time zone differences
    current->timestamp += current->timezone_offset * 60 * 60;
    time_t now = time(NULL);
    struct tm* now_tm = localtime(&now);
    current->timestamp -= now_tm->tm_year * 365 + now_tm->tm_yday - now_tm->tm_min / 60;

    if (current->timestamp < 1970) {
        // Handle timestamps before 1970
        current->temperature = NAN;
        return;
    }

    if (!validate_reading(current)) {
        // Mark invalid readings as such
        current->temperature = NAN;
        return;
    }

    storage->count++;

    if (storage->count >= storage->capacity) {
        Reading* new_data = realloc(storage->data, storage->capacity * 2 * sizeof(Reading));
        if (!new_data) {
            // Handle memory allocation errors
            current->temperature = NAN;
            return;
        }
        storage->capacity *= 2;
        storage->data = new_data;
    }
}

double mean(const Reading* data, size_t n) {
    double sum = 0.0;
    for (size_t i = 0; i < n; ++i) {
        sum += data[i].temperature;
    }
    return sum / n;
}

double standard_deviation(const Reading* data, size_t n, double mean) {
    double sum_squares = 0.0;
    for (size_t i = 0; i < n; ++i) {
        double diff = data[i].temperature - mean;
        sum_squares += diff * diff;
    }
    return sqrt(sum_squares / n);
}

void calculate_statistics(StructStorage* storage, double* mean, double* stddev) {
    size_t count = 0;
    for (size_t i = 0; i < storage->count; ++i) {
        if (!isnan(storage->data[i].temperature)) {
            count++;
        }
    }

    *mean = mean(storage->data, count);
    *stddev = standard_deviation(storage->data, count, *mean);
}

void save_to_external_system(const Reading* data, size_t n) {
    // Implement integration with external data management system here.
}

int main() {
    StructStorage storage;
    init_storage(&storage, 1024);

    pthread_t threads[NUM_THREADS];
    char input_data[NUM_THREADS][MAX_INPUT_LENGTH];
    int station_ids[NUM_THREADS];
    int timezone_offsets[NUM_THREADS];

    // Fill the input data, station ids and timezone offsets.

    pthread_create(&threads[0], NULL, (void*(*)(void*)) process_data, &storage);
    pthread_create(&threads[1], NULL, (void*(*)(void*)) process_data, &storage);
    // ... create other threads as needed.

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    double mean, stddev;
    calculate_statistics(&storage, &mean, &stddev);

    save_to_external_system(storage.data, storage.count);

    free(storage.data);

    return 0;
}
