#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

record* init_data(int num_offsets, int num_records, int min_value, int max_value) {
    // Allocate memory for offsets and keys arrays
    long *offsets = (long*) malloc(num_offsets * sizeof(long));
    if (!offsets) {
        perror("Error allocating memory for offsets");
        return NULL;
    }

    int *keys = (int*) malloc(num_offsets * sizeof(int));
    if (!keys) {
        perror("Error allocating memory for keys");
        free(offsets);
        return NULL;
    }

    // Initialize offsets and keys arrays with sequential values
    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = i;
        keys[i] = i;
    }

    // Allocate memory for records array
    record *records = (record*) malloc(num_records * sizeof(record));
    if (!records) {
        perror("Error allocating memory for records");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize records array with random integer values
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = min_value + (rand() % (max_value - min_value + 1));
    }

    // Free memory if an error occurs during data retrieval or processing
    int partial_allocation = num_offsets * sizeof(long) + num_offsets * sizeof(int) + num_records * sizeof(record);
    if (partial_allocation > 1024 * 1024 * 5 && getrusage(RUSAGE_SELF, &ru) && ru.ru_maxrss >= (1024 * 1024 * 5 - partial_allocation)) {
        fprintf(stderr, "Memory usage exceeded system limit\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    return records;
}
```
