    size_t count;
    NFAPI_CRC_INDICATION_PDU_T* data;
    pthread_mutex_t mutex;
} PDU_ARRAY;

void init_pdu_array(PDU_ARRAY* array, size_t initial_capacity) {
    array->capacity = initial_capacity;
    array->count = 0;
    array->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        fprintf(stderr, "Failed to allocate initial memory\n");
        exit(-1);
    }
    array->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void push_pdu(PDU_ARRAY* array, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    clock_t start = clock();
    pthread_mutex_lock(&array->mutex);

    // Check if we need to reallocate memory due to capacity exceeded
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_data) {
            fprintf(stderr, "Failed to reallocate memory\n");
            pthread_mutex_unlock(&array->mutex);
            exit(-1);
        }

        array->capacity = new_capacity;
        array->data = new_data;
    }

    // Populate the structure with random CRCFLAG and increment count
    array->data[array->count++] = *pdu;

    printf("Pushed PDU. Allocation time: %.6fs\n", (clock() - start) / CLOCKS_PER_SEC);

    pthread_mutex_unlock(&array->mutex);
}

void cleanup(PDU_ARRAY* array) {
    free(array->data);
}
