#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>

typedef struct _NODE {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct _NODE* next;
    pthread_mutex_t mutex;
} NODE;

NODE* create_node() {
    NODE* node = (NODE*)malloc(sizeof(NODE));
    node->data.RX_UE_INFORMATION_TAG = 0;
    node->data.RNTI = 0;
    node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    node->next = NULL;
    pthread_mutex_init(&node->mutex, NULL);
    return node;
}

void add_to_list(NODE** head, NODE* node) {
    pthread_mutex_lock(&((*head)->mutex));
    node->next = *head;
    *head = node;
    pthread_mutex_unlock(&((*head)->mutex));
}

void remove_from_list(NODE** head, NODE* node) {
    pthread_mutex_lock(&((*head)->mutex));
    if (*head == node) {
        *head = node->next;
    } else {
        NODE* temp = *head;
        while (temp->next != node) {
            temp = temp->next;
        }
        temp->next = node->next;
    }
    pthread_mutex_unlock(&((*head)->mutex));
}

void clear_list(NODE** head) {
    NODE *current, *next;
    pthread_mutex_lock(&((*head)->mutex));
    current = *head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
    pthread_mutex_destroy(&((*head)->mutex));
}
```

