#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    int customer_id;
    char order_date[20];
    double total_amount;
    char status[10];

    int item_id;
    int quantity;
    double price;
} CUSTOMER_ORDER_RECORD_T;

#define TABLE_SIZE 1024

typedef struct hash_entry {
    CUSTOMER_ORDER_RECORD_T record;
    struct hash_entry *next;
} HASH_ENTRY;

typedef struct hash_table {
    HASH_ENTRY **table;
    sem_t lock;
    int size, count;
} HASH_TABLE;

HASH_TABLE* create_hash_table() {
    HASH_TABLE *ht = malloc(sizeof(HASH_TABLE));
    ht->size = TABLE_SIZE;
    ht->count = 0;
    ht->table = calloc(TABLE_SIZE, sizeof(HASH_ENTRY*));
    sem_init(&ht->lock, 0, 1);
    return ht;
}

int hash(int key) {
    return key % TABLE_SIZE;
}

void insert(HASH_TABLE *ht, CUSTOMER_ORDER_RECORD_T record) {
    sem_wait(&ht->lock);
    int index = hash(record.customer_id);
    HASH_ENTRY **entry = &ht->table[index];
    while (*entry != NULL)
        entry = &( (*entry)->next );

    *entry = malloc(sizeof(HASH_ENTRY));
    (**entry) = record;
    (**entry).next = NULL;
    ht->count++;
    sem_post(&ht->lock);
}

CUSTOMER_ORDER_RECORD_T* find(HASH_TABLE *ht, int customer_id) {
    CUSTOMER_ORDER_RECORD_T *result = NULL;
    sem_wait(&ht->lock);
    int index = hash(customer_id);
    HASH_ENTRY **entry = &ht->table[index];
    while (*entry != NULL && (*entry)->record.customer_id != customer_id) {
        entry = &( (*entry)->next );
    }

    if (*entry != NULL) {
        result = malloc(sizeof(CUSTOMER_ORDER_RECORD_T));
        *result = (**entry).record;
    }
    sem_post(&ht->lock);
    return result;
}

void clear(HASH_TABLE *ht) {
    sem_wait(&ht->lock);
    for (int i = 0; i < ht->size; ++i) {
        HASH_ENTRY *entry = ht->table[i];
        while (entry != NULL) {
            HASH_ENTRY *tmp = entry;
            entry = entry->next;
            free(tmp);
        }
    }
    memset(ht->table, 0, TABLE_SIZE * sizeof(HASH_ENTRY*));
    ht->count = 0;
    sem_post(&ht->lock);
}

void destroy(HASH_TABLE *ht) {
    clear(ht);
    free(ht->table);
    free(ht);
}
