['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

struct MemoryPool {
    pthread_mutex_t lock;
    Node* head, *tail;
};

void initMemoryPool(struct MemoryPool* pool) {
    pool->head = pool->tail = NULL;
    pthread_mutex_init(&pool->lock, NULL);
}

Node* allocateFromMemoryPool(struct MemoryPool* pool) {
    Node *node = NULL;
    pthread_mutex_lock(&pool->lock);
    if (pool->head != NULL) {
        node = pool->head;
        pool->head = pool->head->next;
        if (pool->head == NULL)
            pool->tail = NULL;
    } else {
        node = malloc(sizeof(Node));
        if (!node) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
    }
    memset(node, 0, sizeof(Node));
    node->data.crc_indication.crcflag = rand() % 2;
    pthread_mutex_unlock(&pool->lock);
    return node;
}

void freeToMemoryPool(struct MemoryPool* pool, Node* node) {
    pthread_mutex_lock(&pool->lock);
    node->next = pool->head;
    pool->head = node;
    pthread_mutex_unlock(&pool->lock);
}

NFAPI_CRC_INDICATION_PDU_T* createArray(int N) {
    struct MemoryPool memoryPool;
    initMemoryPool(&memoryPool);
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        freeMemoryPool(&memoryPool);
        return NULL;
    }
    for (int i = 0; i < N; ++i) {
        array[i].crc_indication.crcflag = rand() % 2;
        if (!(array + i)->next = allocateFromMemoryPool(&memoryPool)) {
            fprintf(stderr, "Memory allocation failed\n");
            free(array);
            freeMemoryPool(&memoryPool);
            return NULL;
        }
    }
    return array;
}

void freeArray(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    for (int i = 0; i < N; ++i)
        freeToMemoryPool(&memoryPool, array + i);
    free(array);
}

void freeMemoryPool(struct MemoryPool* pool) {
    Node *current, *next;
    pthread_mutex_lock(&pool->lock);
    current = pool->head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    pool->head = pool->tail = NULL;
    pthread_mutex_destroy(&pool->lock);
}
```

