#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_TRANSPORT_LAYER_PACKET {
    int PDCP_SN;
    int SRB_ID;
    int PDUSessionID;
} LTE_TRANSPORT_LAYER_PACKET;

struct memory_pool {
    void* data;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
};

void init_memory_pool(struct memory_pool* pool, size_t capacity) {
    pool->data = malloc(capacity * sizeof(LTE_TRANSPORT_LAYER_PACKET));
    if (!pool->data) {
        perror("Error allocating memory");
        return;
    }
    pool->capacity = capacity;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

LTE_TRANSPORT_LAYER_PACKET* allocate(struct memory_pool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used < pool->capacity) {
        LTE_TRANSPORT_LAYER_PACKET* packet = (LTE_TRANSPORT_LAYER_PACKET*)((char*)pool->data + pool->used * sizeof(LTE_TRANSPORT_LAYER_PACKET));
        pool->used++;
        pthread_mutex_unlock(&pool->lock);
        return packet;
    } else {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
}

void free_memory_pool(struct memory_pool* pool) {
    if (pool->data) {
        free(pool->data);
        pool->capacity = 0;
        pool->used = 0;
        pthread_mutex_destroy(&pool->lock);
    }
}

LTE_TRANSPORT_LAYER_PACKET** create_packet_array(int M) {
    if (M <= 0 || M > 500) {
        fprintf(stderr, "Invalid input value for M. Valid range: [1, 500]\n");
        return NULL;
    }

    struct memory_pool* pool = malloc(sizeof(struct memory_pool));
    if (!pool) {
        perror("Error allocating memory");
        return NULL;
    }

    init_memory_pool(pool, M);

    LTE_TRANSPORT_LAYER_PACKET** packets = malloc(M * sizeof(LTE_TRANSPORT_LAYER_PACKET*));
    if (!packets) {
        perror("Error allocating memory");
        free_memory_pool(pool);
        free(pool);
        return NULL;
    }

    for (int i = 0; i < M; ++i) {
        packets[i] = allocate(pool);
        if (!packets[i]) {
            fprintf(stderr, "Error allocating memory. Increase the capacity of the memory pool or reduce the number of packets.\n");
            free_memory_pool(pool);
            free(pool);
            free(packets);
            return NULL;
        }
    }

    return packets;
}
```

