    pthread_mutex_lock(&nfit->lock);

    if (nfit->size == nfit->capacity) {
        nfit->capacity *= 2;
        nfit->data = realloc(nfit->data, nfit->capacity * sizeof(SENSOR_DATA_RECORD_T));
    }

    memcpy(&nfit->data[nfit->size], &event, sizeof(SENSOR_DATA_RECORD_T));
