    uint16_t RNTI;
    pthread_mutex_t lock;
} RNTI_DATA;

// External logging function
void log(const char *message);

int populate_list(NFAPI_CRC_INDICATION_PDU_T **head, int N) {
    int attempts = 3;
    NFAPI_CRC_INDICATION_PDU_T *current, *new_node, *prev = NULL;
    RNTI_DATA *rnti_data;
    FILE *db;
    int db_fd, ret;

    // Allocate memory for RNTI data structure
    rnti_data = malloc(sizeof(RNTI_DATA) * N);
    if (!rnti_data) {
        log("Failed to allocate memory for RNTI data structure");
        return -1;
    }

    // Initialize mutex locks
    for (int i = 0; i < N; ++i) {
        pthread_mutex_init(&rnti_data[i].lock, NULL);
    }

    *head = NULL;
    int successfully_allocated = 0;

    // Open database connection
    db_fd = open("/path/to/db", O_RDWR | O_CREAT | O_EXCL, 0644);
    if (db_fd == -1) {
        log("Failed to open database connection");
        goto cleanup;
    }
    db = fdopen(db_fd, "w+");

    // Try allocating and populating the list up to N times
    for (int i = 0; i < N && attempts > 0; ++i) {
        for (int j = 0; j < i; ++j) {
            current = *head;
            while (current != NULL) {
                if (current->RNTI == rnti_data[i].RNTI) {
                    attempts--;
                    log("RNTI collision, retrying...");
                    goto cleanup;
                }
                current = current->next;
            }
        }

        new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            log("Failed to allocate memory for new node");
            attempts--;
            continue;
        }

        ret = write(db_fd, &new_node->RNTI, sizeof(new_node->RNTI));
        if (ret != sizeof(new_node->RNTI)) {
            log("Failed to write RNTI to database");
            free(new_node);
            attempts--;
            continue;
        }

        new_node->RX_UE_INFORMATION_TAG = rand();
        new_node->CRC_INDICATION_REL8_TAG = rand() % 256;
        new_node->CRCFLAG = (rand() % 2) == 0;

        pthread_mutex_lock(&rnti_data[new_node->RNTI].lock);
        // Write RNTI to database
        ret = write(db_fd, &new_node->RNTI, sizeof(new_node->RNTI));
        if (ret == sizeof(new_node->RNTI)) {
            attempts = 3;
            if (!*head) {
                *head = new_node;
            } else {
                current = *head;
                while (current->next != NULL) {
                    current = current->next;
                }
                current->next = new_node;
            }
            successfully_allocated++;
        }
        pthread_mutex_unlock(&rnti_data[new_node->RNTI].lock);
    }

    // Close database connection and clean up
cleanup:
    for (int i = 0; i < N; ++i) {
        pthread_mutex_destroy(&rnti_data[i].lock);
    }
    free(rnti_data);
    fclose(db);
    close(db_fd);

    logf("Successfully allocated %d structures", successfully_allocated);
    return successfully_allocated;
}

void serialize(NFAPI_CRC_INDICATION_PDU_T *head, const char *filename) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        log("Failed to open file for writing");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        write(fd, current, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        current = current->next;
    }

    close(fd);
}
