typedef std::list<UEContextInfo> UEContextList;
UEContextList ue_context_list;
pthread_mutex_t ue_context_list_mutex;

// Initialize the mutex at program start
void init_ue_context_list() {
    pthread_mutex_init(&ue_context_list_mutex, NULL);
}

// Lock the list before accessing it
void lock_ue_context_list() {
    pthread_mutex_lock(&ue_context_list_mutex);
}

// Unlock the list after accessing it
void unlock_ue_context_list() {
    pthread_mutex_unlock(&ue_context_list_mutex);
}

// Function to insert a new UE context into the list
void insert_ue_context(UEContextInfo ue_context) {
    lock_ue_context_list();
    ue_context_list.push_back(ue_context);
    unlock_ue_context_list();
}

// Function to remove a UE context from the list by UE Identity
void remove_ue_context(uint32_t ue_identity) {
    lock_ue_context_list();
    auto it = ue_context_list.begin();
    while (it != ue_context_list.end()) {
        if (it->getUEIdentity() == ue_identity) {
            ue_context_list.erase(it);
            break;
        }
        ++it;
    }
    unlock_ue_context_list();
}

// Function to get a UE context by its identity, returning NULL if not found
UEContextInfo* find_ue_context(uint32_t ue_identity) {
    lock_ue_context_list();
    auto it = ue_context_list.begin();
    while (it != ue_context_list.end()) {
        if (it->getUEIdentity() == ue_identity) {
            UEContextInfo* result = new UEContextInfo(*it); // Clone the structure to return a copy, avoiding concurrency issues when modifying the list
            unlock_ue_context_list();
            return result;
        }
        ++it;
    }
    unlock_ue_context_list();
    return NULL;
}
