struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
};

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
int successful_allocations = 0;

void* create_node(void *data) {
    struct NFAPI_CRC_INDICATION_PDU_T *node = (struct NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    if (!node) return NULL;
    pthread_mutex_lock(&list_mutex);
    memcpy(node, data, sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    successful_allocations++;
    pthread_mutex_unlock(&list_mutex);
    return node;
}

void serialize_list() {
    struct NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    int num_attempts = 5;
    while (num_attempts > 0) {
        void* temp = create_node((void *)head);
        if (!temp) num_attempts--;
        else {
            struct NFAPI_CRC_INDICATION_PDU_T *next;
            head = temp;
            for (int i = 1; i < successful_allocations; ++i) {
                next = (void *)((char *)head + sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
                head->next = next;
                head = next;
            }
            head->next = NULL;
            break;
        }
    }

    if (successful_allocations == 0) {
        // Log error and terminate
    } else {
        int fd = open("list.bin", O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
        if (fd < 0) {
            // Log error and terminate
        } else {
            mmap(NULL, successful_allocations * sizeof(struct NFAPI_CRC_INDICATION_PDU_T), PROT_WRITE, MAP_SHARED, fd, 0);
            memcpy(mmap(..., head), head, successful_allocations * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
            munmap(..., head);
            close(fd);
        }
    }
}
