typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU;

typedef void (*PF_PROCESS_CB)(NFAPI_CRC_INDICATION_PDU* pdu);

void init_flexible_list(PF_PROCESS_CB process_cb, size_t initial_capacity) {
    size_t capacity = initial_capacity;
    NFAPI_CRC_INDICATION_PDU** list = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU*));
    if (!list) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }

    size_t count = 0;
    *list = NULL;

    void* realloc_ptr = list;
    void** temp_list = NULL;

    if (process_cb) {
        for (size_t i = 0; i < capacity; ++i) {
            NFAPI_CRC_INDICATION_PDU* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
            if (!pdu) {
                fprintf(stderr, "Out of memory\n");
                exit(1);
            }
            process_cb(pdu); // Perform any necessary initialization
            list[count++] = pdu;
        }
    }

    void swap(void** a, void** b) {
        void* temp = *a;
        *a = *b;
        *b = temp;
    }

    void grow_list() {
        capacity *= 2;
        temp_list = malloc((capacity + 1) * sizeof(NFAPI_CRC_INDICATION_PDU*));
        if (!temp_list) {
            fprintf(stderr, "Out of memory\n");
            exit(1);
        }

        for (size_t i = 0; i <= count; ++i) {
            swap(&((realloc_ptr + i)[0]), &((temp_list + i)[0]));
        }

        free(realloc_ptr);
        realloc_ptr = temp_list;
    }

    void push_back(NFAPI_CRC_INDICATION_PDU* pdu) {
        if (count == capacity) {
            grow_list();
        }
        realloc_ptr[count++] = pdu;
    }

    void pop_front() {
        if (count <= 0) {
            return;
        }
        free(realloc_ptr[0]);
        count--;
        memmove(realloc_ptr, realloc_ptr + 1, sizeof(NFAPI_CRC_INDICATION_PDU*) * count);
    }

    void clear() {
        for (size_t i = 0; i < count; ++i) {
            free(realloc_ptr[i]);
        }
        free(list);
        list = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU*));
        realloc_ptr = list;
        count = 0;
    }
}
```

