struct circular_buffer {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity; // Max number of elements in the buffer
    size_t head;     // Index of the next free element to add data
    size_t tail;     // Index of the first unused element (wraps around when full)
    pthread_mutex_t lock;
    policy_callback policy; // Pointer to the current validation policy
};

// Function to initialize a circular buffer with a given capacity and policy callback
void init_circular_buffer(struct circular_buffer *cb, size_t capacity, policy_callback policy) {
    cb->capacity = capacity;
    cb->head = cb->tail = 0;
    cb->policy = policy;
    pthread_mutex_init(&cb->lock, NULL);
    cb->data = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
}

// Function to add a new element to the buffer
void push_element(struct circular_buffer *cb, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&cb->lock);

    // If the buffer is full, remove the first element before adding a new one
    if ((cb->head + 1) % cb->capacity == cb->tail) {
        free(cb->data + cb->tail);
        cb->head = (cb->head + 1) % cb->capacity;
    }

    // Validate the element based on the current policy
    if (!cb->policy(pdu)) {
        printf("Error: Failed policy validation for PDU.\n");
        pthread_mutex_unlock(&cb->lock);
        return;
    }

    cb->data[cb->head].rx_ue_information = pdu->rx_ue_information;
    cb->data[cb->head].rnti = pdu->rnti;
    cb->data[cb->head].crc_indication = pdu->crc_indication;
    cb->data[cb->head].crcflag = pdu->crcflag; // Set the custom field here

    cb->head = (cb->head + 1) % cb->capacity;
    pthread_mutex_unlock(&cb->lock);
