        da->elements = new_elements;
        da->capacity = new_capacity;
    }

    // Add the new element and increment the count
    da->elements[da->count++] = new_pdu;
    pthread_mutex_unlock(&da->mutex); // Unlock the mutex after successful addition
    return 0;
}

void destroy_dynamic_array(DynamicArray *da) {
