#define MEMORY_THRESHOLD (MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T))

typedef struct {
    RX_UE_INFORMATION_TAG rxi;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG cindTag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* list = NULL;
size_t num_elements = 0;

void populateElement(NFAPI_CRC_INDICATION_PDU_T* element) {
    element->rxi.presenceMask = RX_UE_INFORMATION_TAG__PRESENT;
    element->rxi.ueId = rand() % 65536;
    element->rxi.mmeCode = rand() % 256;
    element->rxi.rnti = element->rxi.ueId << 16 | element->rxi.mmeCode << 8 | rand() % 256;

    element->cindTag.presenceMask = CRC_INDICATION_REL8_TAG__PRESENT;
    element->cindTag.crcFlag = rand() % 2;
}

void* createList(void* arg) {
    pthread_mutex_lock(&list_mutex);

    if (num_elements + MAX_ELEMENTS > MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory threshold exceeded.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* newList = realloc(list, (num_elements + MAX_ELEMENTS) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newList) {
        fprintf(stderr, "Failed to allocate memory.\n");
        pthread_mutex_unlock(&list_mutex);
        return NULL;
    }
    list = newList;

    for (size_t i = num_elements; i < num_elements + MAX_ELEMENTS; ++i) {
        populateElement(list + i);
    }

    num_elements += MAX_ELEMENTS;
    pthread_mutex_unlock(&list_mutex);

    return list + num_elements - MAX_ELEMENTS;
}

void deallocateList() {
    free(list);
    list = NULL;
    num_elements = 0;
}

void logOperation(const char* operation, NFAPI_CRC_INDICATION_PDU_T* element) {
    printf("%s: RXI %d, RNTI 0x%lX, CRCFLAG %d\n", operation, element->rxi.ueId, element->rxi.rnti, element->cindTag.crcFlag);
}

int main() {
    void* result = createList(NULL);
    if (!result) return 1;

    logOperation("Created", (NFAPI_CRC_INDICATION_PDU_T*)result);

    deallocateList();
    return 0;
}
