// Specify the valid range for L2_PDU_TYPE values
#define MIN_L2_PDU_TYPE 1
#define MAX_L2_PDU_TYPE UINT16_MAX

// Error codes for different failure scenarios
#define MEMORY_FAILURE -1
#define OUT_OF_RANGE -2
#define DUPLICATE_TYPE -3
#define DATA_MISSING -4

// Forward declaration of helper functions
void init_list(NFAPI_L2_PDU_T** list, size_t* capacity);
void free_list(NFAPI_L2_PDU_T* list, size_t length);
bool is_valid_type(uint16_t type);
bool add_to_list(NFAPI_L2_PDU_T** list, size_t* length, NFAPI_L2_PDU_T new_pdu);
void log_error(const char* message, int error_code);

// Function to manage and process a list of NFAPI_L2_PDU_T structures
void process_pdus(NFAPI_L2_PDU_T** list, size_t* length, L2_RX_STATS* stats, ...) {
    va_list args;
    va_start(args, stats);

    // Process the variadic arguments and add them to the list, handling potential errors
    while (true) {
        NFAPI_L2_PDU_T new_pdu = va_arg(args, NFAPI_L2_PDU_T);
        if (new_pdu.type < MIN_L2_PDU_TYPE || new_pdu.type > MAX_L2_PDU_TYPE) {
            log_error("Invalid L2_PDU_TYPE value", OUT_OF_RANGE);
            continue; // Skip invalid entries and move to the next one
        }

        if (!add_to_list(list, length, new_pdu)) {
            if (va_arg(args, int) == MEMORY_FAILURE) {
                log_error("Memory allocation failure", MEMORY_FAILURE);
                break; // Exit the loop on memory allocation error
            } else {
                log_error("Duplicate L2_PDU_TYPE or list capacity exceeded", DUPLICATE_TYPE);
            }
        }
    }

    va_end(args);
}

// Helper functions for process_pdus() implementation
void init_list(NFAPI_L2_PDU_T** list, size_t* capacity) {
    *list = malloc(*capacity * sizeof(NFAPI_L2_PDU_T));
    if (*list == NULL) {
        log_error("Memory allocation failure", MEMORY_FAILURE);
        exit(MEMORY_FAILURE);
    }
}

void free_list(NFAPI_L2_PDU_T* list, size_t length) {
    if (length > 0 && list != NULL) {
        free(list);
    }
}

bool is_valid_type(uint16_t type) {
    return type >= MIN_L2_PDU_TYPE && type <= MAX_L2_PDU_TYPE;
}

bool add_to_list(NFAPI_L2_PDU_T** list, size_t* length, NFAPI_L2_PDU_T new_pdu) {
    if (*length >= *capacity) {
        // Dynamically scale the capacity based on current needs
        void* temp_list = mmap(NULL, *capacity * 2 * sizeof(NFAPI_L2_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (temp_list == MAP_FAILED) {
            log_error("Memory allocation failure", MEMORY_FAILURE);
            return false;
        }

        memcpy(temp_list, *list, *length * sizeof(NFAPI_L2_PDU_T));
        free(*list);
        *list = temp_list;
        *capacity *= 2;
    }

    bool found_duplicate = false;
    for (size_t i = 0; i < *length && !found_duplicate; ++i) {
        if ((*list + i)->type == new_pdu.type && i != (*length - 1)) { // Check for duplicate L2_PDU_TYPE, excluding the last entry (as there are no more entries to compare with)
            found_duplicate = true;
        }
    }

    if (!found_duplicate) {
        (*list + *length) = new_pdu;
        (*length)++;
        return true;
    }

    return false;
}

void log_error(const char* message, int error_code) {
    // Implement your logging system here using a suitable API (e.g., syslog(), printf(), or any custom logging library)
    fprintf(stderr, "%s: Error code %d\n", message, error_code);
}
