#include <pthread.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <time.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct Connection {
    int socket_fd;
    struct sockaddr_in peer_addr;
    bool connection_status; // e.g., CONNECTED or DISCONNECTED
    time_t last_activity;
    uint64_t latency_metrics;
} Connection;

typedef struct ConnectionPool {
    Connection** connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t not_empty;
} ConnectionPool;

ConnectionPool* connection_pool_create(size_t initial_capacity) {
    ConnectionPool* pool = malloc(sizeof(ConnectionPool));
    pool->connections = calloc(initial_capacity, sizeof(Connection*));
    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->not_empty, NULL);
    return pool;
}

void connection_pool_destroy(ConnectionPool* pool) {
    for (size_t i = 0; i < pool->capacity; ++i) {
        if (pool->connections[i]) {
            free(pool->connections[i]);
        }
    }
    free(pool->connections);
    pthread_mutex_destroy(&pool->mutex);
    pthread_cond_destroy(&pool->not_empty);
    free(pool);
}

Connection* connection_create(int socket_fd, struct sockaddr_in peer_addr) {
    Connection* conn = malloc(sizeof(Connection));
    conn->socket_fd = socket_fd;
    memcpy(&conn->peer_addr, &peer_addr, sizeof(struct sockaddr_in));
    conn->connection_status = true;
    conn->last_activity = time(NULL);
    conn->latency_metrics = 0;
    return conn;
}

Connection* connection_pool_add(ConnectionPool* pool, Connection* connection) {
    pthread_mutex_lock(&pool->mutex);
    while (pool->count >= pool->capacity && !pool->connections[pool->count - 1]) {
        pthread_cond_wait(&pool->not_empty, &pool->mutex);
    }

    if (pool->count < pool->capacity) {
        pool->connections[pool->count] = connection;
        ++pool->count;
    } else {
        Connection** temp_array = realloc(pool->connections, sizeof(Connection*) * 2 * pool->capacity);
        if (!temp_array) {
            pthread_mutex_unlock(&pool->mutex);
            return NULL;
        }
        memmove(&temp_array[pool->capacity], pool->connections, sizeof(Connection*) * pool->count);
        pool->connections = temp_array;
        pool->capacity *= 2;

        Connection* temp_connection = connection_create(-1, (struct sockaddr_in){0, 0, 0, 0});
        memmove(&pool->connections[pool->count - 1], &temp_connection, sizeof(Connection*));
        pool->count++;
    }
    pthread_mutex_unlock(&pool->mutex);
    return connection;
}

void connection_pool_remove(ConnectionPool* pool, Connection* connection) {
    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->connections[i] == connection) {
            memmove(pool->connections + i, pool->connections + i + 1, sizeof(Connection*) * (pool->count - i - 1));
            --pool->count;
            break;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
}

void connection_update_status(Connection* connection, bool new_status) {
    if (!new_status && connection->connection_status) {
        connection->last_activity = time(NULL);
    }
    connection->connection_status = new_status;
}

// Implement functions for updating latency metrics efficiently in real-time, periodically pruning inactive connections, logging, etc.
