```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T {
    uint32_t RRC_UE_ID;
    uint16_t MEASUREMENT_REPORT_TAG, RECONFIGURATION_COMPLETE_TAG;
    uint16_t SEQUENCE_NUMBER;
} NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T;

typedef struct Node {
    NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T data;
    struct Node *next;
    pthread_mutex_t mutex;
} Node;

struct FlexibleList {
    Node *head, *tail;
    size_t size;
    void (*callback)(NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T*);
};

void flexibleListInit(struct FlexibleList* list) {
    list->head = list->tail = NULL;
    list->size = 0;
    list->callback = NULL;
}

Node* createNode(const NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T* data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    newNode->data = *data;
    newNode->next = NULL;
    pthread_mutex_init(&newNode->mutex, NULL);
    return newNode;
}

void insertNode(struct FlexibleList* list, Node* node) {
    if (!list || !node) {
        fprintf(stderr, "Error: Invalid input\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&node->mutex);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
    pthread_mutex_unlock(&node->mutex);
    list->size++;
}

void freeNode(Node* node) {
    if (!node) return;

    pthread_mutex_lock(&node->mutex);
    Node *temp = node;
    node = node->next;
    free(temp);
    pthread_mutex_unlock(&node->mutex);
}

void deleteNodeAtIndex(struct FlexibleList* list, size_t index) {
    if (index >= list->size) {
        fprintf(stderr, "Error: Index out of bounds\n");
        return;
    }

    Node *current = list->head;
    for (size_t i = 0; i < index; i++) {
        current = current->next;
    }

    pthread_mutex_lock(&current->mutex);

    if (index == 0) {
        list->head = current->next;
        freeNode(current);
    } else if (index == list->size - 1) {
        for (Node *prev = list->head;; prev = prev->next) {
            if (!prev->next) {
                fprintf(stderr, "Error: Invalid index\n");
                return;
            }

            if (--index == 0) {
                prev->next = current->next;
                freeNode(current);
                list->tail = prev;
                break;
            }
        }
    } else {
        current->next = current->next->next;
        freeNode(current);
    }

    pthread_mutex_unlock(&current->mutex);
    list->size--;
}

void processNodes(struct FlexibleList* list) {
    if (!list || !list->callback) return;

    Node *current = list->head;
    while (current != NULL) {
        NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T* data = &current->data;
        list->callback(data);
        current = current->next;
    }
}

void flexibleListAddCallback(struct FlexibleList* list, void (*callback)(NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T*)) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);
    list->callback = callback;
    pthread_mutex_unlock(&list->mutex);
}
```

