#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <stdio.h>
#include <string.h>

#define MAX_ELEMENTS 5000
#define MEMORY_LIMIT 20 * (1024 * 1024) // 20 MB
#define GUARD_SIZE 64 // Size of the guard page

typedef struct NFMMAP_TX_REPORT {
    int id;
    double value;
    // Other fields as needed
} NFMMAP_TX_REPORT;

typedef sem_t Semaphore;

struct collection {
    void *data;
    size_t capacity;
    size_t count;
    Semaphore mutex;
};

// Initialize a collection with given capacity and zero elements
void CollectionInit(struct collection *collection, size_t capacity) {
    collection->capacity = capacity;
    collection->count = 0;
    collection->data = mmap(NULL, (capacity + GUARD_SIZE) * sizeof(NFMMAP_TX_REPORT), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (collection->data == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    collection->mutex = sem_init(Semaphore_UNBOUNDED, 1, 1);
}

// Free a collection, including unmapping the shared memory and destroying the mutex
void CollectionFree(struct collection *collection) {
    munmap(collection->data, (collection->capacity + GUARD_SIZE) * sizeof(NFMMAP_TX_REPORT));
    sem_destroy(&collection->mutex);
}

// Add an element to the collection, returning false if the operation fails due to memory constraints
bool CollectionPush(struct collection *collection, const NFMMAP_TX_REPORT *element) {
    size_t current_size = collection->capacity + GUARD_SIZE;
    size_t remaining_space = current_size - (collection->count + GUARD_SIZE);

    if (remaining_space < sizeof(NFMMAP_TX_REPORT)) {
        fprintf(stderr, "Out of memory\n");
        return false;
    }

    sem_wait(&collection->mutex);

    memcpy((char *)collection->data + collection->count * sizeof(NFMMAP_TX_REPORT), element, sizeof(NFMMAP_TX_REPORT));
    collection->count++;

    sem_post(&collection->mutex);

    return true;
}

// Implement other necessary functions for the collection (e.g., pop, iterate)
```

