void check_rnti_unique(NFAPI_CRC_INDICATION_PDU_T* pdu_list, size_t len) {
    for (size_t i = 1; i < len; ++i) {
        if (pdu_list[i].rnti == pdu_list[i - 1].rnti) {
            printf("Error: RNTI duplication detected\n");
            exit(1);
        }
    }
}

size_t get_unique_rnti(NFAPI_CRC_INDICATION_PDU_T* pdu_list, size_t len) {
    static unsigned long long last_rnti = 0;

    while (true) {
        last_rnti++;
        for (size_t i = 0; i < len; ++i) {
            if (last_rnti == pdu_list[i].rnti) {
                break;
            }
            if (i == len - 1) { // not found in the list
                return last_rnti;
            }
        }
    }
}

void generate_pdus(NFAPI_CRC_INDICATION_PDU_T** pdu_list, size_t* num_pdus, size_t N) {
    *pdu_list = malloc(*num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*pdu_list == NULL) {
        printf("Error: Memory allocation failed\n");
        exit(1);
    }

    *num_pdus = N;

    size_t len = 0;
    for (size_t i = 0; i < N; ) {
        (*pdu_list)[i].rnti = get_unique_rnti(*pdu_list, len);
        ++len;
        i += sizeof(NFAPI_CRC_INDICATION_PDU_T) / sizeof((*pdu_list)[0]);
    }

    check_rnti_unique(*pdu_list, len);
}
