    unsigned char *data;
    size_t capacity;
    size_t length;
} KeyArray;

typedef struct RecordArray {
    Record *data;
    size_t capacity;
    size_t length;
} RecordArray;

typedef struct RecordsContainer {
    OffsetArray offsets;
    KeyArray keys;
    RecordArray records;
} RecordsContainer;

RecordsContainer* initializeRecordsContainer(size_t num_records, int min_key, int max_key) {
    RecordsContainer *container = (RecordsContainer*)malloc(sizeof(RecordsContainer));

    if (!container) {
        perror("Failed to allocate container");
        return NULL;
    }

    // Initialize offset array
    container->offsets.data = malloc(num_records * sizeof(size_t));
    if (!container->offsets.data) {
        free(container);
        perror("Failed to allocate offset array");
        return NULL;
    }
    container->offsets.capacity = num_records;
    container->offsets.length = 0;

    // Initialize key array
    container->keys.data = malloc(num_records * sizeof(unsigned char));
    if (!container->keys.data) {
        free(container->offsets.data);
        free(container);
        perror("Failed to allocate key array");
        return NULL;
    }
    container->keys.capacity = num_records;
    container->keys.length = 0;

    // Initialize record array
    container->records.data = malloc(num_records * sizeof(Record));
    if (!container->records.data) {
        free(container->keys.data);
        free(container->offsets.data);
        free(container);
        perror("Failed to allocate record array");
        return NULL;
    }
    container->records.capacity = num_records;
    container->records.length = 0;

    // Generate random keys and records
    for (size_t i = 0; i < num_records; ++i) {
        container->keys.data[container->keys.length] = rand() % (max_key - min_key + 1) + min_key;
        container->records.data[container->records.length].value = rand() % MAXINT;
        container->offsets.data[container->offsets.length] = i;
        ++container->keys.length;
        ++container->records.length;
        ++container->offsets.length;
    }

    return container;
}

// Implement custom encryption functions here using OpenSSL's EVP library

void deinitializeRecordsContainer(RecordsContainer *container) {
    if (container) {
        free(container->records.data);
        free(container->keys.data);
        free(container->offsets.data);
        free(container);
    }
}
