void garbage_collect(struct dynamic_array* array) {
    for (size_t i = 0; i < array->count; ++i) {
        if (!array->data[i].mac_address || !array->data[i].interface.valid) {
            memmove(&array->data[i], &array->data[i + 1], (array->count - i - 1) * sizeof(MEC));
            --array->count;
        }
    }
}

size_t allocate_mec(struct dynamic_array* array) {
    if (array->capacity == array->count) {
        array->capacity *= 2;
        array->data = realloc(array->data, array->capacity * sizeof(MEC));
    }

    MEC* mec = &array->data[array->count];
    mec->mac_address = get_next_mac_address(); // External function to allocate a unique MAC Address
    mec->interface = initialize_l1_interface(); // Initialize L1 Interface Information
    ++array->count;

    return array->count - 1;
}

size_t create_mec(struct dynamic_array* array) {
    size_t index = allocate_mec(array);
    if (validate_and_allocate_mac_address(index, mec->mac_address)) {
        return index;
    } else {
