// Path validation function
bool validate_path(const char *path) {
    struct stat st;
    return stat(path, &st) == 0 && S_ISDIR(st.st_mode);
}

// Logging function
void log_msg(const char *msg) {
    FILE *logfile = fopen("convert_log.txt", "a");
    if (logfile != NULL) {
        fprintf(logfile, "%s\n", msg);
        fclose(logfile);
    } else {
        warnx("%s", msg);
    }
}

// Convert JPEG to PDF and compress using imagemagick's tools
void convert_jpeg_to_pdf(const char *src, const char *dst) {
    char cmd[256];
    snprintf(cmd, sizeof(cmd), "convert %s %s.tmp.pdf", src, dst);
    log_msg(cmd);
    system(cmd);

    // Compress PDF using pdftk's tools
    snprintf(cmd, sizeof(cmd), "pdftk A=%s output %s.pdf compress maxdepth 3 deflate");
    log_msg(cmd);
    system(cmd);
}

// Function to create directory recursively if it doesn't exist
void mkdir_p(const char *path) {
    int len = strlen(path);
    int i;
    for (i = 0; i < len; ++i) {
        char dir[PATH_MAX];
        snprintf(dir, sizeof(dir), "%s/%d", path, i);
        if (validate_path(dir)) continue;
        mkdir(dir, 0755);
    }
}

// Main function to process JPEG file and convert it to a PDF
int process_jpeg(const char *src, const char *dst_dir, const char *dest) {
    bool dst_exists = validate_path(dst_dir);
    if (!dst_exists) {
        mkdir_p(dst_dir);
        dst_exists = true;
    }

    char dest_path[PATH_MAX];
    snprintf(dest_path, sizeof(dest_path), "%s/%s", dst_dir, dest);

    if (access(src, R_OK) != 0 || access(dest_path, W_OK | F_OK) != 0) {
        warnx("Source file or destination directory not accessible.");
        return 1;
    }

    // Concurrently convert and compress the JPEG to PDF
    pthread_t thread_id;
    int ret = pthread_create(&thread_id, NULL, (void*(*)(void*))convert_jpeg_to_pdf, src, dest_path);
    if (ret != 0) {
        warnx("Failed to create conversion thread.");
        return 1;
    }

    // Wait for the thread to finish execution
    pthread_join(thread_id, NULL);

    // Move compressed PDF without compression if the compressing thread fails
    if (access((dest_path + ".tmp.pdf"), W_OK) != 0) {
        log_msg("Error during PDF compression. Moving raw PDF.");
        rename(dest_path, dest_path + ".raw");
        rename((dest_path + ".tmp.pdf"), dest_path);
    }

    return 0;
}
```
