// Custom allocator for the vector to minimize allocation overhead
template <typename T>
class NFAPI_CRC_PDU_ALLOCATOR : public std::allocator<T> {
public:
    using value_type = typename std::allocator<T>::value_type;
    using pointer = typename std::allocator<T>::pointer;
    using const_pointer = typename std::allocator<T>::const_pointer;
    using reference = typename std::allocator<T>::reference;
    using const_reference = typename std::allocator<T>::const_reference;
    using size_type = std::size_t;
    using difference_type = std::ptrdiff_t;

    pointer allocate(size_type n, const void* hint = nullptr) {
        // Allocate contiguously in larger chunks for better memory usage
        return static_cast<pointer>(std::allocator<char>().allocate((n + alignment - 1) / alignment * alignment, hint));
    }

    void deallocate(pointer p, size_type n) noexcept {
        std::allocator<char>().deallocate(p, (n + alignment - 1) / alignment * alignment);
    }

private:
    static constexpr size_type alignment = sizeof(NFAPI_CRC_INDICATION_PDU_T);
};

// Define the dynamic array class with thread-safe operations
class DynamicArray {
public:
    std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T, decltype(NFAPI_CRC_PDU_ALLOCATOR<NFAPI_CRC_INDICATION_PDU_T>())> data;
    mutex mtx;

    DynamicArray() : data(10, std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>(new (std::nothrow) NFAPI_CRC_INDICATION_PDU_T)) {
        if (!data[0])
            throw std::bad_alloc();
    }

