        std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T[]> newData;
        if constexpr (std::is_same_v<decltype(data), std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T, decltype(NFAPI_CRC_PDU_ALLOCATOR<NFAPI_CRC_INDICATION_PDU_T>())>>) {
            newData.reset(new (std::nothrow) NFAPI_CRC_INDICATION_PDU_T[newSize]);
            if (!newData)
                throw std::bad_alloc();
        }

        // Copy existing elements to the new array, resizing the old one accordingly
        {
            std::lock_guard<mutex> lock(mtx);
            if (size() > 0)
                std::copy(begin(), end(), newData.get());
        }

        if constexpr (std::is_same_v<decltype(data), std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T, decltype(NFAPI_CRC_PDU_ALLOCATOR<NFAPI_CRC_INDICATION_PDU_T>())>>) {
            data.swap(newData);
        } else {
            for (auto& e : newData) {
                if (!e)
                    e.reset();
            }
            data.resize(newSize, std::move(newData));
        }
    }

    void addElement() {
