        printf("[%ld] %s\n", time(NULL) - start, message);
        pthread_mutex_unlock(&log_mutex);
    }
}

void *generate_random_crcflag() {
    return rand() & ((1 << 7) - 1);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(RX_UE_INFORMATION_TAG *ue_information_tag, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu) {
        log("Failed to allocate memory for PDU");
        return NULL;
    }

    pdu->rx_ue_information_tag = *ue_information_tag;
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag.crcflag = generate_random_crcflag();

    return pdu;
}

int verify_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if ((pdus[i].crc_indication_rel8_tag.crcflag & pdus[i].rx_ue_information_tag.checksum) != pdus[i].crc_indication_rel8_tag.crcflag) {
            log("PDU checksum failed verification");
            return -1;
        }
    }

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdus(size_t N, RX_UE_INFORMATION_TAG *ue_information_tag, RNTI rnti, size_t *out_count) {
    start = time(NULL);

    if (!ue_information_tag || !rnti) {
        log("Invalid input parameters");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;

    pdus = calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdus) {
        log("Failed to allocate memory for PDUs");
        return NULL;
    }

    *out_count = N;

    for (size_t i = 0; i < N; ++i) {
        pdus[i].rx_ue_information_tag = *ue_information_tag++;
        pdus[i].rnti = rnti;
    }

    elapsed = time(NULL) - start;

    if (verify_pdus(pdus, N) < 0) {
        log("PDUs failed verification");
        free(pdus);
        return NULL;
    }

    log(("Allocated and verified %ld PDUs in %.6fs\n", *out_count, elapsed));

    return pdus;
}
