#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU;

typedef struct collection_node {
    NFAPI_CRC_INDICATION_PDU data;
    struct collection_node* next;
} node_t;

struct collection {
    int size;
    pthread_mutex_t lock;
    node_t* head;
    node_t* tail;
};

collection_t* create_collection() {
    collection_t* coll = (collection_t*)malloc(sizeof(collection_t));
    coll->size = 0;
    coll->head = NULL;
    coll->tail = NULL;
    pthread_mutex_init(&coll->lock, NULL);
    return coll;
}

void destroy_collection(collection_t* coll) {
    node_t* curr = coll->head;
    while (curr != NULL) {
        node_t* next = curr->next;
        free(curr);
        curr = next;
    }
    pthread_mutex_destroy(&coll->lock);
    free(coll);
}

void insert(collection_t* coll, NFAPI_CRC_INDICATION_PDU data) {
    node_t* new_node = (node_t*)malloc(sizeof(node_t));
    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_lock(&coll->lock);
    if (coll->head == NULL) {
        coll->head = new_node;
    } else {
        coll->tail->next = new_node;
    }
    coll->tail = new_node;
    coll->size++;
    pthread_mutex_unlock(&coll->lock);
}

NFAPI_CRC_INDICATION_PDU* retrieve(collection_t* coll, uint32_t index) {
    pthread_mutex_lock(&coll->lock);
    node_t* curr = coll->head;
    for (int i = 0; i < index; i++) {
        if (curr == NULL) {
            break;
        }
        curr = curr->next;
    }
    if (curr != NULL) {
        NFAPI_CRC_INDICATION_PDU* res = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
        *res = curr->data;
        pthread_mutex_unlock(&coll->lock);
        return res;
    }
    pthread_mutex_unlock(&coll->lock);
    return NULL;
}

void delete(collection_t* coll, uint32_t index) {
    pthread_mutex_lock(&coll->lock);
    node_t* curr = coll->head;
    for (int i = 0; i < index; i++) {
        if (curr == NULL) {
            break;
        }
        if (curr->next == NULL) {
            break;
        }
        curr = curr->next;
    }
    if (curr != NULL && curr->next != NULL) {
        node_t* temp = curr->next;
        curr->next = temp->next;
        free(temp);
        coll->size--;
        pthread_mutex_unlock(&coll->lock);
    } else {
        pthread_mutex_unlock(&coll->lock);
    }
}
