LTE_PACKET* create_packet(const LTEMMEA_USER_INFO* userInfo, int PCI) {
    LTE_PACKET* new_packet = (LTE_PACKET*)malloc(sizeof(LTE_PACKET));
    if (!new_packet) return NULL;
    new_packet->userInfo = *userInfo;
    new_packet->PCI = PCI;
