LTE_PACKET* create_list(size_t initialCapacity) {
    LTE_PACKET *head = NULL, *current = NULL;
    if (initialCapacity == 0) return NULL;

    head = (LTE_PACKET*)malloc(sizeof(LTE_PACKET));
    if (!head) return NULL;

    current = head;
    for (size_t i = 1; i < initialCapacity; ++i) {
        current->next = (LTE_PACKET*)malloc(sizeof(LTE_PACKET));
        if (!current->next) {
            free_list(head);
            return NULL;
        }
        current = current->next;
        current->next = NULL;
    }

    return head;
}

void append_packet(LTE_PACKET** head, LTE_PACKET* new_packet) {
    if (!head || !new_packet) return;
    LTE_PACKET *current = *head;
    if (!current) {
        *head = new_packet;
        return;
    }

    while (current->next) current = current->next;
    current->next = new_packet;
}

size_t count_unique_PCIs(const LTE_PACKET* head) {
    LTE_PACKET* current = const_cast<LTE_PACKET*>(head);
    size_t unique_PCIs = 0;
    std::unordered_set<int> PCISet;

    while (current) {
        if (PCISet.find(current->PCI) == PCISet.end()) {
            PCISet.insert(current->PCI);
            ++unique_PCIs;
        }
        current = current->next;
    }

    return unique_PCIs;
}

bool is_valid_crc(const LTE_PACKET* packet) {
    // You might want to implement a CRC validation function here.
    return true;
}

void free_list(LTE_PACKET* head) {
    LTE_PACKET *current = head, *next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
}
