typedef struct {
    uint16_t channel_id;
    int measurement_value;
    struct TimeSlotInfo ts_info;
} LTE_PHY_MEASUREMENT;

typedef struct {
    uint32_t time_slot;
    int signal_strength;
} CHANNEL_MEASUREMENT;

typedef struct {
    uint16_t slot_number;
    uint16_t frame_number;
} TIME_SLOT_INFO;

#define MAX_STRUCTURES 1000000
#define MEASUREMENT_WINDOW 100
#define MB_LIMIT 1024 * 1024

LTE_PHY_MEASUREMENT* create_measurement_array(size_t size) {
    LTE_PHY_MEASUREMENT *arr = malloc(sizeof(LTE_PHY_MEASUREMENT) * size);

    if (!arr) {
        perror("Memory allocation failed");
        return NULL;
    }

    memset(arr, 0, sizeof(LTE_PHY_MEASUREMENT) * size);

    return arr;
}

int moving_average(int *data, int window_size, int *result) {
    int sum = 0;
    int i;

    if (window_size <= 0 || result == NULL) {
        fprintf(stderr, "Invalid input\n");
        return -1;
    }

    for (i = 0; i < window_size; ++i) {
        sum += data[i];
    }

    *result = sum / window_size;

    for (i = window_size; i < sizeof(data); ++i) {
        sum -= data[i - window_size];
        sum += data[i];
        *result = sum / window_size;
    }

    return 0;
}

int allocate_measurement_array_and_update(LTE_PHY_MEASUREMENT **arr, size_t *len, LTE_PHY_MEASUREMENT new_meas) {
    size_t index = 0;

    for (index = 0; index < *len && arr[index]->channel_id != new_meas.channel_id; ++index);

    if (index == *len) { // New measurement is unique
        LTE_PHY_MEASUREMENT **temp_arr = create_measurement_array(*len + 1);

        if (!temp_arr) {
            perror("Memory allocation failed");
            return -1;
        }

        memcpy(temp_arr, *arr, sizeof(LTE_PHY_MEASUREMENT) * *len);
        temp_arr[*len] = malloc(sizeof(LTE_PHY_MEASUREMENT));

        if (!temp_arr[*len]) {
            perror("Memory allocation failed");
            free(temp_arr);
            return -1;
        }

        *arr = temp_arr;
        (*len)++;
    } else { // Measurement is not unique
        free(*arr + index);
        memmove(&((*arr)[index + 1]), &((*arr)[index + 1]), sizeof(LTE_PHY_MEASUREMENT) * (*len - index - 1));
        (*arr)[index] = new_meas;
    }

    moving_average(arr[new_meas.channel_id]->measurement, MEASUREMENT_WINDOW, &(arr[new_meas.channel_id]->measurement));

    return 0;
}
```

