#include "DAO.h" // DAO class for password update

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct list_node {
    NFAPI_CRUC_INDICATION_PDU_T data;
    struct list_node *next;
};

static struct list_node* head = NULL;
static sem_t lock = SEM_FAIR; // Use a fair lock for thread-fairness
static pthread_key_t key = PTHREAD_KEY_NULL; // Hot-swappable dependencies

int add_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu || (pdu->crc_indication.crcflag < 0 || pdu->crc_indication.crcflag > 255) || is_rnti_duplicate(pdu->rnti)) return -1; // Validation

    struct list_node* node = mmap(NULL, sizeof(struct list_node), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!node) return -2; // Memory allocation failure

    sem_wait(&lock);
    node->data = *pdu;
    node->next = head;
    head = node;
    sem_post(&lock);

    pthread_key_t key_local = key;
    void* dep_ptr = pthread_getspecific(key_local); // Get hot-swappable dependency

    if (dep_ptr) { // If a dependency is loaded, use it for database update
        DAO* dao = dep_ptr;
        if (!update_user_password(dao, pdu->rnti, generate_secure_password())) return -3; // Password update failure
    }

    munmap(node, sizeof(struct list_node));
    return 0;
}

static bool is_rnti_duplicate(uint16_t rnti) {
    sem_wait(&lock);
    struct list_node* node = head;
    bool result = false;
    while (node) {
        if (node->data.rnti == rnti) {
            result = true;
            break;
        }
        node = node->next;
    }
    sem_post(&lock);
    return result;
}
