static size_t total_memory = 0;

void initialize_transport_channels(size_t num_channels) {
    if (num_channels == 0) {
        fprintf(stderr, "Invalid number of channels: %zu\n", num_channels);
        return;
    }

    pthread_mutex_lock(&channel_mutex);

    // Calculate required memory size
    size_t channel_size = sizeof(LTE_PHY_TransportChannelInfo);
    total_memory += channel_size * num_channels;

    if (num_allocated_channels + num_channels > num_channels) {
        LTE_PHY_TransportChannelInfo *temp_channels = realloc(transport_channels, total_memory);
        if (!temp_channels) {
            fprintf(stderr, "Out of memory\n");
            pthread_mutex_unlock(&channel_mutex);
            return;
        }
        transport_channels = temp_channels;
    }

    num_allocated_channels += num_channels;
    pthread_mutex_unlock(&channel_mutex);

    // Initialize and calculate SRSResourceSetId for each channel
    for (size_t i = num_allocated_channels - num_channels; i < num_allocated_channels; ++i) {
        transport_channels[i].UEIndex = i % 10 + 1; // Valid UE indices: 1-10
        transport_channels[i].TransportChannelID = i / 10 + 1; // Valid TransportChannelIDs: 1-10
        transport_channels[i].TransmissionMode = rand() % 2; // TransmissionModes: 0 or 1
