    struct crc_indication_rel8_tag crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

sem_t sem_mutex; // Mutex to protect shared memory access
pthread_t threads[THREAD_COUNT]; // Thread identifiers

NFAPI_CRC_INDICATION_PDU_T* create_pdus(size_t *num_pdus) {
    void *buffer = mmap(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T)*MAX_PODUS, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    *num_pdus = MAX_PODUS;
    NFAPI_CRC_INDICATION_PDU_T* pdus = buffer;

    sem_init(&sem_mutex, 0, 1); // Initialize mutex

    for (size_t i = 0; i < THREAD_COUNT; ++i) {
        pthread_create(&threads[i], NULL, worker_thread, pdus);
    }

    // Wait for all threads to finish executing
    for (size_t i = 0; i < THREAD_COUNT; ++i) {
        pthread_join(threads[i], NULL);
    }

    munmap(buffer, sizeof(NFAPI_CRC_INDICATION_PDU_T)*MAX_PODUS); // Unmap shared memory
    sem_destroy(&sem_mutex); // Destroy mutex

    return pdus;
}

void* worker_thread(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = arg;
    struct timespec start, end;

    clock_gettime(CLOCK_MONOTONIC, &start);

    for (size_t i = 0; i < *((size_t*)arg); ++i) {
        sem_wait(&sem_mutex); // Lock mutex to protect shared memory access

        pdus[i].rx_ue_info.tag = rand() % 256;
        pdus[i].rx_ue_info.rnti.value = rand() % 65536;
        pdus[i].crc_indication.tag = RNTI_TAG + (rand() % 256);
        pdus[i].crc_indication.crcflag = rand() % 2;

        sem_post(&sem_mutex); // Unlock mutex
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    printf("Thread finished executing in %.6f seconds\n", (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1_000_000_000);

    return NULL;
}
