#include <iostream>
#include <fstream>
#include <vector>
#include <boost/asio.hpp>
#include <boost/filesystem.hpp>
#include <mutex>

struct entry {
    long timestamp;
    float value;
};

class DataManager {
private:
    std::vector<entry> data;
    std::mutex mtx;
    boost::asio::io_service io_service;

public:
    void readFromFile(const std::string& filePath) {
        boost::asio::streambuf buffer;
        boost::asio::ip::tcp::socket socket(io_service);
        boost::asio::connect(socket, boost::asio::ip::tcp::endpoint(boost::asio::ip::tcp::v4(), 0));
        boost::asio::async_read_until(socket, buffer, "\n",
            [this, &buffer](boost::system::error_code ec, std::size_t /*length*/) {
                if (!ec) {
                    std::istream is(&buffer);
                    entry e;
                    is >> e.timestamp >> e.value;
                    std::lock_guard<std::mutex> lock(mtx);
                    data.push_back(e);
                }
                if (!ec || ec == boost::system::errc::eof) {
                    socket.close();
                }
            });
        io_service.run();
    }

    void appendEntry(const entry& e) {
        std::lock_guard<std::mutex> lock(mtx);
        data.push_back(e);
    }

    // Additional methods for iterating through the data, deleting entries, etc.
};
```

