        streams[i].buffer_size = 1024; // Default buffer size, adjust as needed
        streams[i].timestamp = time(NULL);
        streams[i].buffer = malloc(streams[i].buffer_size);
        if (!streams[i].buffer) {
            fprintf(stderr, "Failed to allocate memory for stream %d buffer\n", streams[i].id);
            free(streams);
            return NULL;
        }

        pthread_mutex_init(&streams[i].lock, NULL);
    }

    return streams;
}

void destroy_streams(L2_CONTEXT* streams, int n) {
    for (int i = 0; i < n; ++i) {
        free(streams[i].buffer);
        pthread_mutex_destroy(&streams[i].lock);
    }

    free(streams);
}
