// NFAPI_CRC_INDICATION_PDU_T structure definition
struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxTag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
    bool crcFlag;
    std::chrono::system_clock::time_point timestamp;
};

class DynamicList {
private:
    std::list<NFAPI_CRC_INDICATION_PDU_T> data; // Use a list for efficient insertion and removal
    std::unordered_map<uint32_t, std::list<NFAPI_CRC_INDICATION_PDU_T>::iterator> rntiMap; // Map RNTI to iterators for fast lookup
    std::mutex mtx; // For thread safety
    std::chrono::system_clock::time_point clearThreshold; // The timestamp before which entries are cleared

public:
    DynamicList(std::chrono::system_clock::time_point clearThreshold) : clearThreshold(clearThreshold) {}

    void add(const NFAPI_CRC_INDICATION_PDU_T& dataItem) {
        std::unique_lock<std::mutex> lock(mtx);
        data.push_back(dataItem);
        rntiMap[dataItem.rnti] = data.end(); // Update the RNTI map with the new iterator
    }

    bool remove(uint32_t rnti) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = rntiMap.find(rnti);
        if (it == rntiMap.end()) return false; // RNTI not found

        it->second = data.erase(it->second);
        rntiMap.erase(rnti);
        return true;
    }

    bool update(uint32_t rnti, const NFAPI_CRC_INDICATION_PDU_T& newData) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = rntiMap.find(rnti);
        if (it == rntiMap.end()) return false; // RNTI not found

        newData.timestamp = std::chrono::system_clock::now();
        *it->second = newData;
        return true;
    }

    void clearOldEntries() {
        std::unique_lock<std::mutex> lock(mtx);
        auto now = std::chrono::system_clock::now();
        for (auto it = data.begin(); it != data.end();) {
            if (it->timestamp < clearThreshold) {
                it = data.erase(it);
            } else {
                ++it;
            }
        }
    }
};
```

