        ~Nfademo() {}

        static void init(int seed) {
            std::srand(seed);
            records.reserve(initialRecordsAlloc);
            pduList.clear();
            intSet.clear();
            mtx.lock();
            // Initialize record vector with initial allocation
            for (size_t i = 0; i < initialRecordsAlloc; ++i) {
