            if (num <= 0 || num > 1000000) {
                throw std::invalid_argument("Invalid input value.");
            }
            for (auto it = intSet.begin(); it != intSet.end(); ++it) {
                if (it->second && it->first == num) {
                    throw std::runtime_error("Duplicate integer detected.");
                }
            }
            intSet[num] = true;
        }

        static void createRecords(int count, int num) {
            validateInput(num);
            for (size_t i = 0; i < count; ++i) {
                size_t idx;
                allocateRecord(idx);
                records[idx].value = num;
                // Populate buffer with random characters
                std::generate_n(records[idx].buffer.begin(), records[idx].buffer.size(),
                    []() -> char { return 'a' + rand() % 26; });
                records[idx].checksum = boost::crc32_type().process_bytes(records[idx].buffer.data(), records[idx].buffer.size());
            }
        }

        static void printLargestInt() {
            int maxValue = std::numeric_limits<int>::min();
            for (const auto& record : records) {
                if (record.value > maxValue) {
                    maxValue = record.value;
                }
            }
            std::cout << "Largest integer: " << maxValue << std::endl;
        }
