#include <thread>
#include <mutex>
#include <condition_variable>
#include <stdexcept>

// Custom structures for LTE_PHY_RX_FRAME, RF_CHANNEL_CONFIG_T, and UE_INFO_T.
struct LTE_PHY_RX_FRAME {
    L1PHY_RX_FRAME_T frame;
    RF_CHANNEL_CONFIG_T config;
    UE_INFO_T info;
};

// Signal quality metrics structure.
struct SQM {
    std::atomic<int> rssi, snr, bber;
};

// Frame buffer and metadata class, thread-safe.
class FrameBuffer {
public:
    explicit FrameBuffer(size_t capacity) : buffer_(capacity), next_(0), current_(0), sqm_(), q_(), lock_() {}

    void enqueue(const LTE_PHY_RX_FRAME& frame) {
        std::lock_guard<std::mutex> lock(lock_);
        buffer_[next_] = frame;
        next_ = (next_ + 1) % capacity;
        q_.push_back(true);
    }

    LTE_PHY_RX_FRAME dequeue() {
        std::unique_lock<std::mutex> lock(lock_);
        condition_variable cv;
        while (current_ == next_) {
            cv.wait(lock, [this] { return !q_.empty(); });
        }

        auto frame = buffer_[current_];
        current_ = (current_ + 1) % capacity;
        q_.pop_front();
        lock.unlock();
        return frame;
    }

    void setSQM(const SQM& sqm) { sqm_ = sqm; }
    const SQM& getSQM() const { return sqm_; }

private:
    std::vector<LTE_PHY_RX_FRAME> buffer_;
    size_t next_, current_;
    std::atomic<SQM> sqm_;
    std::queue<bool> q_;
    mutex lock_;
};

// External data processing service callback function.
void processNetworkData(const FrameBuffer& buffer, std::function<void(const SQM&)> on_network_update);

// The main frame manager class with a worker thread.
class FrameManager {
public:
    explicit FrameManager(FrameBuffer& fb, size_t num_threads) : frame_buffer_(fb), threads_(num_threads), done_(false) {}

    void start() {
        for (size_t i = 0; i < threads_.size(); ++i) {
            threads_[i] = std::thread(&FrameManager::processFrames, this);
        }
    }

    void stop() { done_ = true; }

private:
    void processFrames() {
        for (;;) {
            LTE_PHY_RX_FRAME frame = frame_buffer_.dequeue();

            // Process the frame and update SQM here.

            if (done_) break;
        }
    }

    FrameBuffer& frame_buffer_;
    std::vector<std::thread> threads_;
    bool done_;
};
```

