int createAndPopulateList(NFAPI_CRC_INDICATION_PDU_T** list, size_t size, int* seeds, CustomData* data) {
    if (!data || !data->str || data->str[0] == '\0' || !data->connection || !data->processAndSendCRC) {
        return -1; // Invalid input
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    *list = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list) {
        perror("Memory allocation failed");
        return -2; // Memory allocation failure
    }

    int maxSeed = *std::max_element(seeds, seeds + size);
    srand(maxSeed);

    pthread_t workerThreads[size];
    for (size_t i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* currElem = &(*list)[i];
        currElem->RX_UE_INFORMATION_TAG = /* Your implementation for RX_UE_INFORMATION_TAG */;
