        currElem->CRC_INDICATION_REL8_TAG = rand() % 2; // Set CRC_INDICATION_REL8_TAG to either 0 or 1

        pthread_create(&workerThreads[i], NULL, [currElem, data]() {
            data->processAndSendCRC(currElem);
            return NULL;
        }, NULL);
    }

    for (size_t i = 0; i < size; ++i) {
        pthread_join(workerThreads[i], NULL);
    }

    pthread_mutex_destroy(&mutex);
    return 0; // Success
