#include <stdbool.h>
#include <stdint.h>
#include <pthread.h>
#include <stdlib.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint16_t rnti;
    PHY_layer_status_t status;
} NFAPI_RRC_MSG_T;

// Thread-safe linked list structure for the dynamic array
typedef struct Node {
    NFAPI_RRC_MSG_T data;
    struct Node* next;
    pthread_mutex_t lock;
} Node;

// Global variables to maintain the head and tail of the list
Node* head = NULL;
Node* tail = NULL;
pthread_mutex_t listLock;

void init_list() {
    pthread_mutex_init(&listLock, NULL);
}

void add(NFAPI_RRC_MSG_T data) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if (!newNode) return; // Out of memory error handling

    newNode->data = data;
    newNode->next = NULL;
    pthread_mutex_init(&newNode->lock, NULL);

    pthread_mutex_lock(&listLock);

    if (head == NULL) {
        head = newNode;
        tail = newNode;
    } else {
        tail->next = newNode;
        tail = newNode;
    }

    pthread_mutex_unlock(&listLock);
}

bool update(RX_UE_INFORMATION_TAG tag, NFAPI_RRC_MSG_T newData) {
    Node* current = head;
    bool found = false;

    while (current != NULL && !found) {
        pthread_mutex_lock(&current->lock);

        if (current->data.tag == tag) {
            current->data = newData;
            found = true;
        }

        current = current->next;
        pthread_mutex_unlock(&current->lock);
    }

    return found;
}

void iterate(void (*callback)(NFAPI_RRC_MSG_T)) {
    Node* current = head;

    if (current == NULL) return; // Empty list error handling

    pthread_mutex_lock(&listLock);

    while (current != NULL) {
        Node* nextNode = current->next;
        callback(current->data);
        current = nextNode;
    }

    pthread_mutex_unlock(&listLock);
}
```
In this implementation, the dynamic array is managed using a thread-safe linked list. Each node in the list contains an instance of `NFAPI_RRC_MSG_T`, a pointer to the next node, and a mutex for safe access in multi-threaded environments. The `init_list()` function initializes the global mutex.

The `add()` function adds new nodes to the list while handling potential memory allocation failures gracefully. It is optimized for minimal memory usage as it only allocates space for a single node at a time, and the entire structure (including the mutex) resides on the stack.

The `update()` function searches the list for an entry with a specific tag and updates it if found. It uses a while loop to traverse the list safely, locking and unlocking nodes as needed. This approach ensures thread safety when called concurrently by multiple threads.

The `iterate()` function provides an intuitive interface for iterating over the array while efficiently traversing the linked list in a single pass. It allows for custom callbacks to process each element, which can be useful for various purposes such as data analysis or debugging.']

