// Define the structure for NFData_PDU_T
struct NFData_PDU_T {
    RXUEINFO_TAG rxueInfoTag;
    LOGICAL_CHANNEL_ID logChanId;
    std::deque<float> avgSignalStrengths; // last 10 transmissions
};

// Define the dynamic array manager class with thread-safe operations
class DynamicArrayManager {
public:
    DynamicArrayManager(size_t bufferSize, std::function<void(const NFData_PDU_T&)> logFunc)
        : _bufferSize(bufferSize), _logFunc(std::move(logFunc)) {}

    // Thread-safe function to add a new NFData_PDU_T structure
    void push_back(NFData_PDU_T&& data) {
        std::unique_lock<std::mutex> lock(_dataMutex);
        _data.push_back(std::move(data));
        if (_data.size() > _bufferSize) {
            _data.pop_front();
        }
    }

    // Periodically flush outdated data (this function is implemented as a separate thread)
    void startFlushing() {
        std::thread([this]() {
            while (true) {
                std::this_thread::sleep_for(std::chrono::seconds(10)); // Adjust the interval based on your needs
                flush();
            }
        }).detach();
    }

private:
    void flush() {
        std::unique_lock<std::mutex> lock(_dataMutex);
        auto it = _data.cbegin();
        for (; it != _data.cend() && it->avgSignalStrengths.size() < 10; ++it) {}

        // Flush the data before 'it' iterator
        if (it != _data.cbegin()) {
            for (auto begin = _data.cbegin(); begin != it; ) {
                auto end = std::next(begin);
                if (end == _data.cend()) break;

                auto dataToMove = std::move(*begin);
                // Pass the data to the external logging service if necessary
                if (_logFunc) _logFunc(std::move(dataToMove));

                begin = _data.erase(begin);
            }
        }
    }

    size_t _bufferSize;
    std::function<void(const NFData_PDU_T&)> _logFunc;
    std::vector<NFData_PDU_T> _data; // Dynamic array of NFData_PDU_T structures
    std::mutex _dataMutex;
};
