void insertAfterForwardList(std::forward_list<std::string>& users, const std::string& newUsername, IMemoryPool* memPool, IUserAPI* api) {
    auto it = users.begin();
    auto end = users.end();

    // Find the first occurrence of an existing username in the list
    if (it != end && *it == newUsername) {
        ++it;
        std::unique_ptr<std::string> newUserPtr(memPool->alloc());
        *newUserPtr = newUsername;
        users.insert(it, std::move(newUserPtr));
    }

    // If the specified username is not present, append the new username to the end of the list
    else {
        if (newUsername.empty())
            throw std::invalid_argument("New username cannot be empty");

        std::unique_ptr<std::string> newUserPtr(memPool->alloc());
        *newUserPtr = newUsername;
        users.push_back(std::move(newUserPtr));
    }

