#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>

#define THREAD_SAFE_BUFFER_SIZE (1000)
#define NUM_THREADED_BUFFERS 10

typedef struct {
    RXUEINFO_TAG rxueinfo;
    LOGICAL_CHANNEL_ID lcid;
    float avg_signal_strength;
    float max_signal_strength;
} NFData_PDU_T;

struct threaded_buffer {
    NFData_PDU_T *data;
    size_t capacity;
    size_t read_index;
    size_t write_index;
};

// Helper function to find maximum signal strength in an array
float max_signal_strength(const NFData_PDU_T *arr, size_t len) {
    float max = arr[0].max_signal_strength;
    for (size_t i = 1; i < len; ++i) {
        if (arr[i].max_signal_strength > max)
            max = arr[i].max_signal_strength;
    }
    return max;
}

// Helper function to calculate average signal strength in an array
float average_signal_strength(const NFData_PDU_T *arr, size_t len) {
    float sum = 0.0f;
    for (size_t i = 0; i < len; ++i) {
        sum += arr[i].avg_signal_strength;
    }
    return sum / len;
}

void init_threaded_buffer(struct threaded_buffer *tb) {
    tb->data = mmap(NULL, sizeof(NFData_PDU_T) * THREAD_SAFE_BUFFER_SIZE, PROT_WRITE | PROT_READ, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (tb->data == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    tb->capacity = THREAD_SAFE_BUFFER_SIZE;
    tb->read_index = tb->write_index = 0;
}

void enqueue(struct threaded_buffer *tb, const NFData_PDU_T *data) {
    pthread_mutex_lock(&tb->mutex);
    while ((tb->write_index - tb->read_index) == tb->capacity) {
        pthread_cond_wait(&tb->not_full, &tb->mutex);
    }

    memcpy(tb->data + tb->write_index, data, sizeof(NFData_PDU_T));
    tb->write_index = (tb->write_index + 1) % tb->capacity;
    pthread_cond_signal(&tb->not_empty);
    pthread_mutex_unlock(&tb->mutex);
}

void dequeue(struct threaded_buffer *tb, NFData_PDU_T *data) {
    pthread_mutex_lock(&tb->mutex);
    while (tb->read_index == tb->write_index) {
        pthread_cond_wait(&tb->not_empty, &tb->mutex);
    }

    memcpy(data, tb->data + tb->read_index, sizeof(NFData_PDU_T));
    tb->read_index = (tb->read_index + 1) % tb->capacity;
    pthread_cond_signal(&tb->not_full);
    pthread_mutex_unlock(&tb->mutex);
}

void flush(struct threaded_buffer *tb, float signal_strength_threshold) {
    size_t num_to_free = 0;
    for (size_t i = tb->read_index; i != tb->write_index; ) {
        if (tb->data[i].avg_signal_strength < signal_strength_threshold) {
            memmove(tb->data + i, tb->data + (i + 1), (tb->capacity - 1 - i) * sizeof(NFData_PDU_T));
            ++num_to_free;
        } else {
            i = (i + 1) % tb->capacity;
        }
    }
    tb->read_index = (tb->read_index + num_to_free) % tb->capacity;
}
