typedef struct ManagedArray {
    NFData_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    time_t flushInterval;
    time_t lastFlush;
    bool isFlushing;
} ManagedArray;

ManagedArray* manageDynamicArray_init(size_t initialCapacity) {
    ManagedArray* array = malloc(sizeof(ManagedArray));
    if (!array) return NULL;

    array->data = malloc(initialCapacity * sizeof(NFData_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initialCapacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    array->flushInterval = 60; // seconds
    array->lastFlush = 0;
    array->isFlushing = false;

    return array;
