        pthread_mutex_destroy(&managedArray->mutex);
        free(managedArray);
    }
}

void manageDynamicArray_push(ManagedArray* managedArray, const NFData_PDU_T* data) {
    if (managedArray->size == managedArray->capacity) {
        managedArray->data = realloc(managedArray->data, (managedArray->capacity + 10) * sizeof(NFData_PDU_T));
        if (!managedArray->data) return;
        managedArray->capacity += 10;
    }

    pthread_mutex_lock(&managedArray->mutex);
    memcpy(&managedArray->data[managedArray->size], data, sizeof(NFData_PDU_T));
    managedArray->size++;
    pthread_mutex_unlock(&managedArray->mutex);
}

void manageDynamicArray_flush(ManagedArray* managedArray) {
    if (managedArray->isFlushing) return;

    pthread_mutex_lock(&managedArray->mutex);
    managedArray->isFlushing = true;

    size_t toRemove = managedArray->size - (time(NULL) - managedArray->lastFlush) / managedArray->flushInterval * managedArray->size / managedArray->flushInterval;

    if (toRemove > 0 && managedArray->size > toRemove) {
        memcpy(managedArray->data, &managedArray->data[toRemove], (managedArray->size - toRemove) * sizeof(NFData_PDU_T));
        managedArray->size -= toRemove;
    }

    managedArray->lastFlush = time(NULL);
    managedArray->isFlushing = false;
    pthread_mutex_unlock(&managedArray->mutex);
}

