typedef struct NetworkEntityState {
    int DeviceID;
    time_t Timestamp;
    float LinkQuality;
} NetworkEntityState;

NetworkEntityState* createNetworkEntities(int numDevices, float temp, float interference) {
    NetworkEntityState *networkEntities = malloc(numDevices * sizeof(NetworkEntityState));

    if (!networkEntities) {
        fprintf(stderr, "Memory allocation failure\n");
        return NULL;
    }

    int currentDeviceID = 0;
    time_t currentTimestamp = time(NULL);

    for (int i = 0; i < numDevices; ++i) {
        networkEntities[i].DeviceID = currentDeviceID++;
        networkEntities[i].Timestamp = currentTimestamp + i * i; // Increase timestamp based on device index to simulate chronological order
        networkEntities[i].LinkQuality = (temp + interference * 0.5) * (1 - i / 100.0); // Simplified model for link quality calculation
    }

    qsort(networkEntities, numDevices, sizeof(NetworkEntityState), compareDeviceIDs);

    if (hasDuplicateDeviceIDs(numDevices, networkEntities)) {
        fprintf(stderr, "Error: Duplicate DeviceIDs detected\n");
        free(networkEntities);
        return NULL;
    }

    return networkEntities;
}

int compareDeviceIDs(const void *a, const void *b) {
    return (*(NetworkEntityState*)a).DeviceID - (*(NetworkEntityState*)b).DeviceID;
}

bool hasDuplicateDeviceIDs(int numDevices, NetworkEntityState* networkEntities) {
    bool deviceIDSet[MAX_DEVICE_ID + 1] = {false}; // Assuming max device ID is defined as MAX_DEVICE_ID

    for (int i = 0; i < numDevices; ++i) {
        if (deviceIDSet[networkEntities[i].DeviceID]) {
            return true;
        }
        deviceIDSet[networkEntities[i].DeviceID] = true;
    }

    return false;
}
```
