    new_ue->id = ue_collection.size;
    ue_collection.size++;
    Node* new_node = malloc(sizeof(Node));
    new_node->data = *new_ue;
    new_node->next = ue_collection.head;
    ue_collection.head = new_node;
    pthread_mutex_unlock(&ue_collection.mutex);

    // Call external system API to configure the newly created UE
    external_system_api(new_ue);

    return NULL;
}

void init_ue_collection() {
    // Initialize mutex and empty list here

    pthread_t threads[10000]; // Adjust as needed for concurrency level

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        if (pthread_create(&threads[i], NULL, create_ue, NULL)) {
            printf("Error creating thread\n");
            exit(-1);
        }
