typedef struct {
    long* offset;
    int key;
} record;

unsigned long allocate_records(unsigned int num_offsets, unsigned int min_val, unsigned int max_val) {
    if (num_offsets <= 0) {
        return 0;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    long *offsets = malloc(num_offsets * sizeof(long));
    int *keys = malloc(num_offsets * sizeof(int));
    record *records = NULL;
    unsigned long records_size = 0;

    srand((unsigned int)time(NULL));

    for (unsigned int i = 0; i < num_offsets; ++i) {
        offsets[i] = 0;
        keys[i] = min_val + rand() % (max_val - min_val + 1);
    }

    pthread_mutex_t unique_keys_lock = PTHREAD_MUTEX_INITIALIZER;
    for (unsigned int i = 0; i < num_offsets; ++i) {
        int is_unique = 1;
        pthread_mutex_lock(&unique_keys_lock);
        for (unsigned j = 0; j < i; ++j) {
            if (keys[i] == keys[j]) {
                is_unique = 0;
                break;
            }
        }
        pthread_mutex_unlock(&unique_keys_lock);
        if (is_unique) {
            records = realloc(records, (records_size + 1) * sizeof(record));
            records[records_size].offset = &offsets[i];
            records[records_size++].key = keys[i];
        }
    }

    free(keys);

    return records_size * sizeof(record);
}
