    long offset;
    int key;
    double value;
} Record;

// Function prototype for creating and initializing record array
Record* create_record_array(int n, long *offsets, int *keys);

// Global mutex for thread synchronization
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to create and initialize record array
Record* create_record_array(int n, long *offsets, int *keys) {
    Record *records;
    if (n <= 0 || n > MAX_ELEMENTS) {
        fprintf(stderr, "Invalid number of elements: must be between 1 and %d\n", MAX_ELEMENTS);
        return NULL;
    }

    records = malloc(n * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < n; ++i) {
        // Validate input pointers before dereferencing
        if (!offsets || !keys) {
            fprintf(stderr, "Input arrays are not correctly initialized\n");
            free(records);
            records = NULL;
            pthread_mutex_unlock(&mutex);
            break;
        }

        // Check for buffer overflow and validate key within range
        if (offsets[i] >= RINT32_MAX || keys[i] > INT_MAX || keys[i] < INT_MIN) {
            fprintf(stderr, "Buffer overflow or invalid value detected: offset=%ld, key=%d\n", offsets[i], keys[i]);
            free(records);
            records = NULL;
            pthread_mutex_unlock(&mutex);
            break;
        }

        // Initialize record fields and generate random value within specified range
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].value = (double)(rand() % 10000) / 100.0;
    }
    pthread_mutex_unlock(&mutex);

    return records;
}
