    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    new_node->data_double = data_double;
    new_node->unique_id = getUniqueId();
    new_node->data_char = strdup(data_char);
    if (!new_node->data_char) {
        fprintf(stderr, "Memory allocation failed\n");
        free(new_node);
        return NULL;
    }

    new_node->next = NULL;
    return new_node;
}

int getUniqueId() {
    static int next_id = 0;
    int id = ++next_id % MAX_ID;
    return id;
}

Node* insert_node(Node** head, Node* new_node) {
    if (!new_node || !head) {
        fprintf(stderr, "Invalid input\n");
        return NULL;
    }

    if (*head == NULL) {
        *head = new_node;
        return new_node;
    }

    Node* current = *head;
    while (current->next) {
        current = current->next;
    }
    current->next = new_node;
    return new_node;
}

Node* delete_node(Node** head, int id) {
    if (!head || !(*head)) {
        fprintf(stderr, "List is empty\n");
        return NULL;
