    Node* current = *head;
    if (current->unique_id == id) {
        *head = current->next;
        free(current->data_char);
        free(current);
        return current;
    }

    while (current && current->unique_id != id) {
        if (!current->next) {
            fprintf(stderr, "Node not found\n");
            return NULL;
        }
        current = current->next;
    }

    if (!current) {
        fprintf(stderr, "Node not found\n");
        return NULL;
    }

    Node* temp = current->next;
    free(current->data_char);
    free(current);
