#define MAX_ELEMENTS 1024

struct mem_pool {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    sem_t sem_producer;
    sem_t sem_consumer;
};

void init_mem_pool(struct mem_pool *pool) {
    pool->capacity = MAX_ELEMENTS;
    pool->size = 0;
    pool->data = malloc(pool->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    sem_init(&pool->sem_producer, 0, pool->capacity);
    sem_init(&pool->sem_consumer, 0, 0);
}

NFAPI_CRC_INDICATION_PDU_T* acquire(struct mem_pool *pool) {
    sem_wait(&pool->sem_producer);
    NFAPI_CRC_INDICATION_PDU_T *pdu = &pool->data[pool->size];
    if (pool->size < pool->capacity && pdu->tag == NULL) {
        pool->size++;
    }
    sem_post(&pool->sem_consumer);
    return pdu;
}

void release(struct mem_pool *pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu->tag != NULL) {
        // Process the PDU here
    }
    pool->size--;
    sem_post(&pool->sem_producer);
}

void cleanup(struct mem_pool *pool) {
    free(pool->data);
    sem_destroy(&pool->sem_producer);
    sem_destroy(&pool->sem_consumer);
}

NFAPI_CRC_INDICATION_PDU_T* create_array(size_t n, struct mem_pool *pool) {
    if (n > MAX_ELEMENTS || n == 0) {
        fprintf(stderr, "Invalid number of elements\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        pdu_array[i].tag = acquire(pool);
        if (!pdu_array[i].tag) {
            fprintf(stderr, "Could not allocate PDU structure\n");
            free(pdu_array);
            return NULL;
        }
    }

    return pdu_array;
}

void destroy_array(NFAPI_CRC_INDICATION_PDU_T* array, size_t n, struct mem_pool *pool) {
    for (size_t i = 0; i < n; ++i) {
        release(pool, array[i].tag);
    }
    free(array);
}
