#include <time.h>

#define MAX_UNIQUE 50
#define MAX_INPUT 150
#define BUCKET_SIZE (MAX_INPUT / MAX_UNIQUE)

typedef struct {
    int32_t value;
    size_t count;
} Bucket;

struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint8_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    uint16_t CRCFLAG;
};

void log(const char *message) {
    // Implement logging here
}

void readAndProcessInput(NFAPI_CRC_INDICATION_PDU_T **pdu, int32_t *largest) {
    Bucket *buckets = malloc(MAX_UNIQUE * sizeof(Bucket));
    if (!buckets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    memset(buckets, 0, MAX_UNIQUE * sizeof(Bucket));

    int32_t input[MAX_INPUT];
    size_t numInput = 0;
    size_t unique = 0;

    for (size_t i = 0; i < MAX_INPUT && numInput < MAX_INPUT; ++i) {
        if (scanf("%d", &input[i]) != 1) {
            fprintf(stderr, "Invalid input\n");
            exit(EXIT_FAILURE);
        }

        int32_t absValue = labs(input[i]);
        if (absValue > 1000) {
            fprintf(stderr, "Input value exceeds the limit of 1000\n");
            exit(EXIT_FAILURE);
        }

        uint64_t sum = 0;
        for (size_t j = 0; j < unique; ++j) {
            if (buckets[j].value == input[i]) {
                buckets[j].count++;
                ++numInput;
                goto continue_loop;
            }
            sum += abs(buckets[j].value);
        }

        if (unique >= MAX_UNIQUE - 1) {
            log("Warning: Number of unique integers exceeded the limit");
        }

        if (sum == 0 || sum < 0) {
            sum = 0xFFFE;
        }

        buckets[unique].value = input[i];
        buckets[unique].count = 1;
        unique++;
        numInput++;

continue_loop:
        continue;
    }

    qsort(buckets, unique, sizeof(Bucket), compareBucket);

    *largest = buckets[unique - 1].value;

    size_t pduSize = unique;
    *pdu = calloc(pduSize, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdu) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < unique; ++i) {
        (*pdu)[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        (*pdu)[i].RNTI = i + 1;
        (*pdu)[i].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        (*pdu)[i].CRCFLAG = buckets[i].value >= 0 ? (uint16_t)(sum & 0xFFFF);
    }

    free(buckets);
}

int compareBucket(const void *a, const void *b) {
    return ((const Bucket *)a)->value - ((const Bucket *)b)->value;
}
