typedef struct _ue {
    uint64_t ue_id;
    int cell_id;
    char service_type;
    pthread_mutex_t mutex;
} UE;

static UE* ues;
static size_t ue_count = 0;
static const size_t MAX_UE = 100000;
static const int MIN_CELL_ID = 0;
static const int MAX_CELL_ID = 255;
static char* service_types = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
static size_t service_type_count = strlen(service_types);
static const time_t TIMEOUT_MILLISECONDS = 1000; // 1 second timeout for cell ID selection
static pthread_mutex_t ues_mutex = PTHREAD_MUTEX_INITIALIZER;

void* initialize_ue(void* arg) {
    UE* ue = (UE*)arg;
    time_t start_time = time(NULL);

    while ((time(NULL) - start_time) < TIMEOUT_MILLISECONDS / 1000.0) {
        ue->cell_id = MIN_CELL_ID + rand() % (MAX_CELL_ID - MIN_CELL_ID + 1);
        for (size_t i = 0; i < ue_count; ++i) {
            if (ues[i].cell_id == ue->cell_id && &ues[i] != arg) {
                break;
            }
            if (i == ue_count - 1) {
                ue->cell_id = -1; // Cell ID is valid, continue with service type assignment.
                break;
            }
        }
        if (ue->cell_id != -1) {
            continue;
        }
    }

    if (ue->cell_id == -1) {
        fprintf(stderr, "Failed to assign a unique cell ID for UE %ld\n", ue->ue_id);
        exit(EXIT_FAILURE);
    }

    ue->ue_id = ++ue_count;
    if (service_types[rand() % service_type_count]) { // Preferred service type is non-zero.
        ue->service_type = service_types[rand() % service_type_count];
    } else {
        ue->service_type = 0;
    }

    pthread_mutex_init(&ue->mutex, NULL);
    return ue;
}

void initialize_ues(size_t num_ues) {
    if (num_ues > MAX_UE) {
        fprintf(stderr, "Number of UEs to be initialized exceeds the limit: %ld\n", MAX_UE);
        exit(EXIT_FAILURE);
    }

    UE* old_ues = ues;
    ues = mmap(NULL, sizeof(UE) * num_ues, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (ues == MAP_FAILED) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_ues; ++i) {
        UE* ue = &ues[i];
        pthread_create(&ue->mutex, NULL, initialize_ue, ue);
    }

    for (size_t i = 0; i < old_ues ? old_ues_count : 0; ++i) {
        pthread_join(old_ues[i].mutex, NULL);
    }

    if (old_ues) {
        munmap(old_ues, sizeof(UE) * old_ues_count);
    }

    pthread_mutex_destroy(&ues_mutex);
}
