        }
        std::copy(tempUeInstances, tempUeInstances + nextRnti, ueInstances);
        memset(tempUeInstances + nextRnti, 0, (nextRnti * 2 - nextRnti) * sizeof(UEInstance*));
        nextRnti *= 2;
    }

    void releaseUnusedResources() {
        // Implement resource release logic here
    }

    std::vector<UEInstance*> ueInstances;
    uint32_t nextRnti;
    static std::map<uint32_t, UEInstance*> rntiMap;
};
