using System;
using UnityEngine;
using System.Collections.Generic;

public class LinkedRecords
{
    private Node head;
    private int minValue, maxValue;

    public LinkedRecords(int[] offsets, int[] keys, int min, int max)
    {
        minValue = min;
        maxValue = max;
        InitializeLinkedList(offsets, keys);
    }

    private void InitializeLinkedList(int[] offsets, int[] keys)
    {
        head = new Node();
        for (int i = 0; i < offsets.Length; ++i)
        {
            var node = new Node() { offset = offsets[i], key = keys[i] };
            InsertAt(node, head);
        }
    }

    private void InsertAt(Node node, Node current)
    {
        if (current.next == null)
        {
            current.next = new Node() { prev = current, value = UnityEngine.Random.Range(minValue, maxValue + 1) };
            current.next.next = head;
            head.prev = current.next;
        }
        else
        {
            var nextNode = current.next;
            InsertAt(node, current);
            current.next = nextNode;
        }
    }

    public void DeleteAt(int key)
    {
        Node current = head;
        while (current.next != null)
        {
            if (current.next.key == key)
            {
                var nextNode = current.next.next;
                if (current.prev == head)
                    head = nextNode;
                else
                    current.prev.next = nextNode;

                if (nextNode != null)
                    nextNode.prev = current.prev;
            }
            current = current.next;
        }
    }

    public override string ToString()
    {
        return $"Min value: {minValue}, Max value: {maxValue}";
    }

    private class Node
    {
        public long offset;
        public int key;
        public int value;
        public Node prev;
        public Node next;
    }

    ~LinkedRecords()
    {
        Clear();
    }

    public void Clear()
    {
        head = null;
    }
}
```

