InterfaceConfigList* interface_config_list_create(size_t capacity) {
    InterfaceConfigList* list = mmap(NULL, sizeof(InterfaceConfigList), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!list) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    memset(list, 0, sizeof(InterfaceConfigList));
    list->arr = calloc(capacity, sizeof(InterfaceConfig));
    if (!list->arr) {
        free(list);
        perror("calloc");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&list->mutex, NULL);
    return list;
