            free(last_pdu);
            allocated -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
            pthread_mutex_lock(&alloc_mutex);
            fprintf(stderr, "Allocation validation failure for thread %d\n", (int)current_thread);
            pthread_mutex_unlock(&alloc_mutex);
