    if (buffer_len > max_buffer_size) {
        fprintf(stderr, "Error: Buffer size exceeded\n");
        free(new_record);
        sem_post(&buffer_pool_sem);
        return NULL;
    }

    new_record->buffer = malloc(buffer_len);
    if (!new_record->buffer) {
        fprintf(stderr, "Error: Out of memory\n");
        free(new_record);
        sem_post(&buffer_pool_sem);
        return NULL;
    }

    memcpy(new_record->buffer, data, buffer_len);
    new_record->key = key;
    new_record->metadata = calloc(1, max_metadata_size);
    if (!new_record->metadata) {
        fprintf(stderr, "Error: Out of memory\n");
        free(new_record->buffer);
        free(new_record);
        sem_post(&buffer_pool_sem);
        return NULL;
    }

    sem_post(&mutex);
    return new_record;
}

void update_metadata(Record* record, void* metadata) {
    if (!record || !metadata) return;

    sem_wait(&mutex);
    void* old_metadata = record->metadata;
    record->metadata = metadata;
    sem_post(&mutex);

    free(old_metadata);
}

void free_record(Record* record) {
    if (!record) return;

    sem_wait(&mutex);
    free(record->buffer);
    free(record->metadata);
    free(record);
    sem_post(&mutex);
}

