typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

struct dyn_array {
    unsigned int size;
    unsigned int capacity;
    Node** array;
    pthread_mutex_t mutex;
};

void init_dyn_array(struct dyn_array* da, unsigned int initial_capacity) {
    da->size = 0;
    da->capacity = initial_capacity;
    da->array = calloc(initial_capacity, sizeof(Node*));
    if (!da->array) {
        fprintf(stderr, "Failed to allocate memory for dynamic array\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&da->mutex, NULL);
}

unsigned int hash(unsigned int key) {
    unsigned long hash = 5381;
    int c;
    while (key) {
        c = (key & 0xff);
        key >>= 8;
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % da->capacity;
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Failed to allocate memory for node\n");
        exit(EXIT_FAILURE);
    }
    node->data = *data;
    node->next = NULL;
    return node;
}

void add_element(struct dyn_array* da, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&da->mutex);
    unsigned int index = hash(data->rnti);
    Node *head = da->array[index];
    if (head == NULL) {
        da->array[index] = create_node(data);
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
            if (current->data.rnti == data->rnti) {
                current->data.crcflag = data->crcflag;
                pthread_mutex_unlock(&da->mutex);
                return;
            }
        }
        current->next = create_node(data);
    }
    da->size++;
    if (da->size > da->capacity * 0.75) {
        resize_array(da, da->capacity * 2);
    }
    pthread_mutex_unlock(&da->mutex);
}

void remove_element(struct dyn_array* da, RNTI rnti) {
    pthread_mutex_lock(&da->mutex);
    unsigned int index = hash(rnti);
    Node *head = da->array[index];
    if (head == NULL) {
        pthread_mutex_unlock(&da->mutex);
        return;
    }
    if (head->data.rnti == rnti) {
        da->array[index] = head->next;
        free(head);
        da->size--;
        if (da->size <= da->capacity / 4 && da->capacity > 16) {
            resize_array(da, da->capacity / 2);
        }
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
            if (current->data.rnti == rnti) {
                Node *temp = current->next;
                current->next = temp->next;
                free(temp);
                da->size--;
                if (da->size <= da->capacity / 4 && da->capacity > 16) {
                    resize_array(da, da->capacity / 2);
                }
                break;
            }
        }
    }
    pthread_mutex_unlock(&da->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_element(struct dyn_array* da, RNTI rnti) {
    pthread_mutex_lock(&da->mutex);
    unsigned int index = hash(rnti);
    Node *head = da->array[index];
    if (head == NULL) {
        pthread_mutex_unlock(&da->mutex);
        return NULL;
    }
    if (head->data.rnti == rnti) {
        NFAPI_CRC_INDICATION_PDU_T* data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        *data = head->data;
        pthread_mutex_unlock(&da->mutex);
        return data;
    }
    Node* current = head;
    while (current->next != NULL) {
        current = current->next;
        if (current->data.rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            *data = current->data;
            pthread_mutex_unlock(&da->mutex);
            return data;
        }
    }
    pthread_mutex_unlock(&da->mutex);
    return NULL;
}

void resize_array(struct dyn_array* da, unsigned int new_capacity) {
    Node** new_array = calloc(new_capacity, sizeof(Node*));
    if (!new_array) {
        fprintf(stderr, "Failed to allocate memory for new dynamic array\n");
        exit(EXIT_FAILURE);
    }
    unsigned int old_index;
    Node *old_head, *old_current, *new_head, *new_current;
    pthread_mutex_lock(&da->mutex);
    for (unsigned int i = 0; i < da->capacity; ++i) {
        old_head = da->array[i];
        if (old_head != NULL) {
            old_index = hash(old_head->data.rnti);
            new_current = new_head = new_array[old_index];
            while (old_head != NULL) {
                old_current = old_head;
                old_head = old_head->next;
                if (new_current == NULL) {
                    new_current = malloc(sizeof(Node));
                    if (!new_current) {
                        fprintf(stderr, "Failed to allocate memory for new node\n");
                        exit(EXIT_FAILURE);
                    }
                    new_current->data = old_head->data;
                    new_current->next = NULL;
                    new_head = new_current;
                } else {
                    old_current->next = old_head;
                    old_head->next = new_current;
                    old_head = NULL;
                }
            }
        }
        da->array[i] = new_array[i];
    }
    free(da->array);
    da->array = new_array;
    da->capacity = new_capacity;
    pthread_mutex_unlock(&da->mutex);
}
```

This implementation uses a hash table to store the data structures, with chaining for handling collisions. The use of pthreads and locks ensures concurrent access is handled safely. The resize_array function dynamically adjusts the capacity based on the size of the data, aiming for a balance between memory usage and cache efficiency. This implementation makes trade-offs considering performance under high concurrency environments, scalability with a large number of unique RNTI values, and ease of integration with an existing system.']

