void add_request(const char* method, const char* uri, const char* headers[], size_t num_headers, const char* body, size_t body_size) {
    HttpRequest* new_req = (HttpRequest*) malloc(sizeof(HttpRequest));
    strncpy(new_req->method, method, sizeof(new_req->method));
    strncpy(new_req->uri, uri, sizeof(new_req->uri));
