    memcpy(new_req->body, body, body_size);
    new_req->body_size = body_size;
    new_req->next = request_list;
    pthread_mutex_lock(&list_mutex);
    request_list = new_req;
    pthread_mutex_unlock(&list_mutex);
}

void delete_request(HttpRequest* req) {
    if (request_list == req) {
        request_list = req->next;
    } else {
        HttpRequest *current = request_list;
        while (current && current->next != req) {
            current = current->next;
        }
        if (current) {
            current->next = req->next;
        }
    }
    free(req);
}

