typedef enum { INIT, ACTIVE, DELETED } record_status;

struct log_management {
    size_t num_records;
    long *offsets;
    int *keys;
    struct log_record *records;
    record_status *deletion_flags;
    size_t records_size;
};

void init_log(struct log_management *lm, size_t num_records) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Error: Number of records exceeds MAX_RECORDS\n");
        return;
    }

    lm->num_records = num_records;

    // Allocate memory for offsets and keys arrays with efficient handling of up to MAX_RECORDS
    lm->offsets = malloc(num_records * sizeof(long));
    if (!lm->offsets) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return;
    }

    lm->keys = malloc(num_records * sizeof(int));
    if (!lm->keys) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free(lm->offsets);
        return;
    }

    // Initialize all elements in the offsets and keys arrays
    for (size_t i = 0; i < num_records; ++i) {
        lm->offsets[i] = -1;
        lm->keys[i] = -1;
    }

    // Allocate memory for records array and set pointers
    lm->records = malloc(num_records * sizeof(struct log_record));
    if (!lm->records) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free(lm->offsets);
        free(lm->keys);
        return;
    }

    lm->deletion_flags = calloc(num_records, sizeof(record_status));
    if (!lm->deletion_flags) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free(lm->offsets);
        free(lm->keys);
        free(lm->records);
        return;
    }

    lm->records_size = sizeof(struct log_record) * num_records;

    // Randomly initialize keys array
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        lm->keys[i] = rand();
    }
}

void mark_as_deleted(struct log_management *lm, size_t index) {
    if (index >= lm->num_records) {
        fprintf(stderr, "Error: Index out of range\n");
        return;
    }

    lm->deletion_flags[index] = DELETED;
}

void undelete(struct log_management *lm, size_t index) {
    if (index >= lm->num_records) {
        fprintf(stderr, "Error: Index out of range\n");
        return;
    }

    lm->deletion_flags[index] = ACTIVE;
}

void print_state(const struct log_management *lm) {
    printf("Offsets:\n");
    for (size_t i = 0; i < lm->num_records; ++i) {
        printf("%ld ", lm->offsets[i]);
    }
    printf("\nKeys:\n");
    for (size_t i = 0; i < lm->num_records; ++i) {
        printf("%d ", lm->keys[i]);
    }
    printf("\nStatus:\n");
    for (size_t i = 0; i < lm->num_records; ++i) {
        if (lm->deletion_flags[i] == DELETED) {
            printf("DELETED ");
        } else {
            printf("ACTIVE ");
        }
    }
}

size_t total_memory(const struct log_management *lm) {
    return lm->records_size + sizeof(long) * lm->num_records + sizeof(int) * lm->num_records + sizeof(record_status) * lm->num_records;
}
