#include <iostream>
#include <vector>
#include <list>
#include <random>
#include <mutex>
#include <new>
#include <stdexcept>
#include <cstddef>

namespace my_dynamic_linked_list {

struct record {
    long offset;
    int key;
    int value;
};

class random_int_generator {
public:
    static std::random_device rd;
    static std::mt19937 gen;
    static std::uniform_int_distribution<> dist;

    inline int next(int min, int max) {
        return dist(gen);
    }
};

std::random_device random_device::rd;
std::mt19937 random_int_generator::gen(random_device::rd());
std::uniform_int_distribution<int> random_int_generator::dist(0, std::numeric_limits<int>::max());

class linked_list {
private:
    struct node {
        record data;
        node* next;
        node() : next(nullptr) {}
    };

    node* head_;
    node* tail_;
    size_t size_;
    std::mutex mutex_;

public:
    linked_list() : head_(new node()), tail_(head_) {
        size_ = 0;
    }

    ~linked_list() {
        clear();
    }

    void clear() {
        node* current = head_;
        while (current != nullptr) {
            node* temp = current;
            current = current->next;
            delete temp;
        }
        head_ = tail_ = nullptr;
        size_ = 0;
    }

    void initialize(const std::vector<long>& offsets, const std::vector<int>& keys) {
        clear();
        if (offsets.empty() || keys.empty()) {
            return;
        }

        for (size_t i = 0; i < offsets.size(); ++i) {
            record r{offsets[i], keys[i], random_int_generator::next()};
            add(r);
        }
    }

    void merge(const linked_list& other) {
        std::unique_lock<std::mutex> lock(mutex_);
        node* current = head_;
        node* other_current = other.head_;

        while (current != tail_ && other_current != other.tail_) {
            if (current->data.offset < other_current->data.offset) {
                current = current->next;
            } else if (other_current->data.offset < current->data.offset) {
                add(other_current->data);
                other_current = other_current->next;
            } else {
                add(current->data);
                add(other_current->data);
                current = current->next;
                other_current = other_current->next;
            }
        }

        if (other_current != other.tail_) {
            while (other_current != other.tail_) {
                add(other_current->data);
                other_current = other_current->next;
            }
        }
    }

    void reverse() {
        std::unique_lock<std::mutex> lock(mutex_);
        node* current = head_;
        node* next;
        node* previous = tail_;

        while (current != nullptr) {
            next = current->next;
            current->next = previous;
            previous = current;
            current = next;
        }

        std::swap(head_, tail_);
    }

    void iterate_and_display() const {
        node* current = head_;
        while (current != nullptr) {
            std::cout << "Offset: " << current->data.offset << ", Key: " << current->data.key << ", Value: " << current->data.value << '\n';
            current = current->next;
        }
    }

    void add(const record& r) {
        std::unique_lock<std::mutex> lock(mutex_);
        node* new_node = new node{r};

        if (!head_) {
            head_ = tail_ = new_node;
        } else {
            tail_->next = new_node;
            tail_ = new_node;
        }

        ++size_;
    }
};
} // namespace my_dynamic_linked_list

int main() {
    my_dynamic_linked_list::linked_list list1, list2;
    std::vector<long> offsets1 = {0, 5, 10, 15};
    std::vector<int> keys1 = {1, 2, 3, 4};
    std::vector<long> offsets2 = {2, 7, 12, 17};
    std::vector<int> keys2 = {5, 6, 7, 8};

    list1.initialize(offsets1, keys1);
    list2.initialize(offsets2, keys2);
    list1.merge(list2);
    list1.reverse();
    list1.iterate_and_display();

    return 0;
}
