#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int crc;
    LTEMMEA_USER_INFO info;
    unsigned short pci;
} LTE_PACKET;

int hash(int key, int table_size) {
    return key % table_size;
}

void linear_probe(LTE_PACKET **table, int *status, int key, int *position, int table_size) {
    for (*position = hash(key, table_size); *position != -1 && status[*position] == 1; ++(*position)) {
        if ((*position + 1) % table_size == hash(key, table_size))
            *position = -1; // Wrap around
    }
}

void free_table(LTE_PACKET **table, int *status, int *keys, int size) {
    for (int i = 0; i < size; ++i) {
        if (table[i])
            free(table[i]);
    }
    free(status);
    free(keys);
}

LTE_PACKET* create_packet() {
    LTE_PACKET *packet = malloc(sizeof(LTE_PACKET));
    if (!packet) return NULL;

    packet->crc = rand() % MAX_CRC_VALUE;
    // Initialize LTEMMEA_USER_INFO and pci here

    return packet;
}

int create_tables(LTE_PACKET **table, int *status, int *keys, int table_size, int max_packets) {
    if (max_packets > table_size) {
        printf("Error: Maximum number of packets exceeds the allocated table size.\n");
        return 0;
    }

    for (int i = 0; i < table_size; ++i) {
        table[i] = create_packet();
        if (!table[i]) return 0;
        status[i] = 0;
        keys[i] = -1; // Unused slot
    }

    for (int i = max_packets, packet; i < table_size; ++i) {
        packet = create_packet();
        if (!packet) return 0;
        linear_probe(table, status, i, &packet->index, table_size);
        if (packet->index != -1 && status[packet->index] == 1) { // Collision resolution
            do {
                linear_probe(table, status, i, &packet->index, table_size);
            } while (packet->index != -1 && status[packet->index] == 1);
        }
        if (packet->index != -1) { // Slot found
            status[packet->index] = 1;
            keys[packet->index] = i;
        } else { // No slots left, truncate excess records
            break;
        }
    }

    return 1;
}
```

