char* generate_temp_filename(const char *original) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);

    char tempname[64];
    snprintf(tempname, sizeof(tempname), "%s-%04d%02d%02d_%06lu.tmp", original,
             tm_now->tm_year + 1900, tm_now->tm_mon + 1, tm_now->tm_mday,
             (unsigned long)time(NULL));

    int fd = mkdtemp(tempname);
    if (fd == -1 && errno != EEXIST) {
        perror("Failed to create temporary directory\n");
        return NULL;
    }

    char *filename = strdup(tempname);
    if (!filename) {
        perror("Out of memory\n");
        return NULL;
    }

    // Incremental numbering if the file already exists
    int i = 1;
    while (access(filename, F_OK) == 0) {
        snprintf(tempname, sizeof(tempname), "%s-%d%s", filename, i++, ".tmp");
        filename = strdup(tempname);
    }

    return filename;
}

