typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MEMORY_THRESHOLD (1024 * 1024) // 1MB as an example threshold
#define MAX_RNTI 65535 // Maximum RNTI value
#define NUM_THREADS 8 // Number of threads for concurrent access and processing

static pthread_mutex_t mutex;
static NFAPI_CRRC_INDICATION_PDU_T *data;
static size_t data_len = 0;
static size_t max_data_len = MEMORY_THRESHOLD / sizeof(NFAPI_CRC_INDICATION_PDU_T);

void* populate_array(void *arg) {
    data = realloc(data, data_len + NUM_THREADS);
    if (!data) {
        perror("Reallocation failed");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    for (size_t i = data_len; i < data_len + NUM_THREADS; ++i) {
        data[i].RX_UE_INFORMATION_TAG = rand();
        data[i].RNTI = rand() % MAX_RNTI; // Ensure unique RNTIs within the array
        data[i].CRC_INDICATION_REL8_TAG = rand() % 2;

        if (i > 0 && data[i].RNTI == data[i - 1].RNTI) {
            fprintf(stderr, "RNTI validation failed: Duplicate RNTIs detected\n");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
    }
    data_len += NUM_THREADS;
    pthread_mutex_unlock(&mutex);

    return NULL;
}

void init_data() {
    data = malloc(max_data_len);
    if (!data) {
        perror("Initial allocation failed");
        exit(1);
    }

    pthread_mutex_init(&mutex, NULL);
}

void free_data() {
    free(data);
    data = NULL;
    data_len = 0;
    pthread_mutex_destroy(&mutex);
}

// Integrate with existing real-time processing system
// ...
