        perror("Error reading from input stream");
        goto cleanup;
    }

    pdu_arr = realloc(pdu_arr, *num_read * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdu_arr) {
        free(input_arr);
        perror("Error resizing PDU array");
        goto cleanup;
    }

    int largest_index = -1;
    int largest = INT_MIN;
    for (size_t i = 0; i < *num_read; ++i) {
        if (input_arr[i] > largest) {
            largest = input_arr[i];
            largest_index = i;
        }

        // Generate RNTI and populate PDU structure
        uint16_t rnti = generate_rnti();
        if (rnti >= UINT16_MAX || rnti <= 0) {
            fprintf(stderr, "Error: Invalid RNTI value\n");
            goto cleanup;
        }

        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            perror("Error allocating memory for PDU structure");
            goto cleanup;
        }

        pdu->rx_ue_information_tag = YOUR_RX_UE_INFORMATION_TAG_VALUE;
        pdu->rnti = rnti;
        pdu->crc_indication_rel8_tag.crcflag = (uint8_t)(input_arr[i] % 256);

        pdu_arr[i] = pdu;
    }

cleanup:
    if (input_arr) free(input_arr);
    if (*num_read > 0 && pdu_arr) {
        for (size_t i = 0; i < *num_read; ++i) {
            free(pdu_arr[i]);
        }
        free(pdu_arr);
    }

    if (*num_read > 0) {
        return pdu_arr[largest_index];
    } else {
        return NULL;
    }
}
