#include <uniform_int_distribution>
#include <random>

struct UserEquipment {
    int id;
    int cellId;
};

std::unordered_map<int, std::vector<UserEquipment>> initializeUEs(int region, int totalUENum, int minCellNum, int maxCellNum) {
    static std::mt19937ar rng{std::chrono::system_clock::now().time_since_epoch().count()}; // seed based on current system time
    std::uniform_int_distribution<> cellDistribution(minCellNum, maxCellNum);

    std::unordered_map<int, std::vector<UserEquipment>> ueList;
    std::vector<UserEquipment> ues;

    for (int i = 0; i < totalUENum; ++i) {
        UserEquipment ue{i, cellDistribution(rng)};
        if (ueList.count(region)) {
            ueList[region].push_back(ue);
        } else {
            std::cerr << "Error: Specified region does not exist." << std::endl;
            return ueList; // early exit in case of error
        }
    }

    return ueList;
}
