class CRCIndicationPDUList {
private:
    std::mutex mtx;
    boost::container::small_vector<NFAPI_CRC_INDICATION_PDU_T, 8> data;
    std::unordered_map<boost::hash<uint32_t>, NFAPI_CRC_INDICATION_PDU_T*, boost::hash<uint32_t>> hashMap;
    uint64_t seed = 0;
    bool logEnabled = false;

public:
    void setSeed(uint64_t _seed) { seed = _seed; }
    void enableLogging(std::ostream& logStream) { logEnabled = true; }

    CRCIndicationPDUList(size_t initCap = 0) : data(initCap) {}

    NFAPI_CRC_INDICATION_PDU_T* create() {
        if (data.size() > data.capacity()) {
            data.reserve(2 * data.size());
        }
        auto* entry = &data.back();
        resetEntry(*entry);
        return entry;
    }

    bool insert(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::unique_lock<std::mutex> lock(mtx);
        if (!isInRange(pdu.rx_ue_information_tag) || !isInRange(pdu.rnti)) {
            return false;
        }
        auto found = hashMap.emplace_hint(std::make_pair(boost::hash<uint32_t>{}(pdu.rnti), &pdu));
        if (!found.second) {
            resolveCollision(*found.first->second, pdu);
        }
        hashMap[boost::hash<uint32_t>{}(pdu.rnti)] = &pdu;
        return true;
    }

private:
    bool isInRange(NFAPI_CRC_INDICATION_PDU_T::RX_UE_INFORMATION_TAG value) {
        return static_cast<int>(value) >= static_cast<int>(NFAPI_CRC_INDICATION_PDU_T::RX_UE_INFORMATION_TAG::Min) &&
               static_cast<int>(value) <= static_cast<int>(NFAPI_CRC_INDICATION_PDU_T::RX_UE_INFORMATION_TAG::Max);
    }

    bool isInRange(NFAPI_CRC_INDICATION_PDU_T::RNTI value) {
        return static_cast<int>(value) >= static_cast<int>(NFAPI_CRC_INDICATION_PDU_T::RNTI::Min) &&
               static_cast<int>(value) <= static_cast<int>(NFAPI_CRC_INDICATION_PDU_T::RNTI::Max);
    }

    void resetEntry(NFAPI_CRC_INDICATION_PDU_T& entry) {
        entry.rx_ue_information_tag = NFAPI_CRC_INDICATION_PDU_T::RX_UE_INFORMATION_TAG::Min;
        entry.rnti = NFAPI_CRC_INDICATION_PDU_T::RNTI(std::rand_r(static_cast<unsigned int>(&seed)));
        entry.crc_indication_rel8_tag.value = std::rand_r(static_cast<unsigned int>(&seed)) % 3;
        entry.crcflag = bool(std::rand_r(static_cast<unsigned int>(&seed)));
    }

    void resolveCollision(NFAPI_CRC_INDICATION_PDU_T& existing, const NFAPI_CRC_INDICATION_PDU_T& newPdu) {
        auto newRnti = newPdu.rnti;
        do {
            newRnti += 1 + (std::rand_r(static_cast<unsigned int>(&seed)));
        } while (hashMap.count(boost::hash<uint32_t>{}(newRnti)) > 0);
        newPdu.rnti = newRnti;
        insert(newPdu);
    }

