void log_info(const char* message);

node_t* create_list() {
    node_t* head = NULL;
    node_t* current = NULL;
    data_t* element = (data_t*) malloc(sizeof(data_t));

    if (!element) {
        log_error("Failed to allocate memory for data structure.");
        return NULL;
    }

    head = (node_t*) malloc(sizeof(node_t));
    current = head;

    if (!head) {
        log_error("Failed to allocate memory for list header.");
        free(element);
        return NULL;
    }

    current->data = element;
    current->next = NULL;

    return head;
}

void add_entry(node_t* list, data_t* entry) {
    if (!list || !entry) {
        log_error("Invalid input arguments.");
        return;
    }

    node_t* current = list;
    node_t* new_node = (node_t*) malloc(sizeof(node_t));

    if (!new_node) {
        log_error("Failed to allocate memory for new node.");
        return;
    }

    new_node->data = entry;
    new_node->next = NULL;

    // Check if the list is full and handle memory reallocations
    if (current->next) {
        current = current->next;
        if (list_size(list) >= MAX_LIST_SIZE * MEMORY_FRAGMENTATION_THRESHOLD / 100) {
            node_t* temp_head = double_list_capacity(list);
            current = temp_head->next;
        }
    }

    current->next = new_node;
}

int list_size(node_t* list) {
    int size = 0;
    node_t* current = list;

    while (current) {
        ++size;
        current = current->next;
    }

    return size;
}

node_t* double_list_capacity(node_t* list) {
    if (!list) {
        log_error("Invalid input argument.");
        return NULL;
    }

    node_t* current = list;
    node_t* new_head = (node_t*) malloc(sizeof(node_t));

    if (!new_head) {
        log_error("Failed to allocate memory for new header.");
        return NULL;
    }

    int i = 0;
    node_t* current_copy = NULL;
    node_t* new_current = new_head;

    while (current) {
        if (i >= MAX_LIST_SIZE / 2) { // Ensure we don't add the same elements twice in case of memory fragmentation
            break;
        }

        current_copy = (node_t*) malloc(sizeof(node_t));

        if (!current_copy) {
            log_error("Failed to allocate memory for new copy node.");
            return NULL;
        }

        current_copy->data = current->data;
        current_copy->next = NULL;

        if (!new_head->next) {
            new_head->next = current_copy;
            new_current = current_copy;
        } else {
            new_current->next = current_copy;
            new_current = current_copy;
        }

        ++i;
        current = current->next;
    }

    return new_head;
}

