    ue_instance_list_t *list = malloc(sizeof(ue_instance_list_t));
    if (!list) return NULL;
    list->current = 0;
    pj_mutex_init(&list->mutex);
    return list;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdus(ue_instance_list_t *list, size_t n) {
    if (n > 256 || list->current + n >= 256) return NULL; // Handle overflow scenario gracefully

    pj_mutex_lock(&list->mutex);
    size_t start = list->current;
    size_t end = start + n;
    if (end > 256) end -= 256;
    list->current = end;
    pj_mutex_unlock(&list->list->mutex);

    NFAPI_CRC_INDICATION_PDU_T *pdus = &list->pdus[start];

    // Populate with unique RNTIs and random CRCFLAGS
    for (size_t i = start; i < end; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = /* Your tag value */;
        pdus[i].RNTI = i + 1; // Use index as RNTI for simplicity
        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    return pdus;
}

void free_pdus(ue_instance_list_t *list, NFAPI_CRC_INDICATION_PDU_T *pdus, size_t n) {
    if (pdus == NULL) return;

    pj_mutex_lock(&list->mutex);
    size_t start = (size_t)(pdus - list->pdus);
    pj_mutex_unlock(&list->mutex);

    for (size_t i = start; i < start + n; ++i) {
        // Validate RNTIs are unique and log errors if any collisions occur
        size_t j;
        for (j = 0; j < start; ++j) {
            if (pdus[i].RNTI == pdus[j].RNTI) {
                log_error("RNTI collision: %d and %d", pdus[i].RNTI, pdus[j].RNTI);
                break;
            }
        }
        if (j >= start + n) free(pdus[i]); // Release memory for the structure if it's unique
    }
}

