    da->array = malloc(BATCH_SIZE * sizeof(Node*));
    for (int i = 0; i < BATCH_SIZE; ++i)
        da->array[i] = NULL;
}

void free_dynamic_array(struct dynamic_array* da) {
    for (int i = 0; i < da->capacity / BATCH_SIZE; ++i) {
        Node *current, *next;
        current = da->array[i];
        while (current != NULL) {
            next = current->next;
            free(current);
            current = next;
        }
    }
    free(da->array);
