#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <semaphore.h>
#include <queue>
#include <unordered_map>
#include <atomic>

struct TX_PACKET_INFO {
    int transmit_buffer_id;
    int packet_type;
    int queue_depth;
};

class QueueManager {
private:
    std::queue<TX_PACKET_INFO> m_queue;
    std::unordered_map<int, std::atomic<int>> m_buffer_ids;
    sem_t m_mutex;
    sem_t m_notFull;
    sem_t m_notEmpty;
    int m_highWaterMark;

public:
    QueueManager(int highWaterMark) : m_highWaterMark(highWaterMark) {
        sem_init(&m_mutex, 0, 1);
        sem_init(&m_notFull, 0, highWaterMark);
        sem_init(&m_notEmpty, 0, 0);
    }

    void enqueue(const TX_PACKET_INFO& packet) {
        sem_wait(&m_notFull);
        sem_wait(&m_mutex);
        if (packet.transmit_buffer_id > 0 && m_buffer_ids.find(packet.transmit_buffer_id) == m_buffer_ids.end()) {
            // Integration with external network monitoring system here
            int new_id = ++m_highWaterMark;
            m_buffer_ids[packet.transmit_buffer_id] = std::atomic<int>(new_id);
            packet.transmit_buffer_id = new_id;
        }
        m_queue.push(packet);
        sem_post(&m_mutex);
        sem_post(&m_notEmpty);
    }

    TX_PACKET_INFO dequeue() {
        sem_wait(&m_notEmpty);
        sem_wait(&m_mutex);
        TX_PACKET_INFO packet = m_queue.front();
        m_queue.pop();
        if (sem_trywait(&m_notFull) > 0) {
            sem_post(&m_mutex);
        }
        sem_post(&m_notEmpty);
        return packet;
    }
};
