#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag; // randomly set within the function
    struct Node *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
} Node;

static int max_list_size = 1000;
static Node *head = NULL;
static int list_size = 0;
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void init_list() {
    head = malloc(sizeof(Node));
    if (!head) {
        fprintf(stderr, "Failed to allocate memory for list header\n");
        exit(EXIT_FAILURE);
    }
    head->next = NULL;
}

bool add_node(const NFAPI_CRC_INDICATION_PDU_T *data) {
    if (list_size >= max_list_size) return false;

    pthread_mutex_lock(&list_lock);
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list_lock);
        fprintf(stderr, "Failed to allocate memory for new node\n");
        return false;
    }

    new_node->data = *data;
    new_node->next = head->next;
    head->next = new_node;
    list_size++;
    pthread_mutex_unlock(&list_lock);

    return true;
}

bool update_node(uint32_t rnti, const NFAPI_CRC_INDICATION_PDU_T *data) {
    if (rnti >= max_list_size || list_size == 0) return false;

    Node *current = head->next;
    pthread_mutex_lock(&list_lock);
    while (current != NULL && current->data.rnti != rnti) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list_lock);
        return false;
    }

    current->data = *data;
    pthread_mutex_unlock(&list_lock);
    return true;
}

bool remove_node(uint32_t rnti) {
    if (rnti >= max_list_size || list_size == 0) return false;

    Node *current = head;
    pthread_mutex_lock(&list_lock);
    while (current->next != NULL && current->next->data.rnti != rnti) {
        current = current->next;
    }

    if (current->next == NULL) {
        pthread_mutex_unlock(&list_lock);
        return false;
    }

    Node *node_to_free = current->next;
    current->next = node_to_free->next;
    free(node_to_free);
    list_size--;
    pthread_mutex_unlock(&list_lock);

    return true;
}
```

