struct PHY_LAYER_DATA { /* Define your PHY-layer DATA structure here */ };
enum class FRAME_ERROR_FLAGS { CRC_ERROR, FEC_ERROR, PHYSICAL_LAYER_ERROR };

class NFAPI_RX_FRAME_T {
public:
    RX_HEADER header;
    PHY_LAYER_DATA data;
    FRAME_ERROR_FLAGS errorFlags;

    // Constructor
    NFAPI_RX_FRAME_T() : errorFlags(FRAME_ERROR_FLAGS::NONE) {}
};

class FrameManager {
private:
    std::vector<std::unique_ptr<NFAPI_RX_FRAME_T>> frames;
    std::function<void(NFAPI_RX_FRAME_T&)> callback;
    std::atomic<double> memoryUsage{0.0}; // For tracking memory usage
    std::atomic<uint64_t> frameCount{0}; // For tracking the number of frames

public:
    // Function to add a new frame with error flags based on probabilistic model
    void addFrame() {
        auto newFrame = std::make_unique<NFAPI_RX_FRAME_T>();
        if (!newFrame) {
            std::cerr << "Out of memory" << std::endl;
            return;
        }

        // Simulate channel conditions and set error flags probabilistically
        newFrame->errorFlags = [&]() -> FRAME_ERROR_FLAGS {
            static std::uniform_int_distribution<> distribution(0, 1);
            if (distribution(std::random_device()) == 1)
                return FRAME_ERROR_FLAGS::CRC_ERROR;
            else if (distribution(std::random_device()) == 1)
                return FRAME_ERROR_FLAGS::FEC_ERROR;
            else
                return FRAME_ERROR_FLAGS::PHYSICAL_LAYER_ERROR;
        }();

        frames.push_back(std::move(newFrame));
        memoryUsage += sizeof(NFAPI_RX_FRAME_T);
        frameCount++;
    }

    // Function to update the PHY-layer DATA of a specific frame based on external data or algorithms
    void updateData(uint32_t index, const PHY_LAYER_DATA& newData) {
        if (index >= frames.size()) {
            std::cerr << "Invalid index" << std::endl;
            return;
        }
        frames[index]->data = newData;
    }

    // Set the callback function to update PHY-layer DATA for all frames based on external data sources or internal algorithms
    void setCallback(std::function<void(NFAPI_RX_FRAME_T&)> cb) {
        callback = cb;
    }

    // Function to call the callback function for each frame
    void processFrames() {
        if (!callback)
            return;
        auto startTime = std::chrono::steady_clock::now();

        for (auto& frame : frames)
            callback(*frame);

        auto endTime = std::chrono::steady_clock::now();
        // Monitoring component can be integrated here by logging the time taken to process all frames
    }
};
