#include <iostream>
#include <vector>
#include <unordered_map>
#include <boost/circular_buffer.hpp>
#include <boost/lockfree/spsc_queue.hpp>
#include <mutex>
#include <atomic>

constexpr size_t MAX_MEMORY = 1000000; // Max memory limit (bytes)
constexpr size_t INITIAL_CAPACITY = 1024;
constexpr int LOGGING_THRESHOLD = 100;

struct Record {
    int key;
    std::atomic<int> access_count{ 0 };
};

class RecordCollection {
public:
    void insert(Record&& record) {
        // Resize if necessary to accommodate the new record
        if (current_.size() == capacity_) {
            resize();
        }

        current_.emplace_back(std::move(record));
        memory_usage_ += sizeof(Record);

        if (memory_usage_ > MAX_MEMORY) {
            // Implement a cleanup strategy here, such as evicting the least-recently used records.
            std::cerr << "Memory limit exceeded. Cleanup required.\n";
        }
    }

    Record& get(int key) {
        auto it = current_.emplace(std::begin(current_), std::piecewise_construct,
                             std::forward_argument_type<decltype(*current_.begin())>{},
                             std::forward_arguments<>{key});

        if (it->second.access_count >= LOGGING_THRESHOLD) {
            std::lock_guard<std::mutex> lock(log_mutex_);
            std::cout << "Key: " << key << " accessed frequently.\n";
        }

        return it->first;
    }

private:
    void resize() {
        // Implement a strategy to minimize the cost of dynamic resizing.
        // You can consider using std::vector::reserve() for an efficient approach.
        std::vector<Record> new_current(2 * capacity_);
        std::copy(std::begin(current_), std::end(current_), std::begin(new_current));
        current_.swap(new_current);
        capacity_ *= 2;
    }

    boost::lockfree::spsc_queue<Record> queue_; // For insertion from multiple threads
    std::vector<Record> current_; // The collection of records
    std::mutex log_mutex_; // For logging operations
    size_t capacity_{ INITIAL_CAPACITY }; // Current capacity
    size_t memory_usage_{ 0 }; // Total memory usage in bytes
};
```

