#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define N 1000
#define M 1000000

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* dynamic_array = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
size_t num_elements = 0;

void init_dynamic_array() {
    if (!(dynamic_array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T)))) {
        fprintf(stderr, "Error: Memory allocation failure.\n");
        return;
    }
    for (size_t i = 0; i < N; ++i) {
        dynamic_array[i].crc_ind.crci = rand() % 15 + 1; // Set CRC flag randomly
    }
}

void push(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (num_elements >= M) return;
    if (pthread_mutex_lock(&mutex)) {
        fprintf(stderr, "Error: Mutex lock failed.\n");
        return;
    }

    if (!(dynamic_array = realloc(dynamic_array, ++num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T)))) {
        fprintf(stderr, "Error: Memory allocation failure.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    memcpy(&dynamic_array[num_elements - 1], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    dynamic_array[num_elements - 1].crc_ind.crci = rand() % 15 + 1; // Set CRC flag randomly
    pthread_mutex_unlock(&mutex);
}

void serialize(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file for writing.\n");
        return;
    }

    fwrite(dynamic_array, num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    fclose(file);
}

void* deserialize(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file for reading.\n");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    rewind(file);

    if (!(dynamic_array = malloc(file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T)))) {
        fprintf(stderr, "Error: Memory allocation failure.\n");
        fclose(file);
        return NULL;
    }

    fread(dynamic_array, file_size, 1, file);
    num_elements = file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    fclose(file);

    // Set CRC flag randomly for deserialized elements (for potential data corruption during storage)
    for (size_t i = 0; i < num_elements; ++i) {
        dynamic_array[i].crc_ind.crci = rand() % 15 + 1;
    }

    return dynamic_array;
}

