#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
    bool crcflag;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
} DYNAMIC_LIST;

DYNAMIC_LIST *dynamic_list_init(size_t initial_capacity) {
    DYNAMIC_LIST *list = malloc(sizeof(DYNAMIC_LIST));
    if (!list) return NULL;

    list->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;

    pthread_mutex_init(&list->data[0].lock, NULL);
    for (size_t i = 1; i < initial_capacity; ++i) {
        pthread_mutex_init(&list->data[i].lock, NULL);
    }

    return list;
}

void dynamic_list_destroy(DYNAMIC_LIST *list) {
    if (!list || !list->data) return;

    for (size_t i = 0; i < list->count; ++i) {
        pthread_mutex_destroy(&list->data[i].lock);
    }

    free(list->data);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T *dynamic_list_push(DYNAMIC_LIST *list, RX_UE_INFORMATION_TAG tag, RNTI rnti) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].rnti == rnti) return NULL; // Duplicate RNTI found
    }

    NFAPI_CRC_INDICATION_PDU_T *entry = &list->data[list->count];
    entry->tag = tag;
    entry->rnti = rnti;
    entry->crc_tag.crc = rand(); // Randomly set CRC flag
    entry->crcflag = (entry->crc_tag.crc % 2) == 0;

    pthread_mutex_init(&entry->lock, NULL);

    ++list->count;
    if (list->count >= list->capacity / 2 && list->capacity > 128) { // Resize when capacity is too low or capacity/2 threshold is reached
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data) {
            list->data = new_data;
            list->capacity = new_capacity;
            pthread_mutex_init(&list->data[list->count].lock, NULL);
        }
    }

    return entry;
}

size_t dynamic_list_query(const DYNAMIC_LIST *list) {
    return list ? list->count : 0;
}
