[' Here is a simplified C code implementation for managing a dynamic array of `LTE_UE_MEASUREMENT_REPORT` structures based on your requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int rssi;
    int cqi;
    int pmi;
} LTE_UE_MEASUREMENT_REPORT;

struct array_handle {
    size_t capacity;
    size_t count;
    LTE_UE_MEASUREMENT_REPORT* data;
};

void array_init(struct array_handle* handle) {
    handle->capacity = 16;
    handle->count = 0;
    handle->data = malloc(handle->capacity * sizeof(LTE_UE_MEASUREMENT_REPORT));
}

size_t array_find_index(const struct array_handle* handle, const char* id) {
    for (size_t i = 0; i < handle->count; ++i) {
        if (!strcmp(handle->data[i].id, id)) {
            return i;
        }
    }
    return SIZE_MAX;
}

void array_add(struct array_handle* handle, const char* id, const LTE_UE_MEASUREMENT_REPORT* report) {
    size_t index = array_find_index(handle, id);

    if (index != SIZE_MAX && index < handle->count) { // Update existing UE
        memcpy(&handle->data[index], report, sizeof(LTE_UE_MEASUREMENT_REPORT));
    } else if (handle->capacity == handle->count) { // Resize array
        handle->capacity *= 2;
        LTE_UE_MEASUREMENT_REPORT* temp = realloc(handle->data, handle->capacity * sizeof(LTE_UE_MEASUREMENT_REPORT));
        if (!temp) {
            fprintf(stderr, "Error resizing array\n");
            return;
        }
        handle->data = temp;
    }

    strcpy(&handle->data[handle->count].id, id);
    memcpy(&handle->data[handle->count++], report, sizeof(LTE_UE_MEASUREMENT_REPORT));
}

const LTE_UE_MEASUREMENT_REPORT* array_get(const struct array_handle* handle, const char* id) {
    size_t index = array_find_index(handle, id);

    if (index == SIZE_MAX || index >= handle->count) {
        return NULL;
    }

    return &handle->data[index];
}
```

