typedef struct {
    int value;
} record;

struct memory_pool {
    size_t num_allocated;
    size_t capacity;
    record* data;
    pthread_mutex_t lock;
};

void init_memory_pool(struct memory_pool* pool, size_t initial_capacity) {
    pool->data = malloc(initial_capacity * sizeof(record));
    if (!pool->data) {
        fprintf(stderr, "Error allocating memory for the memory pool\n");
        exit(EXIT_FAILURE);
    }
    pool->num_allocated = 0;
    pool->capacity = initial_capacity;
    pool->lock = PTHREAD_MUTEX_INITIALIZER;
}

record* allocate_record(struct memory_pool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->num_allocated < pool->capacity) {
        ++pool->num_allocated;
    } else {
        size_t new_capacity = 2 * pool->capacity;
        record* new_data = realloc(pool->data, new_capacity * sizeof(record));
        if (!new_data) {
            fprintf(stderr, "Error resizing memory pool\n");
            pthread_mutex_unlock(&pool->lock);
            exit(EXIT_FAILURE);
        }
        pool->data = new_data;
        pool->capacity = new_capacity;
    }
    record* result = &pool->data[pool->num_allocated - 1];
    pthread_mutex_unlock(&pool->lock);
    return result;
}

void free_record(struct memory_pool* pool, record* record) {
    pthread_mutex_lock(&pool->lock);
    *record = (record){0};
    --pool->num_allocated;
    pthread_mutex_unlock(&pool->lock);
}

long* create_offsets(size_t num_offsets) {
    long* offsets = malloc(num_offsets * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error allocating memory for the offsets array\n");
