    if (!keys) {
        fprintf(stderr, "Error allocating memory for the keys array\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = i;
    }
    return keys;
}

struct memory_pool record_memory_pool;

record* init_records(size_t num_records, int min_value, int max_value) {
