    init_memory_pool(pool, num_records);

    srand(time(NULL));
    record* records = calloc(num_records, sizeof(record));
    if (!records) {
        fprintf(stderr, "Error allocating memory for the records array\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_records; ++i) {
        record* record = allocate_record(pool);
        (*record).value = rand() % (max_value - min_value + 1) + min_value;
        *records++ = *record;
    }

    free(pool->data);
    pool->num_allocated = 0;
    return records;
}

void sort(void* array, size_t num_elements, bool is_ascending) {
    // Implement your preferred sorting algorithm here.
    // For simplicity, this example uses the bubble sort algorithm:
    for (size_t i = 0; i < num_elements - 1; ++i) {
        for (size_t j = i + 1; j < num_elements; ++j) {
            if ((!is_ascending && (*(long*)(array + i * sizeof(long)) > *(long*)(array + j * sizeof(long))) ||
                (is_ascending && *(long*)(array + i * sizeof(long)) < *(long*)(array + j * sizeof(long)))) {
                long temp = *(long*)(array + i * sizeof(long));
                *(long*)(array + i * sizeof(long)) = *(long*)(array + j * sizeof(long));
                *(long*)(array + j * sizeof(long)) = temp;
            }
        }
    }
}

