typedef struct _node {
    NFAPI_L1_STATS_PDU_T data;
    struct _node* next;
} Node;

static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static Node *head = NULL, *tail = NULL, *cache = NULL;
static uint32_t max_rnti = 0, rnti_count = 0;

void add_to_list(NFAPI_L1_STATS_PDU_T data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list_mutex);
    if (tail) tail->next = new_node;
    else head = new_node;
    tail = new_node;

    // Check for duplicates based on RNTI
    Node *current = head;
    while (current != NULL) {
        if (current->data.rnti == data.rnti) {
            free(new_node);
            break;
        }
        current = current->next;
    }

    // If not a duplicate, increment RNTI count
    if (current == NULL) rnti_count++;

    pthread_mutex_unlock(&list_mutex);
}

void cleanup() {
    Node *temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
    rnti_count = 0;
}

