#include <set>
#define MAX_BANDWIDTH UINT32_MAX

typedef struct {
    char id[16];
    uint32_t bandwidth;
    std::set<char*> ip_list; // Set for fast IP lookup and avoid duplicates
} net_interface;

// Comparator function for sorting net_interfaces by bandwidth in descending order
bool compare(const net_interface *a, const net_interface *b) {
    return a->bandwidth > b->bandwidth;
}

void add_interface(net_interface** array, unsigned int* size, net_interface new_interface) {
    if(*size == 0) {
        *array = (net_interface*)malloc((size_t)*size = 16 * sizeof(net_interface));
    } else if (*size >= 16) {
        *size *= 2;
        net_interface* new_arr = (net_interface*)realloc(*array, *size * sizeof(net_interface));
        memcpy(new_arr + *size - 16, *array, (*size) * sizeof(net_interface));
        *array = new_arr;
    }

    for(unsigned int i = 0; i < *size; ++i) {
        if(strcmp((*array)[i].id, new_interface.id) == 0) {
            printf("Error: Interface with ID \"%s\" already exists.\n", new_interface.id);
            return;
        }
    }

    if(new_interface.bandwidth > MAX_BANDWIDTH) {
        printf("Error: Bandwidth setting %u is out of range.\n", new_interface.bandwidth);
        return;
    }

    for(const char* ip : new_interface.ip_list) {
        if(!new_interface.ip_list.empty() && std::find(array, array + *size, (net_interface){ .id = ip, .bandwidth = 0, .ip_list = {ip} }) != array + *size) {
            printf("Error: Duplicate IP address %s found.\n", ip);
            return;
        }
    }

    *array += 1;
    (*array - 1) = new_interface;
}

void remove_interface(net_interface** array, unsigned int* size, const char* id) {
    for(unsigned int i = 0; i < *size; ++i) {
        if(strcmp((*array)[i].id, id) == 0) {
            memmove((*array + i), (*array + i + 1), (*size - (i + 1)) * sizeof(net_interface));
            --(*size);
            break;
        }
    }
}

void update_interface(net_interface** array, unsigned int* size, const char* id, uint32_t new_bandwidth) {
    for(unsigned int i = 0; i < *size; ++i) {
        if(strcmp((*array)[i].id, id) == 0) {
            (*array)[i].bandwidth = new_bandwidth;
            break;
        }
    }
}

void print_interfaces(const net_interface** array, unsigned int size) {
    printf("Network Interface Configurations:\n");
    for(unsigned int i = 0; i < size; ++i) {
        printf("ID: %s, Bandwidth: %u, IP addresses: ", (*array)[i].id, (*array)[i].bandwidth);
        for(const char* ip : (*array)[i].ip_list) {
            printf("%s ", ip);
        }
        printf("\n");
    }
}
