        validate_rnti(&pdus[i]->rnti, networkConfigMinRNTI, networkConfigMaxRNTI);
        if (!is_valid_crc(pdus[i], CRC_VALIDATION_THRESHOLD)) continue;

        for (int j = 0; j < recordsCount; ++j) {
            // Check if the current RNTI matches the network configuration for the record's RNTI
            if (pdus[i]->rnti == records[j].networkRNTI) {
                pdus[i]->record = records[j];
                break;
            }
        }
    }

    return store_credentials(records, pdus, recordsCount, pdusCount);
}

int main() {
    int networkConfigMinRNTI = 100000;
    int networkConfigMaxRNTI = 200000;
    int CRC_VALIDATION_THRESHOLD = 3;

    const int recordsCount = 5;
    const int pdusCount = 10;

    Record* records = malloc(recordsCount * sizeof(Record));
    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(pdusCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < recordsCount; ++i) {
        records[i].networkRNTI = networkConfigMinRNTI + i;
    }

    for (int i = 0; i < pdusCount; ++i) {
        pdus[i] = init_pdu(RX_UE_INFORMATION_TAG_LTE, &pdus[i]->rnti);
    }

    int statusCode = populate_data(pdus, pdusCount, records, recordsCount);

    free(records);
    free(pdus);

    return statusCode;
}
