#define MAX_UE 1024
#define LRU_SIZE 512

typedef struct {
    int rssi;
    int cqi;
    int pmi;
} LTE_UE_MEASUREMENT_REPORT;

struct cache {
    LTE_UE_MEASUREMENT_REPORT *data;
    size_t capacity;
    size_t head, tail;
};

struct ue_array {
    LTE_UE_MEASUREMENT_REPORT array[MAX_UE];
    struct cache lru_cache;
    pthread_mutex_t lock;
};

struct ue_array *ue_init() {
    struct ue_array *ue = malloc(sizeof(struct ue_array));
    pthread_mutex_init(&ue->lock, NULL);
    ue->lru_cache.data = calloc(LRU_SIZE, sizeof(LTE_UE_MEASUREMENT_REPORT));
    ue->lru_cache.capacity = LRU_SIZE;
    ue->lru_cache.head = ue->lru_cache.tail = 0;
    return ue;
}

void ue_add(struct ue_array *ue, uint32_t id, const LTE_UE_MEASUREMENT_REPORT *report) {
    pthread_mutex_lock(&ue->lock);
    uint32_t idx = id % MAX_UE;
    ue->array[idx] = *report;
    pthread_mutex_unlock(&ue->lock);
}

const LTE_UE_MEASUREMENT_REPORT *ue_get(struct ue_array *ue, uint32_t id) {
    pthread_mutex_lock(&ue->lock);
    uint32_t idx = id % MAX_UE;
    const LTE_UE_MEASUREMENT_REPORT *report = &ue->array[idx];

    if (!report->rssi) { // Not initialized or invalid data
        if (ue->lru_cache.head != ue->lru_cache.tail) {
            const LTE_UE_MEASUREMENT_REPORT *lru_report = &ue->lru_cache.data[ue->lru_cache.head];
            report = lru_report;
            ue->lru_cache.head = (ue->lru_cache.head + 1) % LRU_SIZE;
        }
    }

    pthread_mutex_unlock(&ue->lock);
    return report;
}

void ue_array_cleanup(struct ue_array *ue) {
    free(ue->lru_cache.data);
    pthread_mutex_destroy(&ue->lock);
    free(ue);
}
