class NFAPI_CRC_INDICATION_PDU_ARRAY {
private:
    static constexpr size_t MAX_ELEMENTS = 10000;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data_;
    std::map<uint32_t, bool> tags_map_;

public:
    NFAPI_CRC_INDICATION_PDU_ARRAY() {
        if (data_.capacity() < MAX_ELEMENTS) {
            data_.reserve(MAX_ELEMENTS);
            for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
                data_.emplace_back();
                tags_map_[data_.back().RX_UE_INFORMATION_TAG] = false;
            }
        }
    }

    ~NFAPI_CRC_INDICATION_PDU_ARRAY() {
        if (!data_.empty()) {
            data_.clear();
            tags_map_.clear();
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* add_pdu(uint32_t tag) {
        auto it = tags_map_.find(tag);
        if (it != tags_map_.end() && !it->second) {
            it->second = true;
            auto new_index = data_.size();
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_int_distribution<> dis(0, MAX_ELEMENTS - 1);
            size_t index = dis(gen);
            if (index != new_index) {
                std::swap(data_[new_index], data_[index]);
            }
            data_[new_index].RX_UE_INFORMATION_TAG = tag;
            data_[new_index].CRCFLAG = false;
            return &data_[new_index];
        } else {
            throw std::runtime_error("Duplicate RX_UE_INFORMATION_TAG found.");
        }
    }
};
