['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTURES 1024
#define LOG_LEVEL_NONE 0
#define LOG_LEVEL_ERROR 1
#define LOG_LEVEL_INFO 2
#define LOG_LEVEL_VERBOSE 3

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind;
} NFAPI_CRC_INDICATION_PDU_T;

#define ALIGN(x, a) (((x) + (a) - 1) & ~((a)-1))
typedef struct MemBlock {
    size_t size;
    struct MemBlock *next;
    char data[1]; // Will be aligned properly due to variable-length array
} __attribute__((aligned(64))) MemBlock;

struct MemoryPool {
    pthread_mutex_t mutex;
    MemBlock *free_list;
    size_t num_allocated, num_freed, peak_memory, current_memory;
};

void memory_pool_init(struct MemoryPool *pool, size_t chunk_size) {
    pool->mutex = PTHREAD_MUTEX_INITIALIZER;
    pool->free_list = NULL;
    pool->num_allocated = 0;
    pool->num_freed = 0;
    pool->peak_memory = 0;
    pool->current_memory = 0;
    // Allocate initial chunk of memory
    MemBlock *chunk = malloc(ALIGN(chunk_size, 64));
    if (!chunk) {
        fprintf(stderr, "Failed to allocate initial memory chunk\n");
        exit(1);
    }
    pool->free_list = chunk;
}

MemBlock* memory_pool_acquire(struct MemoryPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    MemBlock *block = pool->free_list;
    if (block) {
        pool->free_list = block->next;
        pool->num_allocated++;
        pool->current_memory += block->size;
        if (pool->current_memory > pool->peak_memory) {
            pool->peak_memory = pool->current_memory;
        }
        pthread_mutex_unlock(&pool->mutex);
        return block;
    }
    pthread_mutex_unlock(&pool->mutex);
    // If no free blocks, allocate a new one
    MemBlock *new_block = malloc(ALIGN(sizeof(NFAPI_CRC_INDICATION_PDU_T), 64));
    if (!new_block) {
        fprintf(stderr, "Failed to allocate memory for new block\n");
        exit(1);
    }
    pool->num_allocated++;
    pool->current_memory += ALIGN(sizeof(NFAPI_CRC_INDICATION_PDU_T), 64);
    if (pool->current_memory > pool->peak_memory) {
        pool->peak_memory = pool->current_memory;
    }
    return new_block;
}

void memory_pool_release(struct MemoryPool *pool, MemBlock *block) {
    pthread_mutex_lock(&pool->mutex);
    block->next = pool->free_list;
    pool->free_list = block;
    pool->num_freed++;
    pool->current_memory -= block->size;
    if (pool->current_memory < pool->peak_memory) {
        pool->peak_memory = pool->current_memory;
    }
    pthread_mutex_unlock(&pool->mutex);
}

void log_message(int level, const char *format, ...) {
    static pthread_once_t once_control = PTHREAD_ONCE_INIT;
    static struct {
        FILE *file;
        int verbosity;
    } logger;

    pthread_once(&once_control, init_logger);

    va_list args;
    if (logger.verbosity >= level) {
        time_t rawtime;
        struct tm *timeinfo;
        char time_buffer[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(time_buffer, sizeof(time_buffer), "[%Y-%m-%d %H:%M:%S] ", timeinfo);

        va_start(args, format);
        vfprintf(logger.file, time_buffer format, args);
        va_end(args);
    }
}

void init_logger() {
#ifdef ENABLE_LOGGING
    logger.file = stdout;
    logger.verbosity = LOG_LEVEL_VERBOSE;
#else
    logger.file = NULL;
    logger.verbosity = LOG_LEVEL_NONE;
#endif
}

