#define MAX_ELEMENTS 10000
#define BUFFER_SIZE 256

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

Node* head = NULL;
pthread_mutex_t lock;

void init() {
    head = malloc(sizeof(Node));
    if (!head) {
        fprintf(stderr, "Failed to allocate memory for list.\n");
        exit(EXIT_FAILURE);
    }
    head->next = NULL;
    pthread_mutex_init(&lock, NULL);
}

void destroy() {
    Node *temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
    pthread_mutex_destroy(&lock);
}

Node* allocate_node() {
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new node.\n");
        return NULL;
    }
    new_node->next = NULL;
    return new_node;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);
    Node *new_node = allocate_node();
    if (new_node != NULL) {
        new_node->data = data;
        new_node->next = head->next;
        head->next = new_node;
    } else {
        fprintf(stderr, "Failed to add element to the list.\n");
    }
    pthread_mutex_unlock(&lock);
}

void process_list() {
    Node *current = head->next;
    int processed = 0;
    while (current != NULL && processed < MAX_ELEMENTS) {
        pthread_mutex_lock(&lock);
        if (current != NULL) {
            NFAPI_CRC_INDICATION_PDU_T temp = current->data;
            current = current->next;
            // Process the data here, set CRCFLAG randomly
            temp.crc_indication.crcflag = rand() % 2;
            // Add the processed element back to the list for reuse
            add_to_list(temp);
            processed++;
        }
        pthread_mutex_unlock(&lock);
    }
}

void log_state() {
    printf("List state at timestamp: \n");
    Node *current = head->next;
    int i = 0;
    while (current != NULL) {
        printf("[%d] RX_UE_INFORMATION_TAG: %ld, RNTI: %ld, CRC_INDICATION_REL8_TAG: %d\n", i++, current->data.rx_ue_information, current->data.rnti, current->data.crc_indication.crcflag);
        current = current->next;
    }
}
```

