#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/time.h>
#include <semaphore.h>
#include <stdbool.h>
#include <json-c/json.h>

typedef struct LTE_PHY_STATS_T {
    uint32_t CELL_ID;
    time_t MEASUREMENT_TIME;
    int PHY_RX_POWER_DBM;
} LTE_PHY_STATS_T;

struct dynamic_list {
    LTE_PHY_STATS_T *data;
    size_t capacity;
    size_t size;
    sem_t mutex;
    sem_t growth_cond;
    sem_t shrink_cond;
};

static inline void timed_sem_wait(sem_t* s) {
    struct timespec ts = { 0, 1000 }; // Timeout of 1ms
    while (sem_timedwait(s, &ts) < 0 && errno == ETIMEDOUT);
}

static inline void timed_sem_post(sem_t* s) {
    sem_post(s);
}

void dl_init(struct dynamic_list *dl, size_t initial_capacity) {
    dl->data = malloc(initial_capacity * sizeof(LTE_PHY_STATS_T));
    if (!dl->data) {
        perror("Memory allocation error");
        return;
    }

    sem_init(&dl->mutex, 0, 1); // Initial value of the mutex is always 1
    sem_init(&dl->growth_cond, 0, 0);
    sem_init(&dl->shrink_cond, 0, initial_capacity);

    dl->capacity = initial_capacity;
    dl->size = 0;
}

void dl_destroy(struct dynamic_list *dl) {
    free(dl->data);
    sem_destroy(&dl->mutex);
    sem_destroy(&dl->growth_cond);
    sem_destroy(&dl->shrink_cond);
}

void dl_append(struct dynamic_list *dl, const LTE_PHY_STATS_T* stat) {
    timed_sem_wait(&dl->mutex);

    if (dl->size == dl->capacity) { // Check if capacity has been reached
        sem_post(&dl->growth_cond);
        timed_sem_wait(&dl->shrink_cond);
    }

    memcpy((void*)(dl->data + dl->size), stat, sizeof(LTE_PHY_STATS_T));
    ++dl->size;

    timed_sem_post(&dl->mutex);
}

size_t dl_get_capacity(const struct dynamic_list *dl) {
    return dl->capacity;
}

size_t dl_get_size(const struct dynamic_list *dl) {
    return dl->size;
}

void dl_export(const struct dynamic_list *dl, char *buffer, size_t buffer_len, const char *format) {
