#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU;

typedef struct NODE {
    NFAPI_CRC_INDICATION_PDU data;
    struct NODE *next;
    pthread_mutex_t lock;
} NODE;

static NODE* head = NULL;
static NODE* tail = NULL;
static int node_count = 0;
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

int add_node(NFAPI_CRC_INDICATION_PDU *pdu) {
    NODE* new_node = (NODE*) malloc(sizeof(NODE));
    if (!new_node) return -1; // Memory allocation failure

    new_node->data = *pdu;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);

    pthread_mutex_lock(&list_lock);
    if (!head) {
        head = new_node;
        tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }
    node_count++;
    pthread_mutex_unlock(&list_lock);

    return 0;
}

int update_node(uint32_t rnti, CRC_INDICATION_REL8_TAG *crc) {
    NODE* current = head;
    pthread_mutex_lock(&list_lock);

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            current->data.crc_indication = *crc;
            pthread_mutex_unlock(&list_lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list_lock);
    return -1; // Not found
}

NFAPI_CRC_INDICATION_PDU* get_node(uint32_t rnti) {
    NODE* current = head;
    pthread_mutex_lock(&list_lock);

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            pthread_mutex_unlock(&list_lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list_lock);
    return NULL; // Not found
}
```

In this implementation, we use a singly linked list with each node containing the required data structure and a mutex for concurrent access. The list is protected by a global mutex to ensure thread safety during operations like adding or updating nodes. Memory allocation failures are handled gracefully, and memory fragmentation is minimized due to the dynamic nature of the list.

The `add_node` function allocates new memory for each node and appends it to the end of the list. The `update_node` function searches linearly through the list until finding the node with the specified RNTI, then updates its CRC_INDICATION_REL8_TAG field. The `get_node` function performs a similar linear search and returns the found node's data structure if it exists in the list; otherwise, it returns NULL.

