void* convertImageToPdfAsync(const char* inputFile, const char* outputFile, const unsigned char* byteArray, void* arg) {
    TplImageConverter* converter = TplImageConverter_create();
    try {
        ImageData inputData;
        inputData.data = malloc(strlen((char*)byteArray));
        strcpy((char*)inputData.data, (char*)byteArray);
        inputData.size = strlen((char*)byteArray);

        ImageData outputData;
        OutputStream* pdfStream = createOutputStream(outputFile);

        converter->convertImageToPdf(converter, inputFile, &inputData, &outputData, pdfStream);

        free(inputData.data);
        outputData.data = NULL; // Free memory after use

        closeOutputStream(pdfStream);
    } catch (Exception& e) {
        logError("Error during image to PDF conversion: %s", e.getMessage());
        free(inputData.data);
        if (outputData.data != NULL) free(outputData.data);
        TplImageConverter_destroy(converter);
        throw RuntimeException("Serialization failure during image to PDF conversion");
    }

    free(inputData.data);
    TplImageConverter_destroy(converter);
}

