// Define the struct record
typedef struct {
    size_t size;
    long offset;
    int *key;
    int value;
} record;

// Function to initialize and manage data structures
int initDataStructures(size_t numElements, long *offsets, int *keys, record **data) {
    // Validate arrays have the same length
    if (numElements != sizeof(offsets) / sizeof(long) || numElements != sizeof(keys) / sizeof(int)) {
        printf("Error: offsets and keys arrays do not match in size.\n");
        return -1;
    }

    // Allocate memory for data array
    *data = malloc(numElements * sizeof(record));
    if (!*data) {
        printf("Error: failed to allocate memory for data structures.\n");
        return -2;
    }

    // Iterate through elements, initializing and setting up each record structure
    for (size_t i = 0; i < numElements; ++i) {
        (*data)[i].offset = offsets[i];
        (*data)[i].key = &keys[i];
        // Initialize value with random number in specified range (e.g., [1, 100])
        (*data)[i].value = rand() % 100 + 1;
        (*data)[i].size = numElements;
    }

    return 0;
}

// Function to free memory for data structures
void destroyDataStructures(record *data, size_t numElements) {
    // Iterate through elements, freeing dynamic memory
    for (size_t i = 0; i < numElements; ++i) {
        if ((*data)[i].value) {
            free((*data)[i].value);
        }
        (*data)[i].value = NULL;
    }

    // Free data array
    free(data);
    data = NULL;
}
