#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <semaphore.h>
#include <stdbool.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
    time_t timestamp;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_PDU_T;

struct list {
    int max_entries;
    int num_entries;
    NFAPI_CRC_INDICATION_PDU_T** entries;
    sem_t add_semaphore;
    sem_t remove_semaphore;
};

void init_list(struct list* list, int max_entries) {
    list->max_entries = max_entries;
    list->num_entries = 0;
    list->entries = calloc(max_entries, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list->entries) {
        perror("Failed to allocate memory for entries");
        exit(1);
    }
    list->add_semaphore = sem_init(0, 0, max_entries);
    list->remove_semaphore = sem_init(0, 0, 0);
}

void destroy_list(struct list* list) {
    for (int i = 0; i < list->max_entries; ++i) {
        if (list->entries[i]) {
            free(list->entries[i]);
        }
    }
    free(list->entries);
    sem_destroy(&list->add_semaphore);
    sem_destroy(&list->remove_semaphore);
}

bool is_unique(struct list* list, RX_UE_INFORMATION_TAG tag) {
    for (int i = 0; i < list->num_entries; ++i) {
        if (list->entries[i] && list->entries[i]->tag == tag) {
            return false;
        }
    }
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* find_entry(struct list* list, unsigned int rnti) {
    for (int i = 0; i < list->num_entries; ++i) {
        if (list->entries[i] && list->entries[i]->rnti == rnti) {
            return list->entries[i];
        }
    }
    return nullptr;
}

void* add_entry(void* arg) {
    struct list* list = static_cast<struct list*>(arg);
    NFAPI_CRC_INDICATION_PDU_T* new_entry = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entry) {
        perror("Failed to allocate memory for new entry");
        return nullptr;
    }

    while (true) {
        sem_wait(&list->add_semaphore);

        // Ensure RNTI is unique within the list and that all RX_UE_INFORMATION_TAG instances are distinct.
        RX_UE_INFORMATION_TAG tag = generate_tag();
        if (is_unique(list, tag)) {
            new_entry->tag = tag;
            break;
        }
    }

    new_entry->rnti = generate_rnti();
    new_entry->crc_indication.CRCFLAG = (rand() % 2) ? true : false;
    new_entry->timestamp = time(nullptr);
    pthread_mutex_init(&new_entry->lock, nullptr);

    int index = -1;
    for (int i = 0; i < list->max_entries; ++i) {
        if (!list->entries[i]) {
            index = i;
            break;
        }
    }
    if (index == -1) {
        fprintf(stderr, "Failed to add entry due to full list\n");
        free(new_entry);
        sem_post(&list->remove_semaphore);
        return nullptr;
    }
    list->entries[index] = new_entry;
    ++list->num_entries;

    sem_post(&list->remove_semaphore);
    return new_entry;
}

void remove_outdated_entries(struct list* list) {
    time_t current_time = time(nullptr);
    int entries_to_remove = 0;

    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->num_entries; ++i) {
        if (!list->entries[i] || (current_time - list->entries[i]->timestamp) > MAX_ENTRY_AGE) {
            entries_to_remove++;
        }
    }
    pthread_mutex_unlock(&list->lock);

    if (entries_to_remove > 0) {
        pthread_mutex_lock(&list->lock);
