```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <random>
#include <thread>
#include <mutex>
#include <atomic>
#include <chrono>
#include <functional>
#include <spdlog/spdlog.h>

// UE struct
struct UserEquipment {
    int id;
    int cell_id;
    int resource_id;
};

std::mutex resources_mutex; // Resource allocation mutex
std::atomic<int> next_resource_id(0); // Atomic variable for managing unique resource IDs
std::unordered_map<int, std::vector<UserEquipment>> allocated_resources; // Map of resource ID to allocated UEs
std::unordered_map<int, UserEquipment> ues; // Map of UE ID to UE data

void createUE(const int& priority) {
    // Generate unique UE identifier
    auto id = ues.size();
    ues[id] = { id, randomCellID(), next_resource_id++ };
}

int randomCellID() {
    static std::mt19937 generator(std::random_device{}());
    std::uniform_int_distribution<> distribution(0, 10); // Define the range for cell IDs (0-10)
    return distribution(generator);
}

int getAvailableResource() {
    int resource;
    {
        std::lock_guard<std::mutex> lock(resources_mutex);
        if (allocated_resources.empty()) {
            resource = 0;
        } else {
            auto it = allocated_resources.begin();
            resource = it->first;
            allocated_resources.erase(it);
        }
    }
    return resource;
}

void logUEAllocation(const UserEquipment& ue) {
    spdlog::info("Allocated resource {} to UE {}", ue.resource_id, ue.id);
}

void handleError(const std::exception_ptr& exception_ptr) {
    try {
        std::rethrow_exception(exception_ptr);
    } catch (const std::exception& e) {
        std::cerr << "Error occurred: " << e.what() << '\n';
    }
}

void initUEs(int num_ues, int priority_level, int resource_pool_size) {
    std::vector<std::thread> threads;
    for (int i = 0; i < num_ues; ++i) {
        threads.emplace_back([this, priority_level]() { createUE(priority_level); });
    }

    // Allocate resources to UEs based on priority level and availability
    for (auto& thread : threads) {
        thread.join();
        auto it = ues.begin();
        std::advance(it, thread.get_id());
        UserEquipment& currentUE = it->second;

        // Acquire a resource while ensuring thread safety and contention reduction
        std::lock_guard<std::mutex> lock(resources_mutex);
        int availableResource = getAvailableResource();

        // Adjust the resource allocation based on priority level and current network load
        if (availableResource >= resource_pool_size * 0.5 && currentUE.priority_level > 1) {
            currentUE.resource_id = availableResource;
        } else {
            currentUE.resource_id = findAvailableResourceForPriority(currentUE.priority_level);
        }

        // Log the UE allocation event and handle any errors that occurred during resource allocation
        logUEAllocation(currentUE);
        if (std::exception_ptr exception = currentUE.exception) {
            handleError(exception);
        }
    }
}

// Function to find an available resource for a UE with the given priority level, considering network load and other UEs' resources
int findAvailableResourceForPriority(const int& priority_level) {
    std::unordered_map<int, UserEquipment> ue_priorities; // Map of priority level to highest-priority UEs with that priority level
    for (auto it = ues.begin(); it != ues.end(); ) {
        if (it->second.priority_level == priority_level) {
            ue_priorities[it->second.priority_level].push_back(it->second);
            it = ues.erase(it);
        } else {
            ++it;
        }
    }

    for (auto it = ue_priorities.begin(); it != ue_priorities.end(); ) {
        std::sort(it->second.begin(), it->second.end(), [](const UserEquipment& l, const UserEquipment& r) { return l.resource_id > r.resource_id; });

        auto resource = getAvailableResource();
        for (auto ue : it->second) {
            if (resource != ue.resource_id) continue;
            // Found an available resource, remove it from the list and return the resource ID
            it->second.erase(std::remove_if(it->second.begin(), it->second.end(), [&](const UserEquipment& ue) { return ue.resource_id == resource; }), it->second.end());
            return resource;
        }

        // No suitable resources found for this priority level, continue to the next one
        ++it;
    }

    // If no available resources were found, create a new one
    int new_resource = next_resource_id++;
    std::lock_guard<std::mutex> lock(resources_mutex);
    allocated_resources[new_resource] = {};
    return new_resource;
}
```

