#include <stdlib.h>
#include <stdint.h>

typedef struct MAC_RLC_AMSDU_BUFFER {
    uint8_t* data; // AMSDU payload
    size_t length; // Payload length
} MAC_RLC_AMSDU_BUFFER;

typedef struct MAC_RLC_T {
    MAC_RLC_AMSDU_HEADER header;
    MAC_RLC_AMSDU_BUFFER buffer;
} MAC_RLC_T;

struct mac_rlc_queue {
    size_t capacity;
    size_t unsent_amsdus;
    MAC_RLC_T* elements;
    size_t head, tail;
};

void mac_rlc_queue_init(struct mac_rlc_queue* queue, size_t capacity) {
    queue->capacity = capacity;
    queue->unsent_amsdus = 0;
    queue->elements = calloc(capacity, sizeof(MAC_RLC_T));
    queue->head = queue->tail = 0;
}

void mac_rlc_queue_push(struct mac_rlc_queue* queue, const MAC_RLC_AMSDU_HEADER* header, uint8_t* data, size_t length) {
    if (queue->unsent_amsdus >= queue->capacity - 1) return;

    queue->elements[queue->tail].header = *header;
    queue->elements[queue->tail].buffer.data = malloc(length);
    queue->elements[queue->tail].buffer.length = length;
    memcpy(queue->elements[queue->tail].buffer.data, data, length);

    if (++queue->tail == queue->capacity) queue->tail = 0;
    ++queue->unsent_amsdus;
}

MAC_RLC_AMSDU_HEADER* mac_rlc_queue_pop(struct mac_rlc_queue* queue) {
    if (queue->unsent_amsdus == 0) return NULL;

    const size_t next = (queue->head + 1 == queue->capacity) ? 0 : queue->head + 1;
    MAC_RLC_AMSDU_HEADER* header = &queue->elements[queue->head].header;
    free(queue->elements[queue->head].buffer.data);

    if (++queue->head == queue->capacity) queue->head = 0;
    --queue->unsent_amsdus;

    return header;
}

float mac_rlc_queue_get_occupancy(const struct mac_rlc_queue* queue) {
    return (float)queue->unsent_amsdus / queue->capacity * 100.0f;
}
```

This implementation provides a dynamic array of `MAC_RLC_T` structures, with functions to add elements (`mac_rlc_queue_push`) and remove them (`mac_rlc_queue_pop`). The queue also tracks the number of unsent AMSDUs for congestion control purposes. The `mac_rlc_queue_get_occupancy` function estimates the current buffer occupancy percentage. To handle bursty traffic patterns efficiently, new elements are added to the end of the array, and when the capacity is reached, old elements are removed from the beginning to make room for new ones (using a circular buffer design). This solution prioritizes efficiency and scalability by minimizing memory overhead through careful management of dynamically allocated memory.']

