void create_and_initialize_node(Node **list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new node\n");
        return;
    }

    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);
    new_node->last_accessed = time(NULL);

    *list = new_node;
}

void append_node(Node **head_ref, Node *new_node) {
    if (*head_ref == NULL) {
        *head_ref = new_node;
        return;
    }

    Node *current = *head_ref;
    while (current->next != NULL) {
        current = current->next;
    }

    current->next = new_node;
}

void remove_least_recently_used_nodes(Node **head_ref, size_t *size_ref) {
    if (*size_ref <= MAX_LIST_SIZE) return;

    Node *current = *head_ref;
    Node **to_remove = NULL;
    time_t oldest_time = LONG_MAX;

    while (current != NULL) {
        if (current->last_accessed < oldest_time) {
            oldest_time = current->last_accessed;
            to_remove = &current;
        }

        current = current->next;
    }

    pthread_mutex_lock(&to_remove[0]->lock);
    Node *temp = to_remove[0];
    Node *next = to_remove[0]->next;
    free(temp);

    while (next != NULL) {
        temp = next;
        next = next->next;
        pthread_mutex_lock(&temp->lock);
        free(temp);
    }

    *size_ref -= 1;
}

void randomize_record_values(Record *records, size_t count, int min_value, int max_value) {
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}

void log_error(const char *message) {
    if (log_file == NULL || pthread_mutex_trylock(&log_mutex) == 0) return;

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) > LOG_FILE_SIZE) {
        ftruncate(fileno(log_file), 0);
        log_file = fopen("logs.txt", "w");
    }

    fprintf(log_file, "%s\n", message);
    pthread_mutex_unlock(&log_mutex);
}
