struct log_record {
    long offset;
    int key;
    record_status status;
};

size_t create_log_manager(int num_records, size_t *record_array_size, struct log_record** records, int* deletion_flags) {
    if (num_records < 0) return 0;
    MAX_RECORDS = (num_records > MAX_RECORDS) ? MAX_RECORDS : num_records;

    *record_array_size = sizeof(struct log_record) * MAX_RECORDS;
    *records = malloc(*record_array_size);
    if (!*records) return 0;

    size_t offsets_size = sizeof(long) * MAX_RECORDS;
    long* offsets = calloc(MAX_RECORDS, sizeof(long));
    if (!offsets) {
        free(*records);
        *record_array_size = 0;
        return 0;
    }

    size_t keys_size = sizeof(int) * MAX_RECORDS;
    int* keys = calloc(MAX_RECORDS, sizeof(int));
    if (!keys) {
        free(offsets);
        free(*records);
        *record_array_size = 0;
        return 0;
    }

    for (int i = 0; i < num_records; ++i) {
        (*records + i)->offset = offsets[i];
        (*keys)[i] = srand(time(NULL)) * UINT32_MAX;
        (*records + i)->key = (*keys)[i] % num_records;
        (*records + i)->status = INIT;
    }

    *deletion_flags = calloc(num_records, sizeof(int));

    size_t allocated_size = *record_array_size - offsets_size - keys_size - sizeof(*deletion_flags);

    return allocated_size;
}

void mark_deleted(struct log_record* record) {
    if (record->status == DELETED) return;
    record->status = DELETED;
}

void activate_record(struct log_record* record) {
    if (record->status != DELETED) return;
    record->status = ACTIVE;
}

void print_records(const struct log_record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        printf("Record %d: Offset=%ld Key=%d Status=%s\n", i, records[i].offset, records[i].key, record_status_names[records[i].status]);
    }
}
```
