        array.update(rnti, *data);
    }
}

int main() {
    for (int i = 0; i < max_threads; ++i)
        arrays.push_back(std::make_shared<DynamicArray>());

    std::vector<std::thread> threads;
    for (size_t i = 0; i < max_threads; ++i)
