#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <arpa/inet.h>

// Maximum array size for efficiency (can be adjusted based on requirements)
#define MAX_NUM 1000000
#define TCP_SEGMENT_SIZE 4096 // Adjustable segment size for network transfer optimization

typedef struct {
    uint32_t psn; // Packet sequence number
    uint32_t ack; // Acknowledgment number
    uint32_t payload_len; // Payload length dynamically scaled based on data
    float data[TCP_SEGMENT_SIZE]; // Holds the floating-point numbers
} TCP_SEGMENT_T;

// Helper function to calculate the average of an array
float calculate_avg(const float *arr, size_t len) {
    float sum = 0.0f;
    for (size_t i = 0; i < len; ++i)
        sum += arr[i];
    return sum / len;
}

// Helper function to find the smallest number in an array
float find_min(const float *arr, size_t len) {
    if (len == 0)
        return FLT_MAX;

    float min = arr[0];
    for (size_t i = 1; i < len; ++i)
        min = (min < arr[i]) ? min : arr[i];

    return min;
}

// Main function to read, process, and output data
int main(void) {
    float numbers[MAX_NUM]; // Stores floating-point numbers
    size_t num_count = 0; // Number of valid numbers read
    TCP_SEGMENT_T segments[TCP_SEGMENT_SIZE / sizeof(TCP_SEGMENT_T)];

    float number;
    while (scanf("%f", &number) == 1) {
        if (!isinf(number) && !isnan(number)) {
            numbers[num_count++] = number;
            // Adjust segment payload length based on the floating-point data
            for (size_t i = num_count - TCP_SEGMENT_SIZE; i < num_count; ++i) {
                TCP_SEGMENT_T *segment = &segments[i - (num_count - TCP_SEGMENT_Size)];
                segment->psn = i + 1;
                segment->ack = segment->psn - 1; // ACK is the previous packet sequence number
                segment->payload_len = sizeof(number);
                memcpy(&segment->data[0], &numbers[i], segment->payload_len);
            }
        }
    }

    if (num_count == 0) {
        printf("No valid floating-point numbers were found.\n");
        return 1;
    }

    float avg = calculate_avg(numbers, num_count);
    float min = find_min(numbers, num_count);

    printf("Average: %.6f\n", avg);
    printf("Smallest number: %.6f\n", min);

    // Print TCP segments containing scaled floating-point data
    for (size_t i = 0; i < TCP_SEGMENT_SIZE / sizeof(TCP_SEGMENT_T); ++i) {
        if (segments[i].payload_len != 0) {
            printf("Packet sequence number: %u\n", segments[i].psn);
            printf("Acknowledgment number: %u\n", segments[i].ack);
            printf("Payload length: %u\n", segments[i].payload_len);
            for (size_t j = 0; j < segments[i].payload_len; ++j)
                printf("%.6f ", segments[i].data[j]);
            printf("\n");
        }
    }

    return 0;
}
```

