class Allocator {
public:
    explicit Allocator(size_t maxSize) : m_maxSize(maxSize), m_nextIndex(0) {}

    std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T[]> allocate(size_t count) {
        if (count > m_maxSize) {
            throw std::runtime_error("Maximum number of structures exceeded.");
        }
        auto data = std::make_unique<NFAPI_CRC_INDICATION_PDU_T[]>(static_cast<size_t>(count));
        if (!data) {
            throw std::bad_alloc();
        }
        m_data.insert(m_data.end(), data.get(), data.get() + count);
        return data;
    }

private:
    size_t m_maxSize;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> m_data;
    size_t m_nextIndex;
};

class AllocatorQueue {
public:
    explicit AllocatorQueue(size_t maxSize, size_t queueCapacity)
        : m_allocator(maxSize), m_queue(queueCapacity) {}

    std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T[]> allocate(size_t count) {
        auto data = m_allocator.allocate(count);
        populateAndValidate(data.get(), count);
        return data;
    }

private:
