['```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;
using System.Timers;

public class ElementService
{
    private readonly HttpClient _httpClient;
    private readonly DatabaseContext _dbContext;
    private readonly TimeSpan _timeLimit = TimeSpan.FromSeconds(5);
    private const int _maxRetries = 3;

    public ElementService(HttpClient httpClient, DatabaseContext dbContext)
    {
        _httpClient = httpClient;
        _dbContext = dbContext;
    }

    public async Task UpdateElementAsync(int pageSectionId, int elementId, string htmlContent)
    {
        if (pageSectionId <= 0 || elementId <= 0 || string.IsNullOrWhiteSpace(htmlContent))
            throw new ArgumentException("Invalid input data");

        var watch = System.Diagnostics.Stopwatch.StartNew();

        try
        {
            await UpdateElementRecursiveAsync(pageSectionId, elementId, htmlContent);

            if (watch.Elapsed > _timeLimit)
                throw new TimeoutException("Operation exceeded time limit");
        }
        catch (Exception ex) when (_maxRetries > 0 && ex is not InvalidOperationException && ex is not TimeoutException)
        {
            Console.WriteLine($"Retrying due to internal error: {ex.Message}");

            if (_maxRetries-- <= 0)
                throw;

            await Task.Delay(TimeSpan.FromSeconds(2)); // Retry delay
            await UpdateElementAsync(pageSectionId, elementId, htmlContent);
        }
    }

    private async Task UpdateElementRecursiveAsync(int pageSectionId, int elementId, string htmlContent)
    {
