#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    struct _NFAPI_CRC_INDICATION_PDU_T *prev, *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t size;
    pthread_mutex_t lock;
    FILE *binary_file;
} doubly_linked_list_t;

doubly_linked_list_t* create_dll() {
    doubly_linked_list_t *dll = malloc(sizeof(doubly_linked_list_t));
    dll->head = NULL;
    dll->tail = NULL;
    dll->size = 0;
    pthread_mutex_init(&dll->lock, NULL);
    dll->binary_file = NULL;
    return dll;
}

NFAPI_CRC_INDICATION_PDU_T* create_node(RX_UE_INFORMATION_TAG tag, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->tag = tag;
    new_node->rnti = rnti;
    new_node->crc_indication.crcflag = rand() % 2; // randomly set CRCFLAG
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

int add_to_dll(doubly_linked_list_t *dll, NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&dll->lock);
    if (dll->head == NULL) {
        dll->head = node;
        dll->tail = node;
    } else {
        node->prev = dll->tail;
        dll->tail->next = node;
        dll->tail = node;
    }
    ++dll->size;
    pthread_mutex_unlock(&dll->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* remove_from_dll(doubly_linked_list_t *dll) {
    pthread_mutex_lock(&dll->lock);
    if (dll->size == 0) {
        pthread_mutex_unlock(&dll->lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *to_remove = dll->head;
    if (dll->size == 1) {
        dll->head = NULL;
        dll->tail = NULL;
    } else {
        dll->head = to_remove->next;
        (dll->head)->prev = NULL;
    }
    --dll->size;
    pthread_mutex_unlock(&dll->lock);

    to_remove->prev = NULL;
    to_remove->next = NULL;
    return to_remove;
}

void clear_and_deallocate(doubly_linked_list_t *dll) {
    pthread_mutex_lock(&dll->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = dll->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }

    dll->head = NULL;
    dll->tail = NULL;
    dll->size = 0;
    pthread_mutex_unlock(&dll->lock);
}

int serialize_to_file(doubly_linked_list_t *dll, const char *filename) {
    pthread_mutex_lock(&dll->lock);
    dll->binary_file = fopen(filename, "wb");
    if (dll->binary_file == NULL) {
        pthread_mutex_unlock(&dll->lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *current = dll->head;
    while (current != NULL) {
        fwrite( &(current->tag), sizeof(RX_UE_INFORMATION_TAG), 1, dll->binary_file );
        fwrite( &current->rnti, sizeof(int), 1, dll->binary_file );
        fwrite( &(current->crc_indication), sizeof(CRC_INDICATION_REL8_TAG), 1, dll->binary_file );
        current = current->next;
    }

    fclose(dll->binary_file);
    dll->binary_file = NULL;
    pthread_mutex_unlock(&dll->lock);
    return 0;
}

int deserialize_from_file(doubly_linked_list_t *dll, const char *filename) {
    pthread_mutex_lock(&dll->lock);
    dll->binary_file = fopen(filename, "rb");
    if (dll->binary_file == NULL) {
        pthread_mutex_unlock(&dll->lock);
        return -1;
    }

    clear_and_deallocate(dll);

    NFAPI_CRC_INDICATION_PDU_T *new_node = NULL;
    while (!feof(dll->binary_file)) {
        new_node = create_node((RX_UE_INFORMATION_TAG)ftell(dll->binary_file), 0); // assume the RX_UE_INFORMATION_TAG is the offset
        add_to_dll(dll, new_node);
    }

    fclose(dll->binary_file);
    dll->binary_file = NULL;
    pthread_mutex_unlock(&dll->lock);
    return 0;
}
